/*
 * Raspberry Pi 4 Model B - MLX91219 Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VOUT -> ADS1115 AIN0
 *   ADS1115 SDA  -> Pi GPIO2 (I2C1 SDA)
 *   ADS1115 SCL  -> Pi GPIO3 (I2C1 SCL)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 VDD -> 3.3V, GND -> GND
 *
 * Build: gcc -Wall -O2 -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register bit layout (16-bit, big-endian on the bus):
 *   [15]    OS       = 1 (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 single-ended)
 *   [11:9]  PGA      = 001 (±4.096 V)
 *   [8]     MODE     = 1 (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4]     COMP_MODE= 0 (traditional)
 *   [3]     COMP_POL  = 0 (active low)
 *   [2]     COMP_LAT  = 0 (non-latching)
 *   [1:0]   COMP_QUE  = 11 (disable comparator)
 *
 * Binary: 1 100 001 1 100 0 0 1 11
 *         = 0xC183
 */
#define ADS1115_CONFIG_BASE 0xC183

/* MLX91219 calibration */
#define MLX_SENSITIVITY_MV_PER_A 40.0f   /* 40 mV/A */
#define MLX_ZERO_CURRENT_V       1.65f   /* volts at zero current (mid-supply) */
#define V_SUPPLY                 3.3f    /* ADC reference voltage */

/* Sampling */
#define SAMPLE_INTERVAL_US       500000  /* 500 ms */
#define CONVERSION_WAIT_US       10000   /* 10 ms (128 SPS -> ~7.8 ms) */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends bytes in the order they are passed,
 * so the MSB must be first.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value >> 8);
    buf[1] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns bytes in the order they are read,
 * so the MSB must be read first.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and return the raw ADC code.
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent (OS bit not set).
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;
    uint16_t conv;
    int attempts;

    /* Write config with OS=1 to start a conversion */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Poll the OS bit (bit 15) until it reads 1 (conversion complete) */
    for (attempts = 0; attempts < 20; attempts++) {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &conv) < 0)
            return -1;
        if (conv & 0x8000)
            break;
        gpioDelay(2000); /* 2 ms */
    }

    if (attempts >= 20) {
        fprintf(stderr, "[ERROR] ADS1115 conversion timeout (OS never set)\n");
        return -2;
    }

    /* Read the 16-bit conversion result */
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* ------------------------------- Conversion ------------------------------- */
static float raw_to_volts(int16_t raw)
{
    /*
     * ADS1115 16-bit signed mode: full scale = 32767 counts = 3.3 V.
     * PGA = ±4.096 V -> LSB = 4.096/32767 = 125 µV.
     */
    return (float)raw * 0.000125f;
}

static float calculate_current(float voltage)
{
    float offset_v = MLX_ZERO_CURRENT_V;
    return (voltage - offset_v) / (MLX_SENSITIVITY_MV_PER_A / 1000.0f);
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    int16_t raw;
    float voltage, current;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor Monitor (via ADS1115)\n");
    printf("I2C bus %d, ADS1115 addr 0x%02X, AIN0 single-ended\n", I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int rc = ads1115_read_ain0(g_i2c_handle, &raw);

        if (rc == -2) {
            fprintf(stderr, "[WARN] Sensor absent or not responding (OS bit never set)\n");
        } else if (rc < 0) {
            fprintf(stderr, "[WARN] I2C communication error during conversion\n");
        } else {
            voltage = raw_to_volts(raw);
            current = calculate_current(voltage);
            printf("Current: %.2f A  (raw=%d, V=%.3f)\n", current, raw, voltage);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

