#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define TEMP_THRESHOLD 60.0f
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 100000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_flame_tick = 0;
static volatile int flame_active = 0;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t elapsed = tick - last_flame_tick;
        if (last_flame_tick != 0 && elapsed < DEBOUNCE_MS * 1000)
            return;
        last_flame_tick = tick;
        flame_active = 1;
    }
}

static int ads1115_init(int handle) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_voltage(int handle, float *voltage) {
    char reg = ADS1115_REG_CONVERSION;
    char data[2];
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to select conversion register\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion\n");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw * 4.096f) / 32768.0f;
    return 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    if (ads1115_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open fire_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register flame sensor ISR\n");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (flame_active) {
            int flame = gpioRead(FLAME_SENSOR_GPIO);
            if (flame == 0) {
                float voltage = 0.0f;
                if (ads1115_read_voltage(i2c_handle, &voltage) == 0) {
                    float temp = (voltage * 80.0f) / 33.0f + 20.0f;
                    if (temp > TEMP_THRESHOLD) {
                        char msg[128];
                        snprintf(msg, sizeof(msg),
                                 "Fire detected! Flame=1 (GPIO%d LOW), Temp=%.2fC",
                                 FLAME_SENSOR_GPIO, temp);
                        log_event(msg);
                        gpioWrite(BUZZER_GPIO, 1);
                        gpioDelay(BUZZER_DURATION_US);
                        gpioWrite(BUZZER_GPIO, 0);
                    } else {
                        char msg[128];
                        snprintf(msg, sizeof(msg), "Flame detected! (GPIO%d LOW)",
                                 FLAME_SENSOR_GPIO);
                        log_event(msg);
                    }
                } else {
                    log_event("Error: ADC read failed");
                }
                flame_active = 0;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

