/*
 * Simulated ADC readings for the MICS-4514 CO sensor.
 * In a real deployment, replace this with the actual I2C read
 * from an ADS1115 or similar 16-bit ADC connected to the sensor.
 */
#define ADC_HIGH 1000
#define ADC_LOW 500

static volatile sig_atomic_t running = 1;
