static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc_simulated(int handle, int *value) {
    int min_val = ADC_LOW, max_val = ADC_HIGH;
    *value = (rand() % (max_val - min_val + 1)) + min_val;
    return 0;
}

static double calculate_ppm(int adc_value) {
    if (adc_value <= 0) return 0.0;
    double resistance = (double)adc_value * 1000.0; /* Simulated sensor: 1000 ohms per ADC count */
    double ratio = resistance / 1000.0; /* RL/Rs ratio */
    if (ratio <= 0.0) return 0.0;
    double ppm = 100.0 * pow(ratio, -1.5);
    if (ppm < 0.0) ppm = 0.0;
    return ppm;
}

static int log_data(double ppm_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

