    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
            return -1;
        }
    }

    if (fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm_value) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

