// Global variable for I2C handle
int i2c_handle = -1;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor_data(int handle, uint16_t *co_ox, uint16_t *no2_red);
float calculate_co_ppm(uint16_t co_ox);
void log_co_data(float co_ppm);
