        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        uint16_t co_ox, no2_red;

        // Read sensor data
        if (read_sensor_data(i2c_handle, &co_ox, &no2_red) == 0) {
            // Calculate CO level in PPM
            float co_ppm = calculate_co_ppm(co_ox);

            // Log CO data
            log_co_data(co_ppm);

            // Check for alerts
            if (co_ppm > CO_THRESHOLD) {
                log_alert(co_ppm);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup resources
    cleanup();

    printf("Air quality monitoring stopped.\n");

    return 0;
}

