#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define REG_DATA 0x00
#define SAMPLE_INTERVAL_US 100000
#define MIC1_SENSITIVITY -38.0
#define REFERENCE_PRESSURE 20.0e-6

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_i2c_word(int handle, int reg) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

static float convert_to_db(int raw) {
    float voltage = (float)raw * 3.3 / 65535.0;
    float pressure = voltage / pow(10.0, (MIC1_SENSITIVITY / 20.0));
    return 20.0 * log10(fabs(pressure - REFERENCE_PRESSURE));
}

static void log_data(float avg_db) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("Error opening audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f\n", ts, avg_db);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for mic1 (0x%02X): %d\n", MIC1_ADDR, handle1);
        gpioTerminate();
        return 1;
    }

    int handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for mic2 (0x%02X): %d\n", MIC2_ADDR, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int raw1 = read_i2c_word(handle1, REG_DATA);
        int raw2 = read_i2c_word(handle2, REG_DATA);

        if (raw1 < 0 || raw2 < 0) {
            fprintf(stderr, "Error reading sensor data (mic1=%d, mic2=%d)\n", raw1, raw2);
            log_data(-999.0f);
        } else {
            float db1 = convert_to_db(raw1);
            float db2 = convert_to_db(raw2);
            float avg = (db1 + db2) / 2.0f;
            log_data(avg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return 0;
}

