static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

// Function prototypes
int read_adc(int channel);
double calculate_rms(int *data, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void trigger_led(int gpio_pin, int duration_ms);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI protocol: 3 bytes
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buf[3] = {0};

    // pigpio's spiXfer handles CS automatically for the channel specified in spiOpen
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx_buf[1] contains the two most significant bits (masked with 0x03)
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double sample = (double)data[i];
        sum_of_squares += (sample * sample);
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to a CSV file
void log_data(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

