void trigger_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

