    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    int data1[NUM_SAMPLES];
    int data2[NUM_SAMPLES];
    int sample_index = 0;

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read ADC samples for both microphones
        int adc1 = read_adc(ADC_CHANNEL_MIC1);
        int adc2 = read_adc(ADC_CHANNEL_MIC2);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC. Exiting.\n");
            break;
        }

        data1[sample_index] = adc1;
        data2[sample_index] = adc2;
        sample_index++;

        // Calculate RMS values when we have enough samples
        if (sample_index >= NUM_SAMPLES) {
            double rms1 = calculate_rms(data1, NUM_SAMPLES);
            double rms2 = calculate_rms(data2, NUM_SAMPLES);

            // Log the data
            log_data(rms1, rms2);

            // Check if the threshold is exceeded
            if (rms1 > THRESHOLD || rms2 > THRESHOLD) {
                printf("Threshold exceeded! Mic1 RMS: %.6f, Mic2 RMS: %.6f\n", rms1, rms2);
                trigger_led(LED_GPIO, LED_ON_DURATION_MS);
            }

            // Reset arrays for the next window
            sample_index = 0;
        }

        // Delay to achieve the desired sample rate
        gpioDelay(1000000 / SAMPLE_RATE); // 1ms delay
    }

    // Cleanup
    cleanup();
