#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define OVERCURRENT_THRESHOLD 50.0
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define ADC_MAX_VALUE 32767.0 // 16-bit signed positive max for +/-4.096V range
#define ADC_VREF 4.096
#define SENSOR_VREF 5.0
#define SENSOR_MAX_CURRENT 100.0

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c(void);
int16_t read_ads1115(void);
float convert_to_current(int16_t adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average(const CircularBuffer *cb);
void signal_handler(int signal);
void cleanup(void);

// Initialize I2C and ADS1115
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    // Configure ADS1115: Single-shot, AIN0, +/-4.096V, 128 SPS
    uint16_t config = ADS1115_CONFIG_BASE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115 channel A0
int16_t read_ads1115(void) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register pointer\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Convert ADC reading to current (A)
float convert_to_current(int16_t adc_value) {
    float voltage = (float)adc_value * ADC_VREF / ADC_MAX_VALUE;
    float current = (voltage / SENSOR_VREF) * SENSOR_MAX_CURRENT;
    return current;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in buffer
float get_average(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C and ADS1115
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer current_buffer = {{0.0}, 0, 0};

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger a single-shot conversion
        uint16_t config = ADS1115_CONFIG_BASE;
        char config_buf[3];
        config_buf[0] = ADS1115_REG_CONFIG;
        config_buf[1] = (config >> 8) & 0xFF;
        config_buf[2] = config & 0xFF;
        if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
            fprintf(stderr, "Error triggering ADS1115 conversion\n");
            break;
        }

        // Wait for conversion to complete (approx 8ms for 128 SPS)
        gpioDelay(10000); // 10ms

        // Read ADC value
        int16_t adc_value = read_ads1115();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(adc_value);

        // Add to circular buffer
        add_to_buffer(&current_buffer, current);

        // Calculate average current
        float average_current = get_average(&current_buffer);

        // Check for overcurrent condition
        if (average_current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Average current: %.2fA\n", average_current);
            gpioWrite(LED_GPIO, 1); // Turn on LED
        } else {
            gpioWrite(LED_GPIO, 0); // Turn off LED
        }

        // Print current reading
        printf("Current: %.2fA, Average: %.2fA\n", current, average_current);

        // Delay for sample rate
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

