#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

#define I2C_BUS 1
#define MAX_CONSECUTIVE_ERRORS 3
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int init_sensor(int handle) {
    int id = i2cReadByteData(handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register: %d\n", id);
        return -1;
    }
    if ((id & 0x0F) != 0x04) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected lower 4 bits 0x04)\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, 0x01) < 0) return -1;

    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE,
                       TCS34725_ENABLE_PON) < 0) return -1;
    gpioDelay(3000);

    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);

    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red,
                           uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_COMMAND_BIT | TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_COMMAND_BIT | TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_COMMAND_BIT | TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red,
                     uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            clear, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open color_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t clear, red, green, blue;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_data(log_file, clear, red, green, blue);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors (%d), exiting\n",
                        consecutive_errors);
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

