    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line 8: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
            goto cleanup;
        }
    } else {
        fclose(fp);
    }

    printf("Starting moisture sensor logging. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_values[NUM_CHANNELS];
        float moisture_levels[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc_values[i] = read_mcp3008(spi_fd, cs_line, i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            moisture_levels[i] = process_moisture_level(adc_values[i]);
        }

        if (!error) {
            if (log_data(moisture_levels[0], moisture_levels[1]) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

