#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define ADC_MAX 1023.0
#define VREF 3.3
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define SPI_RETRIES 3
#define SPI_SPEED_HZ 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spidev");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    motor_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(motor_line, "mlx91211_oc", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); chip = NULL; motor_line = NULL; return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI ioctl failed (attempt %d): %s\n", attempt+1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX * VREF;
    return (voltage - OFFSET) / SENSITIVITY;
}

static void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("fopen log");
            return;
        }
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,current_in_Amperes\n");
        }
    }
    fprintf(log_file, "%s,%.2f\n", ts, current);
    fflush(log_file);
}

static void shutdown_motor(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 0);
        printf("Motor shutdown triggered!\n");
    }
}

static void re_enable_motor(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        printf("Motor re-enabled.\n");
    }
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (init_spi() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        close(spi_fd); spi_fd = -1;
        return 1;
    }
    printf("MLX91211 Current Monitor started. Press Ctrl+C to exit.\n");
    while (program_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        float current = adc_to_current(adc);
        log_current(current);
        printf("Current: %.2f A\n", current);
        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            sleep(1);
            re_enable_motor();
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    cleanup();
    printf("Exiting.\n");
    return 0;
}

