#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure_raw(uint16_t *raw_out)
{
    int rc = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData(reg=0x%02X) failed: %d\n",
                PRESSURE_REG, rc);
        return -1;
    }
    *raw_out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static double raw_to_kPa(uint16_t raw)
{
    return ((double)raw / 65535.0) * 500.0;
}

static int log_data(double pressure_kPa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            perror("Error writing CSV header");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw = 0;
        if (read_pressure_raw(&raw) == 0) {
            consecutive_errors = 0;
            double pressure = raw_to_kPa(raw);
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Error: %d consecutive failures — sensor may be absent\n",
                        consecutive_errors);
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

