        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            perror("Error writing CSV header");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw = 0;
        if (read_pressure_raw(&raw) == 0) {
            consecutive_errors = 0;
            double pressure = raw_to_kPa(raw);
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Error: %d consecutive failures — sensor may be absent\n",
                        consecutive_errors);
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

