#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_MUX_AIN1_GND (0x05 << 12)
#define ADS1115_CONFIG_PGA_2_5V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

#define WARNING_LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL_US 1000000
#define I2C_RETRY_COUNT 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_single(uint8_t mux) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | mux | ADS1115_CONFIG_PGA_2_5V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        return -1;
    }

    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        char reg = ADS1115_REG_CONVERSION;
        if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
            return -1;
        }
        char data[2];
        if (i2cReadDevice(i2c_handle, data, 2) == 2) {
            return (int16_t)((data[0] << 8) | data[1]);
        }
        gpioDelay(1000);
    }
    return -1;
}

static float voltage_to_pressure(float voltage) {
    return (voltage / 5.0f) * 400.0f;
}

static float voltage_to_temperature(float voltage) {
    return (voltage - 1.0f) * 100.0f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", WARNING_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Monitor (via ADS1115)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int16_t raw_pressure = read_ads1115_single(ADS1115_CONFIG_MUX_AIN0_GND);
        int16_t raw_temp = read_ads1115_single(ADS1115_CONFIG_MUX_AIN1_GND);

        if (raw_pressure < 0 || raw_temp < 0) {
            fprintf(stderr, "Error: Failed to read ADS1115 after %d retries.\n", I2C_RETRY_COUNT);
            gpioWrite(WARNING_LED_PIN, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage_pressure = ((float)raw_pressure / 32767.0f) * 2.5f;
        float voltage_temp = ((float)raw_temp / 32767.0f) * 2.5f;

        float pressure = voltage_to_pressure(voltage_pressure);
        float temperature = voltage_to_temperature(voltage_temp);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(WARNING_LED_PIN, 1);
            printf("WARNING: Pressure exceeds threshold!\n");
        } else {
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

