#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define MCP3008_CH  0        /* Single-ended channel 0 */
#define LOG_FILE    "methane_log.txt"
#define THRESHOLD   1000.0   /* PPM */
#define MAX_PPM     5000.0   /* Sensor full-scale */
#define ADC_MAX     1023.0   /* 10-bit ADC */
#define SAMPLE_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (dummy for clocking data out)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

static float adc_to_ppm(int adc)
{
    return ((float)adc / ADC_MAX) * MAX_PPM;
}

static void log_reading(float ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s, %.2f PPM\n", ts, ppm);
    fclose(fp);
}

static void check_threshold(float ppm)
{
    if (ppm > THRESHOLD) {
        fprintf(stderr, "ALARM: Methane level exceeded threshold (%.2f PPM > %.2f PPM)!\n",
                ppm, THRESHOLD);
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus 0, channel 0, 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, MCP3008_CH);
        if (adc < 0) {
            /* SPI error: log to stderr and continue */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float ppm = adc_to_ppm(adc);
        log_reading(ppm);
        check_threshold(ppm);

        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

