#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_OS_BEGIN 0x8000

#define VREF 4.096
#define ADC_MAX 32767.0
#define SENSOR_OFFSET 0.5
#define SENSOR_SENSITIVITY 0.1
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int16_t read_ads1115();
double convert_to_pressure(int16_t adc_value);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C and ADS1115
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115: Single-shot, AIN0, +/-4.096V, 128 SPS
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_MODE_SINGLE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read 16-bit ADC value from ADS1115
int16_t read_ads1115() {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Failed to set conversion register: %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data: %s\n", strerror(errno));
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Convert ADC value to pressure (kPa)
double convert_to_pressure(int16_t adc_value) {
    double voltage = (adc_value / ADC_MAX) * VREF;
    double pressure = (voltage - SENSOR_OFFSET) / SENSOR_SENSITIVITY;
    return pressure;
}

// Log pressure data to file
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C and ADS1115
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_ads1115();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        double pressure = convert_to_pressure(adc_value);

        // Data validation
        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        } else {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US); // 1 second delay
    }

    printf("\nPressure monitoring stopped.\n");
    cleanup();
    return 0;
}

