#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 4095
#define VREF 5.0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define SAMPLE_INTERVAL 5

#define TEMP_BETA 3950.0
#define TEMP_R0 10000.0
#define TEMP_REF 298.15

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    float humidity = (voltage - 0.824) / 0.0315;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    float resistance = 10000.0;
    float beta = TEMP_BETA;
    float r0 = TEMP_R0;
    float temp = (beta * (r0 / resistance - 1.0)) / (beta - 1.0);
    if (temp < TEMP_REF) temp = TEMP_REF;
    return temp;
}

int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command),
             "echo \"Humidity alert: %.2f%%\" | ssmtp -s \"Humidity Alert\" recipient@example.com", humidity);
    FILE *fp = popen(command, "r");
    if (!fp) return -1;
    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp)) {
        printf("%s", buffer);
    }
    int status = pclose(fp);
    return (status == 0) ? 0 : -1;
}

int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) return -1;
    fflush(log_file);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI transfer error\n");
        } else {
            float humidity = calculate_humidity(adc_value);
            float temperature = calculate_temperature(adc_value);
            if (log_data(humidity, temperature) != 0) {
                fprintf(stderr, "Log write error\n");
            }
            if (humidity > HUMIDITY_THRESHOLD) {
                printf("Humidity %.2f%% exceeds threshold. Sending email alert...\n", humidity);
                if (send_email_alert(humidity) != 0) {
                    fprintf(stderr, "Failed to send email alert\n");
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

