#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/*
 * Raspberry Pi 4 Model B
 * ADXL335 (analog accelerometer) -> MCP3008 ADC (SPI0, CE0/GPIO8)
 *   X -> CH0
 *   Y -> CH1
 *   Z -> CH2
 *
 * SPI: 1 MHz, Mode 0, active-low CS on GPIO8
 * Vdd = 3.3 V, 0g point = 1.65 V, sensitivity = 300 mV/g
 */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CS */

#define ADC_CHANNELS   3
#define ADC_MAX        1023       /* 10-bit ADC */
#define ADC_RESOLUTION 10.0       /* volts per count */

#define VDD            3.3
#define V0G            1.65       /* ADXL335 0g output */
#define SENSITIVITY    0.3        /* 300 mV/g */
#define IMPACT_THRESHOLD 2.0      /* g */

#define LOG_FILE       "impact_log.txt"
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one single-ended channel from the MCP3008.
 * Returns 0..1023 on success, -1 on SPI error, -2 on out-of-range. */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    gpioWrite(8, 0);                       /* CS low */
    int status = spiXfer(g_spi_handle, tx, rx, 3);
    gpioWrite(8, 1);                       /* CS high */

    if (status != 3) {
        fprintf(stderr, "SPI transfer failed (status=%d)\n", status);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -2;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int x, int y, int z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp, int x, int y, int z, float magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,IMPACT DETECTED,X=%d,Y=%d,Z=%d,Magnitude=%.2fg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- CS pin (GPIO8) as output, default high (inactive) --- */
    if (gpioSetMode(8, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO8 as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(8, 1);                       /* CS idle high */

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL335 via MCP3008 logging started. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error (x=%d y=%d z=%d)\n", x, y, z);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw ADC to voltage, then to g */
        float v_x = (float)x * ADC_RESOLUTION * VDD / (float)(ADC_MAX + 1);
        float v_y = (float)y * ADC_RESOLUTION * VDD / (float)(ADC_MAX + 1);
        float v_z = (float)z * ADC_RESOLUTION * VDD / (float)(ADC_MAX + 1);

        float x_g = (v_x - V0G) / SENSITIVITY;
        float y_g = (v_y - V0G) / SENSITIVITY;
        float z_g = (v_z - V0G) / SENSITIVITY;

        float magnitude = sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);

        log_data(g_log_file, x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(g_log_file, x, y, z, magnitude);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

