/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * I2C bus 1, default address 0x49.
 *
 * Logs Unix timestamp, raw IR/RED ADC, HR_proxy(bpm), SpO2_proxy(%),
 * and an error flag to biometric_log.csv once per second.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples to meaningful HR/SpO2 values. This program reads the raw 16-bit
 * IR and RED ADC values from the FIFO and logs them as proxy values.
 * A value of 0xFFFF indicates an I2C read failure.
 *
 * Build: gcc -O2 -Wall -o si1172_log si1172_log.c -lpigpio -lrt
 * Run:   sudo ./si1172_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x49

/* Si1172 command register */
#define SI1172_REG_CMD   0xC0
/* Si1172 FIFO data registers (16-bit little-endian per channel) */
#define SI1172_REG_FIFO_RED   0xC1
#define SI1172_REG_FIFO_IR    0xC3

/* Command to trigger a PPG measurement */
#define SI1172_CMD_PPG  0x01

#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a Si1172 register             */
/* ------------------------------------------------------------------ */
static int si1172_read_reg16(uint8_t reg, uint16_t *out)
{
    int lo = i2cReadByteData(g_i2c_handle, reg);
    if (lo < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, lo);
        return -1;
    }
    int hi = i2cReadByteData(g_i2c_handle, reg + 1);
    if (hi < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg + 1, hi);
        return -1;
    }
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a PPG measurement and read raw IR/RED ADC values            */
/* ------------------------------------------------------------------ */
static int read_si1172_data(uint16_t *ir_raw, uint16_t *red_raw)
{
    /* Trigger a PPG measurement */
    if (si1172_write_reg(SI1172_REG_CMD, SI1172_CMD_PPG) < 0)
        return -1;

    /* Small delay for the measurement to complete */
    gpioDelay(50000);  /* 50 ms */

    /* Read raw IR ADC value (register 0xC3, 16-bit little-endian) */
    if (si1172_read_reg16(SI1172_REG_FIFO_IR, ir_raw) < 0)
        return -1;

    /* Read raw RED ADC value (register 0xC1, 16-bit little-endian) */
    if (si1172_read_reg16(SI1172_REG_FIFO_RED, red_raw) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row                                                    */
/* ------------------------------------------------------------------ */
static void log_data(time_t timestamp, uint16_t ir_raw, uint16_t red_raw,
                     int hr_proxy, int spo2_proxy, int error_flag)
{
    if (g_log_file == NULL)
        return;

    fprintf(g_log_file, "%ld,%u,%u,%d,%d,%d\n",
            (long)timestamp, ir_raw, red_raw, hr_proxy, spo2_proxy, error_flag);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
