        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1172 heart-rate logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ir_raw = 0xFFFF;
        uint16_t red_raw = 0xFFFF;
        int hr_proxy = -1;
        int spo2_proxy = -1;
        int error_flag = 0;

        if (read_si1172_data(&ir_raw, &red_raw) < 0) {
