#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define ADC_CHANNEL 0
#define VREF 3.3
#define MAX_FLOW_RATE 5.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_flow_rate(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    float voltage = (float)adc_value * VREF / 1024.0;
    float flow_rate = (voltage / VREF) * MAX_FLOW_RATE;

    if (flow_rate < 0.0) flow_rate = 0.0;
    if (flow_rate > MAX_FLOW_RATE) flow_rate = MAX_FLOW_RATE;

    return flow_rate;
}

static void log_data(float flow_rate) {
    struct timeval tv;
    struct tm tm_info;
    char timestamp[32];

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, (long)tv.tv_usec, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (L/min)\n");
        fflush(log_file);
    }

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC at extreme (%d). Sensor absent or wiring fault?\n", adc_value);
        }

        float flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < 0.0) {
            fprintf(stderr, "Error: Flow rate conversion failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (flow_rate < 0.0 || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Warning: Flow rate out of plausible range: %.2f L/min\n", flow_rate);
        }

        log_data(flow_rate);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

