#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;
    int32_t t_fine;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;

    usleep(20000); // 20ms conversion time for high precision

    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    raw_pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8);
    raw_temperature = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8);

    // Temperature calculation
    t_fine = (raw_temperature >> 8) * 5 + (raw_temperature & 0xFF);
    *temperature = (float)((t_fine * 5 + 128) >> 8) / 100.0;

    // Pressure calculation
    int32_t p_raw = raw_pressure >> 8;
    int32_t p_lsb = raw_pressure & 0xFF;
    int32_t p_cal = (p_raw * 256) + p_lsb;
    *pressure = (float)p_cal;

    return 0;
}

void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(fp);
}

void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", CSV_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

