#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_MIC1 0
#define ADC_CHANNEL_MIC2 1
#define SAMPLE_RATE 16000
#define DEFAULT_GAIN 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

int main(int argc, char *argv[]) {
    float gain = DEFAULT_GAIN;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Error: Gain must be a positive number\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio... Press Ctrl+C to exit.\n");

    while (running) {
        int val1 = read_adc(ADC_CHANNEL_MIC1);
        int val2 = read_adc(ADC_CHANNEL_MIC2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error: ADC read failed, skipping sample\n");
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        int diff = val1 - (int)(val2 * gain);
        printf("%d\n", diff);
        fflush(stdout);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    printf("\nExiting...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

