            }
            retries++;
            usleep(10000);
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: failed to read ADC after %d retries\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (raw_adc > 1023) {
            fprintf(stderr, "Warning: ADC value out of range (%d). Retrying...\n", raw_adc);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (float)raw_adc * 3.3f / 1024.0f;
        float compensated_voltage = calculate_compensated_voltage(raw_adc, ambient_temp);
        int flame_detected = detect_flame(compensated_voltage);

        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        if (flame_detected) {
