#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define LED_GPIO       17
#define WATER_HIGH     75.0
#define WATER_LOW      70.0
#define SAMPLE_PERIOD  5          /* seconds */
#define SPI_XFER_BYTES 3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_json_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from MCP3008 (single-ended, 10-bit)                  */
/* Returns 0-1023 on success, -1 on SPI error                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       Start bit
     *   tx[1] = 0x80 | (channel << 4)      SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       Padding (clocks out low 2 bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[SPI_XFER_BYTES] = { 0x01,
                                (char)(0x80 | (channel << 4)),
                                0x00 };
    char rx[SPI_XFER_BYTES] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, SPI_XFER_BYTES);
    if (ret != SPI_XFER_BYTES) {
        fprintf(stderr, "spiXfer failed: returned %d (pigpio error %d)\n",
                ret, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ------------------------------------------------------------------ */
/* Convert 10-bit ADC value to percentage (0-100)                      */
/* ------------------------------------------------------------------ */
static float adc_to_percentage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Append one JSON entry and flush; keep file a valid JSON array       */
/* ------------------------------------------------------------------ */
static void log_water_level(float percentage)
{
    if (g_json_file == NULL) {
        fprintf(stderr, "JSON file not open\n");
        return;
    }

    /* If file is empty, write a square-bracket array opener */
    long pos = ftell(g_json_file);
    if (pos == 0) {
        fprintf(g_json_file, "[\n");
    } else if (pos > 0) {
        /* Back up to overwrite the trailing ']' of the previous entry */
        fseek(g_json_file, -1, SEEK_CUR);
        fprintf(g_json_file, ",\n");
    }

    /* ISO 8601 timestamp with milliseconds */
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        ts.tv_sec  = time(NULL);
        ts.tv_nsec = 0;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_json_file,
            "  {\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f}\n",
            timestamp, ts.tv_nsec / 1000000L, percentage);

    fflush(g_json_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file != NULL) {
        fflush(g_json_file);
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO ---------------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: pigpio error %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- JSON file --------------------------------------------------- */
    g_json_file = fopen("water_levels.json", "a");
    if (g_json_file == NULL) {
        perror("fopen water_levels.json");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write array closer if file was empty */
    long pos = ftell(g_json_file);
    if (pos == 0) {
        fprintf(g_json_file, "]\n");
        fflush(g_json_file);
    }

    /* --- Signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int led_state = 0;          /* 0 = OFF, 1 = ON */

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error — log and keep going */
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(100000);  /* 100 ms */
            continue;
        }

        float percentage = adc_to_percentage(adc_value);

        printf("Water level: %.2f%% (ADC: %d)\n", percentage, adc_value);
        log_water_level(percentage);

        /* Hysteresis LED control */
        if (percentage > WATER_HIGH && led_state == 0) {
            gpioWrite(LED_GPIO, 1);
            led_state = 1;
            printf("  -> LED ON (water level high)\n");
        } else if (percentage < WATER_LOW && led_state == 1) {
            gpioWrite(LED_GPIO, 0);
            led_state = 0;
            printf("  -> LED OFF (water level normal)\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- Graceful shutdown ------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

