float convert_adc_to_flow(int adc_value);
int log_data(float flow_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI protocol for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x08) | channel << 4
    // Byte 2: Dummy byte (0x00)
    char spi_tx_buf[3] = {0x01, (char)(0x08 | (channel << 4)), 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits (masked with 0x03)
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

