    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,FlowRate(LPM)\n") < 0) {
            fprintf(stderr, "Error: Failed to write CSV header\n");
            fclose(log_file);
            spiClose(spi_handle);
            gpioTerminate();
            return -1;
        }
        fflush(log_file);
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

