    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert ADC value to flow rate
        float flow_rate = convert_adc_to_flow(adc_value);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
