#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTPRC_PATH "/etc/msmtprc"
#define LOG_FILE "plant_data.txt"
#define SPI_BAUD_RATE 500000
#define SPI_FLAGS 0

typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    double moisture_threshold;
    int logging_frequency;
    char *recipient_email;
    char *msmtprc_path;
} Config;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static Config *config = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw == min_raw) return 0.0;
    double pct = ((double)(raw_value - min_raw) / (double)(max_raw - min_raw)) * 100.0;
    if (pct < 0.0) pct = 0.0;
    if (pct > 100.0) pct = 100.0;
    return pct;
}

static void log_data(double moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

static void send_email_alert(double moisture_percentage) {
    char body[256];
    snprintf(body, sizeof(body),
             "Subject: Soil Moisture Alert\n\nSoil moisture is below threshold!\nCurrent moisture: %.2f%%",
             moisture_percentage);

    char command[512];
    snprintf(command, sizeof(command),
             "msmtp -t %s < /dev/stdin", config->recipient_email);

    FILE *pipe = popen(command, "w");
    if (!pipe) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return;
    }

    if (fputs(body, pipe) == EOF) {
        fprintf(stderr, "Error: Failed to write to msmtp pipe\n");
    }

    int status = pclose(pipe);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed\n");
        return;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    free(config->recipient_email);
    free(config->msmtprc_path);
    free(config);
    config = NULL;
}

int main(int argc, char *argv[]) {
    config = (Config *)malloc(sizeof(Config));
    if (!config) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return 1;
    }
    memset(config, 0, sizeof(Config));

    config->spi_channel = DEFAULT_SPI_CHANNEL;
    config->adc_channel = DEFAULT_ADC_CHANNEL;
    config->min_raw = DEFAULT_MIN_RAW;
    config->max_raw = DEFAULT_MAX_RAW;
    config->moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    config->logging_frequency = DEFAULT_LOGGING_FREQUENCY;
    config->recipient_email = strdup(DEFAULT_RECIPIENT_EMAIL);
    config->msmtprc_path = strdup(DEFAULT_MSMTPRC_PATH);

    if (!config->recipient_email || !config->msmtprc_path) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(config->recipient_email);
        free(config->msmtprc_path);
        free(config);
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:f:e:r:h")) != -1) {
        switch (opt) {
            case 's': config->spi_channel = atoi(optarg); break;
            case 'a': config->adc_channel = atoi(optarg); break;
            case 'm': config->min_raw = atoi(optarg); break;
            case 'M': config->max_raw = atoi(optarg); break;
            case 't': config->moisture_threshold = atof(optarg); break;
            case 'f': config->logging_frequency = atoi(optarg); break;
            case 'e': config->recipient_email = strdup(optarg); break;
            case 'r': config->msmtprc_path = strdup(optarg); break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t threshold] [-f frequency] [-e recipient] [-r msmtprc]\n", argv[0]);
                return 1;
        }
    }

    if (config->logging_frequency <= 0) {
        fprintf(stderr, "Error: Logging frequency must be positive\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        free(config->recipient_email);
        free(config->msmtprc_path);
        free(config);
        return 1;
    }

    spi_handle = spiOpen(config->spi_channel, SPI_BAUD_RATE, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        free(config->recipient_email);
        free(config->msmtprc_path);
        free(config);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_mcp3008(config->adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n",
                    config->logging_frequency);
            sleep(config->logging_frequency);
            continue;
        }

        double moisture_percentage = calculate_moisture_percentage(raw_value, config->min_raw, config->max_raw);

        log_data(moisture_percentage);

        if (moisture_percentage < config->moisture_threshold) {
            send_email_alert(moisture_percentage);
        }

        sleep(config->logging_frequency);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

