        fprintf(stderr, "Error: Logging frequency must be positive\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        free(config->recipient_email);
        free(config->msmtprc_path);
        free(config);
        return 1;
    }

