    printf("Plant monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_mcp3008(config->adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n",
                    config->logging_frequency);
            sleep(config->logging_frequency);
            continue;
        }

        double moisture_percentage = calculate_moisture_percentage(raw_value, config->min_raw, config->max_raw);

        log_data(moisture_percentage);

        if (moisture_percentage < config->moisture_threshold) {
