#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* KY-036 A0 on MCP3008 CH0 */
#define LOG_FILE       "soil_moisture.log"
#define DEFAULT_SAMPLE_INTERVAL 1  /* seconds */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended)                     */
/* Returns 0-1023 on success, -1 on SPI error                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC (0-1023) to moisture percentage [0,100]             */
/* ------------------------------------------------------------------ */
static float calculate_moisture_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Log one sample with ISO-8601 timestamp                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, float moisture_pct)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", ts, adc_value, moisture_pct) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval '%s'; using default %d s\n",
                    argv[1], DEFAULT_SAMPLE_INTERVAL);
            sample_interval = DEFAULT_SAMPLE_INTERVAL;
        }
    }

    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ----------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started.\n");
    printf("  SPI channel : %d @ %d Hz\n", SPI_CHANNEL, SPI_SPEED);
    printf("  ADC channel : %d\n", ADC_CHANNEL);
    printf("  Log file    : %s\n", LOG_FILE);
    printf("  Sample rate : %d s\n", sample_interval);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else {
            float moisture_pct = calculate_moisture_percentage(adc_value);
            log_data(g_log_file, adc_value, moisture_pct);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture_pct);
        }

        /* sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sample_interval * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

