#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 CH0
#define VREF 3.3            // Reference voltage
#define MIN_PRESSURE 10.0   // kPa
#define MAX_PRESSURE 150.0  // kPa
#define MIN_VOLTAGE 0.5     // V
#define MAX_VOLTAGE 4.5     // V
#define SAMPLE_INTERVAL 1   // Seconds
#define MAX_CONSECUTIVE_ERRORS 10

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double voltage_to_pressure(double voltage);
void log_data(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Read ADC value from MCP3008 via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI protocol: 3 bytes
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Dummy (0x00)
    char tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx_buf[1] contains the two most significant bits (masked with 0x03)
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Convert voltage to pressure (kPa)
double voltage_to_pressure(double voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage %.3fV outside valid range [%.1f, %.1f]V\n",
                voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0;
    }

    // Linear interpolation: pressure = (voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE
    double pressure = ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
    return pressure;
}

// Log data with ISO-8601 timestamp
void log_data(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
