    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI Channel: %d, ADC Channel: %d, VREF: %.1fV\n", SPI_CHANNEL, ADC_CHANNEL, VREF);
    printf("Press Ctrl+C to exit\n\n");

    int consecutive_errors = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read ADC value (consecutive errors: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: Max consecutive SPI errors reached. Aborting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        // Validate ADC range (10-bit: 0-1023)
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: Invalid ADC value %d (out of 10-bit range)\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert to voltage
        double voltage = (double)adc_value / 1023.0 * VREF;

        // Check for sensor-absent conditions (voltage stuck at 0V or 3.3V)
        if (voltage < 0.01 || voltage > (VREF - 0.01)) {
            fprintf(stderr, "Warning: Sensor-absent condition detected (voltage %.3fV). Check wiring.\n", voltage);
            log_data(-1.0); // Log error indicator
        } else {
            // Convert to pressure
            double pressure = voltage_to_pressure(voltage);
            if (pressure < 0) {
                log_data(-1.0); // Log error indicator
            } else {
                log_data(pressure);
            }
        }

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

