#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define MCP3008_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value, int min_adc, int max_adc) {
    if (max_adc == min_adc) return 0.0f;
    float pct = ((float)(adc_value - min_adc) / (float)(max_adc - min_adc)) * 100.0f;
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void log_moisture_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
    fflush(stdout);
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    /* Open GPIO chip for manual CS control (SPI0 CE0 is GPIO8) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open gpiochip0");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, 8); /* GPIO8 = SPI0 CE0 */
    if (cs_line == NULL) {
        perror("Failed to get GPIO8 line");
        goto cleanup;
    }

    /* Request CS line as output, default HIGH (inactive) */
    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup;
    }

    printf("Soil Moisture Sensor Data Acquisition (libgpiod + spidev)\n");
    printf("SPI: %s @ %d Hz, Mode %d, %d bits\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS_PER_WORD);
    printf("Sensor: SEN0193 on MCP3008 CH0 | Dry=%d, Wet=%d\n", MIN_ADC_VALUE, MAX_ADC_VALUE);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        /* Assert CS low */
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to assert CS low");
            break;
        }

        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        /* Deassert CS high */
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to deassert CS high");
            break;
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read error\n");
            break;
        }

        /* Sensor-absent / bus-error detection: ADC stuck at 0 or 1023 */
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc_value);
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, MIN_ADC_VALUE, MAX_ADC_VALUE);
        log_moisture_data(moisture_percentage);

        /* Sleep in 1-second increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

