    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    /* Open GPIO chip for manual CS control (SPI0 CE0 is GPIO8) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open gpiochip0");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, 8); /* GPIO8 = SPI0 CE0 */
    if (cs_line == NULL) {
        perror("Failed to get GPIO8 line");
        goto cleanup;
    }

    /* Request CS line as output, default HIGH (inactive) */
    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup;
    }

    printf("Soil Moisture Sensor Data Acquisition (libgpiod + spidev)\n");
    printf("SPI: %s @ %d Hz, Mode %d, %d bits\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS_PER_WORD);
    printf("Sensor: SEN0193 on MCP3008 CH0 | Dry=%d, Wet=%d\n", MIN_ADC_VALUE, MAX_ADC_VALUE);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        /* Assert CS low */
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to assert CS low");
            break;
        }

        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        /* Deassert CS high */
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to deassert CS high");
            break;
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read error\n");
            break;
        }

        /* Sensor-absent / bus-error detection: ADC stuck at 0 or 1023 */
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc_value);
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, MIN_ADC_VALUE, MAX_ADC_VALUE);
        log_moisture_data(moisture_percentage);

        /* Sleep in 1-second increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

