    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = read_mcp3008(fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Map 10-bit ADC (0-1023) to moisture percentage (0-100) */
        float moisture_percentage = ((float)adc_value / 1023.0f) * 100.0f;

        /* Clamp to valid range */
        if (moisture_percentage < 0.0f) moisture_percentage = 0.0f;
        if (moisture_percentage > 100.0f) moisture_percentage = 100.0f;

        printf("Moisture: %.2f%% (ADC: %d)\n", moisture_percentage, adc_value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

