        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (program_running) {
        float voltages[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(spi_fd, cs_line, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            voltages[i] = convert_adc_to_voltage(adc_value, VREF);
        }

        if (!error) {
            if (log_data(fp, voltages) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

