#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL_MS 5000
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int spi_handle = -1;
static CircularBuffer log_buffer;
static volatile sig_atomic_t running = 1;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, int moisture_level, int pump_state) {
    time_t now = time(NULL);
    cb->entries[cb->head].timestamp = now;
    cb->entries[cb->head].moisture_level = moisture_level;
    cb->entries[cb->head].pump_state = pump_state;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void print_circular_buffer(const CircularBuffer *cb) {
    printf("\n--- Log Buffer ---\n");
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&cb->entries[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str, cb->entries[idx].moisture_level,
               cb->entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End Log Buffer ---\n\n");
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void control_pump(int moisture_level) {
    static int pump_state = 0;

    if (moisture_level < MOISTURE_LOW_THRESHOLD && !pump_state) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Moisture %d < %d: turning pump ON\n", moisture_level, MOISTURE_LOW_THRESHOLD);
        } else {
            fprintf(stderr, "Failed to turn pump ON\n");
        }
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Moisture %d > %d: turning pump OFF\n", moisture_level, MOISTURE_HIGH_THRESHOLD);
        } else {
            fprintf(stderr, "Failed to turn pump OFF\n");
        }
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Error reading moisture sensor, skipping cycle\n");
        return;
    }

    control_pump(moisture_level);
    add_to_circular_buffer(&log_buffer, moisture_level, gpioRead(PUMP_GPIO));
    print_circular_buffer(&log_buffer);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_circular_buffer(&log_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

