#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define FIFO_DEPTH 16

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) return -1;
    *val = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, int len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char data_buf[32];
    if (i2cReadDevice(i2c_handle, data_buf, len) != len) return -1;
    for (int i = 0; i < len; i++) buf[i] = (uint8_t)data_buf[i];
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to reset MODE_CONFIG\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x0F) != 0) return -1;

    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) != 0) {
        fprintf(stderr, "Error: Failed to set SpO2 mode\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to set SPO2_CONFIG\n");
        return -1;
    }

    if (i2c_write_reg(REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_FIFO_DATA, buf, 6) != 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static int process_data(uint32_t *red, uint32_t *ir, int *spo2, int *hr) {
    if (FIFO_DEPTH < 16) return -1;

    uint32_t red_sum = 0, ir_sum = 0;
    for (int i = 0; i < FIFO_DEPTH; i++) {
        int idx = (FIFO_DEPTH + i - 1) % FIFO_DEPTH;
        red_sum += red[idx];
        ir_sum += ir[idx];
    }

    if (red_sum == 0 || ir_sum == 0) return -1;

    double red_avg = (double)red_sum / FIFO_DEPTH;
    double ir_avg = (double)ir_sum / FIFO_DEPTH;

    double ratio = ir_avg / red_avg;
    double spo2 = 110.0 - 25.0 * ratio;
    if (spo2 > 100) spo2 = 100;
    if (spo2 < 70) spo2 = 70;

    static uint32_t ir_history[FIFO_DEPTH];
    static int hist_idx = 0;
    static uint32_t last_peak_time = 0;
    static int peak_count = 0;

    for (int i = 0; i < FIFO_DEPTH; i++) ir_history[i] = 0;

    uint32_t now = gpioTick() / 1000;
    if (ir_avg > 500 && ir_avg > ir_history[hist_idx]) {
        if (now - last_peak_time > 500) {
            last_peak_time = now;
            peak_count++;
        }
    }
    ir_history[hist_idx] = ir_avg;
    hist_idx = (hist_idx + 1) % FIFO_DEPTH;

    int peaks = peak_count;
    if (peaks == 0) { *hr = 0; return -1; }
    double period_us = (double)(now - last_peak_time) / peaks;
    if (period_us > 0) {
        *hr = (int)(60.0 / period_us);
    }

    *spo2 = (int)spo2;
    *hr = (int)(*hr > 0 ? *hr : 0);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", MAX30102_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() != 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MAX30102 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t red, ir;
        if (read_fifo(&red, &ir) != 0) {
            fprintf(stderr, "Error: Failed to read FIFO data\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int spo2, hr;
        if (process_data(&red, &ir, &spo2, &hr) != 0) {
            fprintf(stderr, "Error: Data processing failed\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (spo2 < 95 || hr > 100) {
            char msg[128];
            snprintf(msg, sizeof(msg), "SpO2: %d%%, HR: %d BPM", spo2, hr);
            log_event(msg);
        }

        printf("SpO2: %d%%, HR: %d BPM\n", spo2, hr);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

