#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000   /* 1 MHz */
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define BUZZER_GPIO    24
#define THRESHOLD      500
#define SAMPLE_US      500000    /* 500 ms */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (don't-care, clocks out low 2 bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer pin --- */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl+C to exit.\n");

    int buzzer_on = 0;

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying in 500 ms...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        printf("ADC Value: %d\n", adc_value);

        if (adc_value >= THRESHOLD && !buzzer_on) {
            if (gpioWrite(BUZZER_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn buzzer ON\n");
            } else {
                buzzer_on = 1;
                printf("Buzzer ON\n");
            }
        } else if (adc_value < THRESHOLD && buzzer_on) {
            if (gpioWrite(BUZZER_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn buzzer OFF\n");
            } else {
                buzzer_on = 0;
                printf("Buzzer OFF\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (buzzer_on) {
        gpioWrite(BUZZER_GPIO, 0);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

