#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(int sensor1, int sensor2, int sensor3) {
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    if (!file_exists) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs0 = gpiod_chip_get_line(chip, CS0_PIN);
    struct gpiod_line *cs1 = gpiod_chip_get_line(chip, CS1_PIN);
    struct gpiod_line *cs2 = gpiod_chip_get_line(chip, CS2_PIN);

    if (!cs0 || !cs1 || !cs2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs0, "mcp3008_cs0", 1) < 0 ||
        gpiod_line_request_output(cs1, "mcp3008_cs1", 1) < 0 ||
        gpiod_line_request_output(cs2, "mcp3008_cs2", 1) < 0) {
        fprintf(stderr, "Failed to request CS lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Soil Moisture Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1 = read_mcp3008(spi_fd, cs0, 0);
        int sensor2 = read_mcp3008(spi_fd, cs1, 0);
        int sensor3 = read_mcp3008(spi_fd, cs2, 0);

        if (log_data(sensor1, sensor2, sensor3) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    gpiod_line_release(cs0);
    gpiod_line_release(cs1);
    gpiod_line_release(cs2);
    gpiod_chip_close(chip);
    close(spi_fd);

    printf("Resources released. Exiting.\n");
    return 0;
}

