#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define DRY_ADC_VALUE 200
#define WET_ADC_VALUE 800
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d), pigpio error %d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(100000);
    }
    return -1;
}

static double calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return 0.0;
    double pct = 100.0 - ((double)(adc_value - DRY_ADC_VALUE) /
                          (double)(WET_ADC_VALUE - DRY_ADC_VALUE)) * 100.0;
    if (pct < 0.0) pct = 0.0;
    if (pct > 100.0) pct = 100.0;
    return pct;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
        log_message("ERROR: Failed to write pump GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "activated" : "deactivated");
    log_message(msg);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                DEFAULT_THRESHOLD = atof(optarg);
                break;
            case 'd':
                DEFAULT_DURATION = atoi(optarg);
                break;
            case 's':
                DEFAULT_SLEEP_INTERVAL = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            log_message("ERROR: ADC read failed");
            sleep(DEFAULT_SLEEP_INTERVAL);
            continue;
        }

        double moisture = calculate_moisture_percentage(adc_value);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.2f%% (ADC: %d)", moisture, adc_value);
        log_message(msg);

        if (moisture < DEFAULT_THRESHOLD) {
            control_pump(1);
            sleep(DEFAULT_DURATION);
            control_pump(0);
        }
        sleep(DEFAULT_SLEEP_INTERVAL);
    }

    log_message("Irrigation system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

