        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 returns the result of the *previous* conversion on the
     * next read.  Do a dummy read to discard the stale byte and start
     * with a fresh sample.
     */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0)
        goto cleanup;

    printf("PCF8591 AIN0 monitoring started (addr 0x%02X on %s). Ctrl-C to exit.\n",
           PCF8591_ADDR, I2C_BUS);

    while (g_running) {
        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0)
            goto cleanup;

        printf("AIN0: %u\n", (unsigned)value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

