#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* ---------------- Constants ---------------- */
#define I2C_BUS          1
#define ADS1115_ADDR     0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01
#define ADS1115_CFG_BASE 0x8000  /* AIN0 single-ended, PGA 4.096 V */
#define ADS1115_CFG_DR   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE 0x0003  /* Disable comparator */
#define ADS1115_CFG      (ADS1115_CFG_BASE | ADS1115_CFG_DR | ADS1115_CFG_CQUE)
#define GPIO_SHUTDOWN    27
#define BUFFER_SIZE      10
#define SAMPLE_PERIOD_US 1000000  /* 1 Hz */
#define THRESHOLD_GAUSS  500.0f
#define VCC             3.3f
#define ZERO_GAUSS_V    2.5f
#define SENSITIVITY_V_G 0.0014f   /* mV/Gauss at 3.3 V */
#define ADC_MAX         32767.0f  /* 16-bit signed, PGA 4.096 V */

/* ---------------- Data Structures ---------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

/* ---------------- Globals ---------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_gpio_setup  = 0;
static int      g_pigpio_inited = 0;
static CircularBuffer g_mag_buffer;

/* ---------------- Prototypes ---------------- */
static int  init_i2c(void);
static int  read_ads1115(int16_t *raw);
static float raw_to_gauss(int16_t raw);
static void buffer_add(CircularBuffer *cb, float gauss);
static float buffer_avg(const CircularBuffer *cb);
static void signal_handler(int sig);
static void cleanup(void);

/* ---------------- Implementation ---------------- */

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %d",
               I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }
    /* Write config: AIN0 single-ended, PGA 4.096 V, 128 SPS, comparator disabled */
    uint16_t cfg = ADS1115_CFG;
    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CFG;
    cfg_buf[1] = (char)(cfg >> 8);
    cfg_buf[2] = (char)(cfg & 0xFF);
    if (i2cWriteDevice(g_i2c_handle, cfg_buf, 3) < 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw) {
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "i2cWriteDevice (reg select) failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "i2cReadDevice (conversion) failed");
        return -1;
    }
    *raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

static float raw_to_gauss(int16_t raw) {
    float voltage = ((float)raw / ADC_MAX) * VCC;
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > VCC)  voltage = VCC;
    float gauss = (voltage - ZERO_GAUSS_V) / SENSITIVITY_V_G;
    return gauss;
}

static void buffer_add(CircularBuffer *cb, float gauss) {
    cb->buffer[cb->head] = gauss;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_avg(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_gpio_setup) {
        gpioWrite(GPIO_SHUTDOWN, 0);
        g_gpio_setup = 0;
    }
    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = 0;
    }
    closelog();
}

int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    g_pigpio_inited = 1;

    if (init_i2c() != 0) {
        syslog(LOG_ERR, "ADS1115 init failed; aborting");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", GPIO_SHUTDOWN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    g_gpio_setup = 1;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall monitor started (ADS1115 @ 0x%02X, GPIO%d shutdown)",
           ADS1115_ADDR, GPIO_SHUTDOWN);

    while (g_running) {
        int16_t raw;
        if (read_ads1115(&raw) != 0) {
            syslog(LOG_ERR, "ADC read failed; skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        buffer_add(&g_mag_buffer, gauss);
        float avg = buffer_avg(&g_mag_buffer);

        syslog(LOG_DEBUG, "raw=%d  V=%.3f  G=%.2f  avg=%.2f",
               raw, raw * (VCC / ADC_MAX), gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_CRIT, "Threshold exceeded (%.2f G > %.1f G)", avg, THRESHOLD_GAUSS);
            if (gpioWrite(GPIO_SHUTDOWN, 1) != 0)
                syslog(LOG_ERR, "gpioWrite(%d, HIGH) failed", GPIO_SHUTDOWN);
            else
                syslog(LOG_INFO, "Motor shutdown signal sent (GPIO%d HIGH)", GPIO_SHUTDOWN);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

