#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10
#define READ_INTERVAL 60
#define LOG_FILE "watering_events.txt"
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Warning: ADC value out of range: %d\n", adc_value);
                return -1;
            }
            return adc_value;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d, ret=%d)\n", attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(100000);
    }
    return -1;
}

static void log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Moisture: %d\n", timestamp, moisture_level);
        fflush(log_file);
    }
    printf("%s, Moisture: %d\n", timestamp, moisture_level);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitor started. Threshold=%d, Watering=%ds, Read=%ds\n",
           MOISTURE_THRESHOLD, WATERING_DURATION, READ_INTERVAL);

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Error: Failed to read moisture sensor\n");
            break;
        }

        log_event(moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d). Watering...\n", MOISTURE_THRESHOLD);
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
                break;
            }

            time_t start = time(NULL);
            while (running && (time(NULL) - start) < WATERING_DURATION) {
                gpioDelay(100000);
            }

            if (gpioWrite(PUMP_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump\n");
                break;
            }
            printf("Watering complete.\n");
        }

        if (running) {
            for (int i = 0; i < READ_INTERVAL && running; i++) {
                gpioDelay(1000000);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

