        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitor started. Threshold=%d, Watering=%ds, Read=%ds\n",
           MOISTURE_THRESHOLD, WATERING_DURATION, READ_INTERVAL);

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Error: Failed to read moisture sensor\n");
            break;
        }

        log_event(moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d). Watering...\n", MOISTURE_THRESHOLD);
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
                break;
            }

            time_t start = time(NULL);
            while (running && (time(NULL) - start) < WATERING_DURATION) {
                gpioDelay(100000);
            }

            if (gpioWrite(PUMP_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump\n");
                break;
            }
            printf("Watering complete.\n");
        }

        if (running) {
            for (int i = 0; i < READ_INTERVAL && running; i++) {
                gpioDelay(1000000);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

