#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

/*
 * Raspberry Pi 4 Model B – YL-83 rain sensor via MCP3008 ADC
 *
 * Wiring:
 *   YL-83 analog out  -> MCP3008 CH0
 *   MCP3008 VDD       -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF      -> 3.3 V (Pi pin 1)
 *   MCP3008 AGND/DGND -> GND  (Pi pin 6)
 *   MCP3008 CLK       -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT      -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN       -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS/SHDN   -> GPIO8  (SPI0 CE0)
 *
 * SPI: channel 0 (CE0), mode 0, 1 MHz, 8-bit words.
 * ADC is single-ended; full-scale = 1023 for 3.3 V supply.
 */

#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define SAMPLE_US      1000000    /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure. */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Map 10-bit ADC value to rainfall intensity 0-10. */
static int adc_to_intensity(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    int intensity = (int)((float)adc_value / (float)ADC_MAX * 10.0f);
    if (intensity < 0)   intensity = 0;
    if (intensity > 10)  intensity = 10;
    return intensity;
}

/* ------------------------------------------------------------------ */
static void log_data(int adc_value, int intensity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    printf("[%s] ADC: %4d  Intensity: %2d/10\n", ts, adc_value, intensity);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Rain sensor logging started. Press Ctrl+C to exit.\n");
    printf("SPI channel %d, ADC channel %d, %d Hz, mode 0.\n",
           SPI_CHANNEL, ADC_CHANNEL, SPI_SPEED);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; will retry next cycle.\n");
        } else {
            int intensity = adc_to_intensity(adc_value);
            log_data(adc_value, intensity);
        }

        /* sleep SAMPLE_US; pigpio's gpioDelay is microseconds */
        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup ---------------------------------------------------- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

