#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0 (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)

#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }
    return 0;
}

static int read_conversion(int16_t *value) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error selecting conversion register\n");
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register\n");
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double read_magnetic_field(void) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS;

    if (write_config(config) < 0) {
        return -1.0;
    }

    gpioDelay(8000);

