#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD 30.0
#define MOISTURE_HYSTERESIS 35.0
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc) {
    if (adc < 0 || adc > 1023) return -1.0f;
    return 100.0f - ((float)adc / 1023.0f) * 100.0f;
}

static void set_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", PUMP_GPIO);
    }
}

static void mqtt_connect_cb(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP_CONTROL, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to pump_control topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_cb(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_message_cb(struct mosquitto *m, void *userdata, const struct mosquitto_message *msg) {
    (void)m; (void)userdata;
    if (msg->payloadlen > 0) {
        char payload[32] = { 0 };
        int len = msg->payloadlen < (int)sizeof(payload) - 1 ? msg->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, msg->payload, len);

        if (strcmp(msg->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                syslog(LOG_INFO, "Received pump_on command");
                set_pump(1);
            } else if (strcmp(payload, "pump_off") == 0) {
                syslog(LOG_INFO, "Received pump_off command");
                set_pump(0);
            } else {
                syslog(LOG_WARNING, "Unknown pump command: %s", payload);
            }
        }
    }
}

static void publish_moisture(float moisture) {
    char payload[32];
    int len = snprintf(payload, sizeof(payload), "%.2f", moisture);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Moisture formatting failed");
        return;
    }
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, (int)len, payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture data");
    }
}

