    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    set_pump(0);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_cb);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_cb);
    mosquitto_message_callback_set(mosq, mqtt_message_cb);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed; skipping cycle");
        } else {
            float moisture = adc_to_moisture(adc);
            if (moisture < 0.0f) {
                syslog(LOG_ERR, "Sensor out of range (ADC=%d)", adc);
            } else {
                syslog(LOG_INFO, "Moisture: %.2f%%", moisture);
                publish_moisture(moisture);

                if (moisture < MOISTURE_THRESHOLD) {
                    set_pump(1);
                } else if (moisture > MOISTURE_HYSTERESIS) {
                    set_pump(0);
                }
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    set_pump(0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

