        int adc[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(i);
            if (adc[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
        }

        if (error) {
            fprintf(stderr, "Aborting sample due to SPI error\n");
            break;
        }

        float v0 = adc_to_voltage(adc[0]);
        float v1 = adc_to_voltage(adc[1]);
        float v2 = adc_to_voltage(adc[2]);

        if (log_data(v0, v1, v2) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        for (int s = 0; s < SAMPLE_INTERVAL_SEC && running; s++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return 0;
}

