#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define NOISE_THRESHOLD 500
#define SAMPLE_DELAY_US 10000
#define LOG_FILE "vibration_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;
    if (channel < 0 || channel > 7) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Noise level: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, adc_value);
    }
    fclose(fp);
}

static void control_motors(int adc_value) {
    if (adc_value > NOISE_THRESHOLD) {
        int duty = (adc_value - NOISE_THRESHOLD) * 255 / (1023 - NOISE_THRESHOLD);
        if (duty > 255) duty = 255;
        if (duty < 0) duty = 0;

        if (gpioPWM(MOTOR1_GPIO, duty) < 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", MOTOR1_GPIO);
        }
        if (gpioPWM(MOTOR2_GPIO, duty) < 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", MOTOR2_GPIO);
        }
        log_event(adc_value);
    } else {
        gpioPWM(MOTOR1_GPIO, 0);
        gpioPWM(MOTOR2_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        gpioPWM(MOTOR1_GPIO, 0);
        gpioPWM(MOTOR2_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    printf("Vibration control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        control_motors(adc_value);
        usleep(SAMPLE_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    gpioTerminate();
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

