#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES2 0x11
#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd, float *lux) {
    uint8_t cmd = BH1750_CONT_HRES2;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(180000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -2;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_adc(int fd, int channel, int *value) {
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -3;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

