        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    fprintf(csv_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (running) {
        int sound_level = -1;
        float light_level = -1.0f;
        int err = 0;

        if (read_adc(spi_fd, ADC_CHANNEL, &sound_level) != 0) {
            err = -3;
        }

        if (read_bh1750(i2c_fd, &light_level) != 0) {
            err = -2;
        }

        log_data(csv_fp, sound_level, light_level, err);
        sleep(SAMPLE_INTERVAL);
    }

    if (csv_fp) fclose(csv_fp);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

