#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_S 1
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    } else {
        fprintf(fp, "[timestamp error] %s\n", event);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_sensor", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int distance_cm = (int)(((float)adc_value / 1023.0f) * 10.0f);
        if (distance_cm < 0) distance_cm = 0;

        printf("Distance: %d cm\n", distance_cm);

        if (distance_cm < PROXIMITY_THRESHOLD) {
            printf("Proximity detected! Energizing relay.\n");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("Failed to energize relay");
            } else {
                log_event("Door opened");
            }

            sleep(DEBOUNCE_DELAY_S);

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("Failed to de-energize relay");
            } else {
                log_event("Door closed");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    printf("\nCleaning up...\n");
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

