#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define NUM_SENSORS 3
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_valve(int opening_percent) {
    if (opening_percent < 0) opening_percent = 0;
    if (opening_percent > 100) opening_percent = 100;
    int duty = (opening_percent * PWM_RANGE) / 100;
    if (gpioPWM(VALVE_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static int log_data(int sensor_values[NUM_SENSORS], float avg, int opening) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor: %d, %d, %d, %d, Avg: %.2f, Opening: %d%%\n",
                timestamp,
                sensor_values[0], sensor_values[1], sensor_values[2], avg, opening) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    int sensor_values[NUM_SENSORS];
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int valid_readings = 0;

        for (i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] >= 0) {
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading sensor %d, skipping\n", i);
            }
        }

        if (valid_readings == 0) {
            fprintf(stderr, "No valid sensor readings, skipping cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float avg = 0.0f;
        for (i = 0; i < NUM_SENSORS; i++) {
            if (sensor_values[i] >= 0) {
                avg += (float)sensor_values[i];
            }
        }
        avg /= (float)valid_readings;

        int opening = 100 - (int)((avg / 1023.0f) * 100.0f);
        if (opening < 0) opening = 0;
        if (opening > 100) opening = 100;

        if (control_valve(opening) != 0) {
            fprintf(stderr, "Error controlling valve\n");
        }

        if (log_data(sensor_values, avg, opening) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

