#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int delay_us = RETRY_DELAY_BASE_US * (1 << attempt);
        if (delay_us > 100000) delay_us = 100000;

        gpioDelay(delay_us);

        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "ADC value out of range: %d\n", adc_value);
                return -1;
            }
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, result);
    }
    return -1;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(moisture_percentage);
            printf("Moisture: %.2f%% (ADC: %d)\n", moisture_percentage, adc_value);
        }
        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

