#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define CONFIG_FILE "theremin_config.txt"
#define DEFAULT_TRIG_PIN 23
#define DEFAULT_ECHO_PIN 24
#define DEFAULT_PWM_PIN 18
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000
#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define PWM_PERIOD_NS 10000000  // 10ms period for 100Hz base
#define SPI_BITS 8
#define SPI_SPEED_HZ 1000000

static volatile sig_atomic_t running = 1;
static FILE *config_file = NULL;

struct config {
    int trig_pin;
    int echo_pin;
    int pwm_pin;
    char spi_device[64];
    int spi_speed;
};

static struct config config_data = {
    .trig_pin = DEFAULT_TRIG_PIN,
    .echo_pin = DEFAULT_ECHO_PIN,
    .pwm_pin = DEFAULT_PWM_PIN,
    .spi_device = DEFAULT_SPI_DEVICE,
    .spi_speed = DEFAULT_SPI_SPEED
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void save_config() {
    if (config_file) {
        fflush(config_file);
        fclose(config_file);
        config_file = NULL;
    }
    config_file = fopen(CONFIG_FILE, "w");
    if (!config_file) {
        perror("fopen config write");
        return;
    }
    fprintf(config_file, "%d %d %d %s %d\n",
            config_data.trig_pin, config_data.echo_pin, config_data.pwm_pin,
            config_data.spi_device, config_data.spi_speed);
    fclose(config_file);
    config_file = NULL;
}

static void load_config() {
    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) return;
    int pins[3], speed;
    char dev[64] = {0};
    if (fscanf(config_file, "%d %d %d %63[^\n] %d",
               &pins[0], &pins[1], &pins[2], dev, &speed) == 5) {
        config_data.trig_pin = pins[0];
        config_data.echo_pin = pins[1];
        config_data.pwm_pin = pins[2];
        strncpy(config_data.spi_device, dev, sizeof(config_data.spi_device) - 1);
        config_data.spi_speed = speed;
    }
    fclose(config_file);
    config_file = NULL;
}

static void cleanup() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

static int spi_init() {
    spi_fd = open(config_data.spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI bits");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int speed = config_data.spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int read_photoresistor() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_distance() {
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000 +
                          (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed_us > 30000) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000 +
                          (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed_us > 30000) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    long pulse_us = (now.tv_sec - start.tv_sec) * 1000000 +
                    (now.tv_nsec - start.tv_nsec) / 1000;
    return (pulse_us / 2.0f) / 58.0f;
}

static int map_distance_to_frequency(float distance) {
    if (distance < 0) return MIN_FREQUENCY;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    float freq = MIN_FREQUENCY + (distance - MIN_DISTANCE) *
                 (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return (int)freq;
}

static int set_pwm_frequency(int freq) {
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    int period_ns = 1000000000 / freq;
    int duty_ns = period_ns / 2;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    FILE *p = fopen(path, "w");
    if (!p) { perror("fopen period"); return -1; }
    fprintf(p, "%d", period_ns);
    fclose(p);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    p = fopen(path, "w");
    if (!p) { perror("fopen duty"); return -1; }
    fprintf(p, "%d", duty_ns);
    fclose(p);
    return 0;
}

static int set_pwm_duty_cycle(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *p = fopen(path, "w");
    if (!p) { perror("fopen duty"); return -1; }
    fprintf(p, "%d", duty_ns);
    fclose(p);
    return 0;
}

int main() {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    load_config();

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    trig_line = gpiod_chip_get_line(chip, config_data.trig_pin);
    echo_line = gpiod_chip_get_line(chip, config_data.echo_pin);
    if (!trig_line || !echo_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI init failed\n");
        cleanup();
        return 1;
    }

    save_config();

    float last_distance = -1.0;
    int last_freq = MIN_FREQUENCY;
    int last_duty = 50;

    while (running) {
        float d = read_distance();
        if (d < 0) {
            fprintf(stderr, "Sensor read error\n");
            d = last_distance;
        } else {
            last_distance = d;
        }
        int freq = map_distance_to_frequency(d);
        if (freq != last_freq) {
            if (set_pwm_frequency(freq) == 0) {
                last_freq = freq;
            }
        }
        int photo = read_photoresistor();
        if (photo >= 0) {
            int duty = (photo * 100) / 1023;
            if (duty != last_duty) {
                if (set_pwm_duty_cycle(duty) == 0) {
                    last_duty = duty;
                }
            }
        }
        usleep(20000);
    }

    set_pwm_frequency(0);
    set_pwm_duty_cycle(0);
    save_config();
    cleanup();
    return 0;
}

