#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define AQI_THRESHOLD 100
#define MAX_AQI 500
#define LOG_FILE "air_quality.log"
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY_MS 1000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)(0x08 | (channel << 4)), 0x00};
    char rx[3] = {0};

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d), ret=%d\n", attempt + 1, SPI_RETRIES, ret);
        if (attempt < SPI_RETRIES - 1) {
            gpioDelay(SPI_RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value %d\n", adc_value);
        return -1;
    }
    return (int)(((float)adc_value / 1023.0f) * MAX_AQI);
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON (AQI=%d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF (AQI=%d)\n", aqi);
    }
}

static void log_data(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(1000000);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-init failed: %d\n", spi_handle);
                break;
            }
            continue;
        }

        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "AQI calculation failed\n");
            continue;
        }

        control_fan(aqi);
        log_data(aqi);
        printf("AQI: %d\n", aqi);

        gpioDelay(5000000);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

