#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture, int pump_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_pump(0); // Turn off the pump
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(log_file, "%ld: Error: Invalid MCP3008 channel: %d\n", time(NULL), channel);
        fflush(log_file);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message for MCP3008 single-ended mode
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(log_file, "%ld: Error: SPI transfer failed\n", time(NULL));
        fflush(log_file);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_data(-1, state); // Log pump state without moisture data
}

// Function to log data to file
void log_data(int moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", timestamp, moisture, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");

    while (program_running) {
        // Read soil moisture sensor
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(log_file, "%ld: Error reading moisture sensor\n", time(NULL));
            fflush(log_file);
            gpioDelay(SAMPLE_INTERVAL * 1000000); // Wait 60 seconds
            continue;
        }

        // Check if moisture is below threshold
        if (moisture < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn on the pump
        } else {
            control_pump(0); // Turn off the pump
        }

        // Log data
        log_data(moisture, gpioRead(PUMP_GPIO));

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Wait 60 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    control_pump(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

