#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// MCP3008 SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

// Potentiometer channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM range
#define PWM_RANGE 255

// Speed mapping constants
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile timing
#define ACCEL_DELAY_MS 2000
#define HOLD_DELAY_MS 2000
#define DECEL_DELAY_MS 2000
#define PAUSE_DELAY_MS 5000

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
void set_motor_speed(int motor, int speed);
void move_motors(int motor1_speed, int motor2_speed);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", handle);
        return -1;
    }

    int status = spiXfer(handle, tx_buf, rx_buf, 3);
    spiClose(handle);

    if (status < 0) {
        fprintf(stderr, "Error: spiXfer failed (%d)\n", status);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 3) << 8) | rx_buf[2];
    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid speed %d for motor %d\n", speed, motor);
        return;
    }

    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
        gpioWrite(MOTOR1_DIR, 0); // Forward
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
        gpioWrite(MOTOR2_DIR, 0); // Forward
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
    }
}

// Function to move both motors
void move_motors(int motor1_speed, int motor2_speed) {
    set_motor_speed(1, motor1_speed);
    set_motor_speed(2, motor2_speed);
}

// Function to clean up GPIO and SPI resources
void cleanup() {
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_adc(POT1_CHANNEL);
        int pot2_value = read_adc(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            gpioDelay(1000000); // Wait 1 second before retry
            continue;
        }

        // Map potentiometer values to speed factors using logarithmic mapping
        // Logarithmic mapping for finer control at low speeds
        float speed_factor1 = log10(pot1_value + 1) / log10(1024);
        float speed_factor2 = log10(pot2_value + 1) / log10(1024);

        // Scale speed factors to PWM range
        int motor1_speed = (int)(MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
        int motor2_speed = (int)(MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

        if (motor1_speed < MIN_SPEED) motor1_speed = MIN_SPEED;
        if (motor1_speed > MAX_SPEED) motor1_speed = MAX_SPEED;
        if (motor2_speed < MIN_SPEED) motor2_speed = MIN_SPEED;
        if (motor2_speed > MAX_SPEED) motor2_speed = MAX_SPEED;

        printf("Pot1: %d, Pot2: %d, Motor1 Speed: %d, Motor2 Speed: %d\n", pot1_value, pot2_value, motor1_speed, motor2_speed);

        // Move motors forward
        move_motors(motor1_speed, motor2_speed);
        gpioDelay(ACCEL_DELAY_MS * 1000);

        // Hold constant speed
        gpioDelay(HOLD_DELAY_MS * 1000);

        // Decelerate
        gpioDelay(DECEL_DELAY_MS * 1000);

        // Pause
        gpioDelay(PAUSE_DELAY_MS * 1000);

        // Reverse directions
        gpioWrite(MOTOR1_DIR, 1); // Reverse Motor 1
        gpioWrite(MOTOR2_DIR, 1); // Reverse Motor 2

        // Read potentiometer values after reversal
        pot1_value = read_adc(POT1_CHANNEL);
        pot2_value = read_adc(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values after reversal\n");
            gpioDelay(1000000);
            continue;
        }

        speed_factor1 = log10(pot1_value + 1) / log10(1024);
        speed_factor2 = log10(pot2_value + 1) / log10(1024);

        motor1_speed = (int)(MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
        motor2_speed = (int)(MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

        if (motor1_speed < MIN_SPEED) motor1_speed = MIN_SPEED;
        if (motor1_speed > MAX_SPEED) motor1_speed = MAX_SPEED;
        if (motor2_speed < MIN_SPEED) motor2_speed = MIN_SPEED;
        if (motor2_speed > MAX_SPEED) motor2_speed = MAX_SPEED;

        printf("Pot1: %d, Pot2: %d, Motor1 Speed: %d, Motor2 Speed: %d\n", pot1_value, pot2_value, motor1_speed, motor2_speed);

        move_motors(motor1_speed, motor2_speed);
        gpioDelay(ACCEL_DELAY_MS * 1000);

        gpioDelay(HOLD_DELAY_MS * 1000);

        gpioDelay(DECEL_DELAY_MS * 1000);

        gpioDelay(PAUSE_DELAY_MS * 1000);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

