#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define LED_GPIO 17
#define THRESHOLD 10 // 10% above average
#define DEBOUNCE_MS 10
#define CALIBRATION_TIME 5 // seconds
#define SAMPLE_INTERVAL_US 100000 // 100 ms

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
void control_led(int state);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx_buf[1] contains the two most significant bits (masked with 0x03)
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off the LED
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Calibration period
    float sum = 0.0;
    int valid_samples = 0;
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < CALIBRATION_TIME && program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            sum += adc_value;
            valid_samples++;
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (!program_running) {
        cleanup();
        return 0;
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration. Using default threshold.\n");
    } else {
        float average_sound_level = sum / valid_samples;
        float threshold_value = average_sound_level * (1.0 + THRESHOLD / 100.0);
        printf("Average sound level: %.2f, Threshold: %.2f\n", average_sound_level, threshold_value);
    }

    // Main loop
    int led_state = 0;
    struct timespec last_led_change = {0, 0};

    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float sound_level = (float)adc_value / 1023.0 * 100.0; // Convert to percentage

        if (sound_level > threshold_value) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);

            long elapsed_ms = (current_time.tv_sec - last_led_change.tv_sec) * 1000 +
                              (current_time.tv_nsec - last_led_change.tv_nsec) / 1000000;

            if (elapsed_ms >= DEBOUNCE_MS) {
                led_state = !led_state;
                control_led(led_state);
                last_led_change = current_time;
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

