#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// MCP3008 SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)

// ADXL335 parameters
#define SENSITIVITY 0.300 // 300 mV/g
#define ZERO_G_BIAS 1.5   // 1.5V at 0g

// Kalman filter parameters
#define Q_ANGLE 0.001
#define R_MEASUREMENT 0.01

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float angle = 0.0;
float angle_rate = 0.0;

// Function prototypes
int read_mcp3008(int channel);
void kalman_filter(float measurement);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transaction failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Kalman filter function
void kalman_filter(float measurement) {
    float y = measurement - angle_rate;
    angle += (Q_ANGLE * angle_rate) + y;
    angle_rate = y - (R_MEASUREMENT * angle_rate);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output and initialize high (deselected)
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values for X, Y, and Z channels
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        // Check for SPI errors
        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: SPI read failed, skipping sample\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert ADC values to voltages (3.3V reference)
        float x_voltage = (x_adc * 3.3) / 1023.0;
        float y_voltage = (y_adc * 3.3) / 1023.0;
        float z_voltage = (z_adc * 3.3) / 1023.0;

        // Convert voltages to acceleration values (g)
        float x_accel = (x_voltage - ZERO_G_BIAS) / SENSITIVITY;
        float y_accel = (y_voltage - ZERO_G_BIAS) / SENSITIVITY;
        float z_accel = (z_voltage - ZERO_G_BIAS) / SENSITIVITY;

        // Apply Kalman filter
        kalman_filter(x_accel);
        kalman_filter(y_accel);
        kalman_filter(z_accel);

        // Print filtered acceleration values (in g)
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", angle, angle_rate, 0.0); // Z axis is not filtered

        // Delay to control loop rate (10 Hz)
        gpioDelay(100000); // 100ms = 10 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

