#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define VCC 3.3
#define V_QUIEZNTENTIAL (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, const char *name) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading %s sensor: %s\n", name, strerror(errno));
        return -1;
    }
    return val;
}

static float calculate_magnetic_field(int digital_value) {
    float voltage = (float)digital_value * VCC;
    return (voltage - V_QUIEZNTENTIAL) / SENSITIVITY;
}

static int log_data(FILE *fp, float f1, float f2, float f3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", f1, f2, f3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    const char *names[3] = {"Sensor1", "Sensor2", "Sensor3"};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], names[i]) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting DRV5055VA Hall-Effect sensor monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int v1 = read_sensor(lines[0], names[0]);
        int v2 = read_sensor(lines[1], names[1]);
        int v3 = read_sensor(lines[2], names[2]);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error reading sensor data, skipping this iteration.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float f1 = calculate_magnetic_field(v1);
        float f2 = calculate_magnetic_field(v2);
        float f3 = calculate_magnetic_field(v3);

        if (log_data(fp, f1, f2, f3) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (f1 < -100.0 || f1 > 100.0 || f2 < -100.0 || f2 > 100.0 || f3 < -100.0 || f3 > 100.0) {
            fprintf(stderr, "Warning: Magnetic field values out of range (Sensor1: %.2f mT, Sensor2: %.2f mT, Sensor3: %.2f mT)\n", f1, f2, f3);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

