#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define LOG_FILE "watering.log"

static volatile int keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", handle);
        return -1;
    }
    int ret = spiXfer(handle, tx, rx, 3);
    spiClose(handle);
    if (ret < 0) {
        fprintf(stderr, "spiXfer failed: %d\n", ret);
        return -1;
    }
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    time_t last_watering = 0;
    while (keep_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error\n");
            time_t now = time(NULL);
            char ts[64];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - ADC read error\n", ts);
            fflush(log_file);
            sleep(60);
            continue;
        }
        int moisture = (int)((float)adc / ADC_MAX * 100);
        time_t now = time(NULL);
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s - Moisture: %d%%\n", ts, moisture);
        fflush(log_file);
        if (moisture < MOISTURE_THRESHOLD) {
            gpioWrite(PUMP_GPIO, 1);
            fprintf(log_file, "%s - Pump ON\n", ts);
            fflush(log_file);
            last_watering = now;
        } else if (moisture >= MOISTURE_THRESHOLD && moisture < (MOISTURE_THRESHOLD + 5)) {
            gpioWrite(PUMP_GPIO, 0);
            fprintf(log_file, "%s - Pump OFF (near threshold)\n", ts);
            fflush(log_file);
        } else {
            gpioWrite(PUMP_GPIO, 0);
            fprintf(log_file, "%s - Pump OFF\n", ts);
            fflush(log_file);
        }
        sleep(60);
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    return 0;
}

