#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MIN_RECONNECT_DELAY 1

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led(int state) {
    if (gpioWrite(LED_GPIO, state) != 0) {
        log_error("Failed to write to GPIO");
        return -1;
    }
    return 0;
}

static int parse_json(const char *json_string, int *led_state) {
    cJSON *json = cJSON_Parse(json_string);
    if (!json) {
        log_error("Error parsing JSON");
        return -1;
    }
    cJSON *item = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(item)) {
        log_error("Invalid led_state type");
        cJSON_Delete(json);
        return -1;
    }
    *led_state = (int)item->valued.b;
    cJSON_Delete(json);
    return 0;
}

static void message_callback(struct mosquitto *m, void *userdata,
                              const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (!message || !message->payload || message->payloadlen <= 0) {
        log_error("Empty MQTT message");
        return;
    }
    char *payload = malloc(message->payloadlen + 1);
    if (!payload) {
        log_error("Memory allocation failed for payload");
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    int led_state = 0;
    if (parse_json(payload, &led_state) == 0) {
        if (set_led(led_state) == 0) {
            printf("LED set to %s\n", led_state ? "ON" : "OFF");
        }
    } else {
        log_error("Failed to parse or apply LED state");
    }
    free(payload);
}

static void connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Connection failed");
    }
}

static void disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnect");
    }
}

static int reconnect_mqtt(void) {
    int delay = MIN_RECONNECT_DELAY;
    int rc;
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        return -1;
    }
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);
    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to broker");
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start mosquitto loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    printf("Reconnected to MQTT broker\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to set signal handlers");
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to broker");
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start mosquitto loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    printf("Subscribed to topic %s\n", MQTT_TOPIC);

    while (running) {
        sleep(1);
        if (!mosquitto_loop_running(mosq)) {
            log_error("mosquitto loop stopped unexpectedly");
            if (reconnect_mqtt() != 0) {
                log_error("Reconnection failed, exiting");
                break;
            }
        }
    }

    printf("Shutting down...\n");
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete\n");
    return 0;
}

