        return EXIT_FAILURE;
    }

    /* Request alarm LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, "alarm-led", 0);
    if (ret < 0) {
        perror("Failed to request alarm LED line as output");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("Failed to read sound sensor value");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected: blink alarm LED for 1 second */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("Failed to set LED ON");
                break;
            }
            usleep(ALARM_BLINK_MS * 1000);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("Failed to set LED OFF");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up: turn LED off and release all resources */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

