#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int shutdown_system(void)
{
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "shutdown command did not succeed (exit status %d)\n",
                WIFEXITED(ret) ? WEXITSTATUS(ret) : -1);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP ")");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE);

    while (program_running) {
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000,
                               .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int rv = gpiod_line_event_wait(line, &ts);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (rv == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char message[128];
            snprintf(message, sizeof(message),
                     "Vibration detected on GPIO%d. Initiating shutdown.",
                     GPIO_LINE);
            if (log_event(message) < 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            } else {
                printf("%s\n", message);
            }
            if (shutdown_system() < 0) {
                fprintf(stderr, "Shutdown command failed. Continuing to monitor.\n");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Vibration monitoring stopped.\n");
    return ret;
}

