#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define SEA_LEVEL_PRESSURE 101325.0
#define LOG_FILE "altitude_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp280_calib_t *c) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: failed to read 24-byte calibration block\n");
        return -1;
    }
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw(int handle, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte raw data block\n");
        return -1;
    }
    *raw_p = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_t = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

static double compensate_temperature(int32_t raw_t, const bmp280_calib_t *c) {
    double var1 = ((double)raw_t / 16384.0 - (double)c->dig_T1 / 1024.0) * (double)c->dig_T2;
    double var2 = ((double)raw_t / 131072.0 - (double)c->dig_T1 / 8192.0) *
                  ((double)raw_t / 131072.0 - (double)c->dig_T1 / 8192.0) * (double)c->dig_T3;
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_p, const bmp280_calib_t *c) {
    double var1 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P2;
    double var2 = ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) * (double)c->dig_P3;
    double var3 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P4;
    double var4 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P5;
    double var5 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P6;
    double var6 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P7;
    double var7 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P8;
    double var8 = ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)c->dig_P1 / 8192.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)c->dig_P1 / 1024.0) * (double)c->dig_P9;
    double p = var1 + var2 + var3 + var4 + var5 + var6 + var7 + var8;
    return p;
}

static double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

static void log_data(double altitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s Altitude: %.2f m\n", ts, altitude);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X (err=%d)\n", BMP280_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: BMP280 not found (chip_id=0x%02X, expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write ctrl_meas\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int32_t raw_t, raw_p;
        if (read_raw(i2c_handle, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        double temp = compensate_temperature(raw_t, &calib);
        double press = compensate_pressure(raw_p, &calib);
        double alt = calculate_altitude(press);
        log_data(alt);
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

