#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define VREF        3.3f
#define LM35_MV_PER_C 10.0f
#define BUFFER_SIZE 120
#define LOG_FILE    "temp_log.dat"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static float temperature_buffer[BUFFER_SIZE];
static int   buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0f;
    return voltage * 100.0f;
}

static void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int save_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t elements_to_write = (size_t)BUFFER_SIZE;
    size_t elements_written = 0;
    while (elements_written < elements_to_write) {
        size_t to_write = (size_t)BUFFER_SIZE - elements_written;
        if (to_write > elements_to_write - elements_written) to_write = elements_to_write - elements_written;
        size_t written = fwrite(&temperature_buffer[(buffer_index + elements_written) % BUFFER_SIZE], sizeof(float), to_write, fp);
        if (written == 0) {
            perror("fwrite");
            fclose(fp);
            return -1;
        }
        elements_written += written;
    }

    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this sample\n");
        } else {
            float temperature = adc_to_celsius(adc_value);
            store_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        }

        if (save_buffer_to_file(LOG_FILE) != 0) {
            fprintf(stderr, "Warning: failed to save buffer to file\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

