#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGHRES 0x10
#define MCP3008_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_light_level(int i2c_fd) {
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    unsigned char cmd = BH1750_CONT_HIGHRES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(180000); // Wait for measurement (max 180ms for high res mode)

    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int light_level = (buf[0] << 8) | buf[1];
    return light_level;
}

static int read_sound_level(int spi_fd) {
    unsigned char tx[3] = {0x01, (0x08 | MCP3008_CHANNEL) << 4, 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int sound_level = ((rx[1] & 0x03) << 8) + rx[2];
    return sound_level;
}

static void log_data(int light_level, int sound_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }

    unsigned int spi_speed = 1000000;
    unsigned char spi_bits = 8;
    unsigned int spi_mode = 0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    while (running) {
        int light_level = read_light_level(i2c_fd);
        int sound_level = read_sound_level(spi_fd);

        if (light_level >= 0 && sound_level >= 0) {
            log_data(light_level, sound_level);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

