#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define DAC_VREF 3.3
#define DAC_MAX 4095.0
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, mode=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE, spi_handle);
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=1, addr=0x%02X): %d\n",
                MCP4725_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed: returned %d (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_temperature(int adc_value) {
    double voltage = (adc_value / DAC_MAX) * DAC_VREF;
    double temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

static int set_dac_voltage(double voltage) {
    if (voltage < 0.0 || voltage > DAC_VREF) {
        fprintf(stderr, "Error: DAC voltage %.3f out of range [0, %.1f]\n",
                voltage, DAC_VREF);
        return -1;
    }

    unsigned int duty_cycle = (unsigned int)((voltage / DAC_VREF) * DAC_MAX);
    if (duty_cycle > 4095) duty_cycle = 4095;

    unsigned char config[2] = {
        (unsigned char)(duty_cycle >> 8),
        (unsigned char)(duty_cycle & 0xFF)
    };

    int ret = i2cWriteDevice(i2c_handle, (char *)config, 2);
    if (ret != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed: %d\n", ret);
        return -1;
    }
    return 0;
}

static void log_data(int adc_value, double temperature, double dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
            timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file);

    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
           timestamp, adc_value, temperature, dac_voltage);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Warning: ADC read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed after %d retries, skipping cycle\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double temperature = adc_to_temperature(adc_value);
        double dac_voltage = (temperature - TEMP_MIN) * (DAC_VREF / (TEMP_MAX - TEMP_MIN));

        if (set_dac_voltage(dac_voltage) != 0) {
            fprintf(stderr, "Warning: DAC write failed, continuing\n");
        }

        log_data(adc_value, temperature, dac_voltage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

