        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0f;
    }
    return (1.0f - (float)adc_value / 1023.0f) * 100.0f;
}

void log_data(float moisture[MCP3008_CHANNELS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture[0], moisture[1], moisture[2]);
    fflush(log_file);
}

void cleanup(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    while (1) {
        float moisture[MCP3008_CHANNELS];
        int valid = 1;
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            int adc = read_mcp3008(i);
            if (adc < 0) {
                valid = 0;
                break;
            }
            moisture[i] = adc_to_moisture(adc);
            if (moisture[i] < 0.0f) {
                valid = 0;
                break;
            }
        }
        if (valid) {
            log_data(moisture);
        }
        gpioDelay(SLEEP_INTERVAL * 1000000);
    }
    cleanup();
    return 0;
}

