#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

/*
 * Raspberry Pi 3 Model B+ — Relay Sequencer (libgpiod)
 *
 * Four Songle SRD-05VDC-SL relays on BCM GPIO pins:
 *   Relay 1 -> BCM 17
 *   Relay 2 -> BCM 22
 *   Relay 3 -> BCM 23
 *   Relay 4 -> BCM 24
 *
 * Relays are active-high: LOW = relay OFF, HIGH = relay ON.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_seq relay_seq.c -lgpiod
 */

#define NUM_RELAYS 4
#define RELAY_ON_TIME_SEC 1
#define INTER_RELAY_DELAY_SEC 1

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown: deactivate all relays, release */
/* lines, close chip, and exit.                                       */
/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all relays (set every line LOW) and release resources.   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Request a single GPIO line as output, initially LOW.               */
/* Returns a pointer to the line or NULL on failure.                   */
/* ------------------------------------------------------------------ */
static struct gpiod_line *request_relay_line(unsigned int offset)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        perror("gpiod_chip_get_line");
        return NULL;
    }

    if (gpiod_line_request_output(line, "relay-sequencer", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        return NULL;
    }
    return line;
}

/* ------------------------------------------------------------------ */
/* Activate a single relay (set line HIGH).                           */
/* ------------------------------------------------------------------ */
static int activate_relay(int relay_index)
{
    if (gpiod_line_set_value(relay_lines[relay_index], 1) < 0) {
        perror("gpiod_line_set_value (activate)");
        return -1;
    }
    printf("Relay %d (BCM %u) ON\n", relay_index + 1, relay_pins[relay_index]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate a single relay (set line LOW).                          */
/* ------------------------------------------------------------------ */
static int deactivate_relay(int relay_index)
{
    if (gpiod_line_set_value(relay_lines[relay_index], 0) < 0) {
        perror("gpiod_line_set_value (deactivate)");
        return -1;
    }
    printf("Relay %d (BCM %u) OFF\n", relay_index + 1, relay_pins[relay_index]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Open GPIO chip 0 (default on RPi 3B+) ---- */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* ---- Request each relay line as output, initially LOW ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = request_relay_line(relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to request BCM %u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    /* ---- Main loop: sequential activation and deactivation ---- */
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            if (activate_relay(i) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            sleep(RELAY_ON_TIME_SEC);
            if (!keep_running) break;
            if (deactivate_relay(i) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            sleep(INTER_RELAY_DELAY_SEC);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

