#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor driver GPIO pins (BCM numbering) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* Rain sensor ADC channel on MCP3008 (single-ended) */
#define RAIN_ADC_CHANNEL 0

/* Rain threshold (0-10 scale, 0=heaviest rain, 10=dry) */
#define RAIN_THRESHOLD 5

/* PWM range and duty cycle for motor speed */
#define PWM_RANGE 255
#define MOTOR_SPEED 150

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define SPI_FLAGS 0         /* Mode 0, active-low CE */

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t program_running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int read_rain_sensor(int spi_handle, int channel);
static int adc_to_rain_level(int adc_value);
static void open_window(void);
static void close_window(void);
static void log_rain_data(int rain_level);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a single-ended channel from the MCP3008 via SPI.
 * Returns the 10-bit ADC value (0-1023) on success, or -1 on error.
 */
static int read_rain_sensor(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01  (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: bits 9-8 in rx[1] (masked 0x03), bits 7-0 in rx[2]
     */
    char tx_buffer[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buffer[3] = { 0 };

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

/*
 * Convert ADC value (0-1023) to rain level (0-10).
 * Higher ADC value (dry air) -> lower rain level (0).
