#include <stdint.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_INTERVAL_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_ADC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc_bit(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        return -1;
    }
    gpioDelay(1);
    int level = gpioRead(pin);
    gpioSetMode(pin, PI_INPUT);
    return level;
}

static int read_adc_10bit(int pin) {
    int value = 0;
    for (int i = 0; i < 10; i++) {
        int bit = read_adc_bit(pin);
        if (bit < 0) {
            return -1;
        }
        value |= (bit << i);
    }
    return value;
}

static void trigger_led(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn on LED.\n");
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED.\n");
    }
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Warning: localtime failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int adc_value = read_adc_10bit(MIC_ADC_PIN);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed on GPIO%d.\n", MIC_ADC_PIN);
            gpioDelay(100000);
            continue;
        }

        if (adc_value > THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                trigger_led(LED_PIN);
                log_detection();
                last_trigger_tick = now;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

