#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIR_PATH "/sys/class/gpio/gpio%d/direction"
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio%d/value"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int gpio_export(int pin) {
    int fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        return -1;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error unexporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_DIR_PATH, pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Error setting direction for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_VALUE_PATH, pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading GPIO %d value: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return (value == '1') ? 1 : 0;
}

static float voltage_to_distance(float voltage) {
    if (voltage <= 0.0f) return 1000.0f;
    return 26.0f / voltage - 6.0f;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }
    usleep(100000);

    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction. Exiting.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    while (program_running) {
        int val = gpio_read(GPIO_PIN);
