#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_GPIO_LINE    8
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define VREF_MV         3300
#define SENSITIVITY_MV_MT 100
#define QUIESCENT_MV    1650
#define SAMPLE_MS       500
#define LOG_FILE        "magnetic_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    return 0;
}

static int read_adc(int fd, struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then 10-bit result */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("CS low");
        return -1;
    }

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("CS high");
        return -1;
    }

    /* rx[1] low nibble + rx[2] form the 10-bit result */
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static float calculate_magnetic_field(int adc_value)
{
    int32_t vout_mv = (int32_t)adc_value * VREF_MV / ADC_MAX;
    int32_t field_mt = (vout_mv - QUIESCENT_MV) / SENSITIVITY_MV_MT;
    return (float)field_mt / 1000.0f;
}

static int log_data(FILE *fp, float field_mt)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (fprintf(fp, "%ld,%.2f\n", (long)now, field_mt) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI bits");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI speed");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        goto cleanup;
    }

    printf("Starting DRV5055-A1 magnetic field logging (MCP3008 CH0, SPI0.0, %d Hz)...\n",
           SPI_SPEED_HZ);

    while (g_running) {
        int adc = read_adc(spi_fd, cs_line, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
        } else {
            float field = calculate_magnetic_field(adc);
            if (log_data(log_fp, field) < 0) {
                fprintf(stderr, "Log write failed\n");
            }
            printf("ADC=%4d  Vout=%.1f mV  B=%.2f mT\n", adc,
                   (float)adc * VREF_MV / ADC_MAX, field);
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    return ret;
}

