    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(const char *timestamp, int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s, %d\n", timestamp, moisture_level);
    fclose(fp);
}

static void log_error(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s, Error reading moisture level\n", timestamp);
    fclose(fp);
}

