    while (!terminate) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        int moisture_level = read_mcp3008(MCP3008_CHANNEL);

        if (moisture_level >= 0) {
