#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – Current Monitoring via MLX91211 + MCP3008
 *
 * Wiring:
 *   MCP3008 VDD/VREF -> Pi 5V (pins 2/4)
 *   MCP3008 AGND/DGND -> Pi GND (pins 6/9)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V (pin 2/4)
 *   MLX91211 GND -> Pi GND (pin 6/9)
 *   MLX91211 OUT -> MCP3008 CH0
 *
 * MLX91211 ratiometric output:
 *   2.5 V  -> 0 A
 *   5.0 V  -> 50 A
 *   V = VDD/2 + (I_fullscale * VDD/2)
 *   I = (V - 2.5) * 50 / 2.5
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define ADC_MAX_CODE   1023       /* 10-bit ADC */
#define ADC_VREF       5.0        /* VREF = 5V */
#define SENSOR_VDD     2.5        /* MLX91211 VDD/2 = 2.5V at zero current */
#define SENSOR_FULL_V  5.0        /* MLX91211 VDD at full-scale current */
#define FULL_SCALE_A   50.0       /* MLX91211 full-scale current (A) */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit, single/diff + channel, then don't-care */
    unsigned char tx[3] = {
        0x01,                       /* start bit */
        (unsigned char)(0x80 | (channel << 4)), /* single-ended, channel */
        0x00                        /* don't-care */
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
static float raw_to_voltage(int raw)
{
    return ((float)raw / (float)ADC_MAX_CODE) * ADC_VREF;
}

/* ------------------------------------------------------------------ */
static float voltage_to_current(float v)
{
    if (v < SENSOR_VDD)
        return 0.0f;
    if (v > SENSOR_FULL_V)
        return FULL_SCALE_A;
    return (v - SENSOR_VDD) * (FULL_SCALE_A / (SENSOR_FULL_V - SENSOR_VDD));
}

/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(g_log) != 0)
        fprintf(stderr, "fflush failed\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    spiClose(0);   /* close SPI0 CE0 */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI0 CE0, 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        int raw = mcp3008_read(spi_handle, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        if (voltage < 0.0f || voltage > ADC_VREF) {
            fprintf(stderr, "Voltage out of range (%.3f V) – skipping sample\n",
                    voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = voltage_to_current(voltage);
        log_current(current);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

