#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(struct gpiod_line *line) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line\n");
            return -1;
        }
        if (val == 0) low_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count >= DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor 1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor 2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-db01-s1") < 0) {
        perror("gpiod_line_request_input (sensor 1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01-s2") < 0) {
        perror("gpiod_line_request_input (sensor 2)");
        goto cleanup;
    }

    while (running) {
        int s1 = read_sensor_debounced(line1);
        int s2 = read_sensor_debounced(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        printf("Sensor 1 (GPIO%d): %d\n", SENSOR1_GPIO, s1);
        printf("Sensor 2 (GPIO%d): %d\n", SENSOR2_GPIO, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

