#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 50000
#define CAPTURE_DIR "/home/pi/security_cam/"
#define MAX_PATH 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create directory '%s': %m", path);
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }
    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execlp("libcamera-still", "libcamera-still",
               "-o", filename,
               "--width", "1280",
               "--height", "720",
               "--nopreview",
               (char *)NULL);
        _exit(127); /* If execvp returns, it failed */
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!running) {
                syslog(LOG_ERR, "Interrupted during libcamera-still wait");
                return -1;
            }
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }

    if (WIFEXITED(status)) {
        syslog(LOG_ERR, "libcamera-still exited with status %d",
               WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        syslog(LOG_ERR, "libcamera-still killed by signal %d",
               WTERMSIG(status));
    } else {
        syslog(LOG_ERR, "libcamera-still terminated abnormally");
    }
    return -1;
}

static void generate_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on GPIO%d, output dir '%s')",
           PIR_GPIO, CAPTURE_DIR);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); /* 200 ms debounce */
            current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                syslog(LOG_ERR, "gpioRead failed during debounce on GPIO%d", PIR_GPIO);
                break;
            }

            if (current_state == last_state) {
                /* Spurious edge, ignore */
                continue;
            }

            last_state = current_state;

            if (current_state == 1) {
                char timestamp[32];
                generate_timestamp(timestamp, sizeof(timestamp));

                char filepath[MAX_PATH];
                snprintf(filepath, sizeof(filepath),
                         "%s%s.jpg", CAPTURE_DIR, timestamp);

                syslog(LOG_INFO, "Motion detected on GPIO%d — capturing %s",
                       PIR_GPIO, filepath);

                if (capture_image(filepath) == 0) {
                    syslog(LOG_INFO, "Image saved: %s", filepath);
                } else {
                    syslog(LOG_ERR, "Image capture failed for %s", filepath);
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

