#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define NUM_BUFFERS 4

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int fd = -1;
static buffer_t *buffers = NULL;
static unsigned int n_buffers = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static void cleanup(void) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers && buffers[i].start && buffers[i].start != MAP_FAILED) {
                if (munmap(buffers[i].start, buffers[i].length) < 0) {
                    perror("munmap");
                }
            }
        }
        close(fd);
        fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int xioctl(int fh, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    n_buffers = req.count;

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

static int capture_frame(struct timeval *tv) {
    fd_set fds;
    struct timeval timeout;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &timeout);

    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        perror("select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *tv = buf.timestamp;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

static int log_timestamp(struct timeval tv) {
    if (!log_file) {
        log_file = fopen(FRAME_LOG_FILE, "w");
        if (!log_file) {
            perror("fopen");
            return -1;
        }
    }

    fprintf(log_file, "%ld.%06ld\n", (long)tv.tv_sec, (long)tv.tv_usec);
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera() < 0) {
        cleanup();
        return 1;
    }

    printf("Capturing MJPEG video from %s... Press Ctrl+C to stop.\n", DEVICE_NAME);

    while (!stop_flag) {
        struct timeval tv;

        if (capture_frame(&tv) < 0) {
            if (stop_flag) {
                break;
            }
            fprintf(stderr, "Frame capture failed\n");
            continue;
        }

        if (log_timestamp(tv) < 0) {
            fprintf(stderr, "Failed to log timestamp\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

