    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera() < 0) {
        cleanup();
        return 1;
    }

    printf("Capturing MJPEG video from %s... Press Ctrl+C to stop.\n", DEVICE_NAME);

    while (!stop_flag) {
        struct timeval tv;

        if (capture_frame(&tv) < 0) {
            if (stop_flag) {
                break;
            }
            fprintf(stderr, "Frame capture failed\n");
            continue;
        }

        if (log_timestamp(tv) < 0) {
            fprintf(stderr, "Failed to log timestamp\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

