        }

        if (buf.index >= n_buffers) {
            fprintf(stderr, "Buffer index out of range\n");
            break;
        }

        MPEG_HEADER header;
        header.frame_index = frame_number;
        header.fragment_index = buf.index;
        header.total_fragments = n_buffers;
        header.payload_size = buffer_lengths[buf.index];

        unsigned char header_data[sizeof(MPEG_HEADER)];
        memcpy(header_data, &header, sizeof(MPEG_HEADER));

        size_t total_size = sizeof(MPEG_HEADER) + buffer_lengths[buf.index];
        size_t max_datagram_size = MAX_DATAGRAM_SIZE;
        int num_datagrams = 0;
        size_t remaining = total_size;

        while (remaining > 0 && !stop_flag) {
