            }
            remaining -= chunk_size;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_number++;
    }

    cleanup_camera(fd, buffers, n_buffers);
    if (sockfd >= 0) {
        close(sockfd);
    }

