            perror("VIDIOC_QBUF");
            break;
        }

        frame_number++;
    }

    cleanup_camera(fd, buffers, n_buffers);
    if (sockfd >= 0) {
        close(sockfd);
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

