/*
 * Pan-tilt servo control with libgpiod software PWM.
 *
 * Wiring (Raspberry Pi 40-pin header):
 *   GPIO4  -> Pan servo signal
 *   GPIO5  -> Tilt servo signal
 *   GPIO6  -> Tilt up   button (active-low, internal pull-up)
 *   GPIO7  -> Tilt down button (active-low, internal pull-up)
 *   GPIO8  -> Pan left  button (active-low, internal pull-up)
 *   GPIO9  -> Pan right button (active-low, internal pull-up)
 *
 * Build: gcc -O2 -Wall -o pan_tilt pan_tilt.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

#define PWM_PERIOD_US    20000   /* 50 Hz */
#define PULSE_MIN_US     1000    /* 1 ms  */
#define PULSE_MAX_US     2000    /* 2 ms  */
#define PULSE_MID_US     1500    /* 1.5 ms (50% of 3 ms center) */
#define STEP_US          5000    /* 5 ms  */
#define POLL_DELAY_US    50000   /* 50 ms */

#define MIN_DUTY         25
#define MAX_DUTY         125
#define MID_DUTY         75
#define DUTY_STEP        5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Software PWM: drive a servo to the given duty cycle (0-1000) for duration_us. */
static int servo_pwm(struct gpiod_line *line, int duty, int duration_us)
{
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    int on_us  = (duty * PULSE_MAX_US) / 1000;
    int off_us = PWM_PERIOD_US - on_us;

    if (on_us <= 0) {
        if (gpiod_line_set_value(line, 0) < 0) return -1;
        usleep(off_us);
        return 0;
    }
    if (off_us <= 0) {
        if (gpiod_line_set_value(line, 1) < 0) return -1;
        usleep(on_us);
        return 0;
    }

    for (;;) {
        if (gpiod_line_set_value(line, 0) < 0) return -1;
        usleep(on_us);
        if (gpiod_line_set_value(line, 1) < 0) return -1;
        usleep(off_us);
    }
}

static int set_servo_position(struct gpiod_line *line, int duty)
{
    return servo_pwm(line, duty, PWM_PERIOD_US);
}

static int move_tilt(struct gpiod_line *line, int direction)
{
    static int tilt_duty = MID_DUTY;
    int new_duty = tilt_duty + direction * DUTY_STEP;
    if (new_duty < MIN_DUTY) new_duty = MIN_DUTY;
    if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
    tilt_duty = new_duty;
    return set_servo_position(line, tilt_duty);
}

static int move_pan(struct gpiod_line *line, int direction)
{
    static int pan_duty = MID_DUTY;
    int new_duty = pan_duty + direction * DUTY_STEP;
    if (new_duty < MIN_DUTY) new_duty = MIN_DUTY;
    if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
    pan_duty = new_duty;
    return set_servo_position(line, pan_duty);
}

static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *pan,
                    struct gpiod_line *tilt,
                    struct gpiod_line *btn_up,
                    struct gpiod_line *btn_down,
                    struct gpiod_line *btn_left,
                    struct gpiod_line *btn_right)
{
    if (pan)   gpiod_line_release(pan);
    if (tilt)  gpiod_line_release(tilt);
    if (btn_up)  gpiod_line_release(btn_up);
    if (btn_down) gpiod_line_release(btn_down);
    if (btn_left) gpiod_line_release(btn_left);
    if (btn_right) gpiod_line_release(btn_right);
    if (chip) gpiod_chip_close(chip);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *btn_up_line = NULL, *btn_down_line = NULL;
    struct gpiod_line *btn_left_line = NULL, *btn_right_line = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line   = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line  = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    btn_up_line = gpiod_chip_get_line(chip, TILT_UP_PIN);
    btn_down_line = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    btn_left_line = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    btn_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !btn_up_line || !btn_down_line ||
        !btn_left_line || !btn_right_line) {
        fprintf(stderr, "Failed to acquire one or more GPIO lines\n");
        goto out;
    }

    if (gpiod_line_request_output(pan_line, "pan_tilt", 1) < 0) {
        perror("request pan output");
        goto out;
    }
    if (gpiod_line_request_output(tilt_line, "pan_tilt", 1) < 0) {
        perror("request tilt output");
        goto out;
    }

    /* Buttons are active-low with internal pull-ups; request as input with pull. */
    if (gpiod_line_request_input_flags(btn_up_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request btn_up input");
        goto out;
    }
    if (gpiod_line_request_input_flags(btn_down_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request btn_down input");
        goto out;
    }
    if (gpiod_line_request_input_flags(btn_left_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request btn_left input");
        goto out;
    }
    if (gpiod_line_request_input_flags(btn_right_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request btn_right input");
        goto out;
    }

    if (set_servo_position(pan_line, MID_DUTY) < 0) {
        fprintf(stderr, "Failed to initialize pan servo\n");
        goto out;
    }
    if (set_servo_position(tilt_line, MID_DUTY) < 0) {
        fprintf(stderr, "Failed to initialize tilt servo\n");
        goto out;
    }

    printf("Pan-tilt ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        int up   = gpiod_line_get_value(btn_up_line);
        int down = gpiod_line_get_value(btn_down_line);
        int left = gpiod_line_get_value(btn_left_line);
        int right = gpiod_line_get_value(btn_right_line);

        if (up < 0 || down < 0 || left < 0 || right < 0) {
            fprintf(stderr, "GPIO read error\n");
            break;
        }

        if (up == 0)   move_tilt(tilt_line,  1);
        if (down == 0) move_tilt(tilt_line, -1);
        if (left == 0) move_pan(pan_line,  1);
        if (right == 0) move_pan(pan_line, -1);

        usleep(POLL_DELAY_US);
    }

    /* Stop PWM and release lines cleanly. */
    if (pan_line)   gpiod_line_set_value(pan_line, 1);
    if (tilt_line)  gpiod_line_set_value(tilt_line, 1);

    rc = EXIT_SUCCESS;

out:
    cleanup(chip, pan_line, tilt_line, btn_up_line, btn_down_line,
            btn_left_line, btn_right_line);
    return rc;
}

