#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer_start;
    size_t buffer_length;
} camera_t;

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(camera_t *cam) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(cam->fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&cam->buf, 0, sizeof(cam->buf));
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam->fd, VIDIOC_DQBUF, &cam->buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

static void yuyv_to_rgb(const unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int i = 0, j = 0; i < w * h * 2; i += 4, j += 6) {
        int y1 = yuyv[i], u = yuyv[i + 1], y2 = yuyv[i + 2], v = yuyv[i + 3];
        int r1 = y1 + 1.1407 * (v - 128);
        int g1 = y1 - 0.3407 * (u - 128) - 0.5807 * (v - 128);
        int b1 = y1 + 1.1407 * (u - 128);
        int r2 = y2 + 1.1407 * (v - 128);
        int g2 = y2 - 0.3407 * (u - 128) - 0.5807 * (v - 128);
        int b2 = y2 + 1.1407 * (u - 128);
        rgb[j]   = (r1 < 0) ? 0 : (r1 > 255) ? 255 : r1;
        rgb[j+1] = (g1 < 0) ? 0 : (g1 > 255) ? 255 : g1;
        rgb[j+2] = (b1 < 0) ? 0 : (b1 > 255) ? 255 : b1;
        rgb[j+3] = (r2 < 0) ? 0 : (r2 > 255) ? 255 : r2;
        rgb[j+4] = (g2 < 0) ? 0 : (g2 > 255) ? 255 : g2;
        rgb[j+5] = (b2 < 0) ? 0 : (b2 > 255) ? 255 : b2;
    }
}

static void box_blur(unsigned char *rgb, int w, int h, int radius, unsigned char *out) {
    int pad = radius * 2 + 1;
    int ow = w + pad * 2;
    int oh = h + pad * 2;
    unsigned char *tmp = malloc((size_t)ow * oh * 3);
    if (!tmp) { fprintf(stderr, "box_blur tmp alloc\n"); return; }
    memset(tmp, 0, (size_t)ow * oh * 3);
    for (int y = -radius; y <= h + radius; y++) {
        for (int x = -radius; x <= w + radius; x++) {
            int ny = y + radius;
            int nx = x + radius;
            if (ny >= 0 && ny < h && nx >= 0 && nx < w) {
                int idx = (ny * w + nx) * 3;
                for (int c = 0; c < 3; c++) {
                    int sx = x + radius;
                    int sy = y + radius;
                    for (int k = -radius; k <= radius; k++) {
                        int t = sx + k;
                        int u = sy + k;
                        if (t >= 0 && t < w && u >= 0 && u < h) {
                            int t2 = t * 3 + c;
                            int u2 = u * 3 + c;
                            tmp[idx + t2] += rgb[u2];
                        }
                    }
                }
            }
        }
    }
    for (int y = 0; y < oh; y++) {
        for (int x = 0; x < ow; x++) {
            int v = tmp[y * ow + x] / (radius * 2 + 1);
            if (v > 255) v = 255;
            if (v < 0) v = 0;
            out[y * w + (x - pad) / 2] = (unsigned char)v;
        }
    }
    free(tmp);
}

static int write_jpeg(const unsigned char *rgb, int w, int h, const char *fn) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = fopen(fn, "wb");
    if (!outfile) { perror("fopen"); return -1; }
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);
    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row_pointer[1];
    int row_stride = w * 3;
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    camera_t cam;
    cam.fd = -1;
    cam.buffer_start = NULL;
    cam.buffer_length = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    cam.fd = open(DEVICE_NAME, O_RDWR);
    if (cam.fd == -1) {
        perror("open " DEVICE_NAME);
        return 1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(cam.fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(cam.fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV\n");
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(cam.fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&cam.buf, 0, sizeof(cam.buf));
    cam.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam.buf.memory = V4L2_MEMORY_MMAP;
    cam.buf.index = 0;
    if (xioctl(cam.fd, VIDIOC_QUERYBUF, &cam.buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    cam.buffer_length = cam.buf.length;
    cam.buffer_start = mmap(NULL, cam.buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam.fd, cam.buf.m.offset);
    if (cam.buffer_start == MAP_FAILED) {
        perror("mmap");
        goto cleanup;
    }

    if (xioctl(cam.fd, VIDIOC_QBUF, &cam.buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(cam.fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    unsigned char *rgb = malloc((size_t)IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!rgb) { fprintf(stderr, "malloc rgb\n"); goto cleanup; }
    unsigned char *blurred = malloc((size_t)IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!blurred) { fprintf(stderr, "malloc blurred\n"); goto cleanup; }

    if (stop_flag) {
        fprintf(stderr, "Interrupted before capture\n");
        goto cleanup;
    }
    if (capture_frame(&cam) == -1) {
        fprintf(stderr, "Failed to capture frame\n");
        goto cleanup;
    }

    yuyv_to_rgb((unsigned char *)cam.buffer_start, rgb, IMAGE_WIDTH, IMAGE_HEIGHT);
    box_blur(rgb, IMAGE_WIDTH, IMAGE_HEIGHT, 2, blurred);

    time_t rawtime;
    time(&rawtime);
    struct tm *timeinfo = localtime(&rawtime);
    char filename[64];
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (write_jpeg(blurred, IMAGE_WIDTH, IMAGE_HEIGHT, filename) == -1) {
        fprintf(stderr, "Failed to write JPEG\n");
        goto cleanup;
    }

    printf("Saved %s\n", filename);

cleanup:
    if (cam.fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(cam.fd, VIDIOC_STREAMOFF, &type);
        if (cam.buffer_start && cam.buffer_start != MAP_FAILED) {
            munmap(cam.buffer_start, cam.buffer_length);
        }
        close(cam.fd);
    }
    free(rgb);
    free(blurred);
    return 0;
}

