#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_capability(const struct v4l2_capability *cap)
{
    printf("  %-20s : %s\n", "Driver", cap->driver);
    printf("  %-20s : %s\n", "Card", cap->card);
    printf("  %-20s : %s\n", "Bus Info", cap->bus_info);
    printf("  %-20s : %s\n", "Version", cap->version);
    printf("  %-20s : %s\n", "Caps", cap->capabilities);
    printf("  %-20s : %s\n", "Min Version", cap->minor_version);
    printf("  %-20s : %s\n", "Max Version", cap->max_version);
    printf("  %-20s : %s\n", "Reserved", cap->reserved[0]);
    printf("  %-20s : %s\n", "Reserved", cap->reserved[1]);
    printf("  %-20s : %s\n", "Reserved", cap->reserved[2]);
}

static void print_format(const struct v4l2_format *fmt)
{
    printf("    Format : %s\n", fmt->type == V4L2_BUF_TYPE_VIDEO_CAPTURE
                                ? "Video Capture" : "Video Output");
    printf("    Width  : %u\n", fmt->fmt.pix.width);
    printf("    Height : %u\n", fmt->fmt.pix.height);
    printf("    Depth  : %u\n", fmt->fmt.pix.depth);
    printf("    Pixel  : %u\n", fmt->fmt.pix.pixelformat);
}

static void print_frmsize(const struct v4l2_frmsizeenum *frmsize)
{
    printf("      Width : %u, Height : %u\n",
           frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE
           ? frmsize->discrete.width : 0,
           frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE
           ? frmsize->discrete.height : 0);
}

static void print_frmival(const struct v4l2_frmivalenum *frmival)
{
    printf("      Value : %u/%u\n",
           frmival->type == V4L2_FRMIVAL_TYPE_DISCRETE
           ? frmival->discrete.numerator : 0,
           frmival->type == V4L2_FRMIVAL_TYPE_DISCRETE
           ? frmival->discrete.denominator : 0);
}

static int query_control(int fd, unsigned int id, unsigned int *val)
{
    struct v4l2_control ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = id;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0)
        return -1;

    *val = ctrl.value;
    return 0;
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    unsigned int focus_auto = 0;
    int ret = EXIT_FAILURE;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    print_capability(&cap);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_ENUM_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }
    print_format(&fmt);

    if (cap.capabilities & V4L2_CAP_STREAMING) {
        if (ioctl(fd, VIDIOC_S_STREAM, &fmt.type) < 0) {
            fprintf(stderr, "VIDIOC_S_STREAM failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    if (cap.capabilities & V4L2_CAP_DEVICE_CAPS) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("\nSupported resolutions:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            print_frmsize(&frmsize);
            if (frmsize.index < 10)
                break;
        }
        if (frmsize.index >= 10) {
            fprintf(stderr, "Warning: frame-size enumeration truncated\n");
        }

        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("\nSupported frame rates:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            print_frmival(&frmival);
            if (frmival.index < 10)
                break;
        }
        if (frmival.index >= 10) {
            fprintf(stderr, "Warning: frame-interval enumeration truncated\n");
        }
    }

    if (query_control(fd, V4L2_CID_FOCUS_AUTO, &focus_auto) < 0) {
        fprintf(stderr, "Warning: could not query focus-auto control: %s\n",
                strerror(errno));
    } else {
        printf("\nAutofocus support: %s\n", focus_auto ? "Yes" : "No");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

