#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define BUTTON_UP_PIN  6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_US  1000
#define SERVO_MAX_US  2000
#define SERVO_CENTER  1500
#define STEP_US       10
#define LOOP_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-ups so the active-low buttons read HIGH when not pressed */
    if (gpioSetPullUpDown(BUTTON_UP_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", BUTTON_UP_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_DOWN_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", BUTTON_DOWN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_LEFT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", BUTTON_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_RIGHT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", BUTTON_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Center both servos at startup */
    if (gpioServo(PAN_SERVO_PIN, SERVO_CENTER) != 0) {
        fprintf(stderr, "Error: failed to set servo on GPIO%d.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioServo(TILT_SERVO_PIN, SERVO_CENTER) != 0) {
        fprintf(stderr, "Error: failed to set servo on GPIO%d.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Stop PWM on both servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Servo Control\n");
    printf("Pins: Pan=GPIO%d, Tilt=GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons: UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           BUTTON_UP_PIN, BUTTON_DOWN_PIN, BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN);
    printf("Center position: %d us\n", SERVO_CENTER);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int pan_pos  = SERVO_CENTER;
    int tilt_pos = SERVO_CENTER;

    while (g_running) {
        int up   = (gpioRead(BUTTON_UP_PIN)   == 0);
        int down = (gpioRead(BUTTON_DOWN_PIN) == 0);
        int left = (gpioRead(BUTTON_LEFT_PIN) == 0);
        int right = (gpioRead(BUTTON_RIGHT_PIN) == 0);

        if (up)   tilt_pos += STEP_US;
        if (down) tilt_pos -= STEP_US;
        if (left) pan_pos  += STEP_US;
        if (right) pan_pos  -= STEP_US;

        /* Clamp to valid range */
        if (tilt_pos < SERVO_MIN_US) tilt_pos = SERVO_MIN_US;
        if (tilt_pos > SERVO_MAX_US) tilt_pos = SERVO_MAX_US;
        if (pan_pos  < SERVO_MIN_US) pan_pos  = SERVO_MIN_US;
        if (pan_pos  > SERVO_MAX_US) pan_pos  = SERVO_MAX_US;

        if (gpioServo(PAN_SERVO_PIN, pan_pos) != 0) {
            fprintf(stderr, "Warning: gpioServo(pan) failed.\n");
        }
        if (gpioServo(TILT_SERVO_PIN, tilt_pos) != 0) {
            fprintf(stderr, "Warning: gpioServo(tilt) failed.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

