#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define UPLOAD_SERVER_IP "http://localhost:8000"
#define UPLOAD_SERVER_PORT 8000
#define CAPTURE_DIR "motion_captures"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width %d --height %d --quality %d",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_motion_data(const char *filename, const char *timestamp,
                            int motion_detected, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    char json_data[512];
    snprintf(json_data, sizeof(json_data),
             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_detected\":%d,\"gpio_pin\":%d}",
             filename, timestamp, motion_detected, gpio_pin);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, UPLOAD_SERVER_IP);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    if (res == CURLE_OK) {
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    }

    int success = (res == CURLE_OK && http_code >= 200 && http_code < 300);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (!success) {
        fprintf(stderr, "HTTP POST failed (code=%ld)\n", http_code);
        return -1;
    }

    printf("Motion data sent successfully to %s\n", UPLOAD_SERVER_IP);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (ensure_capture_dir() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "curl_global_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    time_t last_motion_time = 0;

    while (program_running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", PIR_GPIO);
            break;
        }

        if (motion_detected) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_SEC) {
                struct tm *tm_info = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                char filename[256];
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg",
                         CAPTURE_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    printf("Motion detected at %s. Captured image: %s\n",
                           timestamp, filename);

                    struct tm *tm_info2 = localtime(&now);
                    char timestamp2[32];
                    strftime(timestamp2, sizeof(timestamp2), "%Y-%m-%dT%H:%M:%S", tm_info2);

                    if (send_motion_data(filename, timestamp2, motion_detected, PIR_GPIO) != 0) {
                        fprintf(stderr, "Failed to send motion data\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }

                last_motion_time = now;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    curl_global_cleanup();
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

