#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN          17
#define IMAGE_DIR        "/home/pi/images"
#define LOG_FILE         "/home/pi/motion_capture.log"
#define DEBOUNCE_MS      50
#define POLL_TIMEOUT_MS  1000
#define CAPTURE_CMD      "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char cmd[512];
    int n = snprintf(cmd, sizeof(cmd), CAPTURE_CMD, filename);
    if (n < 0 || (size_t)n >= sizeof(cmd)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int rc = system(cmd);
    if (rc == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(rc) || WEXITSTATUS(rc) != 0) {
        fprintf(stderr, "libcamera-still failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    log_event("Motion detection service started on GPIO17");
    printf("Motion detection service started on GPIO17. Press Ctrl+C to exit.\n");

    while (running) {
        int rv = gpiod_line_event_wait(line, &((struct timespec){0, POLL_TIMEOUT_MS * 1000000L}));
        if (rv < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (rv == 0) {
            continue;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        nanosleep(&ts, NULL);

        char filename[256];
        time_t t = time(NULL);
        struct tm tm;
        if (!localtime_r(&t, &tm)) {
            perror("localtime_r");
            continue;
        }
        snprintf(filename, sizeof(filename), "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec,
                 (int)(tm.tm_milli / 100));

        char logmsg[512];
        snprintf(logmsg, sizeof(logmsg), "Motion detected on GPIO17, capturing %s", filename);
        log_event(logmsg);

        if (capture_image(filename) == 0) {
            snprintf(logmsg, sizeof(logmsg), "Image saved to %s", filename);
            log_event(logmsg);
        } else {
            snprintf(logmsg, sizeof(logmsg), "ERROR: Failed to capture image for %s", filename);
            log_event(logmsg);
        }
    }

    log_event("Motion detection service stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

