#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CROP_LEFT 100
#define CROP_TOP 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_format captured_fmt;
    enum v4l2_buf_type type;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    FILE *out_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != CAPTURE_WIDTH || fmt.fmt.pix.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Warning: captured size %ux%u (requested %ux%d)\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height, CAPTURE_WIDTH, CAPTURE_HEIGHT);
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: device does not support YUYV\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Error: insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }
    buffer_length = buf.length;
    buffer_start = mmap(NULL, buffer_length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap");
        buffer_start = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int got_frame = 0;
    while (!g_stop && !got_frame) {
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }
        got_frame = 1;
    }
    if (g_stop) {
        fprintf(stderr, "Interrupted before frame capture\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF (after dequeue)");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        goto cleanup;
    }

    memset(&captured_fmt, 0, sizeof(captured_fmt));
    if (xioctl(fd, VIDIOC_QUERYFMT, &captured_fmt) == -1) {
        perror("VIDIOC_QUERYFMT");
        goto cleanup;
    }
    if (captured_fmt.fmt.pix.width != CAPTURE_WIDTH ||
        captured_fmt.fmt.pix.height != CAPTURE_HEIGHT ||
        captured_fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: captured format %ux%u YUYV (requested %ux%d)\n",
                captured_fmt.fmt.pix.width, captured_fmt.fmt.pix.height,
                CAPTURE_WIDTH, CAPTURE_HEIGHT);
    }

    out_file = fopen(OUTPUT_FILE, "wb");
    if (!out_file) {
        perror("fopen(" OUTPUT_FILE ")");
        goto cleanup;
    }

    int crop_left = CROP_LEFT;
    int crop_top = CROP_TOP;
    int crop_width = CROP_WIDTH;
    int crop_height = CROP_HEIGHT;
    if (captured_fmt.fmt.pix.width < crop_left + crop_width ||
        captured_fmt.fmt.pix.height < crop_top + crop_height) {
        fprintf(stderr, "Crop region exceeds captured size\n");
        goto cleanup;
    }

    size_t output_size = (size_t)crop_width * (size_t)crop_height * 2;
    unsigned char *output_buffer = malloc(output_size);
    if (!output_buffer) {
        perror("malloc");
        goto cleanup;
    }

    size_t yuyv_pitch = captured_fmt.fmt.pix.bytesperline;
    size_t yuyv_bytes = (size_t)captured_fmt.fmt.pix.width * (size_t)captured_fmt.fmt.pix.height * 2;
    size_t yuyv_remaining = yuyv_bytes;
    size_t output_index = 0;

    for (int y = crop_top; y < crop_top + crop_height && !g_stop; y++) {
        for (int x = crop_left; x < crop_left + crop_width && !g_stop; x++) {
            if (yuyv_remaining < yuyv_pitch) {
                fprintf(stderr, "Truncated frame capture\n");
                goto cleanup;
            }
            unsigned char *yuyv_ptr = (unsigned char *)(buffer_start + (yuyv_remaining - yuyv_pitch));
            for (int channel = 0; channel < 2; channel++) {
                unsigned char *src = yuyv_ptr + (size_t)x * 2 + (size_t)channel;
                unsigned char *dst = output_buffer + output_index;
                *dst = *src;
                output_index++;
            }
        }
    }

    if (output_index != output_size) {
        fprintf(stderr, "Short crop output (%zu bytes, expected %zu)\n", output_index, output_size);
        goto cleanup;
    }

    if (fwrite(output_buffer, 1, output_size, out_file) != (size_t)output_size) {
        perror("fwrite");
        goto cleanup;
    }

    printf("Cropped frame saved as %s (%zu bytes)\n", OUTPUT_FILE, output_size);
    ret = EXIT_SUCCESS;

cleanup:
    if (out_file) fclose(out_file);
    if (buffer_start && buffer_start != MAP_FAILED) munmap(buffer_start, buffer_length);
    if (fd != -1) close(fd);
    return ret;
}

