#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <ctype.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18

#define MIN_PULSE_WIDTH 500   /* microseconds for 0 degrees   */
#define MAX_PULSE_WIDTH 2500  /* microseconds for 180 degrees */
#define NEUTRAL_ANGLE   90
#define STEP_SIZE       5
#define DELAY_MS        100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Convert angle (0-180) to pulse width in microseconds. */
static int angle_to_pulse(int angle)
{
