#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_ADDR 0x3C
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int oled_command(int handle, unsigned char cmd) {
    char buf[2] = {0x00, (char)cmd};
    return i2cWriteDevice(handle, buf, 2);
}

static int oled_data(int handle, const unsigned char *data, int len) {
    char buf[1 + OLED_WIDTH * 8 / 8];
    if (len > (int)sizeof(buf)) len = (int)sizeof(buf);
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    return i2cWriteDevice(handle, buf, len + 1);
}

static int oled_init(int handle) {
    if (oled_command(handle, 0xAE) < 0) return -1;
    oled_command(handle, 0xD5); oled_command(handle, 0x80);
    oled_command(handle, 0xA8); oled_command(handle, 0x3F);
    oled_command(handle, 0xD3); oled_command(handle, 0x00);
    oled_command(handle, 0x40);
    oled_command(handle, 0x8D); oled_command(handle, 0x14);
    oled_command(handle, 0x20); oled_command(handle, 0x00);
    oled_command(handle, 0xA1);
    oled_command(handle, 0xC8);
    oled_command(handle, 0xDA); oled_command(handle, 0x12);
    oled_command(handle, 0xDB); oled_command(handle, 0x20);
    oled_command(handle, 0x81); oled_command(handle, 0x7F);
    oled_command(handle, 0xD9); oled_command(handle, 0xF1);
    oled_command(handle, 0xDB); oled_command(handle, 0x40);
    oled_command(handle, 0xA4);
    oled_command(handle, 0xA6);
    oled_command(handle, 0xAF);
    return 0;
}

static int oled_clear(int handle) {
    unsigned char blank[OLED_WIDTH * (OLED_HEIGHT / 8)];
    memset(blank, 0, sizeof(blank));
    return oled_data(handle, blank, sizeof(blank));
}

static int oled_set_cursor(int handle, int x, int y) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return -1;
    return oled_command(handle, 0xB0 + (y / 8));
}

static int oled_write_string(int handle, int x, int y, const char *str) {
    if (oled_set_cursor(handle, x, y) < 0) return -1;
    unsigned char buf[OLED_WIDTH * 8 / 8 + 1];
    buf[0] = 0x40;
    int len = strlen(str);
    if (len > (int)OLED_WIDTH) len = OLED_WIDTH;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (c < 32 || c > 126) c = 32;
        int idx = c - 32;
        if (idx > 63) idx = 63;
        for (int j = 0; j < 8; j++) {
            if (idx & (1 << (7 - j))) buf[i * 8 + j] = 0x7E;
            else buf[i * 8 + j] = 0x00;
        }
    }
    for (int i = len; i < OLED_WIDTH; i++) {
        for (int j = 0; j < 8; j++) buf[i * 8 + j] = 0x00;
    }
    return oled_data(handle, buf, sizeof(buf));
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) return -1;
    char buf[16];
    if (!fgets(buf, sizeof(buf), fp)) { fclose(fp); return -1; }
    fclose(fp);
    long raw = strtol(buf, NULL, 10);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int read_cpu_usage(float *usage) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1;
    char line[256];
    if (!fgets(line, sizeof(line), fp)) { fclose(fp); return -1; }
    fclose(fp);
    char *tokens[10];
    int count = 0;
    char *p = strtok(line, " ");
    while (p) { tokens[count++] = p; p = strtok(NULL, " "); }
    if (count < 2) return -1;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    for (int i = 0; i < 10; i++) {
        if (i == 2) user = strtoull(tokens[i], NULL, 10);
        else if (i == 3) nice = strtoull(tokens[i], NULL, 10);
        else if (i == 4) system = strtoull(tokens[i], NULL, 10);
        else if (i == 5) idle = strtoull(tokens[i], NULL, 10);
        else if (i == 6) iowait = strtoull(tokens[i], NULL, 10);
        else if (i == 7) irq = strtoull(tokens[i], NULL, 10);
        else if (i == 8) softirq = strtoull(tokens[i], NULL, 10);
        else if (i == 9) steal = strtoull(tokens[i], NULL, 10);
    }
    unsigned long long prev_idle = idle + iowait;
    sleep(1);
    FILE *fp2 = fopen("/proc/stat", "r");
    if (!fp2) { fclose(fp2); return -1; }
    char line2[256];
    if (!fgets(line2, sizeof(line2), fp2)) { fclose(fp2); return -1; }
    fclose(fp2);
    unsigned long long cur_idle = idle + iowait;
    unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
    unsigned long long cur_non_idle = 0;
    for (int i = 0; i < 10; i++) {
        if (i == 2) cur_non_idle += strtoull(tokens[i], NULL, 10);
        else if (i == 3) cur_non_idle += strtoull(tokens[i], NULL, 10);
        else if (i == 4) cur_non_idle += strtoull(tokens[i], NULL, 10);
        else if (i == 7) cur_non_idle += strtoull(tokens[i], NULL, 10);
        else if (i == 8) cur_non_idle += strtoull(tokens[i], NULL, 10);
        else if (i == 9) cur_non_idle += strtoull(tokens[i], NULL, 10);
    }
    unsigned long long cur_idle2 = idle + iowait;
    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long cur_total = cur_idle + cur_non_idle;
    unsigned long long totald = cur_total - prev_total;
    unsigned long long idled = cur_idle - prev_idle;
    if (totald == 0) return -1;
    *usage = (1.0f - (float)idled / (float)totald) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", OLED_ADDR);
        gpioTerminate();
        return 1;
    }

    if (oled_init(handle) < 0) {
        fprintf(stderr, "OLED initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float cpu_temp = -1.0f, cpu_usage = -1.0f;
        int temp_ok = (read_cpu_temp(&cpu_temp) == 0);
        int usage_ok = (read_cpu_usage(&cpu_usage) == 0);

        if (oled_clear(handle) < 0) {
            fprintf(stderr, "Failed to clear OLED\n");
            break;
        }

        if (oled_write_string(handle, 0, 0, "CPU Temp:") < 0) break;
        if (temp_ok) {
            char buf[16];
            snprintf(buf, sizeof(buf), "%.2f C", cpu_temp);
            if (oled_write_string(handle, 40, 0, buf) < 0) break;
        } else {
            if (oled_write_string(handle, 40, 0, "ERROR") < 0) break;
        }

        if (oled_write_string(handle, 0, 16, "CPU Usage:") < 0) break;
        if (usage_ok) {
            char buf[16];
            snprintf(buf, sizeof(buf), "%.2f%%", cpu_usage);
            if (oled_write_string(handle, 40, 16, buf) < 0) break;
        } else {
            if (oled_write_string(handle, 40, 16, "ERROR") < 0) break;
        }

        gpioDelay(1000000);
    }

    oled_clear(handle);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

