#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define LCD_ADDR 0x27

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x02
#define LCD_BLINKOFF 0x01

#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_ENTRYSHIFTINCREMENT 0x08

#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00
#define LCD_4BITMODE 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_nibble(int handle, uint8_t nibble, uint8_t rs) {
    uint8_t data = (nibble & 0xF0) | rs | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF;
    if (i2cWriteByte(handle, data) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int lcd_send_byte(int handle, uint8_t val, uint8_t rs) {
    if (lcd_write_nibble(handle, val & 0xF0, rs) < 0) return -1;
    if (lcd_write_nibble(handle, (val << 4) & 0xF0, rs) < 0) return -1;
    return 0;
}

static int lcd_command(int handle, uint8_t cmd) {
    return lcd_send_byte(handle, cmd, 0);
}

static int lcd_data(int handle, uint8_t data) {
    return lcd_send_byte(handle, data, LCD_ENTRYLEFT);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_write_nibble(handle, 0x30, 0) < 0) return -1;
    gpioDelay(5000);
    if (lcd_write_nibble(handle, 0x30, 0) < 0) return -1;
    gpioDelay(1000);
    if (lcd_write_nibble(handle, 0x30, 0) < 0) return -1;
    gpioDelay(1000);
    if (lcd_write_nibble(handle, 0x20, 0) < 0) return -1;
    gpioDelay(1000);

    if (lcd_command(handle, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    if (lcd_command(handle, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    if (lcd_command(handle, LCD_CLEARDISPLAY) < 0) return -1;
    gpioDelay(2000);
    if (lcd_command(handle, LCD_ENTRYMODESET | LCD_ENTRYLEFT) < 0) return -1;
    if (lcd_command(handle, LCD_SETDDRAMADDR | 0x00) < 0) return -1;
    return 0;
}

static int lcd_write_string(int handle, const char *str) {
    while (*str) {
        if (lcd_data(handle, (uint8_t)*str++) < 0) return -1;
    }
    return 0;
}

static int lcd_write_line(int handle, const char *line, int row) {
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    if (lcd_command(handle, LCD_SETDDRAMADDR | addr) < 0) return -1;
    if (lcd_write_string(handle, line) < 0) return -1;
    return 0;
}

static int lcd_update(int handle, const char *flow_rate, double volume) {
    if (lcd_command(handle, LCD_CLEARDISPLAY) < 0) return -1;
    gpioDelay(2000);
    if (lcd_write_line(handle, "Flow: ", 0) < 0) return -1;
    if (lcd_write_line(handle, flow_rate, 1) < 0) return -1;
    if (lcd_write_line(handle, "Vol:  ", 2) < 0) return -1;
    char vol_str[20];
    snprintf(vol_str, sizeof(vol_str), "%.2f L", volume);
    if (lcd_write_line(handle, vol_str, 3) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_command(i2c_handle, LCD_CLEARDISPLAY);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, LCD_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int pulse_count = 0;
    double total_volume = 0.0;
    time_t last_i2c_update = time(NULL);

    while (running) {
        int level = gpioRead(FLOW_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "GPIO read error on pin %d\n", FLOW_SENSOR_GPIO);
            gpioDelay(100000);
            continue;
        }

        if (level == 1) {
            pulse_count++;
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_i2c_update) >= 10.0) {
            double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0;
            total_volume += (double)pulse_count / PULSES_PER_LITER;
            pulse_count = 0;

            char flow_str[20];
            snprintf(flow_str, sizeof(flow_str), "%.2f L/min", flow_rate);

            if (lcd_update(i2c_handle, flow_str, total_volume) < 0) {
                fprintf(stderr, "LCD update failed\n");
            }
            last_i2c_update = current_time;
        }

        gpioDelay(1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

