#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LCD_ADDR 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ANEMOMETER_GPIO 17
#define PULSE_FACTOR 0.5
#define SAMPLE_INTERVAL_US 500000

static volatile int pulse_count = 0;
static volatile int running = 1;
static int spi_handle = -1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void lcd_write_nibble(unsigned char nibble) {
    if (i2cWriteByte(i2c_handle, nibble & 0xF0) < 0) return;
    gpioDelay(1000);
}

static void lcd_send_byte(unsigned char val, int is_data) {
    lcd_write_nibble(val & 0xF0);
    lcd_write_nibble((val << 4) & 0xF0);
    if (is_data) {
        gpioDelay(1000);
        unsigned char rs = is_data ? 0x01 : 0x00;
        if (i2cWriteByte(i2c_handle, rs) < 0) return;
        gpioDelay(1000);
    }
}

static void lcd_command(unsigned char cmd) { lcd_send_byte(cmd, 0); }
static void lcd_data(unsigned char data) { lcd_send_byte(data, 1); }

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_write_nibble(0x30); gpioDelay(5000);
    lcd_write_nibble(0x30); gpioDelay(1000);
    lcd_write_nibble(0x30); gpioDelay(1000);
    lcd_write_nibble(0x20); gpioDelay(1000);
    lcd_command(0x28);
    lcd_command(0x0C);
    lcd_command(0x06);
    lcd_command(0x01);
    gpioDelay(2000);
}

static void lcd_clear(void) { lcd_command(0x01); gpioDelay(2000); }

static void lcd_set_cursor(int row, int col) {
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_command(0x80 | addr);
}

static void lcd_print(const char *msg) {
    while (*msg) lcd_data((unsigned char)*msg++);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_print("Shutting down");
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (addr 0x%02X): %d\n", LCD_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    lcd_init();
    lcd_clear();

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        cleanup();
        return 1;
    }

    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses = pulse_count;
        float wind_speed = (float)pulses * PULSE_FACTOR;

        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "SPI transfer error reading wind vane\n");
            continue;
        }
        if (adc == 0 || adc == 1023) {
            fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc);
        }
        float wind_direction = (float)adc * 360.0f / 1024.0f;

        lcd_clear();
        lcd_set_cursor(0, 0);
        char buf[20];
        snprintf(buf, sizeof(buf), "Speed: %.1f m/s", wind_speed);
        lcd_print(buf);

        lcd_set_cursor(1, 0);
        snprintf(buf, sizeof(buf), "Dir: %.0f deg", wind_direction);
        lcd_print(buf);
    }

    cleanup();
    return 0;
}

