#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define PULSES_PER_LITER 7.5
#define SAMPLE_INTERVAL_SEC 1
#define ZERO_FLOW_TIMEOUT_SEC 5

static volatile int pulse_count = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_string(int handle, int col, int row, const char *str) {
    if (handle < 0) return -1;
    int addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    if (i2cWriteByte(handle, addr) < 0) return -1;
    for (int i = 0; str[i] != '\0'; i++) {
        if (i2cWrite(handle, (unsigned char)str[i]) < 0) return -1;
    }
    return 0;
}

static int lcd_init(int handle) {
    if (handle < 0) return -1;
    if (i2cWriteByte(handle, 0x33) < 0) return -1;
    if (i2cWriteByte(handle, 0x32) < 0) return -1;
    if (i2cWriteByte(handle, 0x28) < 0) return -1;
    if (i2cWriteByte(handle, 0x0C) < 0) return -1;
    if (i2cWriteByte(handle, 0x06) < 0) return -1;
    if (i2cWriteByte(handle, 0x01) < 0) return -1;
    return 0;
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cWriteByte(i2c_handle, 0x01);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", LCD_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to initialize LCD.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_flow_time = time(NULL);
    int zero_flow_count = 0;

    while (running) {
        time_t current_time = time(NULL);

        if (current_time - last_flow_time >= SAMPLE_INTERVAL_SEC) {
            int pulses = pulse_count;
            pulse_count = 0;
            last_flow_time = current_time;

            if (pulses == 0) {
                zero_flow_count++;
                if (zero_flow_count >= ZERO_FLOW_TIMEOUT_SEC) {
                    fprintf(stderr, "Warning: No flow detected for %d seconds. Check sensor connection.\n", ZERO_FLOW_TIMEOUT_SEC);
                    zero_flow_count = 0;
                }
            } else {
                zero_flow_count = 0;
                float flow_rate = (float)pulses / PULSES_PER_LITER * 60.0;

                char line1[LCD_WIDTH + 1];
                char line2[LCD_WIDTH + 1];
                snprintf(line1, sizeof(line1), "Flow Rate:");
                snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);

                if (lcd_write_string(i2c_handle, 0, 0, line1) < 0 ||
                    lcd_write_string(i2c_handle, 0, 1, line2) < 0) {
                    fprintf(stderr, "Error: Failed to write to LCD.\n");
                }
            }
        }

        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

