#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DELAY_US 800
#define NUM_ROWS 8
#define NUM_COLS 8

/* BCM GPIO pin numbers for rows (anodes) and columns (cathodes) */
static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void display_row(int row_idx, int *pattern) {
    for (int c = 0; c < NUM_COLS; c++) {
        if (gpiod_line_set_value(col_lines[c], 0) < 0) {
            perror("Failed to set column LOW");
        }
        if (row_idx >= 0 && row_idx < NUM_ROWS &&
            gpiod_line_set_value(row_lines[row_idx], 1) < 0) {
            perror("Failed to set row HIGH");
        }
        usleep(DELAY_US);
    }
    if (row_idx >= 0 && row_idx < NUM_ROWS) {
        if (gpiod_line_set_value(row_lines[row_idx], 0) < 0) {
            perror("Failed to reset row LOW");
        }
    }
}

static void left_to_right_wave(int *pattern) {
    for (int i = 0; i < NUM_ROWS && keep_running; i++) {
        display_row(i, pattern);
        for (int c = 0; c < NUM_COLS - 1 && keep_running; c++) {
            if (gpiod_line_set_value(col_lines[c], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c + 1], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("Failed to set row LOW");
        }
        for (int c = 0; c < NUM_COLS; c++) {
            if (gpiod_line_set_value(col_lines[c], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        for (int c = 0; c < NUM_COLS - 1 && keep_running; c++) {
            if (gpiod_line_set_value(col_lines[c], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c + 1], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("Failed to set row LOW");
        }
    }
}

static void right_to_left_wave(int *pattern) {
    for (int i = 0; i < NUM_ROWS && keep_running; i++) {
        display_row(i, pattern);
        for (int c = NUM_COLS - 2; c >= 0 && keep_running; c--) {
            if (gpiod_line_set_value(col_lines[c], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c + 1], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("Failed to set row LOW");
        }
        for (int c = NUM_COLS - 1; c >= 0 && keep_running; c--) {
            if (gpiod_line_set_value(col_lines[c], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        for (int c = NUM_COLS - 2; c >= 0 && keep_running; c--) {
            if (gpiod_line_set_value(col_lines[c], 0) < 0) {
                perror("Failed to set column LOW");
            }
            if (gpiod_line_set_value(row_lines[i], 1) < 0) {
                perror("Failed to set row HIGH");
            }
            usleep(DELAY_US);
            if (gpiod_line_set_value(col_lines[c + 1], 1) < 0) {
                perror("Failed to set column HIGH");
            }
            if (gpiod_line_set_value(row_lines[i], 0) < 0) {
                perror("Failed to set row LOW");
            }
            usleep(DELAY_US);
        }
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("Failed to set row LOW");
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (setup_gpio() < 0) {
        release_resources();
        return 1;
    }

    int pattern[NUM_ROWS];
    for (int i = 0; i < NUM_ROWS; i++) {
        pattern[i] = 0;
    }

    while (keep_running) {
        left_to_right_wave(pattern);
        if (!keep_running) break;
        for (int i = 0; i < NUM_ROWS; i++) {
            pattern[i] = !pattern[i];
        }
        right_to_left_wave(pattern);
        if (!keep_running) break;
        for (int i = 0; i < NUM_ROWS; i++) {
            pattern[i] = !pattern[i];
        }
    }

    release_resources();
    return 0;
}

