#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DELAY_MS 150
#define NUM_ROWS 8
#define NUM_COLS 8

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_set_value(col_lines[i], 1);
    }
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_set_value(row_lines[i], 0);
    }
}

static void draw_row(int row, int col) {
    for (int c = 0; c < NUM_COLS; c++) {
        gpiod_line_set_value(col_lines[c], 0);
    }
    for (int r = 0; r < NUM_ROWS; r++) {
        gpiod_line_set_value(row_lines[r], 0);
    }
    gpiod_line_set_value(row_lines[row], 1);
    gpiod_line_set_value(col_lines[col], 0);
    usleep(DELAY_MS * 1000);
    gpiod_line_set_value(col_lines[col], 1);
    for (int r = 0; r < NUM_ROWS; r++) {
        gpiod_line_set_value(row_lines[r], 0);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio() < 0) {
        release_resources();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        clear_matrix();
        for (int col = 0; col < NUM_COLS && keep_running; col++) {
            for (int row = 0; row < NUM_ROWS && keep_running; row++) {
                draw_row(row, col);
            }
        }
    }

    clear_matrix();
    release_resources();
    return EXIT_SUCCESS;
}

