/*
 * VL53L3CX multi-target Time-of-Flight sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a complex proprietary firmware download and
 * initialization sequence (ST Ultra Lite Driver / ULD). This example
 * stubs the firmware download with a placeholder comment and fully
 * implements the I2C communication, error handling, and application logic.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO 2 (I2C bus 1 SDA)
 *   VL53L3CX SCL -> GPIO 3 (I2C bus 1 SCL)
 *   VL53L3CX VDD -> 3.3 V
 *   VL53L3CX GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C default address ---- */
#define VL53L3CX_ADDR 0x29

/* ---- STUUB: VL53L3CX proprietary firmware download (placeholder) ---- */
/*
 * In a real deployment, the ST Ultra Lite Driver (ULD) performs the
 * firmware download from a specific register map. This section is a
 * placeholder that writes a magic word to the sensor to indicate
 * that firmware has been loaded.
 */
#define VL53L3CX_SOFT_RESET_GO2_REG 0x0000
#define VL53L3CX_SOFT_RESET_GO2_MAGIC 0x00
#define VL53L3CX_SOFT_RESET_GO2_CMD 0x01

/* ---- Application constants ---- */
#define I2C_BUS 1
#define POLL_DELAY_US 100000  /* 100 ms */
#define MAX_TARGETS 10

/* ---- Data structure for a detected target ---- */
typedef struct {
    uint16_t distance_mm;
    uint8_t  peak_signal_count_rate_rtn;
    uint8_t  ambient_count_rate_rtn;
} TargetData;

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler for graceful shutdown ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

/*
 * Write a 16-bit register address and an 8-bit value.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/*
 * Read an 8-bit value from a 16-bit register address.
 * Returns 0 on success and stores the value in *value, -1 on failure.
 */
static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit register address.
 * Returns 0 on success and stores the value in *value, -1 on failure.
 */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ---- Sensor initialization ---- */
static int init_vl53l3cx(int handle) {
    uint8_t model_id = 0;

    /* Read model ID to verify sensor presence */
    if (i2c_read_reg8(handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    /*
     * STUB: Perform the proprietary firmware download and configuration
     * using the ST Ultra Lite Driver (ULD).
     *
     * In a real deployment, this involves writing specific registers,
     * waiting for the sensor to boot, and verifying configuration.
     */
    printf("VL53L3CX detected (Model ID: 0x%02X). Initializing...\n", model_id);

    /*
     * STUB: Trigger firmware download by writing the magic word to
     * the soft reset register. This is a placeholder; the actual
     * sequence is complex and requires the ST ULD.
     */
    if (i2c_write_reg8(handle, VL53L3CX_SOFT_RESET_GO2_REG, VL53L3CX_SOFT_RESET_GO2_MAGIC) < 0) {
        fprintf(stderr, "Error: Failed to trigger firmware download.\n");
        return -1;
    }

    /*
     * STUB: Wait for firmware download to complete.
     * In a real deployment, this involves polling the sensor status.
     */
    gpioDelay(100000); /* 100 ms */

    printf("Firmware download complete. Starting measurements...\n");
    return 0;
}

/* ---- Read all detected targets ---- */
static int read_targets(int handle, TargetData *targets, int max_targets) {
    uint8_t num_targets = 0;
    uint8_t data_ready = 0;

    /*
     * Check if data is ready. This is a placeholder; the actual
     * register and bit field depend on the ST ULD configuration.
     */
    if (i2c_read_reg8(handle, 0x0014, &data_ready) < 0) {
        return -1;
    }
    if ((data_ready & 0x01) == 0) {
        return 0; /* No new data yet */
    }

    /*
     * Read the number of detected targets. This is a placeholder;
     * the actual register and bit field depend on the ST ULD.
     */
    if (i2c_read_reg8(handle, 0x0016, &num_targets) < 0) {
        return -1;
    }

    if (num_targets > max_targets) {
        num_targets = max_targets;
    }

    /*
     * Read distance and signal metrics for each target.
     * This is a placeholder; the actual registers and data layout
     * depend on the ST ULD.
     */
    for (uint8_t i = 0; i < num_targets; i++) {
        uint16_t dist_reg = 0x0018 + (i * 4);
        if (i2c_read_reg16(handle, dist_reg, &targets[i].distance_mm) < 0) {
            return -1;
        }
        /*
         * STUB: Read peak and ambient signal counts.
         * In a real deployment, read the specific registers.
         */
        if (i2c_read_reg8(handle, dist_reg + 2, &targets[i].peak_signal_count_rate_rtn) < 0) {
            return -1;
        }
        if (i2c_read_reg8(handle, dist_reg + 3, &targets[i].ambient_count_rate_rtn) < 0) {
            return -1;
        }
    }

    return num_targets;
}

/* ---- Log data with ISO-8601 timestamp ---- */
static void log_data(const TargetData *targets, int num_targets) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Targets: %d\n", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("  Target %d: Distance = %u mm, Peak = %u, Ambient = %u\n",
               i + 1, targets[i].distance_mm,
               targets[i].peak_signal_count_rate_rtn,
               targets[i].ambient_count_rate_rtn);
    }
}

/* ---- Main ---- */
int main(void) {
    TargetData targets[MAX_TARGETS];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L3CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l3cx(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX reader started. Press Ctrl+C to stop.\n");

    /* Main polling loop */
    while (g_running) {
        int num_targets = read_targets(g_i2c_handle, targets, MAX_TARGETS);
        if (num_targets < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        } else if (num_targets > 0) {
            log_data(targets, num_targets);
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Resources released. Goodbye.\n");

    return EXIT_SUCCESS;
}

