#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_IRQ_STATUS 0x21
#define REG_IRQ_ENABLE 0x0F
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_RATE   0x0A
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0   0x26
#define REG_PS1_DATA1   0x27
#define REG_COMMAND     0x18

#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06
#define CMD_PSALS_FORCE 0x07
#define CMD_PS_PAUSE    0x0B
#define CMD_ALS_PAUSE   0x0E
#define CMD_PSALS_PAUSE 0x0F
#define CMD_PS_AUTO     0x0D
#define CMD_ALS_AUTO    0x0C
#define CMD_PSALS_AUTO  0x0A

#define EXPECTED_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_lo, uint16_t *val)
{
    uint8_t lo, hi;
    if (read_reg(reg_lo, &lo) < 0) return -1;
    if (read_reg(reg_lo + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void)
{
    uint8_t part_id;

    if (read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART ID 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART ID 0x%02X)\n", part_id);

    /* Reset */
    if (write_reg(REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Write HW_KEY = 0x17 (required for correct operation) */
    if (write_reg(REG_HW_KEY, 0x17) < 0) return -1;

    /* Clear any pending IRQ */
    if (write_reg(REG_IRQ_STATUS, 0x00) < 0) return -1;

    /* Measurement rate: 0x00 = 1 measurement per force/auto cycle */
    if (write_reg(REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(REG_ALS_RATE, 0x00) < 0) return -1;

    /* Enable IRQ on ALS_VIS data ready */
    if (write_reg(REG_IRQ_ENABLE, 0x01) < 0) return -1;

    /* Start autonomous PS+ALS measurement */
    if (write_reg(REG_COMMAND, CMD_PSALS_AUTO) < 0) return -1;

    return 0;
}

static void log_data(uint16_t als, uint16_t ps1)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(log_file, "%s, ALS_VIS=%u, PS1=%u\n", ts, als, ps1);
    fflush(log_file);
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (!terminate) {
        uint16_t als = 0, ps1 = 0;

        if (read_word(REG_ALS_VIS_DATA0, &als) < 0 ||
            read_word(REG_PS1_DATA0, &ps1) < 0) {
            fprintf(stderr, "Read error - continuing\n");
        } else {
            log_data(als, ps1);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
