#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  4
#define LED_PIN     17
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define BLINK_MS    100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("gmtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s %s\n", ts, msg) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose log");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        perror("gpiod_chip_get_line sensor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line led");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk") < 0) {
        perror("gpiod_line_request_input sensor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "e18-d50nk", 0) < 0) {
        perror("gpiod_line_request_output led");
        gpiod_line_release(sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring E18-D50NK on GPIO%d, LED on GPIO%d. Ctrl+C to exit.\n",
           SENSOR_PIN, LED_PIN);

    int prev_state = 1;  /* assume no object at startup (HIGH) */
    int first_read = 1;

    while (running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value sensor");
            break;
        }

        if (first_read) {
            prev_state = val;
            first_read = 0;
        }

        /* Detect HIGH -> LOW transition: object entering range */
        if (prev_state == 1 && val == 0) {
            if (log_event("Object detected") == 0) {
                printf("Object detected — logged.\n");
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }
            /* Blink LED */
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value led on");
                break;
            }
            usleep(BLINK_MS * 1000);
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value led off");
                break;
            }
        }

        prev_state = val;
        usleep(POLL_MS * 1000);
    }

    /* Cleanup */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

