#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 30
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define WATERING_THRESHOLD_CM 15.0
#define POLL_INTERVAL_S 60
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (trigger_line) {
        gpiod_line_set_value(trigger_line, 0);
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(TRIGGER_PULSE_US);
    gpiod_line_set_value(trigger_line, 0);
}

static double measure_distance(void) {
    struct timespec start, end;
    long long elapsed_ns;
    int ret;

    trigger_sensor();

    /* Wait for echo rising edge */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, ECHO_TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        log_message("Error: echo rising edge wait failed");
        return -1.0;
    }
    if (ret == 0) {
        log_message("Error: echo never rose (sensor absent or not responding)");
        return -1.0;
    }

    ret = gpiod_line_event_read(echo_line, &end);
    if (ret < 0) {
        log_message("Error: echo read failed");
        return -1.0;
    }

    /* Wait for echo falling edge */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, ECHO_TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        log_message("Error: echo falling edge wait failed");
        return -1.0;
    }
    if (ret == 0) {
        log_message("Error: echo stuck high (timeout)");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, ECHO_TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        log_message("Error: echo timeout wait failed");
        return -1.0;
    }
    if (ret == 0) {
        log_message("Error: echo timeout (no falling edge)");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    double pulse_seconds = (double)elapsed_ns / 1000000000.0;

    double distance = (pulse_seconds * 34300.0) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Warning: distance out of range (%.2f cm)", distance);
        log_message(msg);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_gpio() < 0) {
        log_message("Error: GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_message("Program started");

    while (program_running) {
        double distance = measure_distance();

        if (distance < 0) {
            log_message("Error: distance measurement failed");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_message(msg);

            if (distance < WATERING_THRESHOLD_CM) {
                log_message("Time to water the plant!");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program exiting");
    cleanup();
    return 0;
}

