#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x39
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_EXPECTED_ID 0xAB
#define APDS9960_ENABLE_PON 0x01
#define APDS9960_ENABLE_AEN 0x02
#define APDS9960_ENABLE_PEN 0x04
#define APDS9960_ENABLE_WEN 0x08
#define APDS9960_ENABLE_AIEN 0x10
#define APDS9960_CONFIG2_AEN 0x01
#define APDS9960_PROX_TH0 0x94
#define APDS9960_PROX_TH1 0x95
#define APDS9960_PTIME 0x96
#define APDS9960_CONTROL_AEN 0x02
#define APDS9960_CONFIG2_AEN 0x01
#define APDS9960_PTIME_DEFAULT 0xF6
#define APDS9960_PPULSE_DEFAULT 0x87
#define APDS9960_ATIME_DEFAULT 0xDB
#define APDS9960_WTIME_DEFAULT 0xF6
#define APDS9960_ID_DEFAULT 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE_NAME "color_proximity_log.csv"
#define I2C_BUS 1
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_apds9960(int handle) {
    uint8_t id = 0;
    if (read_register(handle, APDS9960_ID, &id) < 0) return -1;
    if (id != APDS9960_EXPECTED_ID) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0x%02X)\n", id, APDS9960_EXPECTED_ID);
        return -1;
    }
    if (write_register(handle, APDS9960_ENABLE, APDS9960_ENABLE_PON) < 0) return -1;
    gpioDelay(10000);
    if (write_register(handle, APDS9960_ATIME, APDS9960_ATIME_DEFAULT) < 0) return -1;
    if (write_register(handle, APDS9960_WTIME, APDS9960_WTIME_DEFAULT) < 0) return -1;
    if (write_register(handle, APDS9960_PPULSE, APDS9960_PPULSE_DEFAULT) < 0) return -1;
    if (write_register(handle, APDS9960_CONTROL, APDS9960_CONTROL_AEN) < 0) return -1;
    if (write_register(handle, APDS9960_CONFIG2, APDS9960_CONFIG2_AEN) < 0) return -1;
    if (write_register(handle, APDS9960_ENABLE, APDS9960_ENABLE_PON | APDS9960_ENABLE_AEN | APDS9960_ENABLE_PEN) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_apds9960_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    uint8_t red_l, red_h, green_l, green_h, blue_l, blue_h, prox;
    if (read_register(handle, APDS9960_PTIME, &prox) < 0) return -1;
    if (read_register(handle, APDS9960_PTIME + 1, &prox) < 0) return -1;
    *proximity = prox;
    if (read_register(handle, APDS9960_PTIME + 2, &red_l) < 0) return -1;
    if (read_register(handle, APDS9960_PTIME + 3, &red_h) < 0) return -1;
    *red = (uint16_t)((red_h << 8) | red_l);
    if (read_register(handle, APDS9960_PTIME + 4, &green_l) < 0) return -1;
    if (read_register(handle, APDS9960_PTIME + 5, &green_h) < 0) return -1;
    *green = (uint16_t)((green_h << 8) | green_l);
    if (read_register(handle, APDS9960_PTIME + 6, &blue_l) < 0) return -1;
    if (read_register(handle, APDS9960_PTIME + 7, &blue_h) < 0) return -1;
    *blue = (uint16_t)((blue_h << 8) | blue_l);
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            red, green, blue, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (initialize_apds9960(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        cleanup();
        return 1;
    }
    fprintf(log_file, "# timestamp,red,green,blue,proximity\n");
    fflush(log_file);
    while (!terminate) {
        uint16_t red, green, blue;
        uint8_t proximity;
        if (read_apds9960_data(i2c_handle, &red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(log_file, red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "I2C communication error. Re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1;
            } else if (initialize_apds9960(i2c_handle) < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                terminate = 1;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }
    cleanup();
    return 0;
}

