#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A

#define REG_PART_ID    0x00
#define REG_MEAS_RATE0 0x08
#define REG_PS_DATA0   0x24
#define REG_PS_DATA1   0x25
#define REG_COMMAND    0x47

#define CMD_RESET      0x01
#define CMD_START      0x02

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    int rc = i2c_smbus_read_byte_data(fd, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    int rc = i2c_smbus_write_byte_data(fd, reg, val);
    if (rc < 0) return -1;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1182_reset(int fd) {
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    usleep(10000);
    return 0;
}

static int si1182_start(int fd) {
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_START) < 0) return -1;
    usleep(10000);
    return 0;
}

static int si1182_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: failed to read PART_ID register: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    if (si1182_reset(fd) < 0) {
        fprintf(stderr, "Error: reset failed: %s\n", strerror(errno));
        return -1;
    }
    if (si1182_start(fd) < 0) {
        fprintf(stderr, "Error: start command failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si1182_read_proximity(int fd, uint16_t *prox) {
    if (i2c_read_reg16_le(fd, REG_PS_DATA0, prox) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u\n", ts, prox) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE 0x%02X failed: %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (si1182_init(fd) < 0) {
        close(fd);
        return 1;
    }

    FILE *fp = fopen("heartrate.csv", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open heartrate.csv: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Logging heart rate data to heartrate.csv. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t prox;
        if (si1182_read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read error: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        if (log_data(fp, prox) < 0) {
            fprintf(stderr, "Warning: file write error: %s\n", strerror(errno));
        }

        usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
}

