#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define TRIGGER_PIN 17

#define REG_SYSRANGE_START 0x00
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, want=%u, got=%d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_byte(handle, 0x01, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register (sensor absent or bus error)\n");
        return -1;
    }
    if (who_am_i != 0xEA) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0xEA\n", who_am_i);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    uint8_t data[14] = {0};

    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        if (i2c_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000);
        if (i == 99) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, data, 14) != 0) {
        return -1;
    }

    if (data[0] & 0x01) {
        fprintf(stderr, "Range measurement indicates error\n");
        return -1;
    }

    *distance_mm = (uint16_t)((data[10] << 8) | data[11]);

    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L0X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurements on GPIO %d. Press Ctrl+C to exit.\n", TRIGGER_PIN);

    while (running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            uint16_t distance_mm = 0;
            if (vl53l0x_read_distance(i2c_handle, &distance_mm) == 0) {
                log_distance(log_file, distance_mm);
                printf("Distance: %u mm\n", distance_mm);
            } else {
                fprintf(stderr, "Failed to read distance\n");
            }
        }
        gpioDelay(10000);
    }

