#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_REG    0x00
#define DISTANCE_REG   0x02
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      200000   /* 200 ms between samples */
#define MEASURE_US     50000    /* 50 ms measurement wait */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Build a 'YYYY-MM-DD HH:MM:SS' timestamp into the fixed-size buf.
 * Returns 0 on success, -1 on error.
 */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info) == 0)
        return -1;

    return 0;
}

/*
 * Trigger a measurement and read the 16-bit distance (mm) from the CH101.
 * Returns 0 on success and stores the distance in *out_mm; -1 on error.
 */
static int read_distance(int handle, int *out_mm)
{
    char trigger = 0x01;
    char data[2];
    int  rc;

    /* Trigger a single measurement */
    rc = i2cWriteDevice(handle, &trigger, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (trigger): %d\n", rc);
        return -1;
    }

    /* Wait for the conversion to complete (~50 ms) */
    gpioDelay(MEASURE_US);

    /* Read 2 bytes from the distance register */
    rc = i2cReadI2CBlockData(handle, DISTANCE_REG, data, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (distance): rc=%d\n", rc);
        return -1;
    }

    /* CH101 returns distance in mm, big-endian */
    *out_mm = ((int)(data[0] & 0xFF) << 8) | (int)(data[1] & 0xFF);
    return 0;
}

static int log_distance(FILE *fp, int distance_mm)
{
    char ts[32];

    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    printf("%s, %d mm\n", ts, distance_mm);
    return 0;
}

int main(void)
{
    int handle = -1;
    FILE *fp = NULL;
    int  distance_mm;
    int  rc;

    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to CH101 --- */
    handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, CH101_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH101 distance logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_distance(handle, &distance_mm) == 0) {
            if (log_distance(fp, distance_mm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep 200 ms, but wake early if a signal arrives */
        for (int i = 0; i < 20 && g_running; i++)
            gpioDelay(10000);  /* 10 ms slices */
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (fp != NULL)
        fclose(fp);
    if (handle >= 0)
        i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

