#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define ALS_DATA_REG 0x16
#define PS_DATA_REG 0x18
#define RETRY_COUNT 3
#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register_retry(int handle, uint8_t reg, uint16_t *value) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, RETRY_COUNT, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Si1182 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;

        if (read_register_retry(i2c_handle, ALS_DATA_REG, &ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light data after %d retries.\n", RETRY_COUNT);
            gpioDelay(500000);
            continue;
        }

        if (read_register_retry(i2c_handle, PS_DATA_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
            gpioDelay(500000);
            continue;
        }

        if (log_data(log_file, proximity, ambient_light) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        gpioDelay(500000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

