#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define DEFAULT_THRESHOLD 100
#define POLL_DELAY_US 50000

#define REG_WHO_AM_I 0x00
#define REG_DISTANCE 0x04
#define REG_CONFIG 0x05

#define WHO_AM_I_EXPECTED 0x6A

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting read reg 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int init_sensor(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(REG_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_EXPECTED);
        return -1;
    }
    printf("Sensor detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    if (i2c_write_reg(REG_CONFIG, 0x01) != 0) {
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t raw = 0;
    if (i2c_read_reg(REG_DISTANCE, &raw) != 0) {
        return -1;
    }
    *distance = (uint16_t)raw;
    return 0;
}

static void log_data(uint16_t distance, int threshold_exceeded) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Threshold Exceeded: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, threshold_exceeded ? "YES" : "NO");
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold. Using default value: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            int threshold_exceeded = (distance < threshold) ? 1 : 0;
            gpioWrite(LED_GPIO, threshold_exceeded);
            log_data(distance, threshold_exceeded);
            printf("Distance: %u mm, Threshold Exceeded: %s\n", distance, threshold_exceeded ? "YES" : "NO");
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

