#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define B5L_I2C_ADDR 0x50
#define NUM_SAMPLES 10
#define INTRUSION_THRESHOLD_MM 1000
#define LOG_FILE "intrusion_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define CYCLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_bytes(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_bytes(fd, cmd, sizeof(cmd)) != 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, resp, sizeof(resp)) != 0) {
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X\n", resp[0]);
        return -1;
    }

    *distance_mm = (int16_t)((resp[11] << 8) | resp[12]);
    return 0;
}

static void log_intrusion(int avg_distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Average Distance: %d mm\n", timestamp, avg_distance_mm);
    fclose(fp);
}

int main(void) {
    int fd = -1;
    int distance_mm;
    int sum = 0;
    int samples_valid = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, B5L_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to slave");
        close(fd);
        return 1;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int valid = 0;
        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            if (read_distance(fd, &distance_mm) == 0) {
                sum += distance_mm;
                valid++;
            } else {
                fprintf(stderr, "Error reading distance sample %d\n", i + 1);
            }
            usleep(CYCLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg_distance_mm = sum / valid;
            printf("Average distance: %d mm\n", avg_distance_mm);

            if (avg_distance_mm < INTRUSION_THRESHOLD_MM) {
                log_intrusion(avg_distance_mm);
                printf("Intrusion detected!\n");
            }
        }
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

