#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR 0x29
#define I2C_BUS 1

#define REG_SYSRANGE_START 0x00
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_MODEL_ID 0xC0

#define EXPECTED_MODEL_ID 0xEE

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)(((uint8_t)data_buf[1] << 8) | (uint8_t)data_buf[0]);
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read model ID - sensor may be absent or bus error.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (i2c_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000);
        if (i == 99) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            return -1;
        }
    }

    uint16_t raw = 0;
    if (i2c_read_word(handle, REG_RESULT_RANGE_STATUS, &raw) != 0) {
        return -1;
    }

    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    *distance_mm = raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance readings every 500 ms (Ctrl+C to exit)...\n");

    while (g_running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        uint16_t distance = 0;
        if (vl53l0x_read_distance(handle, &distance) == 0) {
            printf("%s Distance: %u mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "%s Error reading distance.\n", timestamp);
        }
        fflush(stdout);

        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

