static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int si1182_write(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int si1182_init(int handle) {
    if (si1182_write(handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0) return -1;
    if (si1182_write(handle, SI1182_REG_CONFIG, SI1182_CONFIG_PROX) < 0) return -1;
    return 0;
}

