    int rc = i2cReadByteData(handle, SI1182_REG_IRQ);
    if (rc < 0) {
        fprintf(stderr, "I2C read IRQ failed: %d\n", rc);
        return -1;
    }
    return (rc & 0x01) ? 1 : 0;
}

static int si1182_read_proximity(int handle, uint16_t *prox) {
    int lsb = i2cReadByteData(handle, SI1182_REG_PROX_LSB);
    if (lsb < 0) {
        fprintf(stderr, "I2C read PROX_LSB failed: %d\n", lsb);
        return -1;
    }
    int msb = i2cReadByteData(handle, SI1182_REG_PROX_MSB);
    if (msb < 0) {
        fprintf(stderr, "I2C read PROX_MSB failed: %d\n", msb);
        return -1;
    }
    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

