            gpioDelay(50000);
            continue;
        }

        printf("Proximity: %u\n", prox);
        gpioDelay(500000);
    }

    printf("\nExiting...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

