#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DISTANCE_REG   0x00
#define SCALE_FACTOR   0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = MLX75030_ADDR;
    msgs[0].flags = 0;            /* write */
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = MLX75030_ADDR;
    msgs[1].flags = I2C_M_RD;     /* read */
    msgs[1].len   = 2;
    msgs[1].buf   = buf;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0)
        return -1;

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try a zero-length write to confirm the device is present */
    uint8_t probe = 0x00;
    struct i2c_msg msg = {
        .addr  = MLX75030_ADDR,
        .flags = 0,
        .len   = 0,
        .buf   = &probe,
    };
    struct i2c_rdwr_ioctl_data data = {
        .msgs  = &msg,
        .nmsgs = 1,
    };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Error: MLX75030 not responding at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        uint16_t raw = 0;

        if (i2c_read_reg16(fd, DISTANCE_REG, &raw) < 0) {
            fprintf(stderr, "Error reading distance register: %s\n",
                    strerror(errno));
        } else {
            float distance_mm = (float)raw * SCALE_FACTOR;
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        }

        /* Sleep 500 ms; interruptible by signals so we can exit promptly */
        struct timespec ts = {
            .tv_sec  = POLL_MS / 1000,
            .tv_nsec = (POLL_MS % 1000) * 1000000L,
        };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

