#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_CH0_DISTANCE 0x00
#define REG_CH0_AMBIENT 0x02
#define REG_CH0_ERROR 0x04
#define REG_CH0_CONFIG 0x06

#define CONFIG_DEFAULT 0x0000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_register(int handle, uint8_t reg, uint16_t *value) {
    int data = i2cReadWordData(handle, reg);
    if (data < 0) {
        return -1;
    }
    *value = (uint16_t)data;
    return 0;
}

int write_register(int handle, uint8_t reg, uint16_t value) {
    int result = i2cWriteWordData(handle, reg, value);
    if (result < 0) {
        return -1;
    }
    return 0;
}

int read_distance(int handle, uint16_t *distance) {
    return read_register(handle, REG_CH0_DISTANCE, distance);
}

int read_ambient_light(int handle, uint16_t *ambient) {
    return read_register(handle, REG_CH0_AMBIENT, ambient);
}

int read_error_flags(int handle, uint16_t *error_flags) {
    return read_register(handle, REG_CH0_ERROR, error_flags);
}

int configure_sensor(int handle) {
    return write_register(handle, REG_CH0_CONFIG, CONFIG_DEFAULT);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Error configuring sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting OPT3101 readings (Ctrl+C to exit)...\n");

    while (running) {
        uint16_t distance, ambient, error_flags;

        if (read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else if (read_ambient_light(i2c_handle, &ambient) < 0) {
            fprintf(stderr, "Error reading ambient light\n");
        } else if (read_error_flags(i2c_handle, &error_flags) < 0) {
            fprintf(stderr, "Error reading error flags\n");
        } else {
            printf("Distance: %u, Ambient: %u, Error: %u\n", distance, ambient, error_flags);
        }

        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

