/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained; NOT wiringPi)
 *
 * Wiring:
 *   HC-SR04 VCC  -> Pi 5V  (Pin 2 or 4)
 *   HC-SR04 GND  -> Pi GND  (Pin 6)
 *   HC-SR04 TRIG -> Pi GPIO17 (Pin 11, BCM 17)
 *   HC-SR04 ECHO -> Pi GPIO18 (Pin 12, BCM 18) via 1 kOhm resistor
 *
 * The HC-SR04 operates at 5V; the Pi GPIO pins are 3.3V tolerant.
 * The resistor on the echo line protects the sensor from excessive current
 * and adapts the 5V echo signal to a level the Pi can read.
 *
 * Build: gcc -Wall -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 microsecond trigger pulse       */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo edges      */
#define MAX_PULSE_US     38000       /* ~3.8 m round-trip max (343 m/s)    */
#define SAMPLE_PERIOD_US 1000000     /* 1 second between readings          */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * pigpio's gpioTick() returns a 32-bit microsecond counter that wraps
 * every ~71.6 minutes.  The difference between two gpioTick() values
 * is always correct (wraps correctly on overflow), so (b - a) gives the
 * elapsed microseconds accurately.
 */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction handles wraparound */
}

/*
 * Send a 10 microsecond trigger pulse.
 * Returns 0 on success, -1 on write failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in microseconds
 *   -1.0 : echo rising-edge timeout
 *   -2.0 : echo falling-edge timeout
 *   -3.0 : invalid (pulse width <= 0 or > MAX_PULSE_US)
 */
static double measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* --- Wait for echo rising edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1.0;  /* timeout waiting for echo start */
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -2.0;  /* timeout waiting for echo end */
    }
    end_tick = gpioTick();

    double pulse_us = (double)tick_diff(start_tick, end_tick);

    if (pulse_us <= 0.0 || pulse_us > MAX_PULSE_US)
        return -3.0;  /* invalid or out-of-range */

    return pulse_us;
}

/*
 * Convert pulse width (microseconds) to distance (centimetres).
 * Formula: distance_cm = (pulse_us * 0.0343) / 2
 *          (round trip: t = 2*d/34300, t = pulse_us/1000000, d = t*34300/2)
 */
static double pulse_us_to_cm(double pulse_us)
{
    return (pulse_us * 0.0343) / 2.0;
}

/*
 * Print a timestamped distance reading to stdout.
 */
static void log_distance(double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        fprintf(stderr, "       Run as root (sudo) and ensure pigpiod is not running.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(500000);  /* 500 ms */

    install_signal_handlers();

    printf("HC-SR04 distance sensor started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        if (trigger_sensor() != 0) {
            /* Trigger failure - wait and retry */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pulse_us = measure_echo_pulse();

        if (pulse_us < 0.0) {
            /* Timeout or invalid reading */
            if (pulse_us == -1.0)
                fprintf(stderr, "Warning: echo rising-edge timeout\n");
            if (pulse_us == -2.0)
                fprintf(stderr, "Warning: echo falling-edge timeout\n");
            if (pulse_us == -3.0)
                fprintf(stderr, "Warning: invalid pulse width (%.0f us)\n",
                        pulse_us);
        } else {
            double distance_cm = pulse_us_to_cm(pulse_us);
            log_distance(distance_cm);
        }

        /* Wait ~1 second between samples */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");

    return EXIT_SUCCESS;
}

