#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define FRAME_SIZE (NUM_RANGE_BINS * 2)
#define MAGIC_WORD_SIZE 8
#define LOG_FILE "intrusion_log.csv"

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_frame(int fd, uint8_t *buffer, size_t expected_size) {
    size_t total_read = 0;
    while (total_read < expected_size) {
        ssize_t bytes_read = read(fd, buffer + total_read, expected_size - total_read);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("Error reading from UART");
            return -1;
        } else if (bytes_read == 0) {
            fprintf(stderr, "UART read returned 0 bytes (sensor absent?)\n");
            return -1;
        }
        total_read += bytes_read;
    }
    return 0;
}

static int process_frame(const uint8_t *frame, float *range_profile) {
    if (memcmp(frame, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Invalid frame header (magic word mismatch)\n");
        return -1;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        range_profile[i] = (float)((uint16_t)frame[2 * i]) | ((float)((uint16_t)frame[2 * i + 1]) << 8);
    }
    return 0;
}

static int detect_intrusion(const float *range_profile, float threshold) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (range_profile[i] > 0 && range_profile[i] < threshold) {
            return 1;
        }
    }
    return 0;
}

static void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(2000000);
    gpioWrite(gpio_pin, 0);
}

static void log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        fprintf(fp, "%s,%.2f\n", timestamp, distance);
    } else {
        fprintf(fp, "TIMESTAMP_ERROR,%.2f\n", distance);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t frame_buffer[FRAME_SIZE];
    float range_profile[NUM_RANGE_BINS];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_uart_frame(uart_fd, frame_buffer, FRAME_SIZE) != 0) {
            fprintf(stderr, "UART read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (process_frame(frame_buffer, range_profile) != 0) {
            fprintf(stderr, "Frame processing error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (detect_intrusion(range_profile, INTRUSION_THRESHOLD)) {
            float min_distance = INTRUSION_THRESHOLD;
            int index = -1;
            for (int i = 0; i < NUM_RANGE_BINS; i++) {
                if (range_profile[i] > 0 && range_profile[i] < min_distance) {
                    min_distance = range_profile[i];
                    index = i;
                }
            }

            if (index != -1) {
                printf("Intrusion detected! Target at range bin %d (%%.2f meters)\n", index, index * RANGE_RESOLUTION);
                trigger_alert(GPIO_LED);
                log_intrusion(index * RANGE_RESOLUTION);
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioTerminate();
    return 0;
}

