#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line sensor");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line buzzer");
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "e18-d80nk-sensor") < 0) {
        perror("gpiod_line_request_input sensor");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "e18-d80nk-buzzer", 0) < 0) {
        perror("gpiod_line_request_output buzzer");
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");
    log_event("Program started");

    int last_state = -1;

    while (program_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            perror("gpiod_line_get_value sensor");
            log_event("Error reading sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int obstacle = (val == 0);

        if (gpiod_line_set_value(buzzer_line, obstacle ? 1 : 0) < 0) {
            perror("gpiod_line_set_value buzzer");
            log_event("Error writing buzzer");
        }

        if (obstacle && !last_state) {
            log_event("Obstacle detected");
        } else if (!obstacle && last_state) {
            log_event("Obstacle removed");
        }
        last_state = obstacle;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("gpiod_line_set_value buzzer off");
    }
    log_event("Program stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (sensor_line) gpiod_line_release(sensor_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

