static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", ALERT_PIN);
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO %d low\n", ALERT_PIN);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_out) {
    int high = i2cReadByteData(g_i2c_handle, DIST_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading high byte of distance: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(g_i2c_handle, DIST_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading low byte of distance: %d\n", low);
        return -1;
    }
    uint16_t raw = ((uint16_t)high << 8) | (uint16_t)low;
    *distance_out = (float)raw / 10.0f;
    return 0;
}

