    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(fp, "(timestamp error), Distance: %.2f cm\n", distance);
    }
    fclose(fp);
}

static void trigger_alert(float distance) {
    if (distance < DIST_THRESHOLD) {
        gpioWrite(ALERT_PIN, 1);
        gpioDelay(500000);
        gpioWrite(ALERT_PIN, 0);
    }
}

