#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS 1

#define REG_MODEL_ID 0x010F
#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_MODE_START 0x007
#define REG_SYSRANGE_START 0x000
#define REG_RESULT_INT_STATUS 0x013
#define REG_RESULT_RANGE_STATUS 0x078
#define REG_SYSTEM_INT_CLEAR 0x014

#define MODEL_ID_EXPECTED 0xEA
#define DISTANCE_THRESHOLD_STOP 300
#define DISTANCE_THRESHOLD_APPROACH 600
#define DISTANCE_THRESHOLD_SLOW 1200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, MODEL_ID_EXPECTED);
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance_mm) {
    uint8_t status = 0;
    int timeout = 0;
    while (timeout < 100) {
        if (i2c_read_reg16(handle, REG_SYSRANGE_START, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "Error: Ranging timeout.\n");
        return -1;
    }
    uint8_t data[2];
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, data, 2) < 0) return -1;
    *distance_mm = (data[0] << 8) | data[1];
    if (i2c_write_reg16(handle, REG_SYSTEM_INT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fflush(fp);
}

static void parking_guidance(int distance_mm) {
    if (distance_mm < DISTANCE_THRESHOLD_STOP) {
        printf("STOP\n");
    } else if (distance_mm < DISTANCE_THRESHOLD_APPROACH) {
        printf("APPROACH\n");
    } else if (distance_mm < DISTANCE_THRESHOLD_SLOW) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
