#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* ---- CH201 I2C default address ---- */
#define CH201_ADDR 0x45

/* ---- CH201 register addresses (16-bit, big-endian on the bus) ---- */
#define CH201_REG_PRODUCT_ID      0x0002
#define CH201_REG_SYSTEM_CONFIG   0x000A
#define CH201_REG_RANGE_START     0x0010
#define CH201_REG_RANGE_END       0x0012
#define CH201_REG_RANGE_STATUS    0x0014
#define CH201_REG_DISTANCE        0x0016

/* ---- LED pin ---- */
#define LED_PIN 18

/* ---- Blink mapping ---- */
#define MIN_DISTANCE_MM  50
#define MAX_DISTANCE_MM  500
#define MIN_FREQ_HZ      1
#define MAX_FREQ_HZ      10
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 4);
        if (rc == 0)
            return 0;
        fprintf(stderr, "i2cWriteDevice(0x%04X, 0x%04X) attempt %d failed: %s\n",
                reg, value, attempt + 1, strerror(errno));
        gpioDelay(10000); /* 10 ms */
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char cmd[2];
    char data[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "i2cWriteDevice(0x%04X) attempt %d failed: %s\n",
                    reg, attempt + 1, strerror(errno));
            gpioDelay(10000);
            continue;
        }
        if (i2cReadDevice(handle, data, 2) == 2) {
            *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }
        fprintf(stderr, "i2cReadDevice(0x%04X) attempt %d failed: %s\n",
                reg, attempt + 1, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 initialization                                                */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    /*
     * Minimal bring-up: set product ID register to 0x0001 (CH201)
     * so we know the sensor is present and responding.
     */
    uint16_t product_id = 0;
    if (i2c_read_reg16(handle, CH201_REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "CH201: cannot read PRODUCT_ID — sensor absent or bus error\n");
        return -1;
    }
    if (product_id != 0x0001) {
        fprintf(stderr, "CH201: unexpected PRODUCT_ID 0x%04X (expected 0x0001)\n", product_id);
        return -1;
    }

    /*
     * Start a single-shot range measurement.
     * bit[0] = 1 triggers a single-shot conversion.
     */
    if (i2c_write_reg16(handle, CH201_REG_SYSTEM_CONFIG, 0x0001) != 0) {
        fprintf(stderr, "CH201: failed to write SYSTEM_CONFIG\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm)                                                  */
/* ------------------------------------------------------------------ */
static int ch201_read_distance(int handle)
{
    uint16_t distance = 0;
    if (i2c_read_reg16(handle, CH201_REG_DISTANCE, &distance) != 0) {
        fprintf(stderr, "CH201: failed to read DISTANCE register\n");
        return -1;
    }
    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Blink control                                                       */
/* ------------------------------------------------------------------ */
static void control_led(int distance_mm)
{
    int half_period_us;

    if (distance_mm < MIN_DISTANCE_MM)
        distance_mm = MIN_DISTANCE_MM;
    if (distance_mm > MAX_DISTANCE_MM)
        distance_mm = MAX_DISTANCE_MM;

    /*
     * Map linearly: 50 mm -> 10 Hz, 500 mm -> 1 Hz.
     * half_period_us = 1e6 / (2 * freq_hz)  -> 50 µs at 10 Hz, 100 µs at 1 Hz.
     */
    float ratio = (float)(MAX_DISTANCE_MM - distance_mm) /
                  (float)(MAX_DISTANCE_MM - MIN_DISTANCE_MM);
    float freq = MIN_FREQ_HZ + ratio * (MAX_FREQ_HZ - MIN_FREQ_HZ);
    half_period_us = (int)(50000.0f / (2.0f * freq));

    if (half_period_us < 10)
        half_period_us = 10;
    if (half_period_us > 50000)
        half_period_us = 50000;

    static int led_state = 0;
    gpioWrite(LED_PIN, led_state);
    led_state = !led_state;

    gpioDelay(half_period_us);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(1, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                CH201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialization failed — check wiring and I2C address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- LED pin setup ---- */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = ch201_read_distance(g_i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Read error — continuing\n");
        } else {
            int freq_hz = 0;
            control_led(distance);
            freq_hz = (MAX_DISTANCE_MM - distance) > 0 ?
                      MIN_FREQ_HZ + (MAX_FREQ_HZ - MIN_FREQ_HZ) *
                      (MAX_DISTANCE_MM - distance) / (MAX_DISTANCE_MM - MIN_DISTANCE_MM) :
                      MAX_FREQ_HZ;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("%s Distance: %d mm, Blink Freq: %d Hz\n", ts, distance, freq_hz);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

