#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS   50
#define POLL_DELAY_US 10000  /* 10 ms */
#define LOG_FILE      "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Write an ISO 8601 UTC timestamp into buf (size >= 25). */
static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm tm_info;
    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* Append one CSV record to the log file. Returns 0 on success, -1 on error. */
static int log_event(FILE *fp, int sensor_id, const char *event_type) {
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s,%d,%s\n", ts, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a sensor; returns 0 or 1, or -1 on read error. */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int main(void) {
    int sensor1_state = -1;
    int sensor2_state = -1;
    int last_sensor1 = -1;
    int last_sensor2 = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        goto cleanup_gpio;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Debounce: only accept a state change if the raw reading is stable. */
        if (s1 != last_sensor1) {
            last_sensor1 = s1;
            if (s1 != sensor1_state) {
                if (log_event(fp, 1, s1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Logging failed for sensor 1.\n");
                }
                sensor1_state = s1;
            }
        }
        if (s2 != last_sensor2) {
            last_sensor2 = s2;
            if (s2 != sensor2_state) {
                if (log_event(fp, 2, s2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Logging failed for sensor 2.\n");
                }
                sensor2_state = s2;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    ret = EXIT_SUCCESS;

    if (fp != NULL) {
        fclose(fp);
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

