#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49

#define REG_MEAS_TRIGGER 0x04
#define REG_MEAS_STATUS  0x06
#define REG_DIST_HIGH    0x08
#define REG_DIST_LOW     0x09

#define MEAS_STATUS_DATA_READY 0x01
#define MEAS_STATUS_ERROR      0x02

#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 500000
#define MEAS_TIMEOUT_MS 50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Perform a combined write-then-read I2C transaction.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Trigger a single range measurement and read the 16-bit distance.
 * Returns distance in mm on success, -1 on timeout or error.
 */
static int ch101_read_distance(int fd) {
    uint8_t status = 0;
    uint8_t dist_high = 0, dist_low = 0;
    int elapsed = 0;

    /* Trigger measurement */
    if (i2c_read_reg(fd, REG_MEAS_TRIGGER, (uint8_t[]){0x01}) < 0)
        return -1;

    /* Poll data-ready bit with timeout */
    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_read_reg(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & MEAS_STATUS_DATA_READY)
            break;
        if (status & MEAS_STATUS_ERROR) {
            fprintf(stderr, "CH101 measurement error (status=0x%02X)\n", status);
            return -1;
        }
        usleep(1000);
        elapsed++;
    }

    if (elapsed >= MEAS_TIMEOUT_MS) {
        fprintf(stderr, "CH101 measurement timeout\n");
        return -1;
    }

    /* Read 16-bit distance */
    if (i2c_read_reg(fd, REG_DIST_HIGH, &dist_high) < 0)
        return -1;
    if (i2c_read_reg(fd, REG_DIST_LOW, &dist_low) < 0)
        return -1;

    return (dist_high << 8) | dist_low;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

int main(void) {
    int fd = -1;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire exclusive access to the CH101 slave address */
    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open log file in append mode */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    fseek(log, 0, SEEK_END);
    if (ftell(log) == 0) {
        fprintf(log, "timestamp,distance_mm\n");
        fflush(log);
    }

    printf("CH101 parking sensor started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        char ts[32];
        int dist;

        get_timestamp(ts, sizeof(ts));

        dist = ch101_read_distance(fd);

        if (dist >= 0) {
            fprintf(log, "%s,%d\n", ts, dist);
            fflush(log);
            printf("%s  Distance: %d mm\n", ts, dist);
        } else {
            fprintf(stderr, "%s  Read failed; skipping sample\n", ts);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log) {
        fflush(log);
        fclose(log);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

