#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L5CX_ADDR  0x29

/* VL53L5CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_I2C_SLAVE_DEVICE_CONFIG 0x0001
#define REG_SYSTEM_MODE_START      0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS     0x0046
#define REG_RESULT_DISTANCE_BASE    0x0060
#define REG_RESULT_DISTANCE_COUNT   0x0047

#define NUM_ZONES 64
#define READ_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register address (big-endian on the bus) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register address (big-endian on the bus) */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val[2];
    if (read(fd, val, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)val[0] << 8) | val[1];
    return 0;
}

/* Read a block of 16-bit values starting at a 16-bit register address */
static int i2c_read_block16(int fd, uint16_t reg, uint16_t *buf, size_t len) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_block16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[len * 2];
    if (read(fd, data, len * 2) != (ssize_t)len * 2) {
        fprintf(stderr, "i2c_read_block16 read(0x%04X, %zu): %s\n", reg, len, strerror(errno));
        return -1;
    }
    for (size_t i = 0; i < len; i++) {
        buf[i] = ((uint16_t)data[i * 2] << 8) | data[i * 2 + 1];
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x0001) < 0) return -1;
    usleep(10000); /* 10 ms */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x0000) < 0) return -1;
    usleep(10000); /* 10 ms */

    /* Configure I2C slave device (optional, default is usually fine) */
    if (i2c_write_reg16(fd, REG_I2C_SLAVE_DEVICE_CONFIG, 0x0000) < 0) return -1;

    return 0;
}

static int vl53l5cx_start_ranging(int fd) {
    return i2c_write_reg16(fd, REG_SYSTEM_MODE_START, 0x0001);
}

static int vl53l5cx_read_zones(int fd, uint16_t *distances) {
    uint16_t num_ranges;
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE_COUNT, &num_ranges) < 0) return -1;

    if (num_ranges > NUM_ZONES) {
        fprintf(stderr, "Unexpected number of ranges: %u\n", num_ranges);
        return -1;
    }

    if (i2c_read_block16(fd, REG_RESULT_DISTANCE_BASE, distances, num_ranges) < 0) return -1;

    /* Check interrupt status for errors */
    uint16_t int_status;
    if (i2c_read_reg16(fd, REG_RESULT_INTERRUPT_STATUS, &int_status) < 0) return -1;
    if (int_status & 0x0001) {
        fprintf(stderr, "Sensor interrupt status error: 0x%04X\n", int_status);
        return -1;
    }

    /* Check range status for errors */
    uint16_t range_status;
    if (i2c_read_reg16(fd, REG_RESULT_RANGE_STATUS, &range_status) < 0) return -1;
    if (range_status & 0x0001) {
        fprintf(stderr, "Sensor range status error: 0x%04X\n", range_status);
        return -1;
    }

    return 0;
}

static void log_zones(const uint16_t *distances) {
    printf("Zones:");
    for (int i = 0; i < NUM_ZONES; i++) {
        printf(" [%3d] %5u", i, distances[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (vl53l5cx_init(g_fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (vl53l5cx_start_ranging(g_fd) < 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    uint16_t distances[NUM_ZONES];
    int consecutive_errors = 0;

    while (g_running) {
        if (vl53l5cx_read_zones(g_fd, distances) == 0) {
            log_zones(distances);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
        }
        usleep(READ_INTERVAL_MS * 1000);
    }

    /* Stop ranging */
    i2c_write_reg16(g_fd, REG_SYSTEM_MODE_START, 0x0000);

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

