#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASUREMENT_REG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_distance(int handle, int *distance) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(handle, MEASUREMENT_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, RETRY_COUNT, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

void log_distance(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;
    printf("%ld.%03ld: Distance = %d mm\n", ts.tv_sec, milliseconds, distance);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

