#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD_MM 100
#define POLL_DELAY_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET                       0x0001
#define REG_I2C_SLAVE_DEVICE_ADDRESS         0x0001
#define REG_SYSTEM_MODE_START                0x0007
#define REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address + 1 byte of data */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit register address */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *data, int len) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Set I2C slave address (already 0x29, but explicit for clarity) */
    if (vl53l1x_write_reg8(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, 0x29) < 0) return -1;

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_MODE_START, 0x40) < 0) return -1;
    gpioDelay(10000); /* 10 ms for mode to take effect */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t data[2];
    if (vl53l1x_read_reg(handle, REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, data, 2) < 0) {
        return -1;
    }
    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static void control_buzzer(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    control_buzzer(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error reading distance from VL53L1X (I2C bus error or sensor absent)\n");
            /* Attempt to re-initialize on next iteration */
            if (vl53l1x_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialization failed, retrying in 1 s...\n");
                gpioDelay(1000000);
            }
            control_buzzer(BUZZER_GPIO, 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_MM) {
            control_buzzer(BUZZER_GPIO, 1);
        } else {
            control_buzzer(BUZZER_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    control_buzzer(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

