#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_SERVO_PULSE_US 1000
#define MAX_SERVO_PULSE_US 2000
#define ECHO_TIMEOUT_US 50000
#define LOG_FILE "sensor_data.log"
#define LOOP_DELAY_US 200000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_data(float distance, int servo_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Servo Angle: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance, servo_angle);
    }
    fclose(fp);
}

static int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    int angle = (int)(((distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                      (MAX_SERVO_PULSE_US - MIN_SERVO_PULSE_US) + MIN_SERVO_PULSE_US);
    if (angle < MIN_SERVO_PULSE_US) angle = MIN_SERVO_PULSE_US;
    if (angle > MAX_SERVO_PULSE_US) angle = MAX_SERVO_PULSE_US;
    return angle;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_SERVO_PULSE_US) angle = MIN_SERVO_PULSE_US;
    if (angle > MAX_SERVO_PULSE_US) angle = MAX_SERVO_PULSE_US;
    if (gpioServo(SERVO_PIN, angle) < 0) {
        fprintf(stderr, "Error setting servo angle: %s\n", pigpio_error(gpioServo(SERVO_PIN, angle)));
        return -1;
    }
    return 0;
}

static float measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0f;
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0f;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0f;

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1.0f;
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) return -1.0f;
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    float distance = (pulse_width * SPEED_OF_SOUND_CM_PER_US) / 2.0f;
    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    while (program_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor timeout or error\n");
        } else {
            int servo_angle = map_distance_to_angle(distance);
            if (set_servo_angle(servo_angle) < 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }
            log_data(distance, servo_angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

