#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <mqueue.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define MESSAGE_QUEUE_NAME "/vl53l1x_queue"
#define POLL_DELAY_US 50000
#define RANGING_PERIOD_US 50000

#define REG_SOFT_RESET 0x0000
#define REG_MODEL_ID 0x010F
#define REG_SYSTEM_START 0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset low.\n");
        return -1;
    }
    gpioDelay(1000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset high.\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg16(handle, 0x001F, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget.\n");
        return -1;
    }

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        return -1;
    }
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void control_buzzer(int gpio, int state) {
    gpioWrite(gpio, state);
}

static void log_distance(mqd_t mq, int distance) {
    struct mq_msg message;
    message.mq_flags = 0;
    message.mq_id = 0;
    message.mq_priority = 0;
    message.mq_payload = (char *)(&distance);
    message.mq_flags = 0;
    if (mq_send(mq, (const char *)&message, sizeof(int)) == -1) {
        perror("mq_send");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = sizeof(int);
    attr.mq_curmsgs = 0;

    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = 0;
        int rc = read_distance(i2c_handle, &distance);

        if (rc == 0) {
            log_distance(mq, distance);
            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(BUZZER_GPIO, 1);
            } else {
                control_buzzer(BUZZER_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failed.\n");
            control_buzzer(BUZZER_GPIO, 0);
        }

        gpioDelay(RANGING_PERIOD_US);
    }

    printf("\nShutting down...\n");
    control_buzzer(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    mq_close(mq);
    mq_unlink(MESSAGE_QUEUE_NAME);
    gpioTerminate();
    return 0;
}

