#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0   /* cm/s at ~20 C */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000    /* 30 ms max echo wait */
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define ALARM_THRESHOLD_CM 30.0
#define LOOP_DELAY_US 100000     /* 100 ms */

static volatile sig_atomic_t running = 1;

/* Shared state between alert callback and main loop */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;
static volatile int      g_reading_valid = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 0 = falling, 1 = rising, 2 = watchdog timeout
 * tick:  32-bit microsecond counter (wraps every ~71.6 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_seen = 1;
    }
    /* level == 2 watchdog timeout: ignore */
}

static void trigger_sensor(void)
{
    g_start_tick = 0;
    g_end_tick   = 0;
    g_echo_seen  = 0;
    g_reading_valid = 0;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t start, uint32_t end)
{
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t elapsed = end - start;  /* correct for unsigned wrap */

    double pulse_us = (double)elapsed;
    double distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0; /* /2 for round trip */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;  /* out of valid range */
    }
    return distance;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert function on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Trigger=GPIO%d, Echo=GPIO%d, Buzzer=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm. Press Ctrl+C to exit.\n", ALARM_THRESHOLD_CM);

    int buzzer_on = 0;

    while (running) {
        trigger_sensor();

        /* Wait for echo callback to complete or timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);  /* yield CPU */
        }

        if (!running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: sensor timeout - no echo received within %d us.\n",
                    ECHO_TIMEOUT_US);
            gpioWrite(BUZZER_PIN, 0);
            buzzer_on = 0;
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance = calculate_distance(g_start_tick, g_end_tick);

        if (distance < 0.0) {
            fprintf(stderr, "Warning: reading out of range (%.0f-%.0f cm).\n",
                    MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            gpioWrite(BUZZER_PIN, 0);
            buzzer_on = 0;
        } else {
            printf("Distance: %.2f cm\n", distance);

            if (distance < ALARM_THRESHOLD_CM) {
                if (!buzzer_on) {
                    gpioWrite(BUZZER_PIN, 1);
                    buzzer_on = 1;
                    printf("  -> Buzzer ON\n");
                }
            } else {
                if (buzzer_on) {
                    gpioWrite(BUZZER_PIN, 0);
                    buzzer_on = 0;
                    printf("  -> Buzzer OFF\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

