/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16)  [output, initially LOW]
 *   ECHO -> GPIO 24 (physical pin 18)  [input, pull-down, 5V -> 3.3V divider]
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse                  */
#define MEASURE_PERIOD_US 200000     /* 200 ms between measurements         */
#define ECHO_TIMEOUT_US   60000      /* 60 ms max echo wait (~5 m round trip) */
#define MIN_PULSE_US      100        /* reject < 100 us (noise / glitch)     */
#define MAX_PULSE_US      30000      /* reject > 30 ms (timeout / no obj)    */

#define SPEED_OF_SOUND_CM_PER_US 0.0343  /* 343 m/s in cm/us */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_received = false;
static volatile bool     g_echo_error    = false;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_rising_tick = tick;
        g_echo_received = false;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        g_falling_tick = tick;
        g_echo_received = true;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Compute elapsed microseconds with 32-bit tick wraparound            */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction handles wraparound */
}

/* ------------------------------------------------------------------ */
/* Distance in cm from pulse width in us                               */
/* ------------------------------------------------------------------ */
static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

/* ------------------------------------------------------------------ */
/* ISO 8601 timestamp helper                                           */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", ts, distance_cm);
        fflush(g_log_file);
    }
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on TRIG                                       */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
