        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to distance_log.txt\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset shared state before triggering */
        g_echo_received = false;
        g_echo_error    = false;
        g_rising_tick   = 0;
        g_falling_tick  = 0;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_received && g_running) {
            if (tick_diff(wait_start, gpioTick()) > ECHO_TIMEOUT_US) {
                log_error("Echo timeout: no object detected or sensor absent");
                break;
            }
