        }

        if (g_echo_error) {
            log_error("ECHO callback error (gpioSetAlertFunc failure)");
        }

        /* Read and validate pulse width */
        uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

        if (pulse_us < MIN_PULSE_US) {
            log_error("Pulse too short (noise / glitch)");
        } else if (pulse_us > MAX_PULSE_US) {
            log_error("Pulse too long (timeout / no object detected)");
        } else {
            float distance = calculate_distance(pulse_us);
            log_reading(distance);
        }

        /* Wait remainder of 200 ms cycle */
        uint32_t elapsed = tick_diff(wait_start, gpioTick());
        if (elapsed < MEASURE_PERIOD_US) {
            gpioDelay(MEASURE_PERIOD_US - elapsed);
        }
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;

    /*
     * HC-SR04 notes:
     *   - ECHO output is 5V — use a voltage divider (e.g., 1 kΩ / 2 kΩ)
     *     or a logic-level converter (e.g., Adafruit 3384) so the Pi
     *     sees ~3.3V on GPIO 24.
     *   - HC-SR04 is sensitive to obstacles within ~20° of the sensor
