#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24

#define DISTANCE_OPEN_THRESHOLD 50.0
#define DISTANCE_CLOSE_THRESHOLD 60.0

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read VL53L1X model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid VL53L1X model ID: 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set VL53L1X shutdown.\n");
        return -1;
    }
    gpioDelay(10000);
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X ranging.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int timeout = 100;

    while (timeout-- > 0) {
        if (read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
            return -1;
        }
        if ((status & 0x01) != 0) {
            break;
        }
        gpioDelay(1000);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Error: VL53L1X ranging timeout.\n");
        return -1;
    }

    if (read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
        return -1;
    }

    int16_t raw = (dist_buf[0] << 8) | dist_buf[1];
    *distance = (float)raw / 100.0f;
    return 0;
}

static void log_event(const char *event, float distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s (Distance: %.2f cm)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file);
}

static void control_servo(int position) {
    if (position < 0) position = 0;
    if (position > 1000) position = 1000;
    gpioServo(SERVO_PIN, position);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set SERVO_PIN mode.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;
    control_servo(0);

    while (running) {
        float distance = 0.0f;
        if (vl53l1x_read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance.\n");
            log_event("Sensor Error", -1.0f);
            gpioDelay(100000);
            continue;
        }

        if (distance < DISTANCE_OPEN_THRESHOLD && !gate_open) {
            control_servo(1000);
            gate_open = 1;
            log_event("Gate Open", distance);
        } else if (distance > DISTANCE_CLOSE_THRESHOLD && gate_open) {
            control_servo(0);
            gate_open = 0;
            log_event("Gate Close", distance);
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

