#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_DELAY_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_VHV_CONFIG 0x000B
#define VL53L1X_REG_PHASECAL_CONFIG 0x004F
#define VL53L1X_REG_RANGE_CONFIG_A 0x005A
#define VL53L1X_REG_RANGE_CONFIG_B 0x005C
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x006B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0084
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit value to a 16-bit VL53L1X register using i2cWriteI2CBlockData */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 3);
}

/* Read a 16-bit value from a 16-bit VL53L1X register using i2cReadI2CBlockData */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    char data_buf[2];
    int rc;

    rc = i2cWriteI2CBlockData(handle, reg_buf[0], &reg_buf[1], 1);
    if (rc < 0) return rc;

    rc = i2cReadI2CBlockData(handle, reg_buf[0], data_buf, 2);
    if (rc < 0) return rc;

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    int rc;

    /* Soft reset */
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0000);
    if (rc < 0) return rc;
    gpioDelay(1000); /* 1 ms */

    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0001);
    if (rc < 0) return rc;
    gpioDelay(1000); /* 1 ms */

    /* Basic configuration: VHV, phase calibration, timing budget */
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_VHV_CONFIG, 0x0001);
    if (rc < 0) return rc;
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_PHASECAL_CONFIG, 0x0001);
    if (rc < 0) return rc;
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x0000);
    if (rc < 0) return rc;
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x0000);
    if (rc < 0) return rc;
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0000);
    if (rc < 0) return rc;

    /* Start continuous ranging */
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x0001);
    if (rc < 0) return rc;
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001);
    if (rc < 0) return rc;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    int rc;
    uint16_t status;
    uint16_t dist;

    /* Check if data is ready */
    rc = vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status);
    if (rc < 0) return rc;

    if ((status & 0x01) == 0) {
        /* Data not ready yet */
        return 1;
    }

    /* Read distance */
    rc = vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist);
    if (rc < 0) return rc;

    /* Clear interrupt */
    rc = vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001);
    if (rc < 0) return rc;

    *distance_mm = dist;
    return 0;
}

static void control_gate(int open) {
    gpioWrite(GATE_OPEN_PIN, open ? 1 : 0);
    gpioWrite(GATE_CLOSE_PIN, open ? 0 : 1);
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioSetMode(GATE_OPEN_PIN, PI_INPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_INPUT);

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int distance_mm;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        log_event("ERROR: I2C open failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_event("ERROR: VL53L1X init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("INFO: Gate control system started");

    while (running) {
        rc = vl53l1x_read_distance(i2c_handle, &distance_mm);
        if (rc < 0) {
            fprintf(stderr, "I2C read error: %d\n", rc);
            log_event("ERROR: I2C read failure");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance_mm <= DISTANCE_THRESHOLD_MM) {
            control_gate(1);
            log_event("Gate opened");
        } else {
            control_gate(0);
            log_event("Gate closed");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("INFO: Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

