#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define TRIGGER_PIN 24
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int motor_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, 0x0000, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t status = 0;
    int retries = 0;
    int delay_us = RETRY_DELAY_BASE_US;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, 0x0089, &status, 1) < 0) {
            fprintf(stderr, "Error reading status register (retry %d/%d)\n", retries + 1, MAX_RETRIES);
            gpioDelay(delay_us);
            delay_us *= 2;
            retries++;
            continue;
        }
        if (status & 0x01) break;
        gpioDelay(1000);
        delay_us *= 2;
        retries++;
    }

    if (retries >= MAX_RETRIES) return -1;

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, 0x0096, dist_buf, 2) < 0) {
        fprintf(stderr, "Error reading distance registers\n");
        return -1;
    }

    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void motor_forward(void) {
    if (motor_state != 1) {
        gpioWrite(MOTOR_FORWARD, 1);
        gpioWrite(MOTOR_BACKWARD, 0);
        motor_state = 1;
        printf("Motor: FORWARD\n");
    }
}

static void motor_backward(void) {
    if (motor_state != -1) {
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 1);
        motor_state = -1;
        printf("Motor: BACKWARD\n");
    }
}

static void motor_stop(void) {
    if (motor_state != 0) {
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 0);
        motor_state = 0;
        printf("Motor: STOP\n");
    }
}

static void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %d mm\n", distance);
        if (distance < DISTANCE_THRESHOLD_FORWARD) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Sensor read failed; stopping motor for safety.\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

