#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define LOG_FILE "proximity_log.txt"

#define GPIO_CHIP "gpiochip0"
#define LED_PIN_1 17
#define LED_PIN_2 18
#define LED_PIN_3 27
#define LED_PIN_4 22

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static FILE *log_fp = NULL;

static const int led_pins[4] = {LED_PIN_1, LED_PIN_2, LED_PIN_3, LED_PIN_4};

static void log_event(const char *msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (log_fp) {
        fprintf(log_fp, "[%s] %s\n", ts, msg);
        fflush(log_fp);
    }
    printf("[%s] %s\n", ts, msg);
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t whoami = 0;
    if (i2c_read_reg(MPR121_SOFTRESET, &whoami) < 0) return -1;
    if (whoami != 0x63) {
        fprintf(stderr, "MPR121 not responding after reset (read 0x%02X)\n", whoami);
        return -1;
    }

    if (i2c_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLR, 0x00) < 0) return -1;

    if (i2c_write_reg(MPR121_E0TTH, 0x0B) < 0) return -1;
    if (i2c_write_reg(MPR121_E0RTH, 0xC8) < 0) return -1;
    if (i2c_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (i2c_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg(MPR121_AUTOCONFIG1, 0xC8) < 0) return -1;
    if (i2c_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (i2c_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (i2c_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    if (i2c_write_reg(MPR121_ELECONFIG0, 0x0C) < 0) return -1;
    return 0;
}

static int mpr121_read_touch(uint16_t *touch_status) {
    uint8_t lo, hi;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(uint16_t touch_status) {
    int pattern = 0;
    if (touch_status & 0x0001) pattern |= (1 << 0);
    if (touch_status & 0x0002) pattern |= (1 << 1);
    if (touch_status & 0x0004) pattern |= (1 << 2);
    if (touch_status & 0x0008) pattern |= (1 << 3);
    if (touch_status & 0x0010) pattern |= (1 << 4);
    if (touch_status & 0x0020) pattern |= (1 << 5);
    if (touch_status & 0x0040) pattern |= (1 << 6);
    if (touch_status & 0x0080) pattern |= (1 << 7);

    for (int i = 0; i < 4; i++) {
        int val = (pattern >> i) & 1;
        if (gpiod_line_set_value(led_lines[i], val) < 0) {
            log_event("Error setting LED GPIO value");
        }
    }
}

static void log_proximity_event(uint16_t touch_status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    char msg[256];
    snprintf(msg, sizeof(msg), "%s - Proximity detected by electrode(s): 0x%04X", ts, touch_status);
    log_event(msg);
}

static void log_no_proximity_event(void) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    char msg[128];
    snprintf(msg, sizeof(msg), "%s - No electrode detected proximity", ts);
    log_event(msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", led_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_art", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output\n", led_pins[i]);
            cleanup();
            return 1;
        }
    }

    log_event("Proximity art installation started");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(&touch_status) < 0) {
            log_event("Error reading touch status from MPR121");
            usleep(50000);
            continue;
        }

        if (touch_status != 0) {
            set_led_pattern(touch_status);
            log_proximity_event(touch_status);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
            log_no_proximity_event();
        }

        usleep(50000);
    }

    log_event("Proximity art installation stopped");
    cleanup();
    return 0;
}

