    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", led_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_art", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output\n", led_pins[i]);
            cleanup();
            return 1;
        }
    }

    log_event("Proximity art installation started");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(&touch_status) < 0) {
            log_event("Error reading touch status from MPR121");
            usleep(50000);
            continue;
        }

        if (touch_status != 0) {
            set_led_pattern(touch_status);
            log_proximity_event(touch_status);
        } else {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(led_lines[i], 0);
            }
            log_no_proximity_event();
        }

        usleep(50000);
    }

    log_event("Proximity art installation stopped");
    cleanup();
    return 0;
}

