#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEVICE_ID 0x5C
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int mpr121_read(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALLING, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_RELEASETH_0, 0x05) < 0) return -1;

    return 0;
}

static int detect_proximity(void) {
    int touch_status_l = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) return -1;
    return (touch_status_l & 0x01) ? 1 : 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", timestamp);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = mpr121_read(MPR121_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read MPR121 device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x33) {
        fprintf(stderr, "Unexpected MPR121 device ID: 0x%02X (expected 0x33)\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int proximity = detect_proximity();
        if (proximity < 0) {
            fprintf(stderr, "I2C error during proximity detection\n");
            gpioDelay(100000);
            continue;
        }

        if (proximity) {
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(50000);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

