#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 0);
    usleep(5);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);
}

static long measure_pulse_width(void) {
    struct timespec start, now;
    int val;
    long elapsed_us;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while ((val = gpiod_line_get_value(echo_line)) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                     (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while ((val = gpiod_line_get_value(echo_line)) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                     (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &now);
    elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                 (now.tv_nsec - start.tv_nsec) / 1000L;
    return elapsed_us;
}

static float calculate_distance(long pulse_width_us) {
    if (pulse_width_us < 0) {
        return -1.0f;
    }
    return (float)pulse_width_us * SOUND_SPEED_CM_PER_US / 2.0f;
}

static void log_distance(float distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get UTC time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(log_file, "%s, ERROR: Distance out of range (%.2f cm)\n",
                timestamp, distance_cm);
    } else {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance_cm);
    }
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Sensor timeout or error.\n");
            log_distance(-1.0f);
        } else {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

