                 (now.tv_nsec - start.tv_nsec) / 1000L;
    return elapsed_us;
}

static float calculate_distance(long pulse_width_us) {
    if (pulse_width_us < 0) {
        return -1.0f;
    }
    return (float)pulse_width_us * SOUND_SPEED_CM_PER_US / 2.0f;
}

static void log_distance(float distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get UTC time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(log_file, "%s, ERROR: Distance out of range (%.2f cm)\n",
                timestamp, distance_cm);
    } else {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance_cm);
    }
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Sensor timeout or error.\n");
            log_distance(-1.0f);
        } else {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

