#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define SPEED_OF_SOUND_CM_S 34300.0
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 1000000

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end   = 0;
static volatile int      pulse_ready = 0;
static volatile int      running     = 1;
static FILE             *log_file   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_ready = 1;
    }
}

static double calculate_distance_cm(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0;
}

static void log_distance(double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN\n");
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(5);

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on ECHO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_ready = 0;
        pulse_start = 0;
        pulse_end   = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN low\n");
            break;
        }

        gpioDelay(50);

        if (!pulse_ready) {
            fprintf(stderr, "Warning: no echo received on this sample\n");
            continue;
        }

        uint32_t pulse_us = pulse_end - pulse_start;

        if (pulse_us == 0 || pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_us);
            continue;
        }

        double distance_cm = calculate_distance_cm(pulse_us);
        log_distance(distance_cm);
        printf("Distance: %.2f cm\n", distance_cm);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

