#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define TRIGGER_PIN    27
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SYSTEM_RANGE_START  0x0020
#define REG_RESULT_RANGE_STATUS 0x0016
#define REG_RESULT_DISTANCE    0x0014
#define REG_SYSTEM_MODE_START  0x0018
#define REG_SYSTEM_INTERMEAS  0x0019

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a 16-bit VL53L1X register address */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit VL53L1X register address */
static int vl53l1x_read_block(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle)
{
    /* Continuous mode, no timeout */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to set continuous mode");
        return -1;
    }
    if (vl53l1x_write_byte(handle, REG_SYSTEM_INTERMEAS, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to set inter-measurement period");
        return -1;
    }
    /* Start ranging */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_RANGE_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance, uint8_t *status)
{
    uint8_t data[2];
    uint8_t status_byte;

    if (vl53l1x_read_block(handle, REG_RESULT_DISTANCE, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance register");
        return -1;
    }
    *distance = (uint16_t)((data[1] << 8) | data[0]);

    if (vl53l1x_read_block(handle, REG_RESULT_RANGE_STATUS, &status_byte, 1) != 1) {
        syslog(LOG_ERR, "Failed to read range status");
        return -1;
    }
    *status = status_byte;
    return 0;
}

static void log_data(uint16_t distance, uint8_t status)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    syslog(LOG_INFO, "%s Distance: %u mm, Status: 0x%02X", ts, distance, status);
}

int main(void)
{
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1);  /* active-low: HIGH = enabled */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X sensor started on I2C bus %d addr 0x%02X", I2C_BUS, I2C_ADDR);

    while (g_running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Read failed; continuing");
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "VL53L1X sensor shutting down");
    gpioWrite(TRIGGER_PIN, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

