#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_DEFAULT_ANGLE 90
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Shared state between alert callback and main thread */
static volatile uint32_t pulse_start_tick = 0;
static volatile uint32_t pulse_end_tick = 0;
static volatile int pulse_ready = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* pigpio alert callback: level 1 = rising edge, 0 = falling edge */
static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start_tick = tick;
    } else if (level == 0) {
        pulse_end_tick = tick;
        pulse_ready = 1;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

static int map_distance_to_angle(double distance) {
    if (distance < 0) return -1;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    double angle = 180.0 * log(distance + 1.0) / log(MAX_DISTANCE + 1.0);
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH +
                            (double)angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180.0);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to set alert function on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    double distance_history[MOVING_AVG_SIZE] = {0};
    int history_index = 0;
    int samples_collected = 0;

    while (program_running) {
        /* Reset shared state for this sample */
        pulse_ready = 0;
        pulse_start_tick = 0;
        pulse_end_tick = 0;

        /* Trigger the sensor */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo with timeout */
        uint32_t start_wait = gpioTick();
        while (!pulse_ready && program_running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!pulse_ready) {
            log_data(-1.0, -1);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_width = pulse_end_tick - pulse_start_tick;
        double distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            log_data(-1.0, -1);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Moving average */
        distance_history[history_index] = distance;
        history_index = (history_index + 1) % MOVING_AVG_SIZE;
        if (samples_collected < MOVING_AVG_SIZE) {
            samples_collected++;
        }
        double sum = 0.0;
        for (int i = 0; i < samples_collected; i++) {
            sum += distance_history[i];
        }
        double filtered_distance = sum / samples_collected;

        int servo_angle = map_distance_to_angle(filtered_distance);
        if (set_servo_angle(servo_angle) < 0) {
            log_data(-1.0, -1);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(filtered_distance, servo_angle);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

