        if (samples_collected < MOVING_AVG_SIZE) {
            samples_collected++;
        }
        double sum = 0.0;
        for (int i = 0; i < samples_collected; i++) {
            sum += distance_history[i];
        }
        double filtered_distance = sum / samples_collected;

        int servo_angle = map_distance_to_angle(filtered_distance);
        if (set_servo_angle(servo_angle) < 0) {
            log_data(-1.0, -1);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(filtered_distance, servo_angle);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

