    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_SNRR, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_VCSEL_PERIOD, 0x0B) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_LO, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_DYNAMIC_SPAD_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PHASECAL_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SD_CONFIG_WOI_SD0, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SD_CONFIG_WOI_SD1, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SD_CONFIG_INIT_PHASE, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_LO, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PRE_RANGE_CONFIG_VCSEL_PERIOD, 0x0B) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PRE_RANGE_CONFIG_SIGMA_THRESH, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX_ACTIVE_HIGH, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) != 0) return -1;

