        return 1; /* not ready yet */
    }
    uint16_t dist = 0;
    if (i2c_read_reg16_16bit(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) != 0) {
        return -1;
    }
    *distance = (int)dist;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
