    }
    return 0;
}

static void add_to_buffer(int value) {
    distance_buffer[buffer_index] = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int check_threshold(int distance) {
    return (distance < DISTANCE_THRESHOLD) ? 1 : 0;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int distance = -1;
        int ret = read_distance(i2c_handle, &distance);
        if (ret == 0) {
            add_to_buffer(distance);
            int led_state = check_threshold(distance);
            gpioWrite(WARNING_LED_PIN, led_state);
            printf("Distance: %d mm, Threshold: %d\n", distance, led_state);
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

