#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t proximity_alert = 0;
static volatile sig_atomic_t proximity_value = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", address, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_proximity(int *value) {
    int high = i2cReadByteData(i2c_handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading high proximity register: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(i2c_handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading low proximity register: %d\n", low);
        return -1;
    }
    *value = (high << 8) | low;
    return 0;
}

static void log_proximity(int value, int alert) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, value, alert ? "ALERT" : "SAFE");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (read_proximity(&proximity_value) == 0) {
        if (proximity_value > DEFAULT_THRESHOLD) {
            proximity_alert = 1;
        } else {
            proximity_alert = 0;
        }
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting alert function on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("I2C Address: 0x%02X, Threshold: %d\n", i2c_address, threshold);

    while (running) {
        if (proximity_alert) {
            int value = proximity_value;
            proximity_alert = 0;
            if (read_proximity(&value) == 0) {
                log_proximity(value, 1);
            }
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

