#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPEAKER_PIN      18
#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define MIN_FREQUENCY    200
#define MAX_FREQUENCY    2000
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  200.0
#define ECHO_TIMEOUT_US  200000
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using HC-SR04.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static double measure_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, 10, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance = (pulse_us / 1000000.0) * 34300.0 / 2.0;
    return distance;
}

/*
 * Map distance to frequency using logarithmic scaling.
 * Returns frequency in Hz, or MIN_FREQUENCY on error.
 */
static int distance_to_frequency(double distance) {
    if (distance < 0.0) {
        return MIN_FREQUENCY;
    }
    if (distance < MIN_DISTANCE_CM) {
        return MIN_FREQUENCY;
    }
    if (distance > MAX_DISTANCE_CM) {
        return MAX_FREQUENCY;
    }
    double normalized = (distance - MIN_DISTANCE_CM) /
                        (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    double freq = MIN_FREQUENCY * exp(normalized * log(MAX_FREQUENCY / MIN_FREQUENCY));
    return (int)(freq + 0.5);
}

/*
 * Set PWM frequency and 50% duty cycle on the speaker pin.
 * Returns 0 on success, -1 on error.
 */
static int set_tone(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %d out of range [%d, %d]\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }

    /* pigpio hardware PWM: set frequency, 50% duty cycle (range 0-255) */
    if (gpioHardwarePWM(SPEAKER_PIN, frequency, 128) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for %d Hz\n", frequency);
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set speaker pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int current_frequency = MIN_FREQUENCY;
    if (set_tone(current_frequency) < 0) {
        fprintf(stderr, "Error: failed to set initial tone\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Speaker on GPIO%d, Trigger on GPIO%d, Echo on GPIO%d\n",
           SPEAKER_PIN, TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: distance measurement failed, keeping previous frequency\n");
        } else {
            int new_freq = distance_to_frequency(distance);
            if (new_freq != current_frequency) {
                if (set_tone(new_freq) == 0) {
                    current_frequency = new_freq;
                    printf("Distance: %.2f cm -> Frequency: %d Hz\n", distance, new_freq);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioHardwarePWM(SPEAKER_PIN, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

