           SPEAKER_PIN, TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: distance measurement failed, keeping previous frequency\n");
        } else {
            int new_freq = distance_to_frequency(distance);
            if (new_freq != current_frequency) {
                if (set_tone(new_freq) == 0) {
                    current_frequency = new_freq;
                    printf("Distance: %.2f cm -> Frequency: %d Hz\n", distance, new_freq);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioHardwarePWM(SPEAKER_PIN, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

