#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE 5.0f
#define MAX_DISTANCE 50.0f
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define TIMEOUT_US 100000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0f;
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0f;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0f;

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) return -1.0f;
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) return -1.0f;
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0f) * 34300.0f / 2.0f;
    return distance;
}

static int set_buzzer_frequency(float distance) {
    float frequency = MIN_FREQUENCY +
        (MAX_FREQUENCY - MIN_FREQUENCY) *
        (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    if (gpioHardwarePWM(BUZZER_PIN, (unsigned)frequency, 500000) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %.0f Hz\n", frequency);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    float last_valid_distance = 20.0f;

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: ultrasonic read failed, using last valid distance %.2f cm\n", last_valid_distance);
        } else {
            last_valid_distance = distance;
        }

        if (set_buzzer_frequency(last_valid_distance) < 0) {
            fprintf(stderr, "Error: failed to update buzzer frequency\n");
        }

        printf("Distance: %.2f cm, Frequency: %.0f Hz\n", last_valid_distance,
               MIN_FREQUENCY +
               (MAX_FREQUENCY - MIN_FREQUENCY) *
               (MAX_DISTANCE - last_valid_distance) / (MAX_DISTANCE - MIN_DISTANCE));

        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

