#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND 29.1f   /* cm/us */
#define MIN_DISTANCE   2.0f    /* cm */
#define MAX_DISTANCE   400.0f  /* cm */
#define TIMEOUT_US     50000   /* 50 ms */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US   500000 /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in us
 *   -1   : timeout (no echo received)
 *   -2   : echo went low before going high (stuck low)
 *   -3   : echo went high before going low (stuck high)
 */
static int measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    /* Wait for echo to go high (rising edge) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US)
            return -1; /* timeout */
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (falling edge) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US)
            return -2; /* timeout */
    }
    end_tick = gpioTick();

    return (int)(end_tick - start_tick);
}

static float calculate_distance(int pulse_width_us)
{
    if (pulse_width_us < 0)
        return -1.0f;
    return (float)pulse_width_us / SPEED_OF_SOUND / 2.0f;
}

int main(void)
{
    int pulse_width;
    float distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    printf("Ultrasonic distance measurement started.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Send 10 us trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        pulse_width = measure_echo_pulse();

        if (pulse_width < 0) {
            if (pulse_width == -1)
                fprintf(stderr, "Error: echo timeout (no response).\n");
            else if (pulse_width == -2)
                fprintf(stderr, "Error: echo stuck high (sensor absent or wiring fault).\n");
            else if (pulse_width == -3)
                fprintf(stderr, "Error: echo stuck low (sensor absent or wiring fault).\n");
        } else {
            distance = calculate_distance(pulse_width);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < 10.0f)
                    printf("  *** Too close! ***");
                printf("\n");
            }
        }

        /* Wait 500 ms before next measurement */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

