#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR        0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define LOG_FILE_NAME      "proximity_log.csv"
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_low, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_low, &lo) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, reg_low + 1, &hi) < 0) {
        return -1;
    }
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open(\"/dev/i2c-1\")");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE_NAME, "a");
    if (log_fp == NULL) {
        perror("fopen(\"" LOG_FILE_NAME "\")");
        goto cleanup;
    }

    if (fprintf(log_fp, "timestamp,als_visible\n") < 0) {
        perror("fprintf(header)");
        goto cleanup;
    }
    if (fflush(log_fp) != 0) {
        perror("fflush(header)");
        goto cleanup;
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_value = 0;

        if (i2c_read_reg16(i2c_fd, SI1175_REG_ALS_VIS_DATA0, &als_value) < 0) {
            fprintf(stderr, "Error reading ALS visible data (sensor absent or bus error).\n");
        } else {
            if (log_data(log_fp, als_value) < 0) {
                fprintf(stderr, "Error writing to log file.\n");
            } else {
                printf("ALS Visible: %u\n", als_value);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            perror("fclose(log_fp)");
        }
    }
    if (i2c_fd >= 0) {
        if (close(i2c_fd) < 0) {
            perror("close(i2c_fd)");
        }
    }
    return ret_code;
}

