#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_COMMAND 0x30
#define REG_ALS_DATA0 0x22
#define REG_ALS_DATA1 0x23
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19

#define CMD_RESET 0x01
#define EXPECTED_PART_ID 0x41

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading part ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1120 detected (part ID 0x%02X)\n", part_id);

    if (i2c_write_byte(handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_byte(handle, REG_HW_KEY, 0x00) != 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *prox) {
    uint8_t als_low = 0, als_high = 0, prox_low = 0, prox_high = 0;
    int retries = 0;
    int ok = 0;

    while (retries < MAX_RETRIES && !ok) {
        if (i2c_read_byte(handle, REG_ALS_DATA0, &als_low) == 0 &&
            i2c_read_byte(handle, REG_ALS_DATA1, &als_high) == 0 &&
            i2c_read_byte(handle, REG_PS1_DATA0, &prox_low) == 0 &&
            i2c_read_byte(handle, REG_PS1_DATA1, &prox_high) == 0) {
            *als = (uint16_t)((als_high << 8) | als_low);
            *prox = (uint16_t)((prox_high << 8) | prox_low);
            ok = 1;
        } else {
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(RETRY_DELAY_US);
        }
    }
    return ok ? 0 : -1;
}

static void log_data(FILE *fp, uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", SI1120_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t als = 0, prox = 0;
        if (read_sensor_data(i2c_handle, &als, &prox) == 0) {
            log_data(log_file, als, prox);
            printf("ALS: %u, Proximity: %u\n", als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

