#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE 0x06
#define SI1145_REG_ALS_VIS_DATA0 0x1A
#define SI1145_REG_ALS_VIS_DATA1 0x1B
#define SI1145_REG_PS1_DATA0 0x16
#define SI1145_REG_PS1_DATA1 0x17
#define SI1145_REG_COMMAND 0x80
#define SI1145_REG_PS_LED21 0x0C
#define SI1145_REG_PS_LED3 0x0F
#define SI1145_REG_PS_ADC_MISC 0x11
#define SI1145_REG_PS_ADC_GAIN 0x0D
#define SI1145_REG_ALS_VIS_ADC_GAIN 0x24
#define SI1145_REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define SI1145_REG_PS_ADC_COUNTER 0x22

#define SI1145_HW_KEY_VAL 0x03
#define SI1145_MEAS_RATE_2MS 0x02
#define SI1145_PS_FORCE 0x08
#define SI1145_PS_LED21_180MA 0x03
#define SI1145_PS_LED3_180MA 0x0F
#define SI1145_PS_ADC_MISC_SMALLIR 0x03
#define SI1145_PS_ADC_GAIN_77X 0x07
#define SI1145_ALS_VIS_ADC_GAIN_1X 0x00
#define SI1145_ALS_VIS_IR_ADC_COUNTER_16BIT 0x0B
#define SI1145_PS_ADC_COUNTER_16BIT 0x49

#define MAX_RETRIES 3
#define LOG_FILE "proximity_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int handle) {
    if (write_reg(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(handle, SI1145_REG_MEAS_RATE, SI1145_MEAS_RATE_2MS) < 0) return -1;
    if (write_reg(handle, SI1145_REG_ALS_VIS_IR_ADC_COUNTER, SI1145_ALS_VIS_IR_ADC_COUNTER_16BIT) < 0) return -1;
    if (write_reg(handle, SI1145_REG_ALS_VIS_ADC_GAIN, SI1145_ALS_VIS_ADC_GAIN_1X) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_ADC_COUNTER, SI1145_PS_ADC_COUNTER_16BIT) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_ADC_MISC, SI1145_PS_ADC_MISC_SMALLIR) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_ADC_GAIN, SI1145_PS_ADC_GAIN_77X) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_LED21, SI1145_PS_LED21_180MA) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_LED3, SI1145_PS_LED3_180MA) < 0) return -1;
    if (write_reg(handle, SI1145_REG_COMMAND, SI1145_PS_FORCE) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    int low = i2cReadByteData(handle, SI1145_REG_PS1_DATA0);
    if (low < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                SI1145_REG_PS1_DATA0, strerror(errno));
        return -1;
    }
    int high = i2cReadByteData(handle, SI1145_REG_PS1_DATA1);
    if (high < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                SI1145_REG_PS1_DATA1, strerror(errno));
        return -1;
    }
    *prox = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_data(FILE *fp, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, prox);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n",
                SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t prox;
    int retries = 0;

    while (!terminate) {
        if (read_proximity(i2c_handle, &prox) == 0) {
            log_data(log_file, prox);
            retries = 0;
        } else {
            log_error(log_file, "Failed to read proximity data");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries (%d) reached. Exiting.\n", MAX_RETRIES);
                break;
            }
            gpioDelay(100000);
            continue;
        }
        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

