#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end   = 0;
static volatile int      pulse_ready = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_ready = 1;
    }
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN %d low\n", BUZZER_PIN);
        return -1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on ECHO_PIN %d\n", ECHO_PIN);
        return -1;
    }
    return 0;
}

static double measure_distance_cm(void) {
    pulse_ready = 0;
    pulse_start = 0;
    pulse_end   = 0;

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    while (!pulse_ready && (gpioTick() - start_tick) < 100000) {
        gpioDelay(100);
    }
    if (!pulse_ready) {
        fprintf(stderr, "Error: echo pulse timeout\n");
        return -1.0;
    }

    uint32_t pulse_duration = pulse_end - pulse_start;
    return (double)pulse_duration * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance_cm();
        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < DISTANCE_THRESHOLD_CM) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to activate buzzer\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to deactivate buzzer\n");
                }
            }
        }
        sleep(1);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

