#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define MAX_ANGLE 90.0
#define MIN_ANGLE 0.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_PULSE 1500
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0;
    return distance;
}

static void set_servo_angle(float angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse = (int)(SERVO_MIN_PULSE + (angle / MAX_ANGLE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    gpioServo(SERVO_PIN, pulse);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioServo(SERVO_PIN, SERVO_MID_PULSE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
        } else if (distance < MIN_DISTANCE) {
            distance = MIN_DISTANCE;
        }

        float angle = (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE) * MAX_ANGLE;
        set_servo_angle(angle);

        printf("Distance: %.2f cm, Servo Angle: %.2f degrees\n", distance, angle);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

