#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 200
#define DISTANCE_THRESHOLD_CLOSE 250
#define SERVO_PULSE_CLOSED 1000
#define SERVO_PULSE_OPEN 2000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x000C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0082
#define VL53L1X_REG_SYSTEM_TIMING_CONFIG 0x0083
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_CONFIG 0x0084
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_A 0x0085
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_B 0x0086
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_C 0x0087
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_D 0x0088
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_E 0x008A
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_F 0x008B
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_G 0x008C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_H 0x008D
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_I 0x008E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_J 0x008F
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_K 0x0090
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_L 0x0091
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_M 0x0092
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_N 0x0093
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_O 0x0094
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_P 0x0095
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Q 0x0096
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_R 0x0097
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_S 0x0098
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_T 0x0099
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_U 0x009A
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_V 0x009B
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_W 0x009C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_X 0x009D
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Y 0x009E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Z 0x009F

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_TIMING_CONFIG, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_CONFIG, 0x00) != 0) return -1;

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_A, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_B, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_C, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_D, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_E, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_F, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_G, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_H, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_I, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_J, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_K, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_L, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_M, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_N, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_O, 0x0A) != 0) return -1;
