    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_R, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_S, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_T, 0x0A) != 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_U, 0x0A) != 0) return -1;
