#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG 0
#define MAX_ANGLE_DEG 180
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static long measure_echo_pulse(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_duration_us) {
    if (pulse_duration_us < 0) {
        return -1.0f;
    }
    return (float)pulse_duration_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static int map_distance_to_angle(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return MAX_ANGLE_DEG;
    }
    return (int)(((distance_cm - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG);
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_US +
        (int)(((float)(angle - MIN_ANGLE_DEG) /
               (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG)) *
              (float)(SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        long pulse_duration = measure_echo_pulse();
        float distance = calculate_distance(pulse_duration);

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor timeout or invalid reading\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking Assist System stopped.\n");
    return 0;
}

