    if (distance_cm < MIN_DISTANCE_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return MAX_ANGLE_DEG;
    }
    return (int)(((distance_cm - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG);
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_US +
        (int)(((float)(angle - MIN_ANGLE_DEG) /
               (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG)) *
              (float)(SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        long pulse_duration = measure_echo_pulse();
        float distance = calculate_distance(pulse_duration);

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor timeout or invalid reading\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking Assist System stopped.\n");
    return 0;
}

