#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40

#define REG_TEMP_HOLD  0x01
#define REG_HUMID_HOLD 0x02
#define REG_CONFIG     0x03

#define CONFIG_DEFAULT 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int configure_sensor(int handle) {
    if (i2c_write_reg(handle, REG_CONFIG, CONFIG_DEFAULT) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms for configuration to take effect */
    return 0;
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    uint8_t raw_temp, raw_humid;

    if (i2c_read_reg(handle, REG_TEMP_HOLD, &raw_temp) != 0) {
        return -1;
    }
    if (i2c_read_reg(handle, REG_HUMID_HOLD, &raw_humid) != 0) {
        return -1;
    }

    *temperature = ((175.72f * (float)raw_temp) / 65536.0f) - 46.85f;
    *humidity    = ((125.0f  * (float)raw_humid) / 65536.0f) - 6.0f;

    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to configure Si7005\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float temperature, humidity;

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, re-opening I2C bus...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed (handle=%d)\n", g_i2c_handle);
                cleanup();
                return EXIT_FAILURE;
            }
            if (configure_sensor(g_i2c_handle) != 0) {
                fprintf(stderr, "Error: Sensor re-configuration failed\n");
                cleanup();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(2000000); /* 2 seconds */
    }

    cleanup();
    return EXIT_SUCCESS;
}

