#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define PWR_MGMT_1         0x6B
#define SMPLRT_DIV         0x19
#define CONFIG              0x1A
#define GYRO_CONFIG        0x1B
#define ACCEL_CONFIG       0x1C
#define ACCEL_XOUT_H       0x3B

/* Expected sample rate: 1 kHz / (1 + 7) = 125 Hz */
#define SMPLRT_DIV_VAL     7

/* Global handle for signal-safe cleanup */
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I (pigpio error %d)\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset the device */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error: failed to reset MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms reset settling time */

    /* Wake up, internal oscillator, normal mode */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms for oscillator to stabilize */

    /* Sample rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, SMPLRT_DIV, SMPLRT_DIV_VAL) < 0) {
        fprintf(stderr, "Error: failed to set sample rate divider\n");
        return -1;
    }

    /* DLPF config: 0x00 -> 184 Hz bandwidth, 125 Hz output */
    if (i2cWriteByteData(handle, CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set DLPF config\n");
        return -1;
    }

    /* Gyro: ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set gyro config\n");
        return -1;
    }

    /* Accel: ±2 g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set accel config\n");
        return -1;
    }

    return 0;
}

static int read_mpu6050_data(int handle,
                             int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: failed to read 14-byte data block\n");
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X (pigpio error %d)\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 ready. Press Ctrl+C to stop.\n");
    fflush(stdout);

    while (g_running) {
        if (read_mpu6050_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: I2C read failed, retrying...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

