#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR             0x44
#define SHT40_CMD_MEASURE_HIGH 0xFD
#define I2C_BUS                1
#define READ_INTERVAL_US       5000000  /* 5 seconds */
#define MEASURE_DELAY_US       10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (polynomial 0x31, init 0xFF) per Sensirion SHT40 datasheet ---- */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int open_i2c(void)
{
