#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int fd, uint8_t reg, float *temp) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[3];
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temp = (float)raw * 0.02 - 273.15;
    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 1;

        if (read_temperature(fd, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            ok = 0;
        }

        if (ok && read_temperature(fd, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            ok = 0;
        }

        if (ok) {
            if (log_temperature(fp, ambient, object) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

