void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        return -1;
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * (float)raw_temp / 65535.0);
    return 0;
}

