/*
 * Smart Greenhouse Monitor - SHT40 Humidity/Temperature Sensor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1  (SDA=GPIO2, SCL=GPIO3)
 * Address: 0x44 (7-bit)
 * Command: 0xFD (high repeatability, ~10 ms conversion)
 * Log:    sht40_log.txt every 5 seconds
 *
 * Build:  gcc -O2 -Wall -o sht40_monitor sht40_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define SHT40_CMD_MEAS 0xFD          /* high repeatability, ~10 ms */
#define SHT40_MEAS_MS  10000         /* 10 ms conversion time */
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_MS      5000          /* 5 s between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR           */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep                                                   */
/* ------------------------------------------------------------------ */
static void delay_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open I2C bus and set slave address                                  */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
/* Read SHT40: send command, wait, read 6 bytes, validate CRC          */
/* ------------------------------------------------------------------ */
static int sht40_read(int fd, float *temp_c, float *rh)
{
    uint8_t cmd = SHT40_CMD_MEAS;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "[ERROR] write(cmd 0x%02X): %s\n",
                cmd, w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    delay_ms(SHT40_MEAS_MS);

    uint8_t buf[6];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] read(): %s\n",
                r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC validation of each 2-byte data word */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh     = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temp_c < -40.0f || *temp_c > 125.0f) {
        fprintf(stderr, "[WARN] temperature out of range: %.2f C\n", *temp_c);
        return -1;
    }
    if (*rh < 0.0f || *rh > 100.0f) {
        fprintf(stderr, "[WARN] humidity out of range: %.2f %%\n", *rh);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                        */
/* ------------------------------------------------------------------ */
static void log_reading(float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temp_c, rh);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, SHT40_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_MS / 1000);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (sht40_read(g_i2c_fd, &temp_c, &rh) == 0) {
            log_reading(temp_c, rh);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "sample", temp_c, rh);
        } else {
            fprintf(stderr, "[WARN] sensor read failed; will retry next cycle\n");
        }

        /* Sleep SAMPLE_MS but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 100)
            delay_ms(100);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

