/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers with retry ---- */
static int i2c_write_retry(int handle, const uint8_t *buf, int count)
{
    int delay = RETRY_BASE_US;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, count);
        if (rc == count)
            return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d, rc=%d)\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(delay);
        delay *= 2;
    }
    return -1;
}

static int i2c_read_retry(int handle, uint8_t *buf, int count)
{
    int delay = RETRY_BASE_US;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, count);
        if (rc == count)
            return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d, rc=%d)\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(delay);
        delay *= 2;
    }
    return -1;
}

/* ---- SDP31 continuous-read trigger ---- */
static int sdp31_trigger_continuous(int handle)
{
    uint8_t cmd[2] = { 0x21, 0x96 };
    return i2c_write_retry(handle, cmd, sizeof(cmd));
}

/* ---- Read one 6-byte sample ---- */
static int sdp31_read_sample(int handle, uint8_t *buf)
{
    return i2c_read_retry(handle, buf, sizeof(buf));
}

/* ---- Convert raw bytes to physical units ---- */
static void sdp31_convert(const uint8_t *buf, float *pressure_pa,
                          float *temperature_c)
{
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure_pa = (float)raw_pressure / 60.0f;
    *temperature_c = (float)raw_temp / 200.0f;
