    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Start continuous measurement ---- */
    if (sdp31_trigger_continuous(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to start SDP31 continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- First measurement is ready after ~1 ms ---- */
    gpioDelay(MEAS_DELAY_US);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint8_t sample[6];
        if (sdp31_read_sample(g_i2c_handle, sample) != 0) {
            fprintf(stderr, "Failed to read SDP31 sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float pressure_pa, temperature_c;
        sdp31_convert(sample, &pressure_pa, &temperature_c);

        if (log_data(g_log_file, pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

