#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUM_NOHOLD  0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_PERIOD  5.0   /* seconds */
#define MEASURE_TIMEOUT_MS 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the Si7015                           */
/* ------------------------------------------------------------------ */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw 16-bit measurement from the Si7015                         */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si7015_read_raw(int handle, uint16_t *raw_out)
{
    char buf[2];
    int rc;

    /*
     * In No Hold Master mode the sensor holds SCL low while the
     * conversion is under way, so we must poll until data arrives.
     */
    for (int elapsed = 0; elapsed < MEASURE_TIMEOUT_MS; elapsed += 5) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) |
                       (uint16_t)(uint8_t)buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "[ERROR] i2cReadDevice poll failed: %s\n",
                    pigpio_error(rc));
            return -1;
        }
        /* rc == 0: no data yet — keep waiting */
        time_sleep(0.005);
    }

    fprintf(stderr, "[ERROR] Si7015 measurement timed out after %d ms\n",
            MEASURE_TIMEOUT_MS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Convert raw temperature to degrees Celsius                          */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

/* ------------------------------------------------------------------ */
/* Convert raw humidity to percentage RH (clamped to [0, 100])          */
/* ------------------------------------------------------------------ */
static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temp_c, rh);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[WARN] fclose(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sensor sample                                              */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *temp_c, float *rh)
{
    uint16_t raw;

    if (si7015_write_cmd(handle, CMD_TEMP_NOHOLD) < 0)
        return -1;
    if (si7015_read_raw(handle, &raw) < 0)
        return -1;
    *temp_c = raw_to_celsius(raw);

    if (si7015_write_cmd(handle, CMD_HUM_NOHOLD) < 0)
        return -1;
    if (si7015_read_raw(handle, &raw) < 0)
        return -1;
    *rh = raw_to_humidity(raw);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si7015 address ----------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        float temp_c, rh;

        if (read_sensor(g_i2c_handle, &temp_c, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp_c, rh);
            if (log_data(temp_c, rh) < 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed — continuing.\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++) {
            time_sleep(0.1);
        }
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

