#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0
#define TEMP_THRESHOLD_LOW   27.0
#define MAX_RETRIES     3
#define MEAS_DELAY_US   15000   /* 15 ms — exceeds Si7021 max conversion time */

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, float temperature, float humidity) {
    time_t now = time(NULL);
    cb->data[cb->head].temperature = temperature;
    cb->data[cb->head].humidity = humidity;
    cb->data[cb->head].timestamp = now;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int retries;

    /* --- Temperature (Hold Master, 0xE3) --- */
    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (i2cWriteByte(i2c_handle, 0xE3) != 0) {
            fprintf(stderr, "I2C write 0xE3 failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);
        if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
            fprintf(stderr, "I2C read 0xE3 failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *temperature = (175.72f * raw / 65536.0f) - 46.85f;
        break;
    }
    if (retries == MAX_RETRIES) return -1;

    /* --- Humidity (Hold Master, 0xE5) --- */
    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (i2cWriteByte(i2c_handle, 0xE5) != 0) {
            fprintf(stderr, "I2C write 0xE5 failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);
        if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
            fprintf(stderr, "I2C read 0xE5 failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *humidity = (125.0f * raw / 65536.0f) - 6.0f;
        break;
    }
    if (retries == MAX_RETRIES) return -1;

    /* Sanity-check ranges */
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f\n", *humidity);
        return -1;
    }
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temperature);
        return -1;
    }
    return 0;
}

static void control_fan(float temperature) {
    static int fan_on = 0;
    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON  (Temperature: %.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f C)\n", temperature);
    }
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n",
           ts, temperature, humidity);
    add_to_buffer(&buffer, temperature, humidity);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    init_circular_buffer(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed — attempting re-initialisation...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialisation failed. Exiting.\n");
                break;
            }
        }

        /* Sleep 2 s in 200 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(200000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

