#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */
#define MEASUREMENT_INTERVAL_US 1000000 /* 1 second between start and first read */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT           0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY             0xE4B8

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *buf, size_t len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: failed to read %zu bytes\n", len);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(MEASUREMENT_INTERVAL_US);
    return 0;
}

static int stop_periodic_measurement(void) {
    return send_command(CMD_STOP_PERIODIC_MEASUREMENT);
}

static int is_data_ready(void) {
    if (send_command(CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000); /* command processing time */
    uint8_t buf[3];
    if (read_data(buf, sizeof(buf)) != 0)
        return -1;
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    return (word & 0x07FF) != 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *rh) {
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (read_data(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temp_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t rh_raw  = (uint16_t)((buf[6] << 8) | buf[7]);

    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *rh  = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (code %d)\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SCD40 periodic measurement started. Logging to %s every 5 s. Ctrl+C to stop.\n",
           LOG_FILE);

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: failed to poll data-ready flag\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready) {
            uint16_t co2;
            float temp, rh;
            if (read_measurement(&co2, &temp, &rh) == 0) {
                log_data(co2, temp, rh);
                printf("CO2: %u ppm | Temp: %.2f C | RH: %.2f %%\n", co2, temp, rh);
            } else {
                fprintf(stderr, "Error: failed to read measurement\n");
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    }
    gpioDelay(500000); /* allow stop command to take effect */
    if (i2cClose(i2c_handle) != 0) {
        fprintf(stderr, "Warning: failed to close I2C handle\n");
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Warning: failed to close log file\n");
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

