#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8

#define STATUS_DATA_READY 0x01

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(void) {
    if (i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int scd40_stop_periodic_measurement(void) {
    if (i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int scd40_data_ready(bool *ready) {
    if (i2c_write_cmd(CMD_GET_DATA_READY_STATUS) != 0) return -1;
    gpioDelay(1000);
    uint8_t buf[3];
    if (i2c_read_data(buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch in data-ready status\n");
        return -1;
    }
    uint16_t word = (buf[0] << 8) | buf[1];
    *ready = (word & STATUS_DATA_READY) ? true : false;
    return 0;
}

static int scd40_read_measurement(SensorData *data) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(1000);
    uint8_t buf[9];
    if (i2c_read_data(buf, 9) != 0) return -1;

    for (int i = 0; i < 3; i++) {
