#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TIMEOUT_US 50000             /* 50 ms edge timeout */
#define MAX_CONSECUTIVE_ERRORS 3
#define TEMP_MIN_VALID -40.0
#define TEMP_MAX_VALID 150.0

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Wait for a level transition with microsecond timeout               */
/* Returns 0 on success, -1 on timeout                                */
/* ------------------------------------------------------------------ */
static int wait_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure TH (high-pulse width) and TL (total-cycle width) in us      */
/* Returns 0 on success, -1 on timeout / error                        */
/* ------------------------------------------------------------------ */
static int measure_cycle(int pin, uint32_t *th, uint32_t *tl)
{
    uint32_t t_start, t_now;

    /* Wait for rising edge (start of high pulse) */
    if (wait_level(pin, 1, TIMEOUT_US) != 0)
        return -1;
    t_start = gpioTick();

    /* Wait for falling edge (end of high pulse) */
    if (wait_level(pin, 0, TIMEOUT_US) != 0)
        return -1;
    t_now = gpioTick();

    *th = t_now - t_start;
    *tl = t_now - t_start;  /* placeholder — corrected below */

    /* Wait for next rising edge (end of low / start of next cycle) */
    if (wait_level(pin, 1, TIMEOUT_US) != 0)
        return -1;
    t_now = gpioTick();

    *tl = t_now - t_start;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert TH/TL to Celsius using TMP05 formula                        */
/* ------------------------------------------------------------------ */
static double convert_to_celsius(uint32_t th, uint32_t tl)
{
    if (tl == 0)
        return -999.0;  /* guard against division by zero */
    return 4215.0 - (2143.0 * (double)th / (double)tl);
}

/* ------------------------------------------------------------------ */
/* Log a reading with ISO-8601 timestamp                              */
/* ------------------------------------------------------------------ */
static void log_temperature(double temp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temp < TEMP_MIN_VALID || temp > TEMP_MAX_VALID) {
        fprintf(log_file, "%s, ERROR: Temperature out of valid range (%.2f C)\n",
                timestamp, temp);
    } else {
        fprintf(log_file, "%s, %.2f\n", timestamp, temp);
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Log a malfunction entry                                            */
/* ------------------------------------------------------------------ */
static void log_malfunction(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: SENSOR MALFUNCTION — 3 consecutive read failures\n",
            timestamp);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pin --- */
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_PIN);

    /* --- Main sampling loop --- */
    while (program_running) {
        uint32_t th = 0, tl = 0;

        if (measure_cycle(GPIO_PIN, &th, &tl) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: failed to measure cycle on GPIO%d (timeout or stuck)\n",
                    GPIO_PIN);
            log_temperature(-999.0);
        } else {
            consecutive_errors = 0;
            double temp = convert_to_celsius(th, tl);

            if (temp < TEMP_MIN_VALID || temp > TEMP_MAX_VALID) {
                fprintf(stderr, "Warning: temperature %.2f C out of valid range\n",
                        temp);
                log_temperature(temp);
            } else {
                printf("Temperature: %.2f C\n", temp);
                log_temperature(temp);
            }
        }

        /* Malfunction after 3 consecutive failures */
        if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
            log_malfunction();
            consecutive_errors = 0;  /* reset so we don't spam */
        }

        /* Sleep for the sample interval (interruptible by signals) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

