#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000 /* 15 ms max conversion time */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t sht35_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to SHT35\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT35\n");
        return -1;
    }

    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t hum_raw  = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *humidity    = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static int ensure_csv_header(void) {
    FILE *fp = fopen(CSV_FILENAME, "r");
    if (fp != NULL) {
        fseek(fp, 0, SEEK_END);
        long sz = ftell(fp);
        fclose(fp);
        if (sz > 0)
            return 0; /* file exists and has content */
    }
    fp = fopen(CSV_FILENAME, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot create CSV file '%s'\n", CSV_FILENAME);
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open '%s' for appending\n", CSV_FILENAME);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
