    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d) on bus %d addr 0x%02X\n",
                handle, I2C_BUS, SHT35_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    while (g_running) {
        if (read_sht35(handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

