#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define POLL_TIMEOUT_MS    100
#define SAMPLE_INTERVAL_S  5

#define CMD_MEASURE_RH_NH  0xF5
#define CMD_MEASURE_TEMP_NH 0xF3
#define CMD_READ_PREV_TEMP 0xE0
#define CMD_RESET          0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) return -1;
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;

    uint8_t buf[3];
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        usleep(1000);
        elapsed++;
        if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
        if (crc8(buf, 2) == buf[2]) break;
    }
    if (elapsed >= POLL_TIMEOUT_MS) return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_NH, &raw) < 0) return -1;
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_RH_NH, &raw) < 0) return -1;
    *hum = (125.0f * raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static int log_data(const char *ts, float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return -1; }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

static int log_error(const char *ts) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return -1; }
    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n", LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        float temp = 0.0f, hum = 0.0f;
        int ok = 1;

        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "%s: temp read failed\n", ts);
            ok = 0;
        }
        if (ok && read_humidity(g_i2c_fd, &hum) < 0) {
            fprintf(stderr, "%s: hum read failed\n", ts);
            ok = 0;
        }

        if (ok) {
            if (log_data(ts, temp, hum) < 0)
                fprintf(stderr, "%s: log write failed\n", ts);
            printf("%s  T=%.2f C  RH=%.2f %%\n", ts, temp, hum);
        } else {
            if (log_error(ts) < 0)
                fprintf(stderr, "%s: error log write failed\n", ts);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) sleep(1);
    }

    if (g_i2c_fd >= 0) {
        i2c_write_cmd(g_i2c_fd, CMD_RESET);
        close(g_i2c_fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

