    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        SensorData data = read_sensor_data();
        if (data.valid) {
            log_data(data.pressure);
            printf("Pressure: %.2f Pa\n", data.pressure);
        } else {
            fprintf(stderr, "Failed to read valid sensor data.\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

