#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define MIN_RAW 1638
#define MAX_RAW 14745
#define MIN_FLOW 0.0f
#define MAX_FLOW 10.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_raw(int handle, int16_t *raw_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes): %s\n", bytes, strerror(errno));
        return -1;
    }
    uint16_t word = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t status = (word >> 14) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }
    *raw_out = (int16_t)(word >> 2);
    return 0;
}

static float calculate_flow_rate(int16_t raw) {
    if (raw < MIN_RAW) raw = MIN_RAW;
    if (raw > MAX_RAW) raw = MAX_RAW;
    return MIN_FLOW + ((float)(raw - MIN_RAW) * (MAX_FLOW - MIN_FLOW) / (MAX_RAW - MIN_RAW));
}

static void set_fan_speed(float flow_rate) {
    int duty = (int)(flow_rate / MAX_FLOW * (float)PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(FILE *fp, int16_t raw, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, raw, flow_rate);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed on bus %d addr 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);
    gpioPWM(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw;
        if (read_sensor_raw(i2c_handle, &raw) == 0) {
            float flow = calculate_flow_rate(raw);
            set_fan_speed(flow);
            log_data(log_file, raw, flow);
            printf("Raw: %d, Flow: %.2f SLPM\n", raw, flow);
        } else {
            fprintf(stderr, "Sensor read error; keeping fan at current duty.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

