#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from STLM75.
 * The sensor returns a 16-bit two's-complement word with 9-bit resolution.
 * pigpio's i2cReadWordData returns the two bytes in little-endian order,
 * so we swap them and then right-shift by 7 to get the 9-bit value.
 * The result is then scaled by 2 (since each LSB is 1/2 deg C).
 */
static int read_temperature(int handle, float *out) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        return -1;
    }

    uint16_t swapped = ((uint16_t)(raw & 0xFF) << 8) | ((uint16_t)(raw >> 8) & 0xFF);
    int16_t value = (int16_t)swapped;
    value >>= 7;                       /* 9-bit two's complement */
    *out = (float)value / 2.0f;       /* each LSB = 1/2 deg C */
    return 0;
}

static void update_circular_buffer(float temp, float buf[], int *idx, int size) {
    buf[*idx] = temp;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float buf[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buf[i];
    }
    return sum / (float)size;
}

int main(void) {
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Open I2C bus --- */
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Circular buffer --- */
    float temp_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    /* --- Main loop --- */
    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: I2C read failed; skipping sample.\n");
        } else {
            update_circular_buffer(temperature, temp_buffer, &buffer_index, BUFFER_SIZE);
            float average_temp = calculate_average(temp_buffer, BUFFER_SIZE);

            if (average_temp > TEMP_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }

            printf("Temperature: %.2f C, Average: %.2f C, LED: %s\n",
                   temperature, average_temp,
                   (average_temp > TEMP_THRESHOLD) ? "ON" : "OFF");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

