#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1199
#define MEASUREMENT_INTERVAL_SEC 2

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (crc8(buf, 2) != 0) return -1;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) return -1;
    return 0;
}

static int scd30_write_command_with_args(uint16_t cmd, uint16_t arg1, uint16_t arg2) {
    uint8_t buf[7];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg1 >> 8);
    buf[3] = (uint8_t)(arg1 & 0xFF);
    buf[4] = (uint8_t)(arg2 >> 8);
    buf[5] = (uint8_t)(arg2 & 0xFF);
    buf[6] = crc8(buf, 5);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 7) != 0) return -1;
    return 0;
}

static int scd30_read_data(uint8_t *data, int len) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, len);
    if (bytes_read != len) return -1;
    for (int i = 0; i < len; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) return -1;
    }
    return 0;
}

