/*
 * SDP32 differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SDP32 SDA -> GPIO2 (pin 3)
 *   SDP32 SCL -> GPIO3 (pin 5)
 *   SDP32 VDD -> 3.3 V
 *   SDP32 GND -> GND
 *
 * Build: gcc -O2 -Wall -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_I2C_ADDR      0x21
#define I2C_BUS             1

/* Continuous measurement command (no clock stretching, average until read) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

/* SDP32 continuous measurement read frame: 9 bytes */
#define FRAME_LEN           9
static const uint8_t FRAME_WORDS[FRAME_LEN] = {
    0, 1, 2, 3, 4, 5, 6, 7, 8
};

/* CRC-8 polynomial used by Sensirion: x^8 + x^5 + x^4 + 1 (0x31), init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read one 9-byte frame from the SDP32 and convert to differential pressure.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp32(int handle, float *pressure_pa)
{
    uint8_t buf[FRAME_LEN];
    int n = i2cReadDevice(handle, (char *)buf, FRAME_LEN);
    if (n != FRAME_LEN) {
        fprintf(stderr, "[ERROR] I2C read failed: expected %d bytes, got %d\n",
                FRAME_LEN, n);
        return -1;
    }

    /* Verify CRC on each 3-byte word */
    for (int w = 0; w < 3; w++) {
        uint8_t calc = crc8(&buf[w * 3], 2);
        if (calc != buf[w * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d (calc=0x%02X, got=0x%02X)\n",
                    w, calc, buf[w * 3 + 2]);
            return -2;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t scale_factor  = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero — invalid frame\n");
        return -2;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

static void log_reading(float pressure_pa)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    printf("[%s] Pressure: %.2f Pa\n", ts, pressure_pa);
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    int interval_ms = 1000;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "[ERROR] Invalid interval '%s'; using default 1000 ms\n", argv[1]);
            interval_ms = 1000;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP32_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SDP32_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (i2cWriteDevice(g_i2c_handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send continuous measurement command\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after ~45 ms; allow margin */
    gpioDelay(50000); /* microseconds */

    printf("SDP32 pressure reader started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           interval_ms);

    while (g_running) {
        float pressure_pa;
        int rc = read_sdp32(g_i2c_handle, &pressure_pa);

        if (rc == 0) {
            log_reading(pressure_pa);
        } else if (rc == -1) {
            /* I2C bus error — sensor may be disconnected or bus hung */
            fprintf(stderr, "[ERROR] I2C bus error; sensor may be disconnected.\n");
            break;
        } else {
            /* CRC mismatch — sensor data is corrupted */
            fprintf(stderr, "[ERROR] CRC mismatch on SDP32 frame.\n");
            break;
        }

        /* Sleep for the configured interval (interruptible by signals) */
        gpioDelay(interval_ms * 1000); /* microseconds */
    }

    cleanup();
    return EXIT_SUCCESS;
}

