    uint8_t cmd[2] = { (uint8_t)(CMD_CONTINUOUS >> 8),
                       (uint8_t)(CMD_CONTINUOUS & 0xFF) };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x%04X)\n", CMD_CONTINUOUS);
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] I2C read failed: got %d bytes, expected 9\n", n);
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t p_sf = (uint16_t)((buf[6] << 8) | buf[7]);

    if (p_sf == 0) {
        fprintf(stderr, "[ERROR] Scale factor for pressure is zero\n");
        return -2;
    }

    *pressure    = (float)raw_pressure / (float)p_sf;
    *temperature = (float)raw_temp / 200.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float pressure, temperature;
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C bus error — continuing\n");
        } else {
            fprintf(stderr, "[WARN] CRC/validation error — continuing\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

