/*
 * HDC1000 temperature & humidity reader for Raspberry Pi 4 Model B
 * Uses the Linux i2c-dev API (no wiringPi).
 *
 * Wiring:
 *   HDC1000 SDA  -> GPIO 2 (pin 3, I2C bus 1)
 *   HDC1000 SCL  -> GPIO 3 (pin 5, I2C bus 1)
 *   HDC1000 VDD  -> 3.3 V
 *   HDC1000 GND  -> GND
 *   HDC1000 ADDR -> GND  (default address 0x40)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc1000 hdc1000.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40

/* HDC1000 register addresses */
#define REG_TEMP       0x00
#define REG_HUMID      0x01
#define REG_CONFIG     0x02

/* Config register bits */
#define CFG_TEMP_HUMID 0x0800  /* bit 12: take temperature + humidity together */
#define CFG_14BIT      0x0000  /* bits 13-12 = 00 -> 14-bit resolution */

#define SAMPLE_PERIOD_S 5
#define CONV_WAIT_MS   20   /* 14-bit conversion takes ~12.5 ms; 20 ms is safe */

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an 8-bit register pointer.                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int hdc1000_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);        /* low byte first */
    buf[2] = (uint8_t)((value >> 8) & 0xFF); /* high byte second */

    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%04X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes from the currently pointed register.               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int hdc1000_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg pointer 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read the data bytes */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(reg=0x%02X, len=%zu) failed: %s (got %zd bytes)\n",
                reg, len, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int hdc1000_init(int fd)
{
    /*
     * Configure: 14-bit resolution, no heater, no alert,
     * bit 12 = 1 -> take temperature and humidity together.
     */
    uint16_t cfg = CFG_14BIT | CFG_TEMP_HUMID;
    if (hdc1000_write_reg16(fd, REG_CONFIG, cfg) != 0) {
        fprintf(stderr, "Failed to configure HDC1000 (sensor may be absent or bus error)\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int hdc1000_read_temp_humid(int fd, float *temp_c, float *rh)
{
    /*
     * Trigger a combined T+RH measurement by writing the temperature
     * register pointer (0x00).  The HDC1000 then performs a 14-bit
     * conversion for both temperature and humidity simultaneously.
     *
     * Because DRDYn is not connected on the default 7-bit address, we
     * rely on the fixed 12.5 ms conversion time for 14-bit mode.
     */
    uint8_t reg = REG_TEMP;
    uint8_t data[4];

    /* Point to the temperature register to start a measurement */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg pointer 0x%02X) failed: %s\n",
                REG_TEMP, strerror(errno));
        return -1;
    }

    /* Wait for the conversion to complete (14-bit mode: ~12.5 ms) */
    struct timespec ts = { 0, CONV_WAIT_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 4 bytes: 2 temp + 2 humidity */
    if (hdc1000_read_reg(fd, REG_TEMP, data, sizeof(data)) != 0)
        return -1;

    uint16_t raw_t  = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_rh = ((uint16_t)data[2] << 8) | data[3];

    *temp_c = ((float)raw_t  / 65536.0f) * 165.0f - 40.0f;
    *rh     = ((float)raw_rh / 65536.0f) * 100.0f;

    /* Sanity-check ranges */
    if (*temp_c < -40.0f || *temp_c > 125.0f || *rh < 0.0f || *rh > 100.0f) {
        fprintf(stderr, "Warning: reading out of range (T=%.2f C, RH=%.2f %%)\n",
                *temp_c, *rh);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open the I2C bus */
    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the HDC1000 slave address */
    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (hdc1000_init(g_fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed. Check wiring and address.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at address 0x%02X. Sampling every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_PERIOD_S);
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        float temp_c, rh;

        if (hdc1000_read_temp_humid(g_fd, &temp_c, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    if (g_fd >= 0)
        close(g_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

