#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define SI7051_REG_TEMP_HOLD 0xE0
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, SI7051_REG_TEMP_HOLD);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(10000);

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (result != 2) {
            fprintf(stderr, "Unexpected byte count read: %d (attempt %d)\n", result, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
        *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    float temperature;
    int result;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %d\n", SI7051_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7051 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        result = read_temperature(&temperature);
        if (result == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

