#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP_10101_ADDR 0x63

#define CMD_READ_OTP   0x50
#define CMD_MEASURE    0x40

#define MEASURE_DELAY_US 7000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    uint16_t scale_factor_lut;
    uint16_t scale_factor_h;
    uint16_t scale_factor_p;
} icp_calibration_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_otp(int handle, uint8_t *buf, int len) {
    if (i2cWriteByte(handle, CMD_READ_OTP) < 0) {
        fprintf(stderr, "Error: failed to write OTP read command.\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: failed to read OTP data.\n");
        return -1;
    }
    return 0;
}

static int read_calibration(int handle, icp_calibration_t *cal) {
    uint8_t buf[8];
    if (read_otp(handle, buf, sizeof(buf)) != 0) {
        return -1;
    }
    uint16_t lut = (buf[0] << 8) | buf[1];
    uint16_t h  = (buf[2] << 8) | buf[3];
    uint16_t p  = (buf[4] << 8) | buf[5];
    cal->scale_factor_lut = lut;
    cal->scale_factor_h  = h;
    cal->scale_factor_p  = p;
    return 0;
}

static int trigger_measurement(int handle) {
    if (i2cWriteByte(handle, CMD_MEASURE) < 0) {
        fprintf(stderr, "Error: failed to trigger measurement.\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    return 0;
}

static int read_measurement(int handle, uint16_t *raw_t, uint32_t *raw_p) {
    uint8_t buf[6];
    if (i2cReadDevice(handle, (char *)buf, sizeof(buf)) != sizeof(buf)) {
        fprintf(stderr, "Error: failed to read measurement data.\n");
        return -1;
    }
    *raw_t = (buf[0] << 8) | buf[1];
    *raw_p = ((uint32_t)buf[2] << 16) | ((uint32_t)buf[3] << 8) | buf[4];
    return 0;
}

static void compute_compensated(uint16_t raw_t, uint32_t raw_p,
                                const icp_calibration_t *cal,
                                float *temp_c, float *press_pa) {
    float t = (float)raw_t;
    float p = (float)raw_p;
    float t_comp = t * 0.01f - 40.0f;
    float p_comp = p * 0.0001f * cal->scale_factor_h +
                   t * 0.0001f * cal->scale_factor_lut +
                   t * t * 0.0001f * cal->scale_factor_p -
                   45000.0f;
    *temp_c = t_comp;
    *press_pa = p_comp;
}

static void log_data(float temp_c, float press_pa) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp_c, press_pa);
    fflush(stdout);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP_10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (code %d).\n",
                ICP_10101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    icp_calibration_t cal;
    if (read_calibration(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration coefficients.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        if (trigger_measurement(g_i2c_handle) != 0) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
            continue;
        }

        uint16_t raw_t;
        uint32_t raw_p;
        if (read_measurement(g_i2c_handle, &raw_t, &raw_p) != 0) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
            continue;
        }

        float temp_c, press_pa;
        compute_compensated(raw_t, raw_p, &cal, &temp_c, &press_pa);

        if (raw_t == 0xFFFF && raw_p == 0xFFFFFFFF) {
            fprintf(stderr, "Warning: sensor returned 0xFF for both readings "
                            "(sensor absent or not responding).\n");
        } else {
            log_data(temp_c, press_pa);
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

