    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_out)
{
    if (i2c_write_reg8(fd, REG_TRIGGER, TRIGGER_CMD) < 0)
        return -1;

    /* Allow time for the conversion to complete */
    usleep(10000);

    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg8(fd, REG_PRESSURE_MSB, &msb) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_PRESSURE_LSB, &lsb) < 0)
        return -1;

    int16_t raw = (int16_t)((msb << 8) | lsb);
    *pressure_out = (float)raw * SCALE_FACTOR;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure reader started on %s (addr 0x%02X).\n", I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure = 0.0f;
        if (read_pressure(fd, &pressure) < 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %.2f kPa\n", ts, pressure);
            fflush(stdout);
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nExiting...\n");
    close(fd);
    return EXIT_SUCCESS;
}

