#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

static int truncate_log_file(void) {
    FILE *fp = fopen(LOG_FILE, "r+");
    if (!fp) {
        fprintf(stderr, "Error opening log file for truncation: %s\n", strerror(errno));
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "Error getting log file size: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (ftruncate(fileno(fp), file_size) != 0) {
        fprintf(stderr, "Error truncating log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int read_hih6130(float *temperature, float *humidity) {
    uint8_t cmd = 0x00;
    uint8_t buf[4];

    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 4) != 4) {
        fprintf(stderr, "Error reading data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint16_t status = (buf[0] << 8) | buf[1];
    if ((status & 0x03) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    uint16_t raw_humidity = (buf[2] << 8) | buf[3];
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];

    *humidity = (float)raw_humidity * 100.0f / 16383.0f;
    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %s\n",
                HIH6130_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature, humidity;

        if (read_hih6130(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (truncate_log_file() != 0) {
                fprintf(stderr, "Error truncating log file\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        if (running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

