#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define SENT_TICK_US 3
#define SENT_SYNC_TICKS 56
#define SENT_NIBBLE_MIN_TICKS 12
#define SENT_NIBBLE_MAX_TICKS 271
#define SENT_TIMEOUT_US 1000000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
        fclose(fp);
    } else {
        log_error("Failed to open log file");
    }
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_sent_nibble(int gpio, uint8_t *nibble) {
    uint32_t start = gpioTick();
    if (wait_for_level(gpio, 1, SENT_TIMEOUT_US) < 0) return -1;
    uint32_t fall = gpioTick();
