#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define EXPECTED_DEVICE_ID 0x0117
#define SAMPLE_INTERVAL_SEC 60
#define DATA_FILE "greenhouse_temps.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int write_temperature_to_file(FILE *file, float temperature) {
    uint8_t data[4];
    data[0] = (uint8_t)(temperature & 0xFF);
    data[1] = (uint8_t)((temperature >> 8) & 0xFF);
    data[2] = (uint8_t)((temperature >> 16) & 0xFF);
    data[3] = (uint8_t)((temperature >> 24) & 0xFF);
    if (fwrite(data, 1, 4, file) != 4) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    fflush(file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int dev_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (dev_id != (EXPECTED_DEVICE_ID & 0xFF)) {
        fprintf(stderr, "Error: Invalid device ID (0x%02X). Expected LSB.\n", dev_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    dev_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG + 1);
    if (dev_id != ((EXPECTED_DEVICE_ID >> 8) & 0xFF)) {
        fprintf(stderr, "Error: Invalid device ID (0x%02X). Expected MSB.\n", dev_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("TMP117 detected (Device ID: 0x%04X). Starting monitoring...\n", (EXPECTED_DEVICE_ID & 0xFF) | ((EXPECTED_DEVICE_ID >> 8) & 0xFF));

    fp = fopen(DATA_FILE, "ab");
    if (fp == NULL) {
        perror("Error opening data file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (write_temperature_to_file(fp, temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

