#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define I2C_BUS 1
#define LOG_FILE "environmental_data.txt"
#define READ_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, SensorData *data) {
    char cmd = MEASURE_HIGH_PRECISION;
    char buf[6];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8((uint8_t *)buf + 3, 2) != (uint8_t)buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t hum_raw = ((uint8_t)buf[3] << 8) | (uint8_t)buf[4];

    data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    data->humidity = -6.0f + 125.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    SensorData sensor_data;

    while (!terminate) {
        if (read_sht40(i2c_handle, &sensor_data) == 0) {
            if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Error: Logging failed.\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

