#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define SAMPLE_PERIOD  5.0   /* seconds */
#define BUFFER_SIZE    100
#define LOG_FILE       "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from TMP117                                       */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int read_temperature(float *temperature)
{
    char buf[2];
    int  result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register (got %d bytes): %s\n",
                result, pigpio_error(result));
        return -1;
    }

    /* TMP117: 16-bit big-endian, two's complement, 0.0078125 °C/LSB */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the circular buffer                             */
/* ------------------------------------------------------------------ */
static void add_reading(float temperature)
{
    time(&temperature_buffer[buffer_index].timestamp);
    temperature_buffer[buffer_index].temperature = temperature;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

/* ------------------------------------------------------------------ */
/* Persist the entire buffer to a binary file                          */
/* ------------------------------------------------------------------ */
static int persist_buffer(void)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    size_t written = fwrite(temperature_buffer, sizeof(TemperatureReading),
                            buffer_count, fp);
    if (written != (size_t)buffer_count) {
        fprintf(stderr, "Error writing to log file (wrote %zu of %d records)\n",
                written, buffer_count);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C device --- */
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n",
                TMP117_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMP117 temperature logger started. Sampling every %.1f s.\n",
           SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_reading(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature; skipping sample.\n");
        }

        /* Persist every sample and on exit */
        if (persist_buffer() != 0) {
            fprintf(stderr, "Warning: failed to persist buffer.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++)
            time_sleep(0.1);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    if (persist_buffer() != 0)
        fprintf(stderr, "Warning: buffer not flushed on exit.\n");

    cleanup();
    return EXIT_SUCCESS;
}

