#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHTC3_ADDR     0x70
#define MEASURE_CMD    0x7866  /* Normal power, clock stretching disabled */
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5       /* seconds */
#define CONV_DELAY_US  13000   /* 13 ms (>= 12.4 ms for normal power) */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_shtc3(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (measurement command).\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (sensor data).\n");
        return -1;
    }

    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    float t = 175.0f * (float)t_raw / 65535.0f - 45.0f;
    float h = 100.0f * (float)h_raw / 65535.0f;

    if (t < -40.0f || t > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f C\n", t);
        return -1;
    }
    if (h < 0.0f || h > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f %%\n", h);
        return -1;
    }

    *temperature = t;
    *humidity    = h;
    return 0;
}

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", handle);
        gpioTerminate();
        return 1;
    }

    printf("SHTC3 monitoring started. Logging to '%s' every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temperature, humidity;

        if (read_shtc3(handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return 0;
}

