#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* Si7202 register addresses */
#define SI7202_REG_DEVICE_ID 0x00
#define SI7202_REG_FIELD_GAUSS 0x01
#define SI7202_REG_TEMP_CELSIUS 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7202_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: i2cReadI2CBlockData returned %d\n", reg, result);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_si7202_data(int handle, float *magnetic_field, float *temperature) {
    uint16_t raw_field, raw_temp;

    if (read_si7202_register(handle, SI7202_REG_FIELD_GAUSS, &raw_field) != 0) {
        return -1;
    }

    if (read_si7202_register(handle, SI7202_REG_TEMP_CELSIUS, &raw_temp) != 0) {
        return -1;
    }

    *magnetic_field = (float)raw_field * 0.1f;
    *temperature = (float)raw_temp * 0.01f - 25.0f;

    return 0;
}

static int log_data(FILE *fp, float magnetic_field, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    if (fp == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                magnetic_field, temperature) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file.\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
