#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)(buffer[0] & 0x3F) << 8) | (uint8_t)buffer[1];
    uint16_t raw_temp = ((uint16_t)(buffer[2] & 0x3F) << 8) | (uint8_t)buffer[3];

    data->flow_rate = ((float)raw_flow / 16384.0f) - 0.1f / 0.8f * 25.0f;
    data->temperature = ((float)raw_temp / 4096.0f) - 0.1f / 0.8f * 80.0f - 40.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %.2f SLPM, Temperature: %.2f °C\n",
            timestamp, data->flow_rate, data->temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

