#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_RETRIES 3

/* DHT11 timing constants (microseconds) */
#define DHT_START_LOW_US  20000      /* >= 18 ms */
#define DHT_START_HIGH_US 40         /* 20-40 us */
#define DHT_RESP_LOW_US   80
#define DHT_RESP_HIGH_US  80
#define DHT_BIT_LOW_US    50
#define DHT_ZERO_HIGH_US  26
#define DHT_ONE_HIGH_US   70
#define DHT_TIMEOUT_US    200

typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Wait for the line to reach the requested level or time out. */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/* Measure the duration of a pulse at the given level. */
static uint32_t measure_pulse(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == level) {
        if ((gpioTick() - start) > timeout_us)
            return 0;
    }
    return gpioTick() - start;
}

/*
 * Read 40 bits from the DHT11.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht11(int gpio, DHT11Data *data) {
    uint8_t bytes[5] = {0};
    int i;

    /* --- Start signal: pull low for >= 18 ms, then high for 20-40 us --- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, 0) < 0) return -1;
    gpioDelay(DHT_START_LOW_US);
    if (gpioWrite(gpio, 1) < 0) return -1;
    gpioDelay(DHT_START_HIGH_US);

    /* Release the line and switch to input */
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    /* --- Sensor response: ~80 us low, ~80 us high --- */
    if (wait_level(gpio, 0, DHT_TIMEOUT_US) < 0) return -1;  /* line should be low */
    if (wait_level(gpio, 1, DHT_TIMEOUT_US) < 0) return -1;  /* then high */
    if (measure_pulse(gpio, 0, DHT_TIMEOUT_US) < DHT_RESP_LOW_US - 50) return -1; /* low too short */
    if (measure_pulse(gpio, 1, DHT_TIMEOUT_US) < DHT_RESP_HIGH_US - 50) return -1; /* high too short */

    /* --- Read 40 data bits --- */
    for (i = 0; i < 40; i++) {
        /* Each bit begins with a ~50 us low pulse */
        if (wait_level(gpio, 0, DHT_TIMEOUT_US) < 0) return -1;
        uint32_t high_start = gpioTick();
        if (measure_pulse(gpio, 1, DHT_TIMEOUT_US) < DHT_BIT_LOW_US - 50) return -1;
        uint32_t high_duration = measure_pulse(gpio, 1, DHT_TIMEOUT_US);

        int bit = (high_duration > (DHT_ZERO_HIGH_US + DHT_ONE_HIGH_US) / 2) ? 1 : 0;
        bytes[i / 8] = (uint8_t)((bytes[i / 8] << 1) | bit);
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(bytes[0] + bytes[1] + bytes[2] + bytes[3]);
    if (checksum != bytes[4]) {
        data->status = -2;
        return -1;
    }
    data->status = 0;

    /* DHT11: humidity = byte 0, temperature = byte 2 (integer only) */
    data->humidity = (float)bytes[0];
    data->temperature = (float)bytes[2];
    return 0;
}

static void log_data(const DHT11Data *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Temperature: %.1f C, Humidity: %.1f %%\n",
                ts, data->temperature, data->humidity);
    } else {
        fprintf(fp, "(time-error), Temperature: %.1f C, Humidity: %.1f %%\n",
                data->temperature, data->humidity);
    }
    fclose(fp);
}

static void log_error(const char *msg, int status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, ERROR: %s (status %d)\n", ts, msg, status);
    } else {
        fprintf(fp, "(time-error), ERROR: %s (status %d)\n", msg, status);
    }
    fclose(fp);
}

static void log_sensor_absent(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, ERROR: DHT11 sensor absent (line stuck %d)\n",
                ts, gpioRead(DHT11_GPIO));
    } else {
        fprintf(fp, "(time-error), ERROR: DHT11 sensor absent (line stuck %d)\n",
                gpioRead(DHT11_GPIO));
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure clean state before starting */
    gpioSetMode(DHT11_GPIO, PI_INPUT);
    gpioDelay(100000);  /* 100 ms settle */

    DHT11Data data;
    int consecutive_failures = 0;

    while (g_running) {
        int rc = read_dht11(DHT11_GPIO, &data);

        if (rc == 0) {
            consecutive_failures = 0;
            log_data(&data);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n",
                   data.temperature, data.humidity);
        } else {
            consecutive_failures++;
            log_error("DHT11 read failed", rc);

            /* Sensor-absent heuristic: line stuck high or low for > 1 s */
            if (consecutive_failures >= MAX_RETRIES) {
                int stuck = gpioRead(DHT11_GPIO);
                if (stuck == 0 || stuck == 1) {
                    log_sensor_absent();
                }
            }
        }

