        for (int i = 0; i < 20 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean shutdown */
    gpioSetMode(DHT11_GPIO, PI_INPUT);
    gpioTerminate();
    return EXIT_SUCCESS;
}

