#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x44
#define MEASURE_CMD    0x2C06
#define MEASURE_DELAY_US 15000
#define LOG_FILE       "sht31d_data.log"
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES    3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SHT31_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor(sensor_data_t *data) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (rc == 0)
            break;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    if (rc != 0) {
        fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (rc == 6)
            break;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    if (rc != 6) {
        fprintf(stderr, "I2C read failed after %d retries (got %d bytes)\n",
                MAX_RETRIES, rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_h = ((uint16_t)buf[3] << 8) | buf[4];

    data->temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    data->humidity   = 100.0f * (float)raw_h / 65535.0f;

    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, data->temperature, data->humidity);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            log_error("sensor_read_failed");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

