#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

#define REG_DEVID 0x00
#define REG_RED_CH 0x64
#define REG_GREEN_CH 0x66
#define REG_BLUE_CH 0x68

#define EXPECTED_DEVID 0x2A

#define MCCAMY_CONST 128.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_reg16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int write_reg8(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    int rc = i2cWriteI2CBlockData(handle, reg, buf, 1);
    return (rc == 1) ? 0 : -1;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_reg16(handle, REG_RED_CH, red) != 0) return -1;
    if (read_reg16(handle, REG_GREEN_CH, green) != 0) return -1;
    if (read_reg16(handle, REG_BLUE_CH, blue) != 0) return -1;
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float n = r / (r + g + b);
    float x = (g / (r + g + b)) - (n * n * (1 - n) * (1 - n) * (6 * n - 7));
    return MCCAMY_CONST * (4 * x + (n - 0.3320f) * (1 - n) * (1 - n) * (1 - n) * (1 - n) * (1 - n));
}

static void log_cct(float cct) {
    FILE *fp = fopen("cct_log.csv", "a");
    if (!fp) {
        perror("fopen cct_log.csv");
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, cct);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (0x%02X): %d\n", SENSOR1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (0x%02X): %d\n", SENSOR2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg8(h1, REG_DEVID, 0x00) != 0) {
        fprintf(stderr, "Sensor 1 not responding (device ID write failed)\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_reg8(h2, REG_DEVID, 0x00) != 0) {
        fprintf(stderr, "Sensor 2 not responding (device ID write failed)\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t devid1 = 0, devid2 = 0;
    if (read_reg16(h1, REG_DEVID, &devid1) != 0) {
        fprintf(stderr, "Sensor 1 read error (device ID)\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (read_reg16(h2, REG_DEVID, &devid2) != 0) {
        fprintf(stderr, "Sensor 2 read error (device ID)\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (devid1 != EXPECTED_DEVID || devid2 != EXPECTED_DEVID) {
        fprintf(stderr, "Sensor ID mismatch: 1=0x%02X, 2=0x%02X (expected 0x%02X)\n",
                devid1, devid2, EXPECTED_DEVID);
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sensors initialized. Logging to cct_log.csv every 1 second...\n");

    while (running) {
        uint16_t r1 = 0, g1 = 0, b1 = 0;
        uint16_t r2 = 0, g2 = 0, b2 = 0;

        if (read_sensor_data(h1, &r1, &g1, &b1) != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        } else if (read_sensor_data(h2, &r2, &g2, &b2) != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        } else {
            float cct1 = calculate_cct(r1, g1, b1);
            float cct2 = calculate_cct(r2, g2, b2);
            float avg = (cct1 + cct2) / 2.0f;
            log_cct(avg);
            printf("CCT: %.2f\n", avg);
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

