#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define PRESSURE_REG   0x0A2C
#define TEMP_REG       0x0A2E
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_US      2000000  /* 2 seconds */

#define P_MIN_KPA      0.0f
#define P_MAX_KPA      800.0f
#define P_OUT_MIN      0
#define P_OUT_MAX      32768
#define T_MIN_C        -40.0f
#define T_MAX_C        125.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleans up.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file.                           */
/* ------------------------------------------------------------------ */
static void log_line(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }

    if (fp) {
        fprintf(fp, "%s %s\n", ts, msg);
        fflush(fp);
    }
    fprintf(stderr, "%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90824.                 */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteWordData(handle, reg, 0) < 0) {
        return -1;
    }
    gpioDelay(1000);  /* small settle delay */

    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw pressure to kPa using the datasheet formula.            */
/* ------------------------------------------------------------------ */
static float raw_to_kpa(uint16_t raw)
{
    return ((float)raw - (float)P_OUT_MIN) *
           (P_MAX_KPA - P_MIN_KPA) /
           ((float)P_OUT_MAX - (float)P_OUT_MIN) +
           P_MIN_KPA;
}

/* ------------------------------------------------------------------ */
/* Convert raw temperature to degrees Celsius.                         */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (float)raw * 0.01f - 40.0f;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* ---- Install signal handlers ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_line(g_log_file, "TPMS started — logging to " LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t raw_p = 0, raw_t = 0;
        char msg[128];

        if (read_reg16(g_i2c_handle, PRESSURE_REG, &raw_p) != 0) {
            snprintf(msg, sizeof(msg),
                     "ERROR: failed to read pressure register 0x%04X",
                     PRESSURE_REG);
            log_line(g_log_file, msg);
        } else if (read_reg16(g_i2c_handle, TEMP_REG, &raw_t) != 0) {
            snprintf(msg, sizeof(msg),
                     "ERROR: failed to read temperature register 0x%04X",
                     TEMP_REG);
            log_line(g_log_file, msg);
        } else {
            float pressure_kpa = raw_to_kpa(raw_p);
            float temp_c       = raw_to_celsius(raw_t);

            snprintf(msg, sizeof(msg),
                     "Pressure: %.2f kPa, Temperature: %.2f C",
                     pressure_kpa, temp_c);
            log_line(g_log_file, msg);
        }

        /* Sleep 2 s in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 20 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* ---- Graceful cleanup ---- */
    log_line(g_log_file, "TPMS shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

