static float raw_to_celsius(uint16_t raw)
{
    return (float)raw * 0.01f - 40.0f;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* ---- Install signal handlers ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_line(g_log_file, "TPMS started — logging to " LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t raw_p = 0, raw_t = 0;
        char msg[128];

        if (read_reg16(g_i2c_handle, PRESSURE_REG, &raw_p) != 0) {
            snprintf(msg, sizeof(msg),
                     "ERROR: failed to read pressure register 0x%04X",
                     PRESSURE_REG);
            log_line(g_log_file, msg);
        } else if (read_reg16(g_i2c_handle, TEMP_REG, &raw_t) != 0) {
            snprintf(msg, sizeof(msg),
                     "ERROR: failed to read temperature register 0x%04X",
                     TEMP_REG);
            log_line(g_log_file, msg);
        } else {
            float pressure_kpa = raw_to_kpa(raw_p);
            float temp_c       = raw_to_celsius(raw_t);

            snprintf(msg, sizeof(msg),
                     "Pressure: %.2f kPa, Temperature: %.2f C",
                     pressure_kpa, temp_c);
            log_line(g_log_file, msg);
        }

        /* Sleep 2 s in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 20 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* ---- Graceful cleanup ---- */
    log_line(g_log_file, "TPMS shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

