#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_HIGH      28.0f
#define TEMP_LOW       26.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static float temperature_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from LM75B.
 * Returns 0 on success and stores Celsius in *out_temp.
 * Returns -1 on I2C error.
 */
static int read_temperature(float *out_temp)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (rc=%d)\n", rc);
        return -1;
    }

    /* LM75B: 9-bit signed two's complement, bits D9-D1, D0 always 0 */
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 1;                       /* discard D0 */
    *out_temp = (float)raw * 0.5f;   /* 0.5 °C per LSB */
    return 0;
}

static void update_circular_buffer(float temp)
{
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static float calculate_average_temperature(void)
{
    if (buffer_count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++)
        sum += temperature_buffer[i];
    return sum / (float)buffer_count;
}

static void control_fan(float avg_temp)
{
    static int fan_on = 0;

    if (avg_temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (avg_temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("Temperature monitoring started (LM75B @0x%02X, fan GPIO%d)\n",
           I2C_ADDR, FAN_GPIO);

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            update_circular_buffer(temp);
            float avg = calculate_average_temperature();
            printf("Temp: %.2f °C | Avg(%d): %.2f °C\n",
                   temp, buffer_count, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

