#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between samples */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  20000       /* 20 ms conversion wait */

/* Si7021 commands (no-hold master mode) */
#define CMD_MEASURE_RH_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV     0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "i2cWriteDevice(0x%02X) attempt %d failed (rc=%d)\n",
                cmd, attempt + 1, rc);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "i2cReadDevice attempt %d failed (rc=%d)\n",
                attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    uint8_t data[2];

    /*
     * Read temperature from the previous RH measurement (command 0xE0).
     * The Si7021 returns 2 bytes: [MSB, LSB].
     */
    if (i2c_write_cmd(handle, CMD_READ_TEMP_PREV) != 0) {
        fprintf(stderr, "Failed to send read-temperature command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temperature = (175.72f * raw / 65536.0f) - 46.85f;

    /*
     * Read humidity from the previous temperature measurement (command 0xE0
     * after a temperature measurement).  Alternatively, issue Measure RH
     * No Hold (0xF5) and read 2 bytes; the Si7021 returns [MSB, LSB].
     */
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0) {
        fprintf(stderr, "Failed to send measure-RH command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    uint16_t rh_raw = ((uint16_t)data[0] << 8) | data[1];
    *humidity = (125.0f * rh_raw / 65536.0f) - 6.0f;

    /* Clamp humidity to valid physical range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
        fflush(fp);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
    }

    printf("%s  Temperature: %.2f C  Humidity: %.2f %%\n", ts, temperature, humidity);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
    fprintf(stderr, "%s  ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int sensor_present(int handle)
{
    /*
     * Read the electronic ID byte (command 0xFA 0x0F).
     * The Si7021 returns 8 data bytes; the first is the revision/ID.
     */
    uint8_t cmd[2] = { 0xFA, 0x0F };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Sensor not responding to ID command\n");
        return 0;
    }
    gpioDelay(10000);

    uint8_t id_buf[8];
    if (i2cReadDevice(handle, (char *)id_buf, 8) != 8) {
        fprintf(stderr, "Sensor not returning ID data\n");
        return 0;
    }

    /* First byte is the electronic ID / firmware revision */
    uint8_t id = id_buf[0];
    printf("Si7021 detected (electronic ID = 0x%02X)\n", id);
    return 1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Quick presence check before entering main loop */
    if (!sensor_present(g_i2c_handle)) {
        fprintf(stderr, "Si7021 sensor not detected at address 0x%02X\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 sensor initialised. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temperature, humidity;

        if (read_sensor(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_error("Sensor read failed");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

