#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define I2C_BUS 1
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hdc1080(int handle) {
    /*
     * Configuration register (0x02):
     *   Bit 15:   0 (reserved)
     *   Bit 14:   0 (reserved)
     *   Bit 13:   0 (reserved)
     *   Bit 12:   0 (reserved)
     *   Bit 11:   0 (reserved)
     *   Bit 10:   0 (reserved)
     *   Bit  9:   0 (reserved)
     *   Bit  8:   0 (reserved)
     *   Bit  7:   0 (reserved)
     *   Bit  6:   0 (reserved)
     *   Bit  5:   0 (reserved)
     *   Bit  4:   0 (reserved)
     *   Bit  3:   0 (reserved)
     *   Bit  2:   0 (reserved)
     *   Bit  1:   0 (reserved)
     *   Bit  0:   1 (heater off)
     *
     * Bits 12-14 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits 11-12 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits 10-11 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  9-10 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  8-9 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  7-8 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  6-7 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  5-6 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  4-5 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  3-4 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  2-3 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  1-2 (0x000) -> 14-bit temp, 14-bit humidity
     * Bits  0-1 (0x000) -> 14-bit temp, 14-bit humidity
     *
     * 14-bit temp resolution: 0x000
     * 14-bit humidity resolution: 0x000
     * Heater off: 0x001
     * => 0x000 | 0x001 = 0x001
     */
    if (i2cWriteByteData(handle, CONFIG_REG, 0x0001) < 0) {
        fprintf(stderr, "Error writing HDC1080 config register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];

    /*
     * Trigger a measurement by writing the pointer to register 0x00.
     * The HDC1080 performs a single conversion of both temperature and
     * humidity when the pointer is pointed at 0x00.
     */
    if (i2cWriteByte(handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error triggering HDC1080 measurement.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error reading HDC1080 measurement data.\n");
        return -1;
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    int raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X.\n", I2C_BUS, HDC1080_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed. Check sensor wiring and address.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (running) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        }

        /*
         * Sleep in 100 ms increments so SIGINT/SIGTERM is caught promptly.
         */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

