#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x44
#define MEASURE_CMD    0x2C
#define MEASURE_ARG    0xE0
#define CONV_DELAY_MS  10
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_cmd2(int fd, uint8_t cmd, uint8_t arg) {
    uint8_t buf[2] = { cmd, arg };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write(0x%02X 0x%02X) failed: %s\n", cmd, arg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_out) {
    if (i2c_write_cmd2(fd, MEASURE_CMD, MEASURE_ARG) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t data[3];
    ssize_t n = read(fd, data, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n", crc8(data, 2), data[2]);
        return -1;
    }

    uint16_t raw = (uint16_t)((data[0] << 8) | data[1]);
    *temp_out = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temperature(FILE *fp, float temp) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, temp);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            log_temperature(g_log, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log)  fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

