#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_US      1000000  /* 1 second */
#define MEASURE_US     50000    /* 50 ms measurement wait */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8, polynomial 0x31, initial value 0xFF (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

/*
 * Read one continuous-measurement frame from the SDP810.
 * Returns 0 on success, -1 on I2C or CRC error.
 */
static int read_sensor(float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x15};
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    gpioDelay(MEASURE_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error reading 9 bytes from sensor\n");
        return -1;
    }

    /* CRC checks: bytes 0-1, 3-4, 6-7 */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale  = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_line(const char *line) {
    if (log_file != NULL) {
        fprintf(log_file, "%s", line);
        fflush(log_file);
    }
}

int main(void) {
    float pressure, temperature;
    char timestamp[32];
    char line[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_log() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    time_t rawtime;
    struct tm *timeinfo;

    while (!terminate) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (read_sensor(&pressure, &temperature) == 0) {
            snprintf(line, sizeof(line), "%s,%.2f,%.2f\n",
                     timestamp, pressure, temperature);
            log_line(line);
        } else {
            snprintf(line, sizeof(line), "%s,ERROR,I2C/CRC\n", timestamp);
            log_line(line);
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

