#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_READ_MEASUREMENT 0xE000
#define SCD40_CMD_STOP_PERIODIC 0x3F86
#define BUFFER_CAPACITY 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t data_buffer;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    if (pthread_mutex_init(&buffer->mutex, NULL) != 0) {
        log_error("Failed to initialize circular buffer mutex");
        return -1;
    }
    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

static int write_buffer_to_file(const circular_buffer_t *buffer, const char *filename) {
    DIR *dir = opendir(LOG_DIR);
    if (!dir) {
        log_error("Failed to open log directory");
        return -1;
    }
    struct dirent *entry;
    int found = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, filename) == 0) {
            found = 1;
            break;
        }
    }
    closedir(dir);
    if (!found) {
        if (mkdir(LOG_DIR, 0755) != 0) {
            log_error("Failed to create log directory");
            return -1;
        }
    }
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        log_error("Failed to open file for writing");
        return -1;
    }
    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
    pthread_mutex_lock(&data_buffer.mutex);
    int start = (buffer->count == BUFFER_CAPACITY) ? buffer->tail : 0;
    for (int i = 0; i < buffer->count; i++) {
        int idx = (start + i) % BUFFER_CAPACITY;
        fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                (long)buffer->data[idx].timestamp,
                buffer->data[idx].co2,
                buffer->data[idx].temperature,
                buffer->data[idx].humidity);
    }
    pthread_mutex_unlock(&data_buffer.mutex);
    fclose(fp);
    return 0;
}

static int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (SCD40_CMD_READ_MEASUREMENT >> 8) & 0xFF,
                       SCD40_CMD_READ_MEASUREMENT & 0xFF };
    uint8_t buf[9];
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write read measurement command");
        return -1;
    }
    gpioDelay(10000);
    result = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t raw_temp = (buf[3] << 8) | buf[4];
    uint16_t raw_hum = (buf[6] << 8) | buf[7];
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;
    return 0;
}

static void *logging_thread(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running) break;
        pthread_mutex_lock(&data_buffer.mutex);
        int count = data_buffer.count;
        sensor_data_t local_buffer[BUFFER_CAPACITY];
        int copy_count = 0;
        for (int i = 0; i < count && copy_count < BUFFER_CAPACITY; i++) {
            int idx = (data_buffer.tail + i) % BUFFER_CAPACITY;
            local_buffer[copy_count] = data_buffer.data[idx];
            copy_count++;
        }
        pthread_mutex_unlock(&data_buffer.mutex);
        if (copy_count > 0) {
            char filename[256];
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            snprintf(filename, sizeof(filename), "%d-%02d-%02d_%02d-%02d-%02d.csv",
                     tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                     tm.tm_hour, tm.tm_min, tm.tm_sec);
            write_buffer_to_file(&data_buffer, filename);
        }
    }
    return NULL;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        uint8_t cmd[2] = { (SCD40_CMD_STOP_PERIODIC >> 8) & 0xFF,
                           SCD40_CMD_STOP_PERIODIC & 0xFF };
        i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
