#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEAS_REG 0x00
#define MEAS_CMD 0x00
#define MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_US 5000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(int handle, uint16_t cal[4]) {
    char buf[8];
    if (i2cReadI2CBlockData(handle, CALIB_REG, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(buf[2 * i] & 0xFF) << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char buf[6];
    if (i2cWriteByteData(handle, MEAS_REG, MEAS_CMD) < 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadI2CBlockData(handle, MEAS_REG, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read measurement data\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[0] << 16) |
                     ((uint32_t)(uint8_t)buf[1] << 8)  |
                     ((uint32_t)(uint8_t)buf[2]);
    uint32_t raw_t = ((uint32_t)(uint8_t)buf[3] << 16) |
                     ((uint32_t)(uint8_t)buf[4] << 8)  |
                     ((uint32_t)(uint8_t)buf[5]);
    uint16_t cal[4];
    if (read_calibration(handle, cal) != 0) return -1;
    float p_comp = (float)raw_p / 65536.0f;
    float t_comp = (float)raw_t / 65536.0f;
    float p_pa = p_comp * (cal[0] * 1048576.0f + cal[1] * 524288.0f) +
                 p_comp * p_comp * (cal[2] * 262144.0f + cal[3] * 65536.0f);
    *pressure = p_pa / 100.0f;
    *temperature = t_comp * (cal[0] * 256.0f + cal[1] * 16.0f) + 25.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", ts, pressure, temperature);
}

