/*
 * Raspberry Pi 4 Model B — TDK ICP-10125 barometric pressure sensor
 *
 * Reads pressure and temperature over I2C (default address 0x63),
 * drives a warning LED on GPIO 17 (BCM) using libgpiod, and blinks
 * at 1 Hz (normal) or 5 Hz (high-altitude warning) based on pressure.
 *
 * Build:  gcc -O2 -Wall -o icp10125_warn icp10125_warn.c -lgpiod
 *
 * Uses the Linux I2C character-device interface (no wiringPi).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP_10125_ADDR 0x63

#define REG_OTP_COEFF  0x66
#define CMD_MEASURE   0x4011  /* high-accuracy measurement */
#define MEASURE_MS    20      /* conversion time */
#define POLL_MS       1000

#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO on Pi 4 */
#define LED_BCM_PIN    17

#define PRESS_THRESHOLD_PA 95000.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (polynomial 0x31, init 0x00, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write cmd 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor data ---- */
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

/*
 * Read 4 calibration coefficients from OTP register 0x66.
 * Each coefficient is 16-bit big-endian, stored as 2 bytes + CRC.
 */
static int read_calibration(int fd, uint16_t coeffs[4])
{
    uint8_t reg = REG_OTP_COEFF;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to select OTP register: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[8];
    if (i2c_read_block(fd, buf, sizeof(buf)) < 0)
        return -1;

    for (int i = 0; i < 4; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on coefficient %d\n", i);
            return -1;
        }
        coeffs[i] = ((uint16_t)buf[i * 3] << 8) | buf[i * 3 + 1];
    }
    return 0;
}

/*
 * Trigger a measurement, wait, read 6 bytes, verify CRC,
 * apply the official InvenSense conversion formulas.
 */
static int read_sensor(int fd, sensor_data_t *out)
{
    if (i2c_write_cmd(fd, CMD_MEASURE) < 0)
        return -1;

    usleep(MEASURE_MS * 1000);

    uint8_t reg = 0x00;  /* data register */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to select data register: %s\n", strerror(errno));
        return -1;
    }

    uint8_t buf[6];
    if (i2c_read_block(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8);
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8);

    /*
     * Conversion formulas from the InvenSense ICP-10125 datasheet.
     * Coefficients are the four values read from OTP.
     */
    const uint16_t *c = coeffs;
    float p_comp = (float)raw_p;
    float t_comp = (float)raw_t;

    float p_lin = c[0] * 0.5f + c[1] * p_comp;
    float t_lin = c[2] * 0.5f + c[3] * t_comp;

    float p_quad = c[0] * 0.25f + c[1] * p_comp;
    float t_quad = c[2] * 0.25f + c[3] * t_comp;

    float p_out = p_lin + p_quad;
    float t_out = t_lin + t_quad;

    /* Temperature compensation */
    float t_comp_scaled = t_out * 0.01f;
    float t_comp_shifted = t_comp_scaled - 273.15f;
    float t_comp_quad = c[2] * t_comp_scaled + c[3] * t_comp_shifted;
    float t_comp_final = t_comp_quad + 25.0f;

    /* Pressure compensation */
    float p_comp_scaled = p_out * 0.01f;
    float p_comp_shifted = p_comp_scaled - 273.15f;
    float p_comp_quad = c[0] * p_comp_scaled + c[1] * p_comp_shifted;
    float p_comp_final = p_comp_quad + 50000.0f;

    out->pressure_pa = p_comp_final;
    out->temperature_c = t_comp_final;
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP_10125_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Read calibration coefficients */
    uint16_t coeffs[4];
    if (read_calibration(i2c_fd, coeffs) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_BCM_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "icp10125_warn", 0) < 0) {
        fprintf(stderr, "Cannot request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        sensor_data_t data;
        if (read_sensor(i2c_fd, &data) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
               data.pressure_pa, data.temperature_c);

        int led_state = (data.pressure_pa > PRESS_THRESHOLD_PA)
                            ? 0 : 1;  /* 0 = normal (1 Hz), 1 = warning (5 Hz) */

        if (gpiod_line_set_value(led, led_state) < 0)
            fprintf(stderr, "Warning: failed to set LED value: %s\n",
                    strerror(errno));

        /* Blink at the appropriate rate for the current state */
        if (led_state == 0) {
            /* Normal: 500 ms on, 500 ms off */
            gpiod_line_set_value(led, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led, 0);
            usleep(500 * 1000);
        } else {
            /* Warning: 100 ms on, 100 ms off */
            gpiod_line_set_value(led, 1);
            usleep(100 * 1000);
            gpiod_line_set_value(led, 0);
            usleep(100 * 1000);
        }
    }

    /* Clean shutdown */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

