            fprintf(stderr, "Sensor read error — continuing.\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
               data.pressure_pa, data.temperature_c);

        int led_state = (data.pressure_pa > PRESS_THRESHOLD_PA)
                            ? 0 : 1;  /* 0 = normal (1 Hz), 1 = warning (5 Hz) */

        if (gpiod_line_set_value(led, led_state) < 0)
            fprintf(stderr, "Warning: failed to set LED value: %s\n",
                    strerror(errno));

        /* Blink at the appropriate rate for the current state */
        if (led_state == 0) {
            /* Normal: 500 ms on, 500 ms off */
            gpiod_line_set_value(led, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led, 0);
            usleep(500 * 1000);
        } else {
            /* Warning: 100 ms on, 100 ms off */
            gpiod_line_set_value(led, 1);
            usleep(100 * 1000);
            gpiod_line_set_value(led, 0);
            usleep(100 * 1000);
        }
    }

    /* Clean shutdown */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

