#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static int i2c_handle = -1;
static int server_fd = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht40(float *temperature, float *humidity) {
    unsigned char cmd = 0xFD;
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned int temp_raw = (data[0] << 8) | data[1];
        unsigned int hum_raw = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)hum_raw / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void handle_client(int client_socket) {
    float temperature, humidity;
    char response[256];
    int len;

    if (read_sht40(&temperature, &humidity) != 0) {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 503 Service Unavailable\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Error</title>"
                 "<meta http-equiv=\"refresh\" content=\"2\"></meta>"
                 "<body><h1>SHT40 Sensor Read Error</h1>"
                 "<p>Temperature: N/A &deg;C</p>"
                 "<p>Humidity: N/A %%</p>"
                 "<p>Please try again later.</p></body></html>\r\n");
        len = strlen(response);
    } else {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 200 OK\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40</title>"
                 "<meta http-equiv=\"refresh\" content=\"2\"></meta>"
                 "<body><h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "<p>Powered by Raspberry Pi 4 & SHT40</p></body></html>\r\n",
                 temperature, humidity);
        len = strlen(response);
    }

    if (send(client_socket, response, len, 0) < 0) {
        perror("send() failed");
    }
    close(client_socket);
}

static int setup_server() {
    struct sockaddr_in address;
    int opt = 1;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket() failed");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt() failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind() failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen() failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    printf("Server listening on port %d...\n", PORT);
    return 0;
}

static void cleanup() {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction() failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (setup_server() != 0) {
        cleanup();
        return 1;
    }

    while (!terminate) {
        int new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            if (errno == EINTR && terminate) break;
            perror("accept() failed");
            continue;
        }
        handle_client(new_socket);
    }

    cleanup();
    printf("Server shut down cleanly.\n");
    return 0;
}

