#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define TEMP_LOW_REG        0x00
#define HUMID_LOW_REG       0x02
#define MEAS_CONFIG_REG     0x0E
#define CONFIG_REG          0x0F
#define MEAS_CONFIG_RESET   0x01
#define MEAS_CONFIG_READY   0x01
#define MAX_RETRIES         5
#define POLL_TIMEOUT_MS     500
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_word(int handle, uint8_t reg, uint16_t *out) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *out = (uint16_t)result;
    return 0;
}

static int write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
        return -1;
    }
    return 0;
}

static int trigger_measurement(int handle) {
    if (write_byte(handle, MEAS_CONFIG_REG, MEAS_CONFIG_RESET) < 0)
        return -1;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint16_t cfg;
        if (read_word(handle, MEAS_CONFIG_REG, &cfg) < 0)
            return -1;
        if ((cfg & MEAS_CONFIG_READY) == 0)
            return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Measurement timeout\n");
    return -1;
}

static int read_temperature(int handle, float *temp) {
    uint16_t raw;
    if (read_word(handle, TEMP_LOW_REG, &raw) < 0)
        return -1;
    *temp = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(int handle, float *hum) {
    uint16_t raw;
    if (read_word(handle, HUMID_LOW_REG, &raw) < 0)
        return -1;
    *hum = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t cfg;
    if (read_word(i2c_handle, CONFIG_REG, &cfg) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (NAK or bus error)\n", HDC2010_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if ((cfg & 0x0001) == 0) {
        fprintf(stderr, "Sensor not in measurement mode; CONFIG=0x%04X\n", cfg);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && running) {
            if (trigger_measurement(i2c_handle) == 0) {
                float temp, hum;
                if (read_temperature(i2c_handle, &temp) == 0 &&
                    read_humidity(i2c_handle, &hum) == 0) {
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
                    ok = 1;
                    break;
                }
            }
            retries++;
            gpioDelay(100000);
        }

        if (!ok && running) {
            fprintf(stderr, "Max retries reached; continuing to next cycle\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++)
            sleep(1);
    }

    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

