#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define MAX_TEMP 250.0
#define MIN_TEMP 120.0

#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_profile(const char *filename, double *profile, int *size) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    *size = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%lf", &profile[*size]) != 1) {
            fprintf(stderr, "Error parsing profile file: %s\n", line);
            fclose(fp);
            return -1;
        }
        (*size)++;
    }
    fclose(fp);
    if (*size == 0) {
        fprintf(stderr, "Profile file is empty.\n");
        return -1;
    }
    return 0;
}

int read_temperature(int spi_fd, double *temperature) {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int raw = (rx[0] << 8) | rx[1];
    if (raw & 0x04) {
        fprintf(stderr, "Thermocouple open circuit detected.\n");
        return -1;
    }

    int temp_data = raw & 0xFC;
    *temperature = (double)temp_data * 0.25;
    return 0;
}

double calculate_pid(double setpoint, double actual_temp, double *integral, double *prev_error, double dt) {
    double error = setpoint - actual_temp;
    *integral += error * dt;
    double derivative = (error - *prev_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

int log_data(const char *filename, double time, double target, double actual, double pid_output) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(fp, "%.6f,%.2f,%.2f,%.2f,%.4f\n", time, target, actual, pid_output);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    unsigned char bits = SPI_BITS;
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    double target_temp_profile[100];
    int profile_size = 0;
    if (read_profile(PROFILE_FILE, target_temp_profile, &profile_size) != 0) {
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    double integral = 0.0, prev_error = 0.0;
    double dt = 1.0;

    while (program_running) {
        double current_time = time(NULL);
        if (current_time < 0) {
            perror("time() failed");
            break;
        }

        if (read_temperature(spi_fd, &current_temp_profile[profile_size - 1]) != 0) {
            fprintf(stderr, "Error reading temperature. Skipping cycle.\n");
            sleep(1);
            continue;
        }

        double pid_output = calculate_pid(target_temp_profile[profile_size - 1], current_temp_profile[profile_size - 1], &integral, &prev_error, dt);

        int duty_cycle = (int)(pid_output * 100);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        if (gpiod_line_set_value(relay_line, duty_cycle) < 0) {
            perror("Failed to set relay GPIO value");
            break;
        }

        if (log_data(LOG_FILE, current_time, target_temp_profile[profile_size - 1], current_temp_profile[profile_size - 1], pid_output) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(1);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

