#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define DS18B20_DIR "/sys/bus/w1/devices/"
#define HEATER_ENABLE_PIN 17
#define HEATER_PWM_PIN 18
#define LOG_FILE "greenhouse.log"
#define PWM_PERIOD_NS 10000000  /* 10ms = 100Hz */
#define PWM_DUTY_MAX 1000000    /* 100% duty */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *enable_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static double Kp = 1.0, Ki = 0.1, Kd = 0.01;
static double integral = 0.0, prev_error = 0.0;
static double setpoint = 25.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(double *temp) {
    char path[256];
    char buf[256];
    snprintf(path, sizeof(path), "%s/28-XXXXXXXXXXXX/w1_slave", DS18B20_DIR);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buf, sizeof(buf), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (!strstr(buf, "YES")) {
        fprintf(stderr, "CRC check failed for sensor\n");
        return -1;
    }
    char *t = strstr(buf, "t=");
    if (!t) return -1;
    long raw = strtol(t + 2, NULL, 10);
    *temp = (double)raw / 1000.0;
    return 0;
}

static int set_pwm_duty(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    if (gpiod_line_set_value(pwm_line, duty_ns > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "PWM set_value failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static double pid_control(double temp) {
    double error = setpoint - temp;
    integral += error;
    double derivative = error - prev_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    prev_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static void log_data(double avg, double sp, double out, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg, sp, out, duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (enable_line) gpiod_line_set_value(enable_line, 0);
    if (pwm_line) gpiod_line_set_value(pwm_line, 0);
    if (enable_line) gpiod_line_release(enable_line);
    if (pwm_line) gpiod_line_release(pwm_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc == 4) {
        setpoint = atof(argv[1]);
        Kp = atof(argv[2]);
        Ki = atof(argv[3]);
        if (Kp <= 0 || Ki <= 0) {
            fprintf(stderr, "Invalid gains\n");
            return 1;
        }
    } else {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    enable_line = gpiod_chip_get_line(chip, HEATER_ENABLE_PIN);
    pwm_line = gpiod_chip_get_line(chip, HEATER_PWM_PIN);
    if (!enable_line || !pwm_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(enable_line, "heater_en", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "heater_pwm", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse heater started. Setpoint=%.1f Kp=%.2f Ki=%.2f\n", setpoint, Kp, Ki);

    while (running) {
        double temp = 0.0;
        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Sensor read failed, skipping cycle\n");
            sleep(5);
            continue;
        }

        double out = pid_control(temp);
        int duty = (int)out;
        if (set_pwm_duty(duty) != 0) {
            fprintf(stderr, "PWM set failed\n");
        }

        static double sum = 0.0;
        static int count = 0;
        sum += temp;
        count++;
        if (count >= 5) {
            double avg = sum / 5.0;
            log_data(avg, setpoint, out, duty);
            printf("Avg: %.2f SP: %.2f Out: %.2f Duty: %d\n", avg, setpoint, out, duty);
            sum = 0.0;
            count = 0;
        }
        sleep(5);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

