#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define MEAS_DELAY_MS  80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t b0, uint8_t b1, uint8_t b2) {
    uint8_t buf[3] = {b0, b1, b2};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 3) == 3) return 0;
        if (errno == EINTR) continue;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) return 0;
        if (errno == EINTR) continue;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) return -1;
    usleep(20000);
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) return -1;
    usleep(20000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t status;
    if (i2c_read_bytes(fd, &status, 1) < 0) return -1;

    if ((status & 0x18) != 0x18) {
        fprintf(stderr, "AHT20 not calibrated or busy\n");
        return -1;
    }

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    uint32_t raw_humidity = ((uint32_t)data[3] << 12) |
                           ((uint32_t)data[4] << 4) |
                           ((uint32_t)data[5] >> 4);

    *humidity = ((float)raw_humidity / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("AHT20 initialized. Monitoring humidity...\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                gpiod_line_set_value(line, 1);
                printf("  -> Humidity above %.1f%%, dehumidifier ON\n", HUMIDITY_HIGH);
            } else if (humidity < HUMIDITY_LOW) {
                gpiod_line_set_value(line, 0);
                printf("  -> Humidity below %.1f%%, dehumidifier OFF\n", HUMIDITY_LOW);
            }
        } else {
            fprintf(stderr, "Failed to read humidity from AHT20\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

