#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60
#define MEASUREMENT_DELAY_MS 20

#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed (cmd 0x%02X): %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C read: unexpected EOF (sensor may be absent)");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_measurement(int fd, float *value, unsigned char *crc) {
    unsigned char buf[3];
    if (i2c_read_data(fd, buf, 3) < 0) return -1;
    unsigned short raw = (buf[0] << 8) | buf[1];
    *crc = buf[2];
    *value = -6.0f + 125.0f * (float)raw / 65536.0f;
    if (*value < 0.0f) *value = 0.0f;
    if (*value > 100.0f) *value = 100.0f;
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    if (i2c_write_cmd(fd, CMD_HUM_HOLD) < 0) return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);
    unsigned char crc;
    if (read_measurement(fd, humidity, &crc) < 0) return -1;
    unsigned char calc = (unsigned char)(*humidity >> 8) ^ (unsigned char)(*humidity & 0xFF);
    if (calc != crc) {
        syslog(LOG_ERR, "Humidity CRC mismatch: calc=0x%02X crc=0x%02X", calc, crc);
        return -1;
    }
    return 0;
}

static int post_data(const char *json_string) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             API_ENDPOINT, strlen(json_string), json_string);
    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    char response[1024];
    int n = read(sockfd, response, sizeof(response) - 1);
    if (n < 0) {
        syslog(LOG_ERR, "Read failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[n] = '\0';
    int status_code = 0;
    if (sscanf(response, "HTTP/1.%*d %d", &status_code) == 1) {
        if (status_code != 200) {
            syslog(LOG_ERR, "HTTP POST failed with status %d", status_code);
            close(sockfd);
            return -1;
        }
    } else {
        syslog(LOG_ERR, "Malformed HTTP response: %s", response);
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "HTU21D monitor started on %s (addr 0x%02X)", I2C_BUS, HTU21D_ADDR);
    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) < 0) {
            syslog(LOG_ERR, "Failed to read humidity");
        } else {
            char json_string[64];
            snprintf(json_string, sizeof(json_string), "{\"humidity\":%.2f}", humidity);
            if (post_data(json_string) < 0) {
                syslog(LOG_ERR, "Failed to post data");
            } else {
                syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            }
        }
        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

