#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS 1

#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA 0xF7
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0

#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, rc=%d, expected %u)\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X, rc=%d)\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int bmp280_init(void) {
    uint8_t chip_id = 0;
    if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_byte(i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        return -1;
    }
    gpioDelay(2000);

    uint8_t calib_buf[24];
    if (i2c_read_block(i2c_handle, BMP280_REG_CALIB, calib_buf, 24) != 0) {
        return -1;
    }

    calib.dig_T1 = (uint16_t)(calib_buf[0] | (calib_buf[1] << 8));
    calib.dig_T2 = (int16_t)(calib_buf[2] | (calib_buf[3] << 8));
    calib.dig_T3 = (int16_t)(calib_buf[4] | (calib_buf[5] << 8));
    calib.dig_P1 = (uint16_t)(calib_buf[6] | (calib_buf[7] << 8));
    calib.dig_P2 = (int16_t)(calib_buf[8] | (calib_buf[9] << 8));
    calib.dig_P3 = (int16_t)(calib_buf[10] | (calib_buf[11] << 8));
    calib.dig_P4 = (int16_t)(calib_buf[12] | (calib_buf[13] << 8));
    calib.dig_P5 = (int16_t)(calib_buf[14] | (calib_buf[15] << 8));
    calib.dig_P6 = (int16_t)(calib_buf[16] | (calib_buf[17] << 8));
    calib.dig_P7 = (int16_t)(calib_buf[18] | (calib_buf[19] << 8));
    calib.dig_P8 = (int16_t)(calib_buf[20] | (calib_buf[21] << 8));
    calib.dig_P9 = (int16_t)(calib_buf[22] | (calib_buf[23] << 8));

    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int32_t *raw_temp, int32_t *raw_press) {
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x01) != 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    uint8_t data[6];
    if (i2c_read_block(i2c_handle, BMP280_REG_DATA, data, 6) != 0) {
        return -1;
    }

    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) {
        return 0.0;
    }
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p;
}

static void log_breach(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("Error opening pressure_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BMP280_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (bmp280_init() == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "BMP280 init attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioDelay(100000);
    }

    if (!init_ok) {
        fprintf(stderr, "BMP280 initialization failed after %d attempts. Exiting.\n", MAX_RETRIES);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP280 initialized. Monitoring pressure (Ctrl+C to exit)...\n");

    while (running) {
        int32_t raw_temp = 0, raw_press = 0;
        if (bmp280_read_raw(&raw_temp, &raw_press) != 0) {
            fprintf(stderr, "Read error, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            init_ok = 0;
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                if (bmp280_init() == 0) { init_ok = 1; break; }
                gpioDelay(100000);
            }
            if (!init_ok) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            continue;
        }

        double temp = bmp280_compensate_temp(raw_temp);
        double press = bmp280_compensate_press(raw_press);
        press /= 100.0;

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);

        if (press > PRESSURE_HIGH_THRESHOLD) {
            log_breach(press);
            printf("Pressure HIGH breach logged.\n");
        } else if (press < PRESSURE_LOW_THRESHOLD) {
            log_breach(press);
            printf("Pressure LOW breach logged.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

