/*
 * logger.c — Raspberry Pi 4B environmental logger
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 *
 * Hardware:
 *   TMP117  I2C 0x48, register 0x00, 16-bit signed, LSB = 0.0078125 °C
 *   AHT20   I2C 0x38, init 0xBE 0x08 0x00, measure 0xAC 0x33 0x00
 *   PIR     GPIO 17 (BCM), active-high output
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_GPIO       17
#define GPIO_CHIP      "gpiochip4"
#define LOG_DIR        "data"
#define SAMPLE_PERIOD  1          /* seconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

/* ---- TMP117 ---- */
#define TMP117_REG_TEMP  0x00
#define TMP117_LSB       0.0078125f

/* ---- AHT20 ---- */
#define AHT20_CMD_INIT   0xBE
#define AHT20_CMD_MEAS   0xAC
#define AHT20_BUSY_BIT   0x80
#define AHT20_H_MASK     0x07FF
#define AHT20_T_MASK     0x0FFF
#define AHT20_T_OFFSET   0x0000
#define AHT20_H_OFFSET   0x1000

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t addr, const uint8_t *cmd, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write to 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor readings                                                     */
/* ------------------------------------------------------------------ */

static int read_tmp117(int fd, float *temp_c)
{
    uint8_t reg = TMP117_REG_TEMP;
    uint8_t buf[2];

    if (i2c_write_cmd(fd, TMP117_ADDR, &reg, 1) < 0)
        return -1;
    if (i2c_read_data(fd, TMP117_ADDR, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (float)raw * TMP117_LSB;
    return 0;
}

static int read_aht20(int fd, float *temp_c, float *hum_pct)
{
    uint8_t init_cmd[3] = { AHT20_CMD_INIT, 0x08, 0x00 };
    uint8_t meas_cmd[3] = { AHT20_CMD_MEAS, 0x33, 0x00 };
    uint8_t data[7];

    /* Init */
    if (i2c_write_cmd(fd, AHT20_ADDR, init_cmd, 3) < 0)
        return -1;
    usleep(20000);  /* 20 ms */

    /* Measure (max ~12 ms, but we wait 20 ms for safety) */
    if (i2c_write_cmd(fd, AHT20_ADDR, meas_cmd, 3) < 0)
        return -1;
    usleep(20000);

    /* Read 7 bytes: [status, hum_hi, hum_lo, t_hi, t_lo, crc, crc] */
    if (i2c_read_data(fd, AHT20_ADDR, data, 7) < 0)
        return -1;

    if (data[0] & AHT20_BUSY_BIT) {
        fprintf(stderr, "AHT20 busy after measure\n");
        return -1;
    }

    uint16_t hum_raw = ((uint16_t)(data[1] & 0x3F) << 8) | data[2];
    uint16_t t_raw   = ((uint16_t)data[3] << 8) | data[4];

    *hum_pct = (float)hum_raw / 1024.0f;
    *temp_c  = (float)t_raw / 1024.0f - 45.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

static int ensure_log_file(void)
{
    char ts[32];
    char path[256];
    get_timestamp(ts, sizeof(ts));
    snprintf(path, sizeof(path), "%s/%s.csv", LOG_DIR, ts);

    FILE *fp = fopen(path, "r");
    if (fp) {
        fclose(fp);
        return 0;  /* file already exists */
    }

    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "fopen(%s, w): %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

static void log_data(float temp_c, float hum_pct, int motion)
{
    char ts[32];
    char path[256];
    get_timestamp(ts, sizeof(ts));
    snprintf(path, sizeof(path), "%s/%s.csv", LOG_DIR, ts);

    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s, a): %s\n", path, strerror(errno));
        return;
    }
    fprintf(fp, "%s,%.4f,%.2f,%d\n", ts, temp_c, hum_pct, motion);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* GPIO setup via libgpiod */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(pir, "logger-pir") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* I2C setup */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(pir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Sensor presence check */
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "TMP117 not present at 0x%02X\n", TMP117_ADDR);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "AHT20 not present at 0x%02X\n", AHT20_ADDR);
    }

    if (ensure_log_file() < 0) {
        close(i2c_fd);
        gpiod_line_release(pir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Logger started. Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c = 0.0f, hum_pct = 0.0f;
        int motion = 0;
        int ok = 0;

        /* TMP117 with retries */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_tmp117(i2c_fd, &temp_c) == 0) { ok = 1; break; }
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "TMP117 read failed after %d attempts\n", MAX_RETRIES);
        }

        /* AHT20 with retries */
        ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_aht20(i2c_fd, &temp_c, &hum_pct) == 0) { ok = 1; break; }
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "AHT20 read failed after %d attempts\n", MAX_RETRIES);
        }

        /* PIR */
        motion = gpiod_line_get_value(pir);
        if (motion < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
        }

        log_data(temp_c, hum_pct, motion);
        sleep(SAMPLE_PERIOD);
    }

    /* Cleanup */
    close(i2c_fd);
    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    printf("\nLogger stopped.\n");
    return EXIT_SUCCESS;
}

