#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, message);
    fflush(stdout);
}

static void motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                       struct gpiod_line *in2)
{
    if (gpiod_line_set_value(ena, 0) < 0)
        perror("motor: failed to stop ENA");
    if (gpiod_line_set_value(in1, 0) < 0)
        perror("motor: failed to stop IN1");
    if (gpiod_line_set_value(in2, 0) < 0)
        perror("motor: failed to stop IN2");
}

static void motor_run_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                              struct gpiod_line *in2)
{
    if (gpiod_line_set_value(ena, 1) < 0)
        perror("motor: failed to enable");
    if (gpiod_line_set_value(in1, 1) < 0)
        perror("motor: failed to set IN1 high");
    if (gpiod_line_set_value(in2, 0) < 0)
        perror("motor: failed to set IN2 low");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        fprintf(stderr, "Failed to acquire one or more GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain_line)");
        goto cleanup;
    }

    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        perror("gpiod_line_request_output(ena_line)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1_line)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2_line)");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started (GPIO17). Press Ctrl+C to exit.");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            perror("gpiod_line_get_value(rain_line)");
            break;
        }

        if (val == 0) {
            log_event("Rain detected! Closing window.");
            motor_run_forward(ena_line, in1_line, in2_line);
            for (int i = 0; i < MOTOR_RUN_SEC && program_running; i++)
                sleep(1);
            motor_stop(ena_line, in1_line, in2_line);
            log_event("Window closed.");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++)
            sleep(1);
    }

    motor_stop(ena_line, in1_line, in2_line);
    log_event("Program exiting.");
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line) gpiod_line_release(rain_line);
    if (ena_line)  gpiod_line_release(ena_line);
    if (in1_line)  gpiod_line_release(in1_line);
    if (in2_line)  gpiod_line_release(in2_line);
    if (chip)     gpiod_chip_close(chip);
    return ret;
}

