#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void led_off(void)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
}

static void set_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

/*
 * Compute CPU load between two /proc/stat samples.
 * Returns 0.0 on success, -1.0 on error.
 */
static double calculate_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    int matched = fscanf(fp,
        "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
        &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
    fclose(fp);

    if (matched != 8) {
        fprintf(stderr, "Error parsing /proc/stat (got %d fields)\n", matched);
        return -1.0;
    }

    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_total, total;
    if (idle == 0 || system == 0) {
        return 0.0;
    }

    idle_total = idle + iowait;
    total = user + nice + system + idle + iowait + irq + softirq + steal;

    if (prev_total == 0) {
        prev_idle = idle_total;
        prev_total = total;
        return 0.0;
    }

    unsigned long long delta_idle = idle_total - prev_idle;
    unsigned long long delta_total = total - prev_total;

    if (delta_total == 0) {
        return 0.0;
    }

    double load = (double)(delta_total - delta_idle) / (double)delta_total;

    prev_idle = idle_total;
    prev_total = total;

    return load;
}

static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) {
        load = 0.0;
    }
    if (load > 1.0) {
        load = 1.0;
    }

    if (load < 0.5) {
        *r = (int)(load * 255.0);
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 255;
        *b = 0;
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Common-anode LED: drive higher voltage to turn off a channel */
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    led_off();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    while (g_running) {
        double load = calculate_cpu_load();
        if (load < 0.0) {
            fprintf(stderr, "Error calculating CPU load, retrying in 500 ms...\n");
            usleep(SAMPLE_US);
            continue;
        }

        int r, g, b;
        map_load_to_color(load, &r, &g, &b);
        set_color(r, g, b);

        usleep(SAMPLE_US);
    }

    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

