#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_calibration_data(int handle, bmp280_calib_data *cal) {
    char data[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, data, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    cal->dig_T1 = (uint16_t)((data[1] << 8) | data[0]);
    cal->dig_T2 = (int16_t)((data[3] << 8) | data[2]);
    cal->dig_T3 = (int16_t)((data[5] << 8) | data[4]);
    cal->dig_P1 = (uint16_t)((data[7] << 8) | data[6]);
    cal->dig_P2 = (int16_t)((data[9] << 8) | data[8]);
    cal->dig_P3 = (int16_t)((data[11] << 8) | data[10]);
    cal->dig_P4 = (int16_t)((data[13] << 8) | data[12]);
    cal->dig_P5 = (int16_t)((data[15] << 8) | data[14]);
    cal->dig_P6 = (int16_t)((data[17] << 8) | data[16]);
    cal->dig_P7 = (int16_t)((data[19] << 8) | data[18]);
    cal->dig_P8 = (int16_t)((data[21] << 8) | data[20]);
    cal->dig_P9 = (int16_t)((data[23] << 8) | data[22]);
    return 0;
}

int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    char data[6];
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

int32_t compensate_temperature(int32_t raw_temp, const bmp280_calib_data *cal, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)cal->dig_T1)) * ((raw_temp >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

uint32_t compensate_pressure(int32_t raw_press, int32_t t_fine, const bmp280_calib_data *cal) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;
}

int send_udp_data(const char *data) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        return -1;
    }
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int32_t raw_temp, raw_press, t_fine;
        if (read_raw_data(i2c_handle, &raw_temp, &raw_press) == 0) {
            int32_t temp_int = compensate_temperature(raw_temp, &calib, &t_fine);
            uint32_t press_int = compensate_pressure(raw_press, t_fine, &calib);
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"temperature\":%.2f,\"pressure\":%.2f}", temp_int / 100.0, press_int / 100.0);
            if (send_udp_data(json_data) != 0) {
                fprintf(stderr, "Error: Failed to send UDP data\n");
            } else {
                printf("Sent: %s\n", json_data);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        gpioDelay(5000000);
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

