#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0

#define MAX31855_FAULT_OC 0x01
#define MAX31855_FAULT_SCG 0x02
#define MAX31855_FAULT_SCV 0x04
#define MAX31855_FAULT_MASK (MAX31855_FAULT_OC | MAX31855_FAULT_SCG | MAX31855_FAULT_SCV)

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_max31855(uint32_t *raw_data) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    *raw_data = ((uint32_t)(uint8_t)rx[0] << 24) |
                ((uint32_t)(uint8_t)rx[1] << 16) |
                ((uint32_t)(uint8_t)rx[2] << 8)  |
                ((uint32_t)(uint8_t)rx[3]);
    return 0;
}

static float extract_temperature(uint32_t raw) {
    if (raw & 0x00010000) {
        uint8_t fault = raw & MAX31855_FAULT_MASK;
        if (fault & MAX31855_FAULT_OC) fprintf(stderr, "MAX31855 fault: Open circuit\n");
        if (fault & MAX31855_FAULT_SCG) fprintf(stderr, "MAX31855 fault: Short to GND\n");
        if (fault & MAX31855_FAULT_SCV) fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -999.0f;
    }

    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) temp_raw |= 0xC000;
    return temp_raw * 0.25f;
}

static int compute_pwm(float temp) {
    if (temp < TEMP_THRESHOLD_1) return 0;
    if (temp < TEMP_THRESHOLD_2) return (int)((temp - TEMP_THRESHOLD_1) * 50.0f / (TEMP_THRESHOLD_2 - TEMP_THRESHOLD_1));
    if (temp < TEMP_THRESHOLD_3) return 50 + (int)((temp - TEMP_THRESHOLD_2) * 150.0f / (TEMP_THRESHOLD_3 - TEMP_THRESHOLD_2));
    return 255;
}

static void log_data(float temp, int duty) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].temperature = temp;
    log_buffer[buffer_index].pwm_duty = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
        }
    }
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint32_t raw = 0;
        if (read_max31855(&raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temp = extract_temperature(raw);
        if (temp <= -900.0f) {
            gpioPWM(FAN_GPIO, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int duty = compute_pwm(temp);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "PWM write failed\n");
        }

        log_data(temp, duty);
        printf("Temp: %.2f C, PWM: %d\n", temp, duty);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
    return 0;
}

