#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "rtd_log.csv"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define CS_PIN 8
#define SAMPLE_INTERVAL_SEC 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03
#define MAX31865_AUX_REG 0x04
#define MAX31865_TEMP_REG 0x05

#define RTD_NOMINAL_RESISTANCE 1000.0
#define RTD_ALPHA_COEFFICIENT 0.00385
#define RTD_VSUPPLY 5.0
#define RTD_R0 10000.0

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg & 0x7F, value};
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int max31865_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(void) {
    uint8_t config = 0x00;
    if (max31865_read_reg(MAX31865_CONFIG_REG, &config) < 0) {
        return -1;
    }
    config &= ~(0x01 | 0x02);
    config |= 0x01;
    if (max31865_write_reg(MAX31865_CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_read_fault(uint8_t *fault) {
    uint8_t config;
    if (max31865_read_reg(MAX31865_CONFIG_REG, &config) < 0) {
        return -1;
    }
    if (max31865_read_reg(MAX31865_FAULT_REG, fault) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_read_rtd(uint16_t *rtd_raw) {
    uint8_t msb, lsb;
    if (max31865_read_reg(MAX31865_RTD_MSB_REG, &msb) < 0) {
        return -1;
    }
    if (max31865_read_reg(MAX31865_RTD_LSB_REG, &lsb) < 0) {
        return -1;
    }
    *rtd_raw = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static float calculate_temperature(uint16_t rtd_raw) {
    float rtd_resistance = ((float)rtd_raw / 32768.0) * RTD_VSUPPLY;
    float Z = rtd_resistance / RTD_NOMINAL_RESISTANCE;
    float B = RTD_ALPHA_COEFFICIENT * (1.0 + (1.0 / 3.0) * (Z - 1.0));
    float T = (B + Math.sqrt(B * B - 4.0 * (1.0 / RTD_ALPHA_COEFFICIENT))) / 2.0;
    return T;
}

static void log_data(float temperature, const char *error_msg) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (error_msg != NULL) {
            fprintf(log_file, "%s,ERROR,%s\n", timestamp, error_msg);
        } else {
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        }
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2712");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (cs_line == NULL) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "Failed to initialize MAX31865\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C)\n");
        fflush(log_file);
    }

    printf("Starting MAX31865 temperature logging. Press Ctrl+C to exit.\n");

    while (program_running) {
        uint8_t fault = 0;
        if (max31865_read_fault(&fault) < 0) {
            fprintf(stderr, "SPI error reading fault status: %s\n", strerror(errno));
            log_data(0.0, "SPI_READ_FAULT");
        } else if (fault & 0x01) {
            fprintf(stderr, "MAX31865 fault detected: %s\n", strerror(errno));
            log_data(0.0, "MAX31865_FAULT");
        } else {
            uint16_t rtd_raw = 0;
            if (max31865_read_rtd(&rtd_raw) < 0) {
                fprintf(stderr, "SPI error reading RTD data: %s\n", strerror(errno));
                log_data(0.0, "SPI_READ_RTD");
            } else {
                float temperature = calculate_temperature(rtd_raw);
                log_data(temperature, NULL);
                printf("Temperature: %.2f C\n", temperature);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

