#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 50
#define OSS 0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

static pressure_reading_t pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static bmp180_cal_t cal;
static int32_t b5_prev = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    int v;
    v = i2cReadByteData(handle, BMP180_REG_CAL_AC1); if (v<0) return -1; c->ac1 = (int16_t)v;
    v = i2cReadByteData(handle, 0xAC); if (v<0) return -1; c->ac2 = (int16_t)v;
    v = i2cReadByteData(handle, 0xAE); if (v<0) return -1; c->ac3 = (int16_t)v;
    v = i2cReadByteData(handle, 0xB0); if (v<0) return -1; c->ac4 = (uint16_t)v;
    v = i2cReadByteData(handle, 0xB2); if (v<0) return -1; c->ac5 = (uint16_t)v;
    v = i2cReadByteData(handle, 0xB4); if (v<0) return -1; c->ac6 = (uint16_t)v;
    v = i2cReadByteData(handle, 0xB6); if (v<0) return -1; c->b1 = (int16_t)v;
    v = i2cReadByteData(handle, 0xB8); if (v<0) return -1; c->b2 = (int16_t)v;
    v = i2cReadByteData(handle, 0xBA); if (v<0) return -1; c->mb = (int16_t)v;
    v = i2cReadByteData(handle, 0xBC); if (v<0) return -1; c->mc = (int16_t)v;
    v = i2cReadByteData(handle, 0xBE); if (v<0) return -1; c->md = (int16_t)v;
    return 0;
}

static int read_raw_temperature(int handle) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadByteData(handle, BMP180_REG_MSB);
    if (v<0) return -1;
    return v;
}

static int read_raw_pressure(int handle) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34 + (OSS<<6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (msb<0 || lsb<0 || xlsb<0) return -1;
    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    return x1 + x2;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6*b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6*b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7*2) / b4;
    else p = (b7/b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    if (i2c_handle < 0) return;
    int ut = read_raw_temperature(i2c_handle);
    if (ut < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    int up = read_raw_pressure(i2c_handle);
    if (up < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    int32_t b5 = compute_b5(ut);
    if (b5 != b5_prev) {
        pressure_buffer[buffer_index].timestamp = time(NULL);
        pressure_buffer[buffer_index].pressure = calculate_pressure(up, ut);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;
        b5_prev = b5;
    }
    float avg = 0.0f;
    int count = buffer_count;
    if (count > 0) {
        int start = (buffer_index - count + BUFFER_SIZE) % BUFFER_SIZE;
        for (int i = 0; i < count; i++) avg += pressure_buffer[start + i].pressure;
        avg /= count;
    }
    float diff = pressure_buffer[buffer_index].pressure - avg;
    if (buffer_count == BUFFER_SIZE && fabsf(diff) > 5.0f) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "Pressure alert! Current: %.2f hPa, Avg: %.2f hPa, Diff: %.2f hPa\n",
                pressure_buffer[buffer_index].pressure, avg, diff);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (addr 0x%02X): %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
