#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_STATUS_REG 0xF3
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "weather_data.txt"
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calib(int fd, bmp280_calib_t *c) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_reg(fd, BMP280_CALIB_START, buf, BMP280_CALIB_LEN) < 0) return -1;
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t bmp280_compensate_temp(int32_t adc_T, const bmp280_calib_t *c, int32_t *t_fine) {
    int32_t var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    int32_t var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1)) * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static uint32_t bmp280_compensate_press(int32_t adc_P, const bmp280_calib_t *c, int32_t t_fine) {
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)c->dig_P6;
    var2 = var2 + ((var1 * (int64_t)c->dig_P5) << 17);
    var2 = var2 + (((int64_t)c->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)c->dig_P3) >> 8) + ((var1 * (int64_t)c->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)c->dig_P1) >> 33;
    if (var1 == 0) return 0;
    int64_t p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)c->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)c->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)c->dig_P7) << 4);
    return (uint32_t)((p >> 8) & 0xFFFFFFFF);
}

static int bmp280_read(int fd, const bmp280_calib_t *c, float *temp, float *press) {
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, 0x27) < 0) return -1;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg(fd, BMP280_STATUS_REG, &status, 1) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
        if (i == POLL_TIMEOUT_MS - 1) return -1;
    }
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_PRESS_MSB_REG, data, 6) < 0) return -1;
    int32_t adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
