    uint32_t P = bmp280_compensate_press(adc_P, c, t_fine);
    *temp = T / 100.0f;
    *press = P / 256.0f / 100.0f;
    return 0;
}

static void log_data(float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR_1) < 0) {
        perror("ioctl 0x76");
        close(fd); return 1;
    }
    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id, 1) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        close(fd); return 1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        close(fd); return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calib(fd, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd); return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR_2) < 0) {
        perror("ioctl 0x77");
        close(fd); return 1;
    }
    uint8_t chip_id2;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id2, 1) < 0) {
        fprintf(stderr, "Failed to read chip ID from 0x77\n");
    } else if (chip_id2 != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch at 0x77: 0x%02X\n", chip_id2);
    }

    while (running) {
        float temp, press;
        if (bmp280_read(fd, &cal, &temp, &press) == 0) {
            log_data(temp, press);
            printf("Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", temp, press);
        } else {
            fprintf(stderr, "Read failed: %s\n", strerror(errno));
        }
        for (int i = 0; i < 50 && running; i++) usleep(100000);
    }

    close(fd);
    return 0;
}

