#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS         "/dev/i2c-1"
#define LM75_ADDR       0x48
#define LM75_TEMP_REG   0x00
#define GPIO_CHIP        "gpiochip4"
#define GPIO_LED_LINE    18
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD   28.0f
#define POLL_INTERVAL_S  1

static volatile sig_atomic_t running = 1;

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buf_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int i2c_read_temp(int16_t *raw) {
    uint8_t reg = LM75_TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading temperature data (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    int16_t val = (int16_t)((buf[0] << 8) | buf[1]);
    val >>= 5;
    *raw = val;
    return 0;
}

static float read_temperature(void) {
    int16_t raw;
    if (i2c_read_temp(&raw) < 0) {
        return -273.15f;
    }
    return (float)raw / 256.0f;
}

static void buffer_init(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
}

static void buffer_add(CircularBuffer *cb, float temp) {
    pthread_mutex_lock(&buf_mutex);
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&buf_mutex);
}

static float buffer_avg(const CircularBuffer *cb) {
    pthread_mutex_lock(&buf_mutex);
    if (cb->count == 0) {
        pthread_mutex_unlock(&buf_mutex);
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    float avg = sum / (float)cb->count;
    pthread_mutex_unlock(&buf_mutex);
    return avg;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LED_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LED_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static void control_led(float temp) {
    int val = (temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(led_line, val) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&buf_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    pthread_t data_thread;
    if (pthread_create(&data_thread, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temp = read_temperature();
        if (temp > -273.0f) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_avg(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            control_led(temp);
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            if (i2c_init() < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }
        sleep(POLL_INTERVAL_S);
    }

    pthread_join(data_thread, NULL);
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

void *data_acquisition_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp = read_temperature();
        if (temp > -273.0f) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_avg(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            if (i2c_init() < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                running = 0;
            }
        }
        sleep(POLL_INTERVAL_S);
    }
    return NULL;
}

