#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

#define R_REF 430.0
#define R_NOM 100.0
#define A 0.0039083
#define B -0.0000005775

typedef struct {
    double target;
    double kp;
    double ki;
    double kd;
} Config;

static int spi_handle = -1;
static Config config = {25.0, 1.0, 0.1, 0.01};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, Config *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using defaults.\n", filename);
        return -1;
    }
    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Warning: no config data; using defaults.\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (sscanf(line, "{\"target\": %lf, \"kp\": %lf, \"ki\": %lf, \"kd\": %lf}",
               &cfg->target, &cfg->kp, &cfg->ki, &cfg->kd) != 4) {
        fprintf(stderr, "Warning: JSON parse failed; using defaults.\n");
        cfg->target = 25.0;
        cfg->kp = 1.0;
        cfg->ki = 0.1;
        cfg->kd = 0.01;
    }
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t val) {
    char tx[2] = {(char)(reg | 0x80), (char)val};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *val) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)rx[1];
    return 0;
}

static int init_max31865(void) {
    if (spi_write_reg(MAX31865_CONFIG_REG, 0xC1) != 0) return -1;
    gpioDelay(10000);
    uint8_t cfg;
    if (spi_read_reg(MAX31865_CONFIG_REG, &cfg) != 0) return -1;
    if (cfg != 0xC1) {
        fprintf(stderr, "MAX31865 config verify failed: 0x%02X\n", cfg);
        return -1;
    }
    return 0;
}

static int read_rtd(double *rtd_code) {
    uint8_t msb, lsb;
    if (spi_read_reg(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    uint16_t code = ((uint16_t)msb << 8) | lsb;
    if (code & 0x0001) {
        uint8_t fault;
        if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) return -1;
        fprintf(stderr, "MAX31865 fault: 0x%02X\n", fault);
        return -1;
    }
    *rtd_code = (double)code / 32768.0 * R_REF;
    return 0;
}

static double calc_rtd_resistance(double rtd_code) {
    return R_NOM * (1.0 + A * rtd_code + B * rtd_code * rtd_code);
}

static double calc_temperature(double rtd_code) {
    double r = calc_rtd_resistance(rtd_code);
    if (r <= 0.0) return -1000.0;
    return 1.0 / (2.0 * A) * (sqrt(8.0 * r / R_NOM - 4.0 * B) - 2.0 * B * r / R_NOM);
}

static double pid_control(double setpoint, double actual,
                          double kp, double ki, double kd,
                          double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = (double)PWM_RANGE;
    return output;
}

static void set_pwm(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, (int)(duty + 0.5));
}

static void cleanup(void) {
    set_pwm(0.0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    if (read_config(CONFIG_FILE, &config) != 0) {
        fprintf(stderr, "Using defaults: target=%.1f Kp=%.3f Ki=%.3f Kd=%.3f\n",
                config.target, config.kp, config.ki, config.kd);
    }
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_max31865() != 0) {
        fprintf(stderr, "MAX31865 init failed\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    double integral = 0.0, prev_error = 0.0;
    while (running) {
        double rtd_code;
        if (read_rtd(&rtd_code) != 0) {
            fprintf(stderr, "SPI read error — failsafe shutdown\n");
            set_pwm(0.0);
            break;
        }
        double r = calc_rtd_resistance(rtd_code);
        double temp = calc_temperature(rtd_code);
        if (temp < -900.0) {
            fprintf(stderr, "Invalid temperature — failsafe shutdown\n");
            set_pwm(0.0);
            break;
        }
        double duty = pid_control(config.target, temp, config.kp, config.ki, config.kd,
                                  &integral, &prev_error);
        set_pwm(duty);
        if (temp > MAX_TEMP) {
            fprintf(stderr, "Over-temperature (%.2f°C) — failsafe shutdown\n", temp);
            set_pwm(0.0);
            break;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

