#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_WORDS        11
#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define SAMPLE_INTERVAL_US      500000
#define BUFFER_SIZE             60

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_uword(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(void) {
    if (i2c_read_word(i2c_handle, 0xAA, &ac1) < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xAC, &ac2) < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xAE, &ac3) < 0) return -1;
    if (i2c_read_uword(i2c_handle, 0xB0, &ac4) < 0) return -1;
    if (i2c_read_uword(i2c_handle, 0xB2, &ac5) < 0) return -1;
    if (i2c_read_uword(i2c_handle, 0xB4, &ac6) < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xB6, &b1)  < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xB8, &b2)  < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xBA, &mb)  < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xBC, &mc)  < 0) return -1;
    if (i2c_read_word(i2c_handle, 0xBE, &md)  < 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd[2] = { BMP180_REG_CONTROL, 0x2E };
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd[2] = { BMP180_REG_CONTROL, 0x34 };
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) return -1;
    gpioDelay(5000);
    char buf[3];
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                   p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0 || read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return;
    }
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up, ut);
    time_t now = time(NULL);
    buffer.data[buffer.head].timestamp = now;
    buffer.data[buffer.head].temperature = temp;
    buffer.data[buffer.head].pressure    = pres;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)now, temp, pres);
    fflush(stdout);
    if (temp > TEMP_THRESHOLD) gpioWrite(FAN_GPIO, 1);
    else                        gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    buffer.head = 0;
    buffer.count = 0;
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) gpioDelay(100000);
    gpioWrite(FAN_GPIO, 0);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

