#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define GPIO_BUTTON 27
#define DEBOUNCE_MS 200
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_edge_tick = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int vals[12];
    for (int i = 0; i < 12; i++) {
        int reg = BMP180_REG_CAL_AC1 + i * 2;
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc < 0) {
            fprintf(stderr, "Error reading calibration register 0x%02X: %d\n", reg, rc);
            return -1;
        }
        vals[i] = (int16_t)rc;
    }
    ac1 = vals[0]; ac2 = vals[1]; ac3 = vals[2];
    ac4 = (uint16_t)vals[3]; ac5 = (uint16_t)vals[4]; ac6 = (uint16_t)vals[5];
    b1 = vals[6]; b2 = vals[7]; mb = vals[8];
    mc = vals[9]; md = vals[10];
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading temperature MSB\n");
        return -1;
    }
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading temperature LSB\n");
        return -1;
    }
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) < 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading pressure MSB\n");
        return -1;
    }
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading pressure LSB\n");
        return -1;
    }
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) {
        fprintf(stderr, "Error reading pressure XLSB\n");
        return -1;
    }
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t read_pressure_pa(void) {
    int32_t ut, up, x1, x2, b5, b6, x3, b3, p;
    uint32_t b4, b7;

    if (read_raw_temperature(&ut) < 0) return -1;
    b5 = compute_b5(ut);

    if (read_raw_pressure(&up) < 0) return -1;

    b6 = b5 - 4000;
    x1 = ((int32_t)b2 * (b6 * b6 >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((int32_t)ac1 * 4 + x3) << 2) / 4;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)up - b3) * (50000 >> 0);
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d Pa\n", timestamp, pressure_pa);
    fclose(fp);
}

static void button_isr(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t diff = tick - last_edge_tick;
        if (diff > DEBOUNCE_MS * 1000) {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
            last_edge_tick = tick;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR for button\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pressure logging started. Press button on GPIO27 to toggle.\n");

    while (running) {
        if (logging_enabled) {
            int32_t pressure = read_pressure_pa();
            if (pressure >= 0) {
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error reading pressure\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

