#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define MAX_DUTY_CYCLE 80.0
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temp_out) {
    char rx[4] = {0};
    int bytes = spiRead(handle, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI read failed (got %d bytes)\n", bytes);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & 0x00000004) fprintf(stderr, "open circuit\n");
        else if (raw & 0x00000002) fprintf(stderr, "short to GND\n");
        else if (raw & 0x00000001) fprintf(stderr, "short to VCC\n");
        else fprintf(stderr, "unknown fault\n");
        return -1;
    }
    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temp_out = thermocouple_temp * 0.25;
    return 0;
}

static float pi_control(float setpoint, float actual, float *integral, float dt) {
    float error = setpoint - actual;
    *integral += error * dt;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    float output = (error + *integral) * 2.0;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void log_data(float temp, float duty) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, duty);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "# timestamp,temperature_c,duty_cycle_pct\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0;
    float dt = 0.0;
    float target = 25.0;

    while (running) {
        float temp;
        if (read_max31855(spi_handle, &temp) != 0) {
            gpioPWM(HEATER_GPIO, 0);
            log_data(temp, 0.0);
            dt = 1.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float duty = pi_control(target, temp, &integral, dt);
        if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;
        if (duty < 0.0) duty = 0.0;
        gpioPWM(HEATER_GPIO, (int)(duty * 10.0));
        log_data(temp, duty);
        dt = 1.0;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

