#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255
#define POLL_US    500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU temperature in millidegrees Celsius.
 * Returns 0 on success and stores the value in *temp_mc.
 * Returns -1 on any read error. */
static int read_cpu_temp(long *temp_mc)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[32];
    if (!fgets(buf, sizeof(buf), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *end;
    errno = 0;
    long val = strtol(buf, &end, 10);
    if (errno != 0 || end == buf) {
        fprintf(stderr, "Error parsing temperature value: %s\n", strerror(errno));
        return -1;
    }

    *temp_mc = val;
    return 0;
}

/* Map temperature (m°C) to RGB values for a common-anode LED.
 * Below 40000 m°C -> Blue (R=0,G=0,B=255)
 * 40000-59999 m°C -> Green (R=0,G=255,B=0)
 * 60000 m°C and above -> Red (R=255,G=0,B=0) */
static void temp_to_rgb(long temp_mc, int *r, int *g, int *b)
{
    if (temp_mc < 40000) {
        *r = 0;
        *g = 0;
        *b = 255;
    } else if (temp_mc < 60000) {
        *r = 0;
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = 0;
    }
}

/* Set a GPIO pin to the given PWM duty cycle (0-255).
 * For a common-anode LED, duty 0 = fully on, duty 255 = fully off. */
static void set_led_channel(int pin, int duty)
{
    if (gpioPWM(pin, PWM_RANGE - duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pin);
    }
}

/* Turn off all three channels (common-anode off = duty 255). */
static void led_off(void)
{
    set_led_channel(RED_PIN, 255);
    set_led_channel(GREEN_PIN, 255);
    set_led_channel(BLUE_PIN, 255);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins as hardware-PWM outputs. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 0-255 on each channel. */
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off. */
    led_off();

    while (g_running) {
        long temp_mc = 0;
        if (read_cpu_temp(&temp_mc) != 0) {
            /* Skip this cycle; try again next iteration. */
            gpioDelay(POLL_US);
            continue;
        }

        int r, g, b;
        temp_to_rgb(temp_mc, &r, &g, &b);

        set_led_channel(RED_PIN,   (r < 255) ? r : 255);
        set_led_channel(GREEN_PIN, (g < 255) ? g : 255);
        set_led_channel(BLUE_PIN,  (b < 255) ? b : 255);

        printf("CPU Temp: %.1f C, RGB: (%d, %d, %d)\n",
               temp_mc / 1000.0, r, g, b);
        fflush(stdout);

        gpioDelay(POLL_US);
    }

    /* Graceful shutdown: turn off LED and release pigpio. */
    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

