#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL 5

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int bits[40] = {0};
    int last_state = PI_HIGH;
    int counter = 0;
    int bit_idx = 0;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(2000); // 2 ms low
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(30);  // 30 us high
    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor response
    counter = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        gpioDelay(1);
        counter++;
        if (counter > 100) return -1; // Timeout
    }
    counter = 0;
    while (gpioRead(gpio) == PI_LOW) {
        gpioDelay(1);
        counter++;
        if (counter > 100) return -1;
    }
    counter = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        gpioDelay(1);
        counter++;
        if (counter > 100) return -1;
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        counter = 0;
        while (gpioRead(gpio) == PI_LOW) {
            gpioDelay(1);
            counter++;
            if (counter > 100) return -1;
        }
        counter = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            gpioDelay(1);
            counter++;
            if (counter > 100) return -1;
        }
        if (counter > 40) return -1;
        bits[i] = counter;
    }

    // Parse data
    data->humidity = 0.0;
    data->temperature = 0.0;
    data->error = 0;
    for (i = 0; i < 16; i++) {
        j = (i * 2) + 1;
        if (bits[j] > bits[j + 1]) {
            data->humidity = data->humidity + (1 << (15 - i));
        }
    }
    for (i = 0; i < 16; i++) {
        j = (i * 2) + 1;
        if (bits[j] > bits[j + 1]) {
            data->temperature = data->temperature + (1 << (15 - i));
        }
    }

    // Check checksum
    int checksum = 0;
    for (i = 0; i < 16; i++) {
        checksum = checksum + (data->humidity >> (15 - i));
    }
    for (i = 0; i < 16; i++) {
        checksum = checksum + (data->temperature >> (15 - i));
    }
    checksum = checksum & 0xFF;
    if (checksum != (data->humidity + data->temperature) & 0xFF) {
        data->error = -1;
        return -1;
    }

    return 0;
}

int format_json(DHT22Data data, char *json_string, size_t size) {
    int ret = snprintf(json_string, size, "{\"temperature\":%.1f,\"humidity\":%.1f}", data.temperature, data.humidity);
    if (ret < 0 || ret >= (int)size) {
        return -1;
    }
    return 0;
}

int send_http_request(const char *json_string) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    CURLcode res;
    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    res = curl_easy_perform(curl);

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    int ret = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        ret = -1;
    } else if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
        ret = -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    DHT22Data dht22_data;
    char json_string[256];
    int retries;

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
                if (format_json(dht22_data, json_string, sizeof(json_string)) == 0) {
                    if (send_http_request(json_string) == 0) {
                        printf("Data sent successfully: %s\n", json_string);
                        break;
                    } else {
                        fprintf(stderr, "Failed to send data, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Failed to format JSON, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 sensor, retrying...\n");
            }
            retries++;
            sleep(1);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, exiting.\n");
            break;
        }

        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

