#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int read_s16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_u16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(void) {
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    if (ac1 == 0 && ac2 == 0 && ac3 == 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) return -1;
    gpioDelay(26000);
    char buf[3];
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;
    *up = (((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2]) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    static uint32_t last_tick = 0;
    if (tick - last_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_tick = tick;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error setting ISR on GPIO4\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Pressure logging started. Press button on GPIO4 to toggle. Ctrl+C to exit.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                int32_t b5 = compute_b5(ut);
                int32_t pressure = compute_pressure(up, b5);
                time_t rawtime;
                time(&rawtime);
                struct tm *timeinfo = localtime(&rawtime);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                FILE *fp = fopen("pressure_log.txt", "a");
                if (fp) {
                    fprintf(fp, "%s, %d hPa\n", timestamp, pressure / 100);
                    fclose(fp);
                } else {
                    fprintf(stderr, "Error opening pressure_log.txt\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

