#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 10
#define DHT22_TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity) {
    uint8_t data[5] = {0};
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t duration = gpioTick() - start;

        if (duration > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -2;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed: %s", curl_easy_strerror(CURLE_OK));
        return -1;
    }

    char json[64];
    snprintf(json, sizeof(json), "{\"humidity\":%.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    long response_code = 0;
    CURLcode res;
    int retries = 0;

    do {
        curl_easy_setopt(curl, CURLOPT_URL, server_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            retries++;
            if (retries <= MAX_RETRIES) sleep(2);
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code < 200 || response_code >= 300) {
                syslog(LOG_ERR, "HTTP POST returned status %ld", response_code);
                retries++;
                if (retries <= MAX_RETRIES) sleep(2);
            }
        }
    } while (retries <= MAX_RETRIES);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return (response_code >= 200 && response_code < 300) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return 1;
        }
    }

    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitor");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    while (running) {
        float humidity = 0.0f;
        int rc = -1;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            int result = read_dht22(&humidity);
            if (result == 0) {
                rc = post_humidity(humidity);
                if (rc == 0) {
                    syslog(LOG_INFO, "Humidity: %.1f%%", humidity);
                } else {
                    syslog(LOG_ERR, "Failed to post humidity after %d retries", MAX_RETRIES);
                }
                break;
            } else if (result == -2) {
                syslog(LOG_ERR, "DHT22 checksum error (attempt %d)", attempt + 1);
            } else {
                syslog(LOG_ERR, "DHT22 read timeout (attempt %d)", attempt + 1);
            }
            if (attempt < MAX_RETRIES - 1) sleep(2);
        }

        if (rc != 0 && running) {
            syslog(LOG_ERR, "All DHT22 read attempts failed");
        }

        for (int s = 0; s < READ_INTERVAL_SEC && running; s++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    curl_global_cleanup();
    gpioTerminate();
    closelog();
    return 0;
}

