#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

#define MAX_FAN_SPEED 3
#define MIN_TEMP_MILLIC 45000
#define MAX_TEMP_MILLIC 65000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp_millic = -1;
    if (fscanf(fp, "%d", &temp_millic) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_millic;
}

static int read_fan_state(void) {
    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    int state = -1;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return state;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int log_fan_speed(int speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Fan speed set to %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, speed);

    if (fclose(fp) != 0) {
