#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    double Kp, Ki, Kd;
    double integral;
    double last_error;
} PIDController;

static PIDController pid = {1.0, 0.1, 0.01, 0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int read_max31855(double *temp, double *fault) {
    char rx[4] = {0, 0, 0, 0};
    int ret = spiRead(spi_handle, rx, 4);
    if (ret != 4) {
        *fault = -1.0;
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        *fault = 1.0;
        return -2;
    }
    int16_t celsius = (int16_t)(raw >> 18);
    *temp = celsius * 0.25;
    return 0;
}

static void set_heater(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 100.0) duty = 100.0;
    gpioPWM(HEATER_PIN, (int)(duty * PWM_RANGE / 100.0));
}

static double calculate_pid(double temp, double target) {
    double error = target - temp;
    pid.integral += error;
    if (pid.integral > 100.0) pid.integral = 100.0;
    if (pid.integral < 0.0) pid.integral = 0.0;
    double derivative = error - pid.last_error;
    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.last_error = error;
    return output;
}

static void cleanup(void) {
    set_heater(0.0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("System started");
    while (running) {
        double temp = 0.0, fault = 0.0;
        int rc = read_max31855(&temp, &fault);
        if (rc == 0) {
            if (fault == 1.0) {
                log_message("MAX31855 fault: Open Circuit");
                set_heater(0.0);
                pid.integral = 0.0;
                pid.last_error = 0.0;
            } else if (fault == 2.0) {
                log_message("MAX31855 fault: Short to GND");
                set_heater(0.0);
                pid.integral = 0.0;
                pid.last_error = 0.0;
            } else if (fault == 3.0) {
                log_message("MAX31855 fault: Short to VCC");
                set_heater(0.0);
                pid.integral = 0.0;
                pid.last_error = 0.0;
            } else {
                double pid_out = calculate_pid(temp, TARGET_TEMPERATURE);
                set_heater(pid_out);
                char buf[128];
                snprintf(buf, sizeof(buf), "Temp: %.2f C, PID: %.2f, Duty: %.1f%%", temp, pid_out, pid_out * 100.0 / PWM_RANGE);
                log_message(buf);
            }
        } else {
            log_message("SPI read error");
            set_heater(0.0);
            pid.integral = 0.0;
            pid.last_error = 0.0;
        }
        if (temp > MAX_TEMPERATURE || temp < MIN_TEMPERATURE) {
            log_message("Failsafe: Temperature out of range");
            set_heater(0.0);
            pid.integral = 0.0;
            pid.last_error = 0.0;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    log_message("Shutting down");
    cleanup();
    return 0;
}

