#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQ 25000
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int calculate_duty_cycle(int temp) {
    if (temp <= 40000) return 0;
    if (temp >= 70000) return 100;
    return (temp - 40000) * 100 / 30000;
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    unsigned int pwm_value = (unsigned int)((duty_cycle / 100.0) * 255.0);
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", ts, temp, duty);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed, skipping cycle\n");
        } else {
            int duty = calculate_duty_cycle(temp);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }
        sleep(POLL_INTERVAL);
    }

    set_fan_speed(0);
    gpioTerminate();
    return 0;
}

