#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR_1 0x08
#define SENSOR_ADDR_2 0x09
#define MEASUREMENT_CMD 0x3608
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (handle %d, retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(50000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (handle %d, retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on handle %d (retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }
    return -1;
}

static int log_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, SENSOR_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (addr 0x%02X): %d\n", SENSOR_ADDR_1, handle1);
        gpioTerminate();
        return 1;
    }

    int handle2 = i2cOpen(I2C_BUS, SENSOR_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (addr 0x%02X): %d\n", SENSOR_ADDR_2, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(handle1, &flow1);
        int ok2 = read_flow_rate(handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d)\n", ok1, ok2);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

