#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define NUM_PULSES 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_A_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_B_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", SENSOR_A_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", SENSOR_B_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    return gpioRead(pin);
}

static int calculate_state(int a, int b) {
    return (a << 2) | b;
}

static float calculate_angle(int state) {
    return (float)state / (float)(NUM_PULSES - 1) * 360.0f;
}

static int log_data(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Angle: %.2f degrees\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = 0;
    int current_state;

    printf("Monitoring TMAG5110A1 quadrature encoder on GPIO %d and %d...\n", SENSOR_A_PIN, SENSOR_B_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int a = read_sensor(SENSOR_A_PIN);
        int b = read_sensor(SENSOR_B_PIN);

        current_state = calculate_state(a, b);

        if (current_state != last_state) {
            float angle = calculate_angle(current_state);

            if (log_data(angle) != 0) {
                fprintf(stderr, "Warning: Logging failed, continuing...\n");
            }

            printf("State: %d, Angle: %.2f degrees\n", current_state, angle);
            last_state = current_state;
        }

        gpioDelay(10000); // 10ms delay to avoid busy-waiting
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: Failed to close log file: %s\n", strerror(errno));
        }
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

