/*
 * ADPD144RI Red/IR Photometric Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x39
 * LED:    GPIO 17 (active-high)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri adpd144ri.c -lgpiod
 *
 * The ADPD144RI FIFO data register (0x60) returns 16-bit little-endian
 * Red and IR ADC values.  The LED lights when IR > 2000.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR  0x39
#define REG_FIFO_DATA   0x60
#define LED_GPIO        17
#define IR_THRESHOLD    2000
#define SAMPLE_MS       100
#define LOG_FILE        "adpd144ri_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, 2) != 2)
        return -1;

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL)
        return;
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return;
    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- I2C setup --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    /* --- GPIO setup (libgpiod) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* --- Log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("ADPD144RI reader started.  Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (i2c_read_reg16(fd, REG_FIFO_DATA, &ir) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            gpiod_line_set_value(led_line, 0);
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        if (i2c_read_reg16(fd, REG_FIFO_DATA, &red) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            gpiod_line_set_value(led_line, 0);
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        log_data(log_fp, red, ir);

        if (ir > IR_THRESHOLD)
            gpiod_line_set_value(led_line, 1);
        else
            gpiod_line_set_value(led_line, 0);

        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line)
        gpiod_line_release(led_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    if (fd >= 0)
        close(fd);

    printf("\nExiting gracefully.\n");
    return ret;
}

