#include <gpiod.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_CONTROL_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s %d\n", timestamp, level);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *input_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    input_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!input_line) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", AUDIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_CONTROL_PIN);
    if (!gain_line) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", GAIN_CONTROL_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(input_line, "audio_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", AUDIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "audio_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GAIN_CONTROL_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_set_value(gain_line, 0) < 0) {
        fprintf(stderr, "Error setting GAIN pin LOW: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");
    printf("MAX9814 OUT -> GPIO %d, GAIN -> GPIO %d (60dB gain selected)\n", AUDIO_INPUT_PIN, GAIN_CONTROL_PIN);

