    if (prev_value < 0) {
        fprintf(stderr, "Error reading initial input value: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            fprintf(stderr, "Error reading input value: %s\n", strerror(errno));
            break;
        }

        if (value == 1 && prev_value == 0) {
            if (log_event(1) < 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (input_line) {
        gpiod_line_release(input_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Audio monitoring stopped.\n");
    return ret;
}

