#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x36
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000  /* 1 second in microseconds */
#define FLOW_SCALE     1000.0f  /* SLF3S-4000B: raw / 1000 = uL/min */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Sensirion CRC-8 (poly 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Initialize pigpio, I2C, and log file ---- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Start continuous measurement: command 0x3608 */
    uint8_t cmd[2] = { 0x36, 0x08 };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command.\n");
        cleanup();
        return -1;
    }

    /* Open log file once in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return -1;
    }

    return 0;
}

/* ---- Read flow rate ----
 * Returns 0 on success (flow_rate populated), -1 on I/O error,
 * -2 on CRC mismatch.
 */
static int read_flow_rate(float *flow_rate)
{
    uint8_t buf[3];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 3).\n", n);
        return -1;
    }

    /* Validate CRC */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X recv=0x%02X).\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

/* ---- Log one reading ---- */
static void log_flow_rate(float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_file, "%s,%.2f\n", ts, flow_rate);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0)
        return EXIT_FAILURE;

    printf("Monitoring flow rate. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow_rate;
        int rc = read_flow_rate(&flow_rate);
        if (rc == 0) {
            log_flow_rate(flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else if (rc == -1) {
            /* I2C error: attempt to recover on next iteration */
            fprintf(stderr, "I2C read error; retrying in 1 s.\n");
        } else {
            /* CRC error: skip this sample, keep running */
            fprintf(stderr, "CRC error; sample skipped.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

