#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x70
#define REG_STATE      0x00
#define STATE_LEN      7
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5.0

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor_state(int handle, uint8_t *buf, int len)
{
    if (i2cWriteByte(handle, REG_STATE) < 0) {
        fprintf(stderr, "Error: failed to set register pointer to 0x%02X\n", REG_STATE);
        return -1;
    }
    int bytes_read = i2cReadDevice(handle, (char *)buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: expected %d bytes, got %d\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int extract_tvoc_eco2(const uint8_t *buf, int len, uint16_t *tvoc, uint16_t *eco2)
{
    if (len < 7) {
        fprintf(stderr, "Error: state buffer too short for TVOC/eCO2\n");
        return -1;
    }
    *tvoc = ((uint16_t)buf[1] << 8) | buf[0];
    *eco2 = ((uint16_t)buf[5] << 8) | buf[4];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2)
{
    float iaq = 100.0f - (float)tvoc / 10.0f - (float)(eco2 - 400) / 50.0f;
    if (iaq < 0.0f)  iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, iaq, tvoc, eco2);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,iaq_pct,tvoc_ppb,eco2_ppm\n");
    fflush(g_log_file);

    while (g_running) {
        uint8_t state[STATE_LEN];
        if (read_sensor_state(g_i2c_handle, state, STATE_LEN) != 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        uint16_t tvoc = 0, eco2 = 0;
        if (extract_tvoc_eco2(state, STATE_LEN, &tvoc, &eco2) != 0) {
            fprintf(stderr, "Warning: TVOC/eCO2 extraction failed\n");
            time_sleep(SAMPLE_PERIOD);
