#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define CONSUMER_LABEL   "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int elapsed_seconds(const struct timespec *start, const struct timespec *now)
{
    return (int)(now->tv_sec - start->tv_sec) +
           (now->tv_nsec - start->tv_nsec) / 1000000000L;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec start_time, current_time;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, CONSUMER_LABEL) != 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        perror("clock_gettime");
        goto cleanup;
    }

    printf("Monitoring TTP223B on GPIO %d for intrusion (threshold %ds)...\n",
           GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S);
    fflush(stdout);

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (val == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }

            if (elapsed_seconds(&start_time, &current_time) > INTRUSION_THRESHOLD_S) {
                printf("INTRUSION DETECTED on GPIO %d\n", GPIO_LINE_OFFSET);
                fflush(stdout);
                start_time = current_time;
            }
        } else {
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            start_time = current_time;
        }

        struct timespec req = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&req, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting gracefully.\n");

    return ret;
}

