    int sub = snd_pcm_open_minterace(fd, PCM_SUBDEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (sub < 0) {
        fprintf(stderr, "Error opening subdevice: %s\n", snd_strerror(sub));
        close(fd);
        return -1;
    }

    int fmt = snd_pcm_hw_params_t *> snd_pcm_hw_params_alloca();
    if (!fmt) {
        fprintf(stderr, "Error allocating hardware params\n");
        snd_pcm_close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_any(fd, fmt) < 0) {
        fprintf(stderr, "Error setting any params: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_access(fd, fmt, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_format(fd, fmt, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if (snd_pcm_hw_params_set_rate_near(fd, fmt, &rate, 0) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_channels(fd, fmt, NUM_CHANNELS) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    if (snd_pcm_hw_params(fd, fmt) < 0) {
        fprintf(stderr, "Error setting hardware params: %s\n", snd_strerror(snd_pcm_hw_params_t *> snd_pcm_hw_params_get_error(fmt)));
        snd_pcm_close(fd);
        return -1;
    }

    g_pcm_fd = fd;
    return 0;
}

static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_sel_line = gpiod_chip_get_line(g_chip, GPIO_SEL_LINE);
    if (!g_sel_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_SEL_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_sel_line, "inmp441_sel", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_SEL_LINE, strerror(errno));
        g_sel_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

static int select_left_channel(void)
{
    if (gpiod_line_set_value(g_sel_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_frame(int16_t *buffer, int num_frames)
{
    if (select_left_channel() < 0) {
        return -1;
    }

    snd_pcm_t *handle = (snd_pcm_t *)g_pcm_fd;
    int bytes = num_frames * NUM_CHANNELS * (BITS_PER_SAMPLE / 8);
    int ret = snd_pcm_readi(handle, buffer, bytes);

    if (ret < 0) {
        fprintf(stderr, "Error reading audio: %s\n", snd_strerror(ret));
        return -1;
    }
    if (ret != bytes) {
        fprintf(stderr, "Short read: got %d, expected %d\n", ret, bytes);
        return -1;
    }
    return 0;
}

static int write_pcm_file(const int16_t *buffer, int num_frames)
{
    FILE *fp = fopen(OUT_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", OUT_FILE, strerror(errno));
        return -1;
    }

    size_t written = fwrite(buffer, sizeof(int16_t), num_frames, fp);
    if (written != (size_t)num_frames) {
        fprintf(stderr, "Error writing to file: wrote %zu, expected %d\n", written, num_frames);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2s() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    int16_t *audio_buffer = (int16_t *)malloc(FRAMES_PER_READ * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error allocating audio buffer\n");
        cleanup();
        return 1;
    }

    printf("Capturing audio... Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_audio_frame(audio_buffer, FRAMES_PER_READ) < 0) {
            fprintf(stderr, "Error reading audio frame. Exiting.\n");
            break;
        }

        if (write_pcm_file(audio_buffer, FRAMES_PER_READ) < 0) {
            fprintf(stderr, "Error writing PCM file. Exiting.\n");
            break;
        }
    }

    free(audio_buffer);
    cleanup();
    printf("Audio capture stopped.\n");
    return 0;
}

