#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_DELAY_US 50000
#define FLAME_TIMEOUT_SEC 5
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", ts, event);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        log_event("ERROR: gpioRead failed on flame sensor");
        return -1;
    }
    return v;
}

static int control_fan(int flame_active) {
    if (flame_active) {
        int duty = (int)(80.0 * exp(-0.05 * (time(NULL) - last_flame_start)));
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (gpioPWM(FAN_PIN, duty) < 0) {
            log_event("ERROR: gpioPWM failed for fan");
            return -1;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "Fan ON, duty=%d%%", duty);
        log_event(msg);
    } else {
        if (gpioPWM(FAN_PIN, 0) < 0) {
            log_event("ERROR: gpioPWM failed to stop fan");
            return -1;
        }
        log_event("Fan OFF");
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(FAN_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioPWM(FAN_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    int last_flame_state = 0;
    int flame_active = 0;
    time_t last_flame_start = 0;
    int flame_seen = 0;
    time_t last_check = time(NULL);

    while (running) {
        int raw = read_flame_sensor();
        if (raw < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int flame = (raw == 0);

        if (flame != last_flame_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = read_flame_sensor();
            if (confirm < 0) {
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }
            flame = (confirm == 0);
        }

        if (flame && !last_flame_state) {
            last_flame_start = time(NULL);
            flame_seen = 1;
        }

        if (flame && flame_seen && (time(NULL) - last_flame_start > FLAME_TIMEOUT_SEC)) {
            if (!flame_active) {
                flame_active = 1;
                control_fan(1);
            }
        } else if (!flame && flame_active) {
            if (flame_seen) {
                last_flame_start = time(NULL);
            }
            control_fan(0);
            flame_active = 0;
            flame_seen = 0;
        }

        last_flame_state = flame;
        time_t now = time(NULL);
        if (difftime(now, last_check) >= 1.0) {
            if (flame_active) {
                log_event("Flame detected");
            } else {
                log_event("Flame ended");
            }
            last_check = now;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down");
    gpioPWM(FAN_PIN, 0);
    gpioWrite(FLAME_SENSOR_PIN, 1);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return EXIT_SUCCESS;
}

