    uint32_t num_tx_control_bytes_per_symbol;
    uint32_t num_rx_control_bytes_per_symbol;
} __attribute__((packed)) radar_config_t;

static volatile sig_atomic_t terminate = 0;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_transfer(const char *tx, char *rx, int len) {
    int ret = spiXfer(spi_handle, (char *)tx, rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed (ret=%d, expected=%d)\n", ret, len);
        return -1;
    }
    return 0;
}

static int log_frame(FILE *fp, uint32_t frame_number, uint32_t timestamp) {
    uint8_t ts_buf[8];
    memcpy(ts_buf, &timestamp, 8);
    if (fwrite(ts_buf, 1, 8, fp) != 8) return -1;
    if (fwrite(&frame_number, 4, 1, fp) != 1) return -1;
    if (fflush(fp) != 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set DATA_READY_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

