#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01

#define CONFIG_CONTINUOUS 0x00
#define CONFIG_CONV_100MS 0x00
#define CONFIG_AUTO_RANGE 0x00

#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int opt3001_init(void) {
    uint16_t config = (CONFIG_CONTINUOUS << 12) |
                      (CONFIG_CONV_100MS << 6)  |
                      (CONFIG_AUTO_RANGE << 0);

    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, buf, 3) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: config write failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    return -1;
}

static int opt3001_read_lux(float *lux_out) {
    char reg = REG_RESULT;
    char data[2];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, &reg, 1) == 0) {
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
                uint8_t exponent = (raw >> 12) & 0x0F;
                uint16_t mantissa = raw & 0x0FFF;
                *lux_out = 0.01f * (float)(1 << exponent) * (float)mantissa;
                return 0;
            }
        }
        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    return -1;
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f lux\n", ts, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (code %d). Sensor may be absent or bus unavailable.\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_init() != 0) {
        fprintf(stderr, "Error: OPT3001 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("OPT3001 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float lux;
        if (opt3001_read_lux(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Error: failed to read lux value after retries.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

