/*
 * Raspberry Pi 3 Model B+ - SainSmart IR Flame Detection Sensor Module
 * Reads the digital output (DOUT) on GPIO line 17 via libgpiod v2.x API.
 * DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Compile: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run:     sudo ./flame_detect   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure line settings: input, bias pull-up, active-low */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "Error: failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_settings_set_direction(line_settings,
                                            GPIOD_LINE_DIRECTION_INPUT);
    if (ret) {
        fprintf(stderr, "Error: failed to set direction: %s\n",
                strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP);
    if (ret) {
        fprintf(stderr, "Error: failed to set pull-up bias: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Configure the specific line as input with pull-up */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    ret = gpiod_line_config_add_line_settings(line_cfg, offsets, 1,
                                               line_settings);
    if (ret) {
        fprintf(stderr, "Error: failed to add line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request config (consumer label) */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-detect");

    /* Request the line */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error: failed to request GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO line %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    if (request)
        gpiod_line_request_release(request);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (line_settings)
        gpiod_line_settings_free(line_settings);
    if (chip)
        gpiod_chip_close(chip);

    return (g_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

