            fprintf(stderr, "Error: failed to read one or more GPIO pins\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    /* Clean up pigpio resources before exiting */
    gpioTerminate();
    printf("\npigpio terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

