#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for pin %u\n", gpio_pins[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226_reader");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input\n", gpio_pins[i]);
            goto cleanup;
        }
    }

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read GPIO %u\n", gpio_pins[i]);
                goto cleanup;
            }
            values[i] = ret;
        }

        printf("Channel 1: %d, Channel 2: %d, Channel 3: %d, Channel 4: %d, "
               "Channel 5: %d, Channel 6: %d, Channel 7: %d, Channel 8: %d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

