#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(long elapsed_ms)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_nsec / 1000000L;
    printf("[+%ld ms] ", elapsed_ms);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs with pull-down resistors --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = channel_pins[i];

        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("Pins: CH1=GPIO2, CH2=GPIO3, ..., CH8=GPIO9. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (program_running) {
        int states[NUM_CHANNELS];

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int pin = channel_pins[i];
            states[i] = gpioRead(pin);
            if (states[i] < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d.\n", pin);
                states[i] = 0;  /* treat as not touched on read failure */
            }
        }

        clock_gettime(CLOCK_REALTIME, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000L
                        + (current_time.tv_nsec - start_time.tv_nsec) / 1000000L;

        print_timestamp(elapsed_ms);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d ", i + 1, states[i]);
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("pigpio terminated.\n");
    return EXIT_SUCCESS;
}

