/*
 * Raspberry Pi 3 Model B+ - Dual TMAG5110 Hall-Effect Latch Sensor Reader
 *
 * Wiring:
 *   TMAG5110 #1 OUT -> BCM GPIO 4 (physical pin 7)
 *   TMAG5110 #2 OUT -> BCM GPIO 5 (physical pin 10)
 *   TMAG5110 #1 VCC -> 3.3 V (physical pin 1)
 *   TMAG5110 #1 GND -> GND  (physical pin 9)
 *   TMAG5110 #2 VCC -> 3.3 V
 *   TMAG5110 #2 GND -> GND
 *
 * The TMAG5110 open-drain OUT pin is HIGH when not asserted (no magnet)
 * and LOW when asserted (magnet detected).  External 10 kΩ pull-up resistors
 * are assumed on each data line.
 *
 * Compile: gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:     sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the line is defined when the external
       pull-up is disconnected.  TMAG5110 open-drain idles HIGH, so a
       pull-up keeps the line HIGH when unasserted. */
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Pins: GPIO %d and GPIO %d | Poll: %d ms\n",
           SENSOR_1_PIN, SENSOR_2_PIN, POLL_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: GPIO read error (s1=%d, s2=%d).\n",
                    s1, s2);
        } else {
            printf("Sensor 1 (GPIO %d): %s | Sensor 2 (GPIO %d): %s\n",
                   SENSOR_1_PIN,
                   s1 == 0 ? "HIGH (no magnet)" : "LOW (magnet detected)",
                   SENSOR_2_PIN,
                   s2 == 0 ? "HIGH (no magnet)" : "LOW (magnet detected)");
        }

        /* Sleep 500 ms; gpioDelay is microsecond-accurate and non-blocking
           to other pigpio operations, but still blocks the main thread. */
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

