#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50
#define CONSUMER "ttp226_reader"

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
        printf("%s", buf);
    } else {
        printf("1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, gpio_pins, NUM_CHANNELS, settings) != 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        enum gpiod_line_value values[NUM_CHANNELS];
        int read_error = 0;

        if (gpiod_line_request_get_values(request, values) != 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            read_error = 1;
        } else {
            print_timestamp();
            for (int i = 0; i < NUM_CHANNELS; i++) {
                printf(",%u,%d", gpio_pins[i], values[i]);
            }
            printf("\n");
            fflush(stdout);
        }

        if (!read_error) {
            usleep(POLL_INTERVAL_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

