#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_tilt_state(int tilted)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s - %s\n", ts, tilted ? "Tilted" : "Not Tilted");
    fflush(stdout);
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 4 as input with internal pull-up */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d.\n", TILT_SENSOR_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_state = gpioRead(TILT_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed for GPIO %d.\n",
                TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d.\n",
                    TILT_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            log_tilt_state(current_state == 0);
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

