#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CHLIST 0x01
#define REG_ALS_VIS_DATA0 0x22
#define REG_UVINDEX0 0x2C
#define REG_COMMAND 0x18

#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x05
#define CMD_PSALS_FORCE 0x07
#define CMD_PS_AUTO 0x0D
#define CMD_PSALS_AUTO 0x0F

#define HW_KEY_VAL 0x17
#define EXPECTED_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block reg 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int init_si1145(void) {
    int part_id = read_reg(REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_reg(REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_HW_KEY, HW_KEY_VAL) < 0) return -1;

    if (write_reg(REG_CHLIST, 0x03) < 0) return -1;

    if (write_reg(REG_COMMAND, CMD_PSALS_AUTO) < 0) return -1;

    return 0;
}

static int read_uv_index(float *uv_index) {
    int raw = read_reg(REG_UVINDEX0);
    if (raw < 0) return -1;
    *uv_index = (float)raw / 100.0f;
    return 0;
}

static int read_als_visible(uint16_t *als_visible) {
    uint8_t buf[2];
    if (read_block(REG_ALS_VIS_DATA0, buf, 2) < 0) return -1;
    *als_visible = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n", SI1145_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(&uv_index) == 0 && read_als_visible(&als_visible) == 0) {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

