    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n", SI1145_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(&uv_index) == 0 && read_als_visible(&als_visible) == 0) {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

