#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define GPIO_CHIP       "gpiochip4"
#define ALARM_PIN       17
#define FLOW_SCALE      0.036f
#define FLOW_THRESHOLD  0.5f
#define LOG_FILE        "flow_log.txt"
#define READ_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion 8-bit CRC: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (i2c_write_cmd(fd, 0x08, 0x3608) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 0x%02X\n", addr);
        return -1;
    }
    usleep(100000); /* 100 ms for first measurement */
    return 0;
}

static int read_flow(int fd, uint8_t addr, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x00, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC for flow (bytes 0-2) */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data from sensor 0x%02X\n", addr);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * FLOW_SCALE;
    return 0;
}

static void log_flow(FILE *fp, float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Avg: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            f1, f2, avg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n", ALARM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (init_sensor(fd, SENSOR1_ADDR) < 0 || init_sensor(fd, SENSOR2_ADDR) < 0) {
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow(fd, SENSOR1_ADDR, &f1);
        int ok2 = read_flow(fd, SENSOR2_ADDR, &f2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (f1 + f2) / 2.0f;
            log_flow(log, f1, f2, avg);
            gpiod_line_set_value(alarm, avg < FLOW_THRESHOLD ? 1 : 0);
            printf("Avg Flow: %.2f ml/min\n", avg);
        } else {
            fprintf(stderr, "Read error — skipping log entry\n");
            gpiod_line_set_value(alarm, 0);
        }

        sleep(READ_INTERVAL_S);
    }

    /* Cleanup */
    gpiod_line_set_value(alarm, 0);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    fclose(log);
    close(fd);
    printf("\nShutdown complete.\n");
    return 0;
}

