#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        char time_str[32];
        struct tm *tm_info = localtime(&sensor_buffer[i].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Reading: %d\n", time_str, sensor_buffer[i].reading);
        } else {
            printf("[timestamp error] Reading: %d\n", sensor_buffer[i].reading);
        }
    }
    printf("--- End of Log ---\n");
    fflush(stdout);
}

static void cleanup(void) {
    print_buffer();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("KY-033 Obstacle Avoidance Sensor Monitor\n");
    printf("GPIO %d, polling every %d ms. Press Ctrl+C to exit.\n", SENSOR_PIN, POLL_DELAY_US / 1000);
    fflush(stdout);

    while (running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", SENSOR_PIN);
            break;
        }

        if (reading == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
            } else {
                sensor_buffer[buffer_index].timestamp = now;
                sensor_buffer[buffer_index].reading = reading;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
                if (buffer_count < BUFFER_SIZE) {
                    buffer_count++;
                }

                printf("Obstacle detected! Timestamp: %ld, Reading: %d\n",
                       (long)now, reading);
                fflush(stdout);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

