/*
 * fan_health.c — Raspberry Pi 5 (64-bit Bookworm)
 *
 * Reads Omron D7S vibration data over I2C (/dev/i2c-1, address 0x55)
 * and logs timestamped acceleration (X/Y/Z in g) to fan_health.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health   (requires r/w access to /dev/i2c-1)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55

/* D7S register map (16-bit registers, little-endian on the wire) */
#define REG_MODE_CTRL   0x1D
#define REG_STATUS      0x1B
#define REG_AX_LSB      0x2A
#define REG_AY_LSB      0x2C
#define REG_AZ_LSB      0x2E

#define MODE_ACTIVE     0x10
#define STATUS_ACTIVE   0x01

#define ACCEL_SCALE     0.0009765625f   /* g per LSB at default range */
#define SAMPLE_PERIOD_MS 500
#define INIT_TIMEOUT_MS  1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
