#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define LOG_FILE "stall_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(val));
        return -1;
    }
    return val;
}

static int is_stall_confirmed(void) {
    int s1 = read_sensor(SENSOR_1_GPIO);
    int s2 = read_sensor(SENSOR_2_GPIO);

    if (s1 < 0 || s2 < 0) {
        return 0;
    }

    if (s1 != 0 || s2 != 0) {
        return 0;
    }

    static time_t stall_start = 0;
    time_t now = time(NULL);

    if (stall_start == 0) {
        stall_start = now;
        return 0;
    }

    if (difftime(now, stall_start) >= STALL_THRESHOLD_SEC) {
        stall_start = now;
        return 1;
    }

    return 0;
}

static int log_stall(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Stall detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (is_stall_confirmed()) {
            if (log_stall() != 0) {
                fprintf(stderr, "Failed to log stall event\n");
            }
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

