#define TMAG5170_DEVICE_ID 0x8D

/* Sensor configuration: 50 mT range, continuous conversion, XYZ enabled */
#define TMAG5170_SENSOR_CONFIG_VALUE 0x00

/* LSB scale factor for 50 mT range: 1 LSB = 0.0001 mT (100 nT) */
#define TMAG5170_LSB_SCALE 0.0001f

#define I2C_BUS 1
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
