    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (read_register(handle, TMAG5170_REG_X_MSB, &x_msb) < 0) return -1;
    if (read_register(handle, TMAG5170_REG_X_LSB, &x_lsb) < 0) return -1;
    if (read_register(handle, TMAG5170_REG_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(handle, TMAG5170_REG_Y_LSB, &y_lsb) < 0) return -1;
    if (read_register(handle, TMAG5170_REG_Z_MSB, &z_msb) < 0) return -1;
    if (read_register(handle, TMAG5170_REG_Z_LSB, &z_lsb) < 0) return -1;

    int16_t x_raw = (int16_t)((x_msb << 8) | x_lsb);
    int16_t y_raw = (int16_t)((y_msb << 8) | y_lsb);
    int16_t z_raw = (int16_t)((z_msb << 8) | z_lsb);

