    (void)tick;
    (void)userdata;
    if (level == 1) {
        __sync_fetch_and_add(&pulse_count, 1);
    }
}

static int log_rpm(float rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

