#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

typedef enum { STATE_A, STATE_B } sensor_state_t;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile sensor_state_t previous_state = STATE_A;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rotation(const char *direction) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void sensor_a_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level != 0 && level != 1) return;
    sensor_state_t current = (level == 1) ? STATE_B : STATE_A;
    pthread_mutex_lock(&state_mutex);
    if (current != previous_state) {
        previous_state = current;
        if (current == STATE_B) {
            log_rotation("CW");
        } else {
            log_rotation("CCW");
        }
    }
    pthread_mutex_unlock(&state_mutex);
}

static void sensor_b_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level != 0 && level != 1) return;
    sensor_state_t current = (level == 1) ? STATE_A : STATE_B;
    pthread_mutex_lock(&state_mutex);
    if (current != previous_state) {
        previous_state = current;
        if (current == STATE_A) {
            log_rotation("CCW");
        } else {
            log_rotation("CW");
        }
    }
    pthread_mutex_unlock(&state_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert for GPIO %d\n", SENSOR_A_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert for GPIO %d\n", SENSOR_B_GPIO);
        gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    pthread_mutex_destroy(&log_mutex);
    pthread_mutex_destroy(&state_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

