#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    openlog("touch_led_app", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get touch sensor line (GPIO %d): %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get LED line (GPIO %d): %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor application started. Touch=GPIO%d, LED=GPIO%d", TOUCH_SENSOR_PIN, LED_PIN);

    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor value: %s", strerror(errno));
            break;
        }

        if (touch_value == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn on LED: %s", strerror(errno));
                break;
            }
            syslog(LOG_INFO, "Touch detected, LED turned on");
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn off LED: %s", strerror(errno));
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down, turning off LED");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

