#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;          /* 1 = touched (active-high sensor), 0 = released */
} TouchEvent;

static TouchEvent touch_log[BUFFER_SIZE];
static int log_head = 0;
static int log_tail = 0;
static int log_count = 0;
static int log_overflow_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, LED_1_PIN, LED_2_PIN};
    const char *names[] = {"SENSOR_1", "SENSOR_2", "LED_1", "LED_2"};

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%s, PI_INPUT) failed\n", names[i]);
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%s, PI_PUD_DOWN) failed\n", names[i]);
            return -1;
        }
    }

    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_1, PI_OUTPUT) failed\n");
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_2, PI_OUTPUT) failed\n");
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_1, 0) failed\n");
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_2, 0) failed\n");
        return -1;
    }

    return 0;
}

static void add_touch_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed\n");
        now = 0;
    }

    touch_log[log_head].sensor_pin = sensor_pin;
    touch_log[log_head].timestamp = now;
    touch_log[log_head].state = state;

    log_head = (log_head + 1) % BUFFER_SIZE;

    if (log_count == BUFFER_SIZE) {
        log_tail = (log_tail + 1) % BUFFER_SIZE;
        log_overflow_count++;
    } else {
        log_count++;
    }
}

static void print_log(void) {
    printf("\n--- Touch Log ---\n");
    int start = (log_tail == 0) ? log_tail : log_tail + 1;
    for (int i = 0; i < log_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_buf[32];
        struct tm tm_info;
        if (localtime_r(&touch_log[idx].timestamp, &tm_info) != NULL) {
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(time_buf, "UNKNOWN", sizeof(time_buf));
        }
        printf("[%s] Sensor %d: %s\n",
               time_buf,
               touch_log[idx].sensor_pin,
               touch_log[idx].state ? "Touched" : "Released");
    }
    printf("Overflows: %d\n", log_overflow_count);
    printf("--- End Log ---\n\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Error: gpioRead(SENSOR_1_PIN) failed\n");
        } else {
            add_touch_event(SENSOR_1_PIN, s1);
        }

        if (s2 < 0) {
            fprintf(stderr, "Error: gpioRead(SENSOR_2_PIN) failed\n");
        } else {
            add_touch_event(SENSOR_2_PIN, s2);
        }

        if (gpioWrite(LED_1_PIN, gpioRead(SENSOR_1_PIN)) != 0) {
            fprintf(stderr, "Error: gpioWrite(LED_1_PIN) failed\n");
        }
        if (gpioWrite(LED_2_PIN, gpioRead(SENSOR_2_PIN)) != 0) {
            fprintf(stderr, "Error: gpioWrite(LED_2_PIN) failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();

    print_log();
    return EXIT_SUCCESS;
}

