#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Write a timestamped message to the log file and stdout */
static void log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_struct;
    struct tm *tstruct = localtime_r(&now, &tm_struct);
    if (tstruct == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        }
    }

    printf("%s: %s\n", buf, message);
    fflush(stdout);
}

/* Initialize pigpio and configure the rain sensor GPIO */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-up so the input is defined when the sensor is disconnected */
    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read the rain sensor (active-low: 0 = rain, 1 = no rain) */
static int read_rain_sensor(void) {
    int value = gpioRead(RAIN_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", RAIN_SENSOR_GPIO);
        return -1;
    }
    return value;
}

int main(void) {
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    int last_state = -1;  /* Force initial log */

    while (program_running) {
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            /* Sensor read failed; wait and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value != last_state) {
            if (sensor_value == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = sensor_value;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

