#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define POLL_DELAY_US 100000  /* 100 ms */
#define ALARM_THRESHOLD_S 2   /* seconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to the log file                         */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!log_file)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    fprintf(log_file, "%s %s\n", ts, msg);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down resistors so sensors read LOW when idle */
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    /* Ensure alarm starts in the OFF state */
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise alarm pin LOW\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on read error              */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Activate or deactivate the alarm                                   */
/* ------------------------------------------------------------------ */
static void alarm_control(int state)
{
    if (gpioWrite(ALARM_PIN, state) != 0) {
        fprintf(stderr, "gpioWrite failed on alarm pin\n");
        return;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    alarm_control(0);

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
