/*
 * Raspberry Pi 3 Model B+ - Omron D7S-A0011 Seismic Sensor Monitor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (I2C bus 1 SDA)
 *   D7S SCL  -> GPIO3 (I2C bus 1 SCL)
 *   D7S VCC  -> 3.3 V
 *   D7S GND  -> GND
 *   LED anode -> GPIO17 (via 330 ohm resistor) -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */
#define I2C_BUS              1
#define D7S_ADDR             0x1D          /* default 7-bit I2C address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* arbitrary threshold (counts) */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_US            1000000       /* 1 s */
#define I2C_RETRIES          3
#define I2C_RETRY_DELAY_US   10000         /* 10 ms */
#define LOG_FILE             "seismic_events.log"

/* D7S register addresses */
#define D7S_REG_CTRL1        0x1F
#define D7S_REG_X_LSB        0x28
#define D7S_REG_X_MSB        0x29
#define D7S_REG_Y_LSB        0x2A
#define D7S_REG_Y_MSB        0x2B
#define D7S_REG_Z_LSB        0x2C
#define D7S_REG_Z_MSB        0x2D

/* CTRL1 bits */
#define CTRL1_PD_BIT         0x01          /* power-down bit (0 = active) */
#define CTRL1_ODR_MASK       0x0C          /* output data rate (0 = 100 Hz) */
#define CTRL1_ODR_100HZ      0x00          /* 100 Hz output data rate */

/* --------------------------- Global state ---------------------------- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------- Function prototypes ------------------------ */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(int16_t *x, int16_t *y, int16_t *z);
static float calc_vibration(int16_t x, int16_t y, int16_t z);
static void log_event(float vibration);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------ I2C init ----------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, D7S_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init ----------------------------- */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, D7S_REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] D7S not responding at 0x%02X (read CTRL1): %d\n",
                D7S_ADDR, ctrl1);
        return -1;
    }

    /* Clear power-down bit and set ODR to 100 Hz */
    uint8_t ctrl1_val = (uint8_t)(ctrl1 & ~CTRL1_PD_BIT);
    if (i2cWriteByteData(i2c_handle, D7S_REG_CTRL1, ctrl1_val) < 0) {
        fprintf(stderr, "[ERROR] Failed to write CTRL1\n");
        return -1;
    }
    return 0;
}

/* --------------------- Read 6-byte acceleration block ----------------- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc;

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buf, 6);
        if (rc == 6) {
            *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (attempt %d/%d): rc=%d\n",
                attempt + 1, I2C_RETRIES, rc);
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ----------------------- Euclidean vibration magnitude ---------------- */
static float calc_vibration(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)x * x + (float)y * y + (float)z * z);
}

/* ------------------------------ Log event ----------------------------- */
static void log_event(float vibration)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Vibration: %.2f\n", ts, vibration) < 0)
        fprintf(stderr, "[ERROR] Failed to write to log file\n");
    fflush(log_file);
}

/* ------------------------------ Cleanup ------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- Main ------------------------------- */
int main(void)
{
    int16_t x, y, z;
    float vibration;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C and sensor */
    if (init_i2c() < 0 || init_sensor() < 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitor started. Threshold = %.1f, Poll = %d ms, LED = GPIO%d\n",
           (double)VIBRATION_THRESHOLD, POLL_INTERVAL_US / 1000, LED_GPIO);

    /* Main polling loop */
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            vibration = calc_vibration(x, y, z);

            if (vibration > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Vibration: %.2f\n", vibration);
                log_event(vibration);

                /* Turn LED on */
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

