        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C and sensor */
    if (init_i2c() < 0 || init_sensor() < 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitor started. Threshold = %.1f, Poll = %d ms, LED = GPIO%d\n",
           (double)VIBRATION_THRESHOLD, POLL_INTERVAL_US / 1000, LED_GPIO);

    /* Main polling loop */
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            vibration = calc_vibration(x, y, z);

            if (vibration > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Vibration: %.2f\n", vibration);
                log_event(vibration);

                /* Turn LED on */
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

