/*
 * Flame sensor monitor for Raspberry Pi 3 Model B+
 * Sensors : 5 Keyes KY-026 flame sensors
 * Pins    : BCM 2, 3, 4, 17, 27 (physical 3, 5, 7, 11, 13)
 * Log     : /var/log/flame_events.log
 * Build   : gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define CHIP_NAME        "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"S1", "S2", "S3", "S4", "S5"};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Append a timestamped event line to the log file.
 * Returns 0 on success, -1 on error (message already logged by caller).
 */
static int log_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed on %s: %s", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    char ts_buf[32];
    if (strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                ts_buf, sensor_ids[sensor_id - 1], pin) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed on %s: %s", LOG_FILE, strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose() failed on %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_state, 0, sizeof(prev_state));

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open syslog --- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame sensor monitor starting (libgpiod v1.6+)");

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* --- Acquire lines --- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line for %s (GPIO %u): %s",
                   sensor_ids[i], sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- Request lines as inputs --- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line %u as input: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Monitoring %d flame sensors on pins: %u, %u, %u, %u, %u",
           NUM_SENSORS,
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* --- Main polling loop --- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Read failed on %s (GPIO %u): %s",
                       sensor_ids[i], sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising-edge detection with debounce */
            if (val == 1 && prev_state[i] == 0) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                int confirm = gpiod_line_get_value(lines[i]);
                if (confirm < 0) {
                    syslog(LOG_ERR, "Debounce read failed on %s (GPIO %u): %s",
                           sensor_ids[i], sensor_pins[i], strerror(errno));
                    continue;
                }
                if (confirm == 1) {
                    if (log_event(i + 1, sensor_pins[i]) == 0) {
                        syslog(LOG_INFO, "Flame detected on %s (GPIO %u)",
                               sensor_ids[i], sensor_pins[i]);
                    }
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release lines --- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    /* --- Close chip --- */
    if (chip) {
        gpiod_chip_close(chip);
    }

    closelog();
    return ret;
}

