/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Wiring (Raspberry Pi 3 Model B+, BCM numbering):
 *   TTP226 OUT0 -> GPIO5   (physical pin 29)
 *   TTP226 OUT1 -> GPIO6   (physical pin 31)
 *   TTP226 OUT2 -> GPIO13  (physical pin 33)
 *   TTP226 OUT3 -> GPIO19  (physical pin 35)
 *   TTP226 OUT4 -> GPIO26  (physical pin 37)
 *   TTP226 OUT5 -> GPIO12  (physical pin 32)
 *   TTP226 OUT6 -> GPIO16  (physical pin 36)
 *   TTP226 OUT7 -> GPIO20  (physical pin 38)
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
