#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VEML7700_ADDR  0x10
#define REG_CONFIG     0x00
#define REG_ALS        0x04
#define LED_GPIO       18
#define PWM_FREQ       1000
#define PWM_RANGE      100
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_US      1000000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int veml7700_init(int handle)
{
    /* Config: ALS gain 1/8 (0x00), ALS IT 100 ms (0x00), ALS enabled */
    uint16_t cfg = 0x0000;
    char buf[2] = { (char)(cfg & 0xFF), (char)((cfg >> 8) & 0xFF) };

    if (i2cWriteI2CBlockData(handle, REG_CONFIG, buf, 2) < 0) {
        fprintf(stderr, "Error: failed to write VEML7700 config register\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out)
{
    char data[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, REG_ALS, data, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: ALS read failed (rc=%d)\n", rc);
        return -1;
    }

    uint16_t raw = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > 100) brightness = 100;

    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int adaptive_brightness(float lux)
{
    if (lux < 100.0f)  return 100;
    if (lux < 500.0f)  return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d,%d\n", ts, lux, brightness, error_code);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    float lux = 0.0f;
    int   brightness = 0;
    int   error_code = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 sensor not detected or init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        error_code = 0;

        if (veml7700_read_lux(g_i2c_handle, &lux) != 0) {
            error_code = -1;
            lux = 0.0f;
        }

        brightness = adaptive_brightness(lux);
        if (set_led_brightness(LED_GPIO, brightness) != 0) {
            error_code = -2;
        }

        log_data(g_log_file, lux, brightness, error_code);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    set_led_brightness(LED_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

