#define DEBOUNCE_DELAY_US 500000  /* 500 ms */

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state on GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad running. Press Ctrl+C to exit.\n");

    int prev_touch[NUM_CHANNELS] = {0};
    int any_touched = 0;

    while (program_running) {
        any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpioRead(touch_pins[i]);
            if (state < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", touch_pins[i]);
                continue;
            }

            /* Rising edge: transition from untouched to touched */
            if (state == 1 && prev_touch[i] == 0) {
                any_touched = 1;
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
            }
            prev_touch[i] = state;
        }

        if (gpioWrite(LED_PIN, any_touched ? 1 : 0) != 0) {
            fprintf(stderr, "Error writing to LED on GPIO %d\n", LED_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

