#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR        0x44
#define CONFIG_REG          0x01
#define RESULT_REG          0x00
#define CONFIG_VALUE        0xC810  /* RN=1000 (auto), CT=10 (100ms), M=00 (continuous), FC=00, OVF=00, CR=1000 (continuous) */
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US        100000  /* 100 ms first-conversion wait */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio's i2cWriteWordData/i2cReadWordData use little-endian (low byte, high byte).
 * The OPT3001 expects big-endian (MSB first).  Swap before writing and after reading.
 */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_write_config(int handle, uint16_t config)
{
    uint16_t swapped = swap16(config);
    int rc = i2cWriteWordData(handle, CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteWordData failed (pigpio rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result)
{
    int rc = i2cReadWordData(handle, RESULT_REG);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (pigpio rc=%d)\n", rc);
        return -1;
    }
    *result = swap16((uint16_t)rc);
    return 0;
}

static float opt3001_calculate_lux(uint16_t raw)
{
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1u << exponent);
}

static int log_data(float lux_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux_value) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Error: Failed to configure OPT3001\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for the first conversion to complete (100 ms) */
    gpioDelay(CONV_WAIT_US);

    printf("OPT3001 light sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_value = 0;
        if (opt3001_read_result(g_i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Warning: Failed to read result register, skipping sample\n");
        } else {
            float lux_value = opt3001_calculate_lux(raw_value);
            printf("Lux: %.2f\n", lux_value);
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

