#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define FLOW_SCALE     90.0f
#define MIN_FLOW       0.0f
#define MAX_FLOW       100.0f
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define INIT_DELAY_US  2000     /* 2 ms after start command */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Open log file (append) ---- */
static int open_log(void)
{
    /* Check if file exists / is empty to decide on header */
    int write_header = 0;
    FILE *chk = fopen(LOG_FILE, "r");
    if (!chk) {
        write_header = 1;                 /* file does not exist yet */
    } else {
        fseek(chk, 0, SEEK_END);
        if (ftell(chk) == 0) write_header = 1;
        fclose(chk);
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    if (write_header)
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    return 0;
}

/* ---- Initialize I2C ---- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ---- Start continuous measurement ---- */
static int start_measurement(void)
{
    uint8_t cmd[2] = { 0x36, 0x08 };   /* 0x3608 */
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (start) failed: %d\n", rc);
        return -1;
    }
    gpioDelay(INIT_DELAY_US);
    return 0;
}

/* ---- Read 3-byte sample ---- */
static int read_flow(float *flow_out, int *status_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "i2cReadDevice failed: rc=%d\n", rc);
        *status_out = STATUS_I2C_ERROR;
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        *status_out = STATUS_CRC_ERROR;
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float flow = (float)raw / FLOW_SCALE;

    if (flow < MIN_FLOW || flow > MAX_FLOW) {
        *status_out = STATUS_INVALID;
        return -1;
    }

    *status_out = STATUS_OK;
    *flow_out   = flow;
    return 0;
}

/* ---- Log one row ---- */
static void log_row(float flow, int status, const char *status_str)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow, status_str);
    fflush(g_log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }

    if (open_log() != 0) {
        cleanup();
        return 1;
    }

    printf("Monitoring coolant flow. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow = 0.0f;
        int   status = STATUS_OK;

        if (read_flow(&flow, &status) == 0) {
            const char *str = (status == STATUS_OK)
                ? "OK" : (status == STATUS_CRC_ERROR)
                    ? "CRC_ERROR" : "INVALID";
            log_row(flow, status, str);
            printf("Flow: %.2f ml/min, Status: %s\n", flow, str);
        } else {
            /* Attempt recovery: re-open I2C and restart measurement */
            fprintf(stderr, "Recovery: re-initializing I2C...\n");
            if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000);            /* 100 ms back-off */
            if (init_i2c() != 0 || start_measurement() != 0) {
                fprintf(stderr, "Recovery failed; will retry next cycle.\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

