}

static void log_event(int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_fp, "%s - Touch detected, LED state: %d\n", timestamp, led_state) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_fp);
    }
}

