    if (!led_line) {
        fprintf(stderr, "Failed to get LED line (GPIO%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223_touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on touch line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223_led", 0) < 0) {
