/*
 * Flame Detection Safety System (libgpiod version)
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: Keyes KY-026 flame sensor (digital out, active-low)
 * Buzzer: Active buzzer (control line, active-high)
 *
 * Wiring:
 *   KY-026 D0  -> GPIO17 (physical pin 11)
 *   Buzzer +   -> GPIO18 (physical pin 12)
 *   Buzzer -   -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_PIN    17
#define BUZZER_PIN   18
#define POLL_MS      500
#define BUZZER_MS    2000
#define SLICE_MS     100
#define LOG_FILE     "alert_log.txt"
#define CHIP_NAME    "gpiochip0"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    while (ms > 0 && g_running) {
        unsigned int chunk = (ms > SLICE_MS) ? SLICE_MS : ms;
        usleep(chunk * 1000);
        ms -= chunk;
    }
}

static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log, "[%s] %s\n", ts, msg);
    fflush(g_log);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
