#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_PIN    17
#define BUZZER_PIN   18
#define POLL_MS      500
#define BUZZER_MS    2000
#define SLICE_MS     100
#define LOG_FILE     "alert_log.txt"
#define CHIP_NAME    "gpiochip0"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    while (ms > 0 && g_running) {
        unsigned int chunk = (ms > SLICE_MS) ? SLICE_MS : ms;
        usleep(chunk * 1000);
        ms -= chunk;
    }
}

static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log, "[%s] %s\n", ts, msg);
    fflush(g_log);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }
    log_event("System started");

    /* ---- open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- request lines ---- */
    if (gpiod_line_request_input(flame, "flame_alert") < 0) {
        fprintf(stderr, "gpiod_line_request_input(%d): %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "flame_alert", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    log_event("GPIO initialized: flame=GPIO17, buzzer=GPIO18");

    /* ---- main loop ---- */
    int prev_state = gpiod_line_get_value(flame);
    if (prev_state < 0) {
        fprintf(stderr, "gpiod_line_get_value(%d): %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(%d): %s\n",
                    FLAME_PIN, strerror(errno));
            break;
        }

        /* Edge: HIGH -> LOW indicates flame detected */
        if (prev_state == 1 && val == 0) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%d,1): %s\n",
                        BUZZER_PIN, strerror(errno));
                break;
            }
            sleep_ms(BUZZER_MS);
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%d,0): %s\n",
                        BUZZER_PIN, strerror(errno));
                break;
            }
        }

        prev_state = val;
        sleep_ms(POLL_MS);
    }

    /* ---- graceful shutdown ---- */
    if (buzzer)
        gpiod_line_set_value(buzzer, 0);

    log_event("System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (flame)
        gpiod_line_release(flame);
    if (buzzer)
        gpiod_line_release(buzzer);
    if (chip)
        gpiod_chip_close(chip);
