#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_GPIO 4
#define LED_GPIO          17
#define LOG_FILE          "touch_log.txt"
#define POLL_DELAY_US     10000   /* 10 ms */
#define DEBOUNCE_US       200000  /* 200 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_touch_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed; skipping log entry.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Warning: strftime failed; skipping log entry.\n");
        return;
    }

    if (fprintf(log_file, "%s: Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Warning: failed to write to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t last_event_tick = 0;

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_event_tick >= DEBOUNCE_US) {
                last_event_tick = now;
                log_touch_event();
                if (gpioWrite(LED_GPIO, !gpioRead(LED_GPIO)) != 0) {
                    fprintf(stderr, "Error: failed to toggle LED on GPIO%d.\n", LED_GPIO);
                }
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

