/*
 * TMAG5110A1 Hall-effect latch sensor monitor (Raspberry Pi 4 Model B)
 *
 * The TMAG5110A1 is an open-drain output latch sensor:
 *   - Output low  -> magnet present (south pole)
 *   - Output high -> magnet absent
 *
 * The Pi's internal pull-up is enabled so the pin reads HIGH when
 * the sensor is open and LOW when a south-pole magnet is detected.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

#define LOG_FILE_PATH "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Global state                                                        */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, state ? "MAGNET_REMOVED" : "MAGNET_PRESENT") < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_sensor(int gpio_pin)
{
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int sensor_ids[] = {1, 2, 3};
    int num_sensors = (int)(sizeof(sensor_ids) / sizeof(sensor_ids[0]));
    int initial_states[3] = {-1, -1, -1};
    int current_states[3] = {-1, -1, -1};

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE_PATH, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs ------------------------------------- */
    for (int i = 0; i < num_sensors; i++) {
        if (setup_sensor(sensor_ids[i]) != 0) {
            fprintf(stderr, "Error: failed to configure GPIO %d\n", sensor_ids[i]);
            fclose(g_log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO %d, %d, %d. "
           "Press Ctrl+C to exit.\n", SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO);

    /* --- Read initial states ---------------------------------------- */
    for (int i = 0; i < num_sensors; i++) {
        int val = gpioRead(sensor_ids[i]);
        if (val < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", sensor_ids[i]);
            initial_states[i] = -1;
        } else {
            initial_states[i] = val;
        }
    }

    printf("Initial states: Sensor 1 = %s, Sensor 2 = %s, Sensor 3 = %s\n",
           initial_states[0] ? "MAGNET_REMOVED" : "MAGNET_PRESENT",
           initial_states[1] ? "MAGNET_REMOVED" : "MAGNET_PRESENT",
           initial_states[2] ? "MAGNET_REMOVED" : "MAGNET_PRESENT");

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        for (int i = 0; i < num_sensors; i++) {
            int val = gpioRead(sensor_ids[i]);
            if (val < 0) {
                fprintf(stderr, "Warning: gpioRead error on GPIO %d\n", sensor_ids[i]);
                current_states[i] = current_states[i];  /* no change */
                continue;
            }

            if (val != current_states[i]) {
                log_event(sensor_ids[i], val);
                current_states[i] = val;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

