#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    int hw_rev = i2cReadByteData(i2c_handle, REG_HW_REV);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    if (write_reg(REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_reg(REG_AVG, 0x04) < 0) return -1;
    if (write_reg(REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(int *bpm_out) {
    int raw = i2cReadWordData(i2c_handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR data: %d\n", raw);
        return -1;
    }
    *bpm_out = raw * 0.5;
    return 0;
}

static float moving_average(int new_value, float *buffer, int buffer_size, int *index) {
    float sum = 0.0f;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    buffer[*index] = (float)new_value;
    *index = (*index + 1) % buffer_size;
    return sum / (float)buffer_size;
}

static void log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, bpm);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HeartRate(BPM)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float moving_avg_buffer[MOVING_AVG_SIZE] = {0.0f};
    int moving_avg_index = 0;

    while (!terminate) {
        int raw_bpm;
        if (read_heart_rate(&raw_bpm) == 0) {
            float filtered_bpm = moving_average(raw_bpm, moving_avg_buffer, MOVING_AVG_SIZE, &moving_avg_index);
            if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
                log_data(filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM reading: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate data\n");
        }
        gpioDelay(1000000);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

