        fprintf(stderr, "gpiod_line_request_input_flags failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    int prev_value = gpiod_line_get_value(line);
    if (prev_value < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (prev_value == 1 && value == 0) {
            printf("FLAME DETECTED\n");
            if (log_flame_event(log_file) != 0) {
                fprintf(stderr, "Failed to log flame event.\n");
            }
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
