/* touch_counter.c — TTP226 8-channel touch sensor → 8-bit binary counter on output GPIOs
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1..OUT8  → GPIO 5, 6, 7, 8, 9, 10, 11, 12
 *   TTP226 VCC         → 3.3 V (pin 1)
 *   TTP226 GND         → GND  (pin 6)
 *   Counter display, LSB → GPIO17 (pin 11)
 *   Counter display, MSB → GPIO24 (pin 18)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define COUNTER_BITS 8
#define POLL_INTERVAL_US 10000   /* 10 ms  */
#define STABILIZE_MS    200      /* 200 ms after line request */

/* Sensor input pins (BCM) */
static const unsigned int sensor_pins[NUM_CHANNELS] = {
    5, 6, 7, 8, 9, 10, 11, 12
};

/* Output pins (BCM) */
static const unsigned int output_pins[COUNTER_BITS] = {
    17, 24
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_touch_event(int channel, int counter_value)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];
    FILE *fp;

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n",
                strerror(errno));
        /* still log to stdout */
    }

    if (fp != NULL) {
        fprintf(fp, "%s, Channel: %d, Counter: %d\n",
                timestamp, channel, counter_value);
        fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *output_req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    unsigned int offsets[NUM_CHANNELS];
    int ret = EXIT_FAILURE;
    int i;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open gpiochip0 (Raspberry Pi Zero W) ---- */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open(/dev/gpiochip0) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- sensor line settings: input, rising-edge events ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_edge_detection(settings, GPIOD_LINE_EDGE_RISING);

    /* ---- sensor line config: map each channel to a settings object ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    for (i = 0; i < NUM_CHANNELS; i++)
        offsets[i] = sensor_pins[i];

    if (gpiod_line_config_add_line_settings(line_cfg, offsets,
                                            NUM_CHANNELS, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- request sensor lines ---- */
    sensor_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (sensor_req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines (sensor) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- output line settings: output, default low ---- */
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    /* ---- output line config: map each bit to a settings object ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new (output) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    for (i = 0; i < COUNTER_BITS; i++)
        offsets[i] = output_pins[i];

    if (gpiod_line_config_add_line_settings(line_cfg, offsets,
                                            COUNTER_BITS, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (output) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- request output lines ---- */
    output_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (output_req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines (output) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- stabilize: let pull-downs settle ---- */
    usleep(STABILIZE_MS * 1000);

    /* ---- main loop ---- */
    int counter = 0;
    int prev_state[NUM_CHANNELS];
    int any_touched = 0;

    for (;;) {
        if (!g_running)
            break;

        any_touched = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req,
                                                   sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_request_get_value(ch %d) failed: %s\n",
                        i + 1, strerror(errno));
                continue;
            }

            /* rising-edge detection: only count inactive → active */
            if (val == 1 && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                any_touched = 1;
            }
            prev_state[i] = val;
        }

        if (any_touched) {
            for (i = 0; i < COUNTER_BITS; i++) {
                int out_val = (counter >> i) & 1;
                if (gpiod_line_request_set_value(output_req,
                                                 output_pins[i],
                                                 out_val) != 0) {
                    fprintf(stderr, "gpiod_line_request_set_value(out %d) failed: %s\n",
                            i, strerror(errno));
                }
            }
            log_touch_event(any_touched, counter);
            printf("Touch on channel %d | Counter: %d\n",
                   any_touched, counter);
            fflush(stdout);
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- graceful shutdown: reset all outputs ---- */
    for (i = 0; i < COUNTER_BITS; i++)
        gpiod_line_request_set_value(output_req, output_pins[i],
                                     GPIOD_LINE_VALUE_INACTIVE);

    ret = EXIT_SUCCESS;

cleanup:
    if (sensor_req != NULL)
        gpiod_line_request_release(sensor_req);
    if (output_req != NULL)
        gpiod_line_request_release(output_req);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

