#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_data(FILE *fp, int s1, int s2, int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, led_state);
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1_line = NULL, *s2_line = NULL, *led_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    s1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1_line || !s2_line || !led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(s1_line, "tcrt5000") < 0) {
        perror("gpiod_line_request_input s1");
        goto cleanup;
    }
    if (gpiod_line_request_input(s2_line, "tcrt5000") < 0) {
        perror("gpiod_line_request_input s2");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "tcrt5000", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        goto cleanup;
    }

    while (program_running) {
        int s1_val = gpiod_line_get_value(s1_line);
        int s2_val = gpiod_line_get_value(s2_line);

        if (s1_val < 0 || s2_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int led_state = (s1_val == 0 && s2_val == 0) ? 1 : 0;

        if (gpiod_line_set_value(led_line, led_state) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        log_data(log_fp, s1_val, s2_val, led_state);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (s1_line) gpiod_line_release(s1_line);
    if (s2_line) gpiod_line_release(s2_line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);

    return ret;
}

