#include <pigpio.h>

#define MIC_GPIO      4
#define LED_GPIO      17
#define SAMPLE_US     125          /* ~8 kHz polling  */
#define LED_ON_MS     100          /* LED on duration */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
