#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_LEFT  17
#define SENSOR_CENTER 27
#define SENSOR_RIGHT 22
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {SENSOR_LEFT, SENSOR_CENTER, SENSOR_RIGHT};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input_flags(lines[i], "sensor-reader", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input with pull-up\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        int left_val, center_val, right_val;
        int left_err, center_err, right_err;

        left_val = gpiod_line_get_value(lines[0]);
        left_err = (left_val < 0);
        if (left_err) {
            fprintf(stderr, "Error reading left sensor (GPIO%d)\n", SENSOR_LEFT);
        }

        center_val = gpiod_line_get_value(lines[1]);
        center_err = (center_val < 0);
        if (center_err) {
            fprintf(stderr, "Error reading center sensor (GPIO%d)\n", SENSOR_CENTER);
        }

        right_val = gpiod_line_get_value(lines[2]);
        right_err = (right_val < 0);
        if (right_err) {
            fprintf(stderr, "Error reading right sensor (GPIO%d)\n", SENSOR_RIGHT);
        }

        if (!left_err && !center_err && !right_err) {
            printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

