#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"

#define ALS_VIS_DATA0_REG 0x24
#define ALS_VIS_DATA1_REG 0x25

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_als_vis_data(int fd, uint16_t *als_vis_data) {
    uint8_t data0, data1;

    if (i2c_read_reg8(fd, ALS_VIS_DATA0_REG, &data0) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, ALS_VIS_DATA1_REG, &data1) < 0) {
        return -1;
    }

    *als_vis_data = ((uint16_t)data1 << 8) | data0;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to Si1175");
        goto cleanup;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");
    printf("Reading ALS visible data every 100 ms. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_vis_data;

        if (read_als_vis_data(fd, &als_vis_data) < 0) {
            fprintf(stderr, "Error reading ALS visible data: %s\n", strerror(errno));
            break;
        }

        printf("ALS Visible Data: %u\n", als_vis_data);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

