#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LEFT_PIN        2
#define MIDDLE_PIN      3
#define RIGHT_PIN       4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const unsigned int offsets[3] = {LEFT_PIN, MIDDLE_PIN, RIGHT_PIN};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line individually and request it as input */
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %u: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "keywish-tracking-sensor") < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Keywish 3-Way Tracking Sensor reading started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %u: %s\n", offsets[i], strerror(errno));
                goto cleanup;
            }
            values[i] = val;
        }

        printf("L:%d M:%d R:%d\n", values[0], values[1], values[2]);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully...\n");
    }
    return ret;
}

