/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP226, 8 independent active-high output lines
 *         TP1->BCM5  TP2->BCM6  TP3->BCM13 TP4->BCM19
 *         TP5->BCM26 TP6->BCM12 TP7->BCM16 TP8->BCM20
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 * Run:    ./ttp226_reader
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
