#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_DELAY 5.0
#define STEP_DELAY (FADE_DELAY / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void set_led_color(uint8_t r, uint8_t g, uint8_t b) {
    gpioPWM(RED_PIN,   255 - r);
    gpioPWM(GREEN_PIN, 255 - g);
    gpioPWM(BLUE_PIN,  255 - b);
}

static void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    if (s == 0.0f) {
        *r = *g = *b = (uint8_t)(v * 255.0f);
        return;
    }
    h = (h < 0.0f) ? (h + 360.0f) : (h % 360.0f);
    h /= 60.0f;
    int i = (int)h;
    float f = h - i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * f);
    float t = v * (1.0f - s * (1.0f - f));
    switch (i) {
        case 0:  *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(t * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 1:  *r = (uint8_t)(q * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 2:  *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(t * 255.0f); break;
        case 3:  *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(q * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        case 4:  *r = (uint8_t)(t * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        default: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(q * 255.0f); break;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return -1;
    }
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN");
        gpioTerminate();
        return -1;
    }
    set_led_color(0, 0, 0);
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting mood lamp");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    uint8_t current_r = 0, current_g = 0, current_b = 0;
    uint8_t target_r = 0, target_g = 0, target_b = 0;

    while (g_running) {
        target_r = (uint8_t)(rand() % 256);
        target_g = (uint8_t)(rand() % 256);
        target_b = (uint8_t)(rand() % 256);

        for (int i = 0; i < FADE_STEPS && g_running; i++) {
            float f = (float)i / FADE_STEPS;
            hsv_to_rgb(f, 1.0f, 1.0f, &current_r, &current_g, &current_b);
            set_led_color(current_r, current_g, current_b);
            time_sleep(STEP_DELAY);
        }
    }

    cleanup();
    syslog(LOG_INFO, "Mood lamp shut down gracefully");
    return EXIT_SUCCESS;
}

