/*
 * TCS34725 Color Sensor Reader with libgpiod and i2c-dev
 * Board: Raspberry Pi 4 Model B
 * I2C bus: /dev/i2c-1 (BCM pins 2/3)
 * Sensor address: 0x29
 * LED indicator on GPIO17
 *
 * Build: gcc -O2 -Wall -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

/* TCS34725 registers */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x92
#define TCS34725_CDATAL  0x94
#define TCS34725_RDATAL  0x96
#define TCS34725_GDATAL  0x98
#define TCS34725_BDATAL  0x9A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define TCS34725_ID_VALUE   0x44

#define LED_GPIO  17
#define RED_THRESHOLD 200
#define POLL_MS   200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- Sensor init ---- */

static int tcs34725_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    usleep(3000);

    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0)
        return -1;

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    usleep(180000);
    return 0;
}

static int tcs34725_power_down(int fd)
{
    return i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
}

/* ---- Calibration ---- */

static const uint16_t clear_gain  = 1.0f;
static const uint16_t red_gain    = 1.0f;
static const uint16_t green_gain  = 1.0f;
static const uint16_t blue_gain   = 1.0f;
