    *g_out = (float)g * green_gain  + green_offset;
    *b_out = (float)b * blue_gain   + blue_offset;
}

/* ---- Main ---- */

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
