    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* GPIO setup via libgpiod */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    /* I2C setup */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        goto cleanup;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        goto cleanup;
    }

    printf("TCS34725 initialized. Polling every %d ms...\n", POLL_MS);

    while (g_running) {
        uint16_t c, r, g, b;

        if (i2c_read_reg16(fd, TCS34725_CDATAL, &c) < 0 ||
            i2c_read_reg16(fd, TCS34725_RDATAL, &r) < 0 ||
            i2c_read_reg16(fd, TCS34725_GDATAL, &g) < 0 ||
            i2c_read_reg16(fd, TCS34725_BDATAL, &b) < 0) {
            fprintf(stderr, "Read error — re-initializing sensor...\n");
            tcs34725_power_down(fd);
            usleep(3000);
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed; retrying next cycle.\n");
            }
            usleep(POLL_MS * 1000);
            continue;
        }

        float c_cal, r_cal, g_cal, b_cal;
        calibrate(c, r, g, b, &c_cal, &r_cal, &g_cal, &b_cal);

        printf("C: %5.1f  R: %5.1f  G: %5.1f  B: %5.1f\n", c_cal, r_cal, g_cal, b_cal);

        if (r_cal > RED_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }

        usleep(POLL_MS * 1000);
    }

