#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_GPIO 18
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define NUM_LEDS 10
#define WS2812B_T0H 3
#define WS2812B_T0L 9
#define WS2812B_T1H 6
#define WS2812B_T1L 2
#define WS2812B_RESET 50
#define BH1750_CONV_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_light_level(float *lux) {
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error writing BH1750 command\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading BH1750 data: read %d bytes\n", bytes);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float norm = lux / MAX_LUX;
    int b = (int)(norm * 255.0f);
    if (b < 0) b = 0;
    if (b > 255) b = 255;
    return b;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t g = (brightness * 257) / 255;
    uint8_t r = (brightness * 257) / 255;
    uint8_t b = (brightness * 257) / 255;

    uint32_t led_data[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * 3 + 0] = g;
        led_data[i * 3 + 1] = r;
        led_data[i * 3 + 2] = b;
    }

    gpioPulse_t pulse[24 * NUM_LEDS];
    int idx = 0;
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t color = led_data[i * 3 + 0];
        for (int bit = 23; bit >= 0; bit--) {
            int one = (color >> bit) & 1;
            if (one) {
                pulse[idx].gpioOn = (1 << LED_GPIO);
                pulse[idx].gpioOff = 0;
                pulse[idx].usDelay = WS2812B_T1H;
                idx++;
                pulse[idx].gpioOn = 0;
                pulse[idx].gpioOff = (1 << LED_GPIO);
                pulse[idx].usDelay = WS2812B_T1L;
                idx++;
            } else {
                pulse[idx].gpioOn = (1 << LED_GPIO);
                pulse[idx].gpioOff = 0;
                pulse[idx].usDelay = WS2812B_T0H;
                idx++;
                pulse[idx].gpioOn = 0;
                pulse[idx].gpioOff = (1 << LED_GPIO);
                pulse[idx].usDelay = WS2812B_T0L;
                idx++;
            }
        }
    }

    gpioWaveClear();
    gpioWaveAddGeneric(idx, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) {
            gpioDelay(100);
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float lux = 0.0f;
    int consecutive_errors = 0;

    while (running) {
        if (read_light_level(&lux) == 0) {
            consecutive_errors = 0;
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive I2C errors, attempting reinit...\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(1000000);
                if (init_i2c() != 0) {
                    fprintf(stderr, "Reinit failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            } else {
                gpioDelay(100000);
            }
        }
        gpioDelay(50000);
    }

    cleanup();
    return 0;
}

