#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_LEDS 10
#define BH1750_CONV_MS 120
#define MIN_LUX 10.0f
#define MAX_LUX 300.0f
#define BRIGHTNESS_MAX 31

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, 0x20) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, 0x20) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int apa102_send_frame(int fd, uint8_t brightness) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led_data[4];
    led_data[0] = 0xE0 | (brightness & 0x1F);
    led_data[1] = 0x00;
    led_data[2] = 0x00;
    led_data[3] = 0x00;
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)start,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI start frame error: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        memset(led_data, 0, 4);
        led_data[0] = 0xE0 | (brightness & 0x1F);
        tr.tx_buf = (unsigned long)led_data;
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "SPI LED frame error: %s\n", strerror(errno));
            return -1;
        }
    }

    tr.tx_buf = (unsigned long)end;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI end frame error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    return (int)((lux - MIN_LUX) / (MAX_LUX - MIN_LUX) * BRIGHTNESS_MAX);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEV, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED_HZ}) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            usleep(500000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        if (apa102_send_frame(spi_fd, (uint8_t)brightness) < 0) {
            fprintf(stderr, "LED update failed\n");
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(500000);
    }

cleanup:
    if (spi_fd >= 0) {
        uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)end,
            .rx_buf = 0,
            .len = 4,
            .speed_hz = SPI_SPEED_HZ,
            .bits_per_word = 8,
            .delay_usecs = 0
        };
        ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        close(spi_fd);
    }
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

