#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HIGH_RES2 0x21
#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_WAIT_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HIGH_RES2) < 0) {
        fprintf(stderr, "Error: Failed to write command to BH1750 (handle %d)\n", handle);
        return -1;
    }
    gpioDelay(CONVERSION_WAIT_US);
    return 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: BH1750 read failed (handle %d, bytes read: %d)\n", handle, bytes);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int read_sensors(float lux[NUM_SENSORS]) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] < 0) continue;
        if (read_bh1750(i2c_handles[i], &lux[i]) != 0) {
            lux[i] = -1.0f;
        }
    }
    return 0;
}

static int calculate_brightness(const float lux[NUM_SENSORS], int num_valid) {
    if (num_valid == 0) return 31;
    float sum = 0.0f;
    for (int i = 0; i < num_valid; i++) {
        sum += lux[i];
    }
    float avg = sum / num_valid;
    int brightness = 31 - (int)(avg * 0.5f);
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

static int set_apa102_brightness(int brightness) {
    if (spi_handle < 0) return -1;
    uint8_t frame[4] = {0x00, 0x00, 0x00, 0x00};
    frame[0] = 0xE0 | (brightness & 0x1F);
    int bytes = spiWrite(spi_handle, (char *)frame, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: SPI write failed (returned %d)\n", bytes);
        return -1;
    }
    return 0;
}

static int fade_apa102(int target_brightness) {
    int current = 0;
    int step = target_brightness > current ? 1 : -1;
    while (current != target_brightness && running) {
        current += step;
        int val = (current < 0) ? 0 : (current > 31) ? 31 : current;
        uint8_t frame[4] = {0x00, 0x00, 0x00, 0x00};
        frame[0] = 0xE0 | (val & 0x1F);
        int bytes = spiWrite(spi_handle, (char *)frame, 4);
        if (bytes != 4) {
            fprintf(stderr, "Error: SPI write failed during fade\n");
            return -1;
        }
        gpioDelay(FADE_DURATION_MS * 1000);
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    i2c_handles[0] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: Could not open I2C device at 0x%02X\n", BH1750_ADDR_LOW);
    }

    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: Could not open I2C device at 0x%02X\n", BH1750_ADDR_HIGH);
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            if (init_bh1750(i2c_handles[i]) != 0) {
                fprintf(stderr, "Warning: BH1750 init failed for handle %d\n", i2c_handles[i]);
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            }
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float lux[NUM_SENSORS];
    int target_brightness = 31;

    while (running) {
        if (read_sensors(lux) != 0) {
            fprintf(stderr, "Error: Sensor read failed, using last brightness\n");
        } else {
            int num_valid = 0;
            for (int i = 0; i < NUM_SENSORS; i++) {
                if (lux[i] >= 0.0f) num_valid++;
            }
            if (num_valid > 0) {
                target_brightness = calculate_brightness(lux, num_valid);
            } else {
                target_brightness = 31;
            }
        }

        if (fade_apa102(target_brightness) != 0) {
            fprintf(stderr, "Error: Fade failed\n");
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

