#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile int keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int veml7700_init(int fd) {
    // Configuration: 0x0000 = 100ms integration time, gain 1/8
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait for configuration to take effect
    return 0;
}

int veml7700_read_lux(int fd, float *lux) {
    uint16_t als_data;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &als_data) < 0) {
        fprintf(stderr, "Error: Failed to read VEML7700 ALS data: %s\n", strerror(errno));
        return -1;
    }
    // lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
    // For default settings: lux = raw * 0.0288
    *lux = (float)als_data * 0.0288f;
    return 0;
}

int ws2812b_set_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // Bit-bang WS2812B on a single GPIO using libgpiod
    // Each bit: 1us high, 0us low (800kHz)
    // Data bits: 24 bits (3 bytes)
    // We'll send the bytes in a single GPIO transaction using libgpiod's bit-banging capabilities
    // This is simplified; real implementation would use hardware PWM or bit-banging with timing
