                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read lux after %d retries, using last value\n", MAX_RETRIES);
            // Use last valid value if retries fail
            // For simplicity, we'll just use the last known value
            // In production, you'd store previous values or use a default
            // Here we'll just continue with 0
            lux = 0.0f;
        }

        int brightness = map_lux_to_brightness(lux);

        // Drive WS2812B
        if (ws2812b_set_brightness(brightness) < 0) {
