#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define POLL_INTERVAL_US 50000
#define SELF_TEST_DELAY_US 500000
#define SELF_TEST_SAMPLES 5
#define FAULT_BLINK_DELAY_US 100000
#define FAULT_LED_CYCLES 5
#define FAULT_BUZZER_CYCLES 3
#define FAULT_BUZZER_DURATION_MS 200
#define FAULT_BUZZER_GAP_MS 600

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void cleanup(void) {
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Failed to get flame sensor line (GPIO%d): %s\n", FLAME_SENSOR_PIN, strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line (GPIO%d): %s\n", BUZZER_PIN, strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line (GPIO%d): %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int val = gpiod_line_get_value(flame_line);
    if (val < 0) {
        fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static int write_output(struct gpiod_line *line, int value, const char *name) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to %s: %s\n", name, strerror(errno));
        return -1;
    }
    return 0;
}

static void self_test(void) {
    log_event("Starting self-test...");

    if (write_output(led_line, 1, "LED") < 0) return;
    usleep(500000);
    if (write_output(led_line, 0, "LED") < 0) return;
    usleep(500000);

    log_event("Self-test: reading flame sensor 5 times...");
    int flame_count = 0;
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Self-test failed: sensor read error");
            cleanup();
            exit(1);
        }
        if (val == 0) flame_count++;
        usleep(100000);
    }

    if (flame_count == SELF_TEST_SAMPLES) {
        log_event("Self-test: sensor consistently reads flame (fault)");
        cleanup();
        exit(1);
    } else {
        log_event("Self-test: no consistent flame signal");
    }

    log_event("Self-test complete.");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    self_test();

    log_event("Entering main loop...");
    while (program_running) {
        int val = read_flame_sensor();
        if (val < 0) {
            log_event("Error reading flame sensor, retrying...");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val == 0) {
            log_event("Flame detected!");
            if (write_output(buzzer_line, 1, "Buzzer") < 0 ||
                write_output(led_line, 1, "LED") < 0) {
                log_event("Error activating alarm outputs");
            }

            while (program_running) {
                val = read_flame_sensor();
                if (val >= 0 && val != 0) {
                    log_event("Flame gone!");
                    break;
                }
                usleep(POLL_INTERVAL_US);
            }

            if (write_output(buzzer_line, 0, "Buzzer") < 0 ||
                write_output(led_line, 0, "LED") < 0) {
                log_event("Error deactivating alarm outputs");
            }
        } else {
            usleep(POLL_INTERVAL_US);
        }
    }

    log_event("Shutting down...");
    cleanup();
    return 0;
}

