#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(i2c_fd, BH1750_CONT_HIGH_RES) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(180000);
    return 0;
}

static int read_bh1750(float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(i2c_fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int init_gpio(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, GPIO_LED, 1) != 1) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", GPIO_LED, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", GPIO_LED);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, "out", 3) != 3) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_LED, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_LED);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, "0", 1) != 1) {
        fprintf(stderr, "Failed to set initial GPIO %d value: %s\n", GPIO_LED, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int set_led(int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_LED);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) != 1) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n", GPIO_LED, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    int fd = open(path, O_WRONLY);
    if (fd >= 0) {
        write(fd, GPIO_LED, 1);
        close(fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_filled = 0;
    int led_state = 0;

    while (running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Read failed, skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_filled < BUFFER_SIZE) {
            buffer_filled++;
        }

        float sum = 0.0f;
        for (int i = 0; i < buffer_filled; i++) {
            sum += lux_buffer[i];
        }
        float avg_lux = sum / buffer_filled;

        int rate = 0;
        if (buffer_filled == BUFFER_SIZE) {
            rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
        }
        if (rate < 0.5f) rate = 0.5f;
        if (rate > 5.0f) rate = 5.0f;

        set_led(1);
        usleep((useconds_t)(0.5f + (avg_lux / 1000.0f) * 4.5f));
        set_led(0);
        usleep((useconds_t)(0.5f + (avg_lux / 1000.0f) * 4.5f));

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

