#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* Segment patterns for digits 0-9 (common cathode, active high) */
static const unsigned char digit_patterns[10] = {
    0x3F, /* 0: a,b,c,d,e,g */
    0x06, /* 1: b,c */
    0x5B, /* 2: a,b,c,d,e,g,i,j */
    0x4F, /* 3: a,b,c,d,e,g,i,j,k */
    0x66, /* 4: f,g,e,d,c,b */
    0x6D, /* 5: f,g,e,d,c,b,i */
    0x7D, /* 6: f,g,e,d,c,b,i,j */
    0x07, /* 7: a,b,c */
    0x7F, /* 8: a,b,c,d,e,f,g,i */
    0x6F  /* 9: a,b,c,d,e,f,g */
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static void cleanup(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "74hc595", 0) < 0 ||
        gpiod_line_request_output(clock_line, "74hc595", 0) < 0 ||
        gpiod_line_request_output(latch_line, "74hc595", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return -1;
    }

    return 0;
}

static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(clock_line, 0);
        gpiod_line_set_value(data_line, (data >> i) & 1);
        gpiod_line_set_value(latch_line, 0);
        usleep(1); /* latch settle */
        gpiod_line_set_value(latch_line, 1);
        usleep(1); /* latch hold */
        gpiod_line_set_value(clock_line, 1);
        usleep(1); /* clock high */
    }
}

static void display_digit(int digit) {
    if (digit < 0 || digit > 9) return;
    shift_out(digit_patterns[digit]);
}

int main(void) {
    if (setup_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(5);
        usleep(500000);
        display_digit(0);
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

