int main(void) {
    if (setup_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(5);
        usleep(500000);
        display_digit(0);
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

