#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN  24
#define BUTTON_PIN 22
#define BLINK_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip0 device */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON_PIN)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, "led_blink", 0) < 0) {
        perror("gpiod_line_request_output(led_line)");
        goto cleanup;
    }

    /* Request button line as input with internal pull-down */
    if (gpiod_line_request_input_flags(button_line, "button_input",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(button_line)");
        goto cleanup;
    }

    printf("LED on GPIO%d, button on GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    int led_state = 0;
    int last_button_state = 1; /* assume released (pull-down high) */

    while (running) {
        int button_state = gpiod_line_get_value(button_line);
        if (button_state < 0) {
            perror("gpiod_line_get_value(button_line)");
            break;
        }

        /* Detect falling edge: button pressed (pulled low) */
        if (button_state == 0 && last_button_state == 1) {
            /* Blink pattern while button is held */
            while (running) {
                led_state = !led_state;
                if (gpiod_line_set_value(led_line, led_state) < 0) {
                    perror("gpiod_line_set_value(led_line)");
                    break;
                }
                usleep(BLINK_INTERVAL_MS * 1000);
            }
            if (!running) break;
            /* Turn off after release */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led_line)");
                break;
            }
        }

        last_button_state = button_state;
        usleep(10000); /* 10 ms poll interval */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

