#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define RED_PIN    24
#define GREEN_PIN  23
#define BLUE_PIN   18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define STEP_NS     1000000     /* 1 ms */

static volatile sig_atomic_t running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int set_line(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    /* Open GPIO chip 0 (Raspberry Pi 5 uses gpiochip0) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines as outputs, initially low */
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Seed random number generator */
    srand((unsigned int)time(NULL));

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        /* Software PWM: 10 ms period, 1 ms steps */
        if (set_line(red_line,   (r * PWM_PERIOD_NS) / 100) < 0) break;
        if (set_line(green_line, (g * PWM_PERIOD_NS) / 100) < 0) break;
        if (set_line(blue_line,  (b * PWM_PERIOD_NS) / 100) < 0) break;

        /* Sleep for the remainder of the 10 ms period using clock_nanosleep */
        struct timespec ts = {0, PWM_PERIOD_NS};
        while (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) == -1 && errno == EINTR) {
            if (!running) break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

