#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC Accelerometer I2C address (SA0 tied to GND) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC Accelerometer Registers */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* GPIO pin for impact indicator */
#define IMPACT_GPIO 17

/* Default G-force threshold (2.0G) */
#define DEFAULT_THRESHOLD 2.0

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static double threshold = DEFAULT_THRESHOLD;

/* Structure to hold accelerometer data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

/* Function prototypes */
static int init_i2c(void);
static int init_accelerometer(void);
static int read_accelerometer(accel_data_t *data);
static double calculate_magnitude(accel_data_t data);
static void handle_impact(accel_data_t data);
static void log_impact(accel_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize I2C communication */
static int init_i2c(void) {
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                LSM303_ACCEL_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Initialize the LSM303DLHC accelerometer */
static int init_accelerometer(void) {
    /* CTRL_REG1_A: 0x27 = 0b00100111 -> ODR=100Hz (0111), all axes enabled */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    /* CTRL_REG4_A: 0x00 = 0b00000000 -> +/-2G full scale, high-resolution disabled */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data using multi-byte read with auto-increment */
static int read_accelerometer(accel_data_t *data) {
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_L_A with auto-increment (0x80) */
    if (i2cReadI2CBlockData(i2c_handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    /* LSM303DLHC accelerometer: little-endian, 16-bit signed */
    data->x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    return 0;
}

/* Calculate the magnitude of the acceleration vector in G */
static double calculate_magnitude(accel_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;
    return sqrt(x * x + y * y + z * z);
}

/* Handle impact: pulse GPIO and log data */
static void handle_impact(accel_data_t data) {
    printf("Impact detected! Magnitude: %.2f G\n", calculate_magnitude(data));

    /* Pulse GPIO HIGH for 50 ms */
    gpioWrite(IMPACT_GPIO, 1);
    gpioDelay(50000); /* 50 ms in microseconds */
    gpioWrite(IMPACT_GPIO, 0);

    /* Log data to file */
    log_impact(data);
}

/* Log impact data to file */
static void log_impact(accel_data_t data) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f G\n",
            timestamp, data.x, data.y, data.z, calculate_magnitude(data));
    fclose(fp);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(IMPACT_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    /* Parse command-line arguments */
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold value. Using default: %.2f G\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        } else {
            printf("Threshold set to: %.2f G\n", threshold);
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO17 as output */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Initialize accelerometer */
    if (init_accelerometer() != 0) {
        cleanup();
        return 1;
    }

    /* Set up signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        accel_data_t data;

        if (read_accelerometer(&data) == 0) {
            double magnitude = calculate_magnitude(data);
            if (magnitude > threshold) {
                handle_impact(data);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling) */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

