#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define MODE_NORMAL 0x01
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define GREEN_LSB_REG 0x68
#define BLUE_LSB_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adpd188bi(void) {
    if (i2cWriteByteData(i2c_handle, MODE_REG, MODE_NORMAL) < 0) {
        fprintf(stderr, "Error: Failed to write MODE register (0x%02X)\n", MODE_REG);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int als_lsb, als_msb, red_lsb, green_lsb, blue_lsb;

    als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (als_lsb < 0) {
        fprintf(stderr, "Error: Failed to read ALS LSB (0x%02X)\n", ALS_LSB_REG);
        return -1;
    }
    als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (als_msb < 0) {
        fprintf(stderr, "Error: Failed to read ALS MSB (0x%02X)\n", ALS_MSB_REG);
        return -1;
    }
    *als = (uint16_t)((als_msb << 8) | als_lsb);

    red_lsb = i2cReadByteData(i2c_handle, RED_LSB_REG);
    if (red_lsb < 0) {
        fprintf(stderr, "Error: Failed to read Red LSB (0x%02X)\n", RED_LSB_REG);
        return -1;
    }
    green_lsb = i2cReadByteData(i2c_handle, GREEN_LSB_REG);
    if (green_lsb < 0) {
        fprintf(stderr, "Error: Failed to read Green LSB (0x%02X)\n", GREEN_LSB_REG);
        return -1;
    }
    blue_lsb = i2cReadByteData(i2c_handle, BLUE_LSB_REG);
    if (blue_lsb < 0) {
        fprintf(stderr, "Error: Failed to read Blue LSB (0x%02X)\n", BLUE_LSB_REG);
        return -1;
    }
    *red = (uint16_t)((blue_lsb << 8) | red_lsb);
    *green = (uint16_t)((green_lsb << 8) | red_lsb);
    *blue = (uint16_t)((blue_lsb << 8) | blue_lsb);
    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led_brightness(uint16_t als) {
    int pwm_value = (int)(((float)als / 65535.0f) * PWM_RANGE);
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    if (pwm_value < 0) pwm_value = 0;
    gpioPWM(LED_GPIO, pwm_value);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", ADPD188BI_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_adpd188bi() < 0) {
        fprintf(stderr, "Error: ADPD188BI initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t als, red, green, blue;

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led_brightness(als);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

