#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDRESS 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS     0x00
#define FXOS8700_REG_OUT_X_MSB  0x01
#define FXOS8700_REG_WHO_AM_I   0x0D
#define FXOS8700_REG_XYZ_CFG    0x0E
#define FXOS8700_REG_CTRL_REG1  0x2A

/* Expected WHO_AM_I value */
#define FXOS8700_WHOAMI_VAL     0xC7

/* Impact threshold: 2g in m/s^2 (19.62 m/s^2 at 9.81 m/s^2/g) */
#define IMPACT_THRESHOLD_MPS2   19.62

/* Sensitivity for ±2g range: 4096 counts/g */
#define COUNTS_PER_G            4096.0f
#define GRAVITY_MPS2            9.81f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US      50000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Read a single byte from an FXOS8700 register; returns -1 on error */
static int fxos_read_byte(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* Write a single byte to an FXOS8700 register; returns -1 on error */
static int fxos_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* Read 6 bytes of acceleration data; returns -1 on error */
static int fxos_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: rc=%d\n", rc);
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 */
    *x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]) >> 2;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]) >> 2;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]) >> 2;
    return 0;
}

/* Compute acceleration in m/s^2 from 14-bit left-justified counts */
static void compute_accel_mps2(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                float *x_mps2, float *y_mps2, float *z_mps2)
{
    float gx = (float)raw_x / COUNTS_PER_G;
    float gy = (float)raw_y / COUNTS_PER_G;
    float gz = (float)raw_z / COUNTS_PER_G;

    *x_mps2 = gx * GRAVITY_MPS2;
    *y_mps2 = gy * GRAVITY_MPS2;
    *z_mps2 = gz * GRAVITY_MPS2;
}

/* Log impact data to file */
static void log_impact(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                        float x_mps2, float y_mps2, float z_mps2,
                        float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                raw_x, raw_y, raw_z, magnitude);
    } else {
        fprintf(fp, "timestamp_error,%d,%d,%d,%.3f\n",
                raw_x, raw_y, raw_z, magnitude);
    }

    fclose(fp);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint8_t whoami = 0;
    if (fxos_read_byte(i2c_handle, FXOS8700_REG_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (whoami != FXOS8700_WHOAMI_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHOAMI_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Standby mode before configuration */
    if (fxos_write_byte(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ±2g range: 0x00 */
    if (fxos_write_byte(i2c_handle, FXOS8700_REG_XYZ_CFG, 0x00) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Active mode, 200 Hz ODR: bit 0 = 1 */
    if (fxos_write_byte(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(100000); /* 100 ms */

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;

        if (fxos_read_accel(i2c_handle, &raw_x, &raw_y, &raw_z) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float x_mps2, y_mps2, z_mps2;
        compute_accel_mps2(raw_x, raw_y, raw_z, &x_mps2, &y_mps2, &z_mps2);
        float magnitude = sqrtf(x_mps2 * x_mps2 +
                                y_mps2 * y_mps2 +
                                z_mps2 * z_mps2);

        if (magnitude > IMPACT_THRESHOLD_MPS2) {
            printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            log_impact(raw_x, raw_y, raw_z, x_mps2, y_mps2, z_mps2, magnitude);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

