#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define CTRL_REG1_VAL  0x0F
#define CTRL_REG4_VAL  0x00
#define SENSITIVITY    0.00875f
#define THRESHOLD_DPS  50.0f
#define SAMPLE_PERIOD_US 50000
#define CALIB_SAMPLES  100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(void) {
    uint8_t whoami;
    if (i2c_read_block(WHO_AM_I_REG, &whoami, 1) < 0) return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(CTRL_REG1, CTRL_REG1_VAL) < 0) return -1;
    if (i2c_write_reg(CTRL_REG4, CTRL_REG4_VAL) < 0) return -1;
    return 0;
}

static int calibrate_gyro(float *off_x, float *off_y, float *off_z) {
    float x_sum = 0, y_sum = 0, z_sum = 0;
    uint8_t buf[6];
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (i2c_read_block(OUT_X_L, buf, 6) < 0) return -1;
        int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        x_sum += raw_x; y_sum += raw_y; z_sum += raw_z;
