#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0  0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATA_FORMAT 0x31

#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Failed to set data rate\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Failed to set data format (full-res, +/-2g)\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char data[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((data[1] << 8) | (uint8_t)data[0]);
    int16_t raw_y = (int16_t)((data[3] << 8) | (uint8_t)data[2]);
    int16_t raw_z = (int16_t)((data[5] << 8) | (uint8_t)data[4]);

    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X (rc=%d)\n", ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);

            if (fabsf(x) > ACCEL_THRESHOLD ||
                fabsf(y) > ACCEL_THRESHOLD ||
                fabsf(z) > ACCEL_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Read error; skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

