static int read_magnetometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);
    *x = (float)raw_x * MAG_SENSITIVITY / 1000.0f;
    *y = (float)raw_y * MAG_SENSITIVITY / 1000.0f;
    *z = (float)raw_z * MAG_SENSITIVITY / 1000.0f;
    return 0;
}

static float calculate_heading(float pitch, float roll) {
    float cos_roll = cosf(roll * M_PI / 180.0f);
    float sin_roll = sinf(roll * M_PI / 180.0f);
    float cos_pitch = cosf(pitch * M_PI / 180.0f);
    float sin_pitch = sinf(pitch * M_PI / 180.0f);
    float x_h = cos_pitch * cos_roll * MAG_SENSITIVITY / 1000.0f;
    float y_h = cos_pitch * sin_roll * MAG_SENSITIVITY / 1000.0f;
    float z_h = sin_pitch * MAG_SENSITIVITY / 1000.0f;
