static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error setting read reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error setting read reg 0x%04X\n", reg);
        return -1;
    }
    char val_buf[2];
    if (i2cReadDevice(handle, val_buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint8_t)val_buf[0] << 8) | (uint8_t)val_buf[1];
