#define GYRO_SENSITIVITY   0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY  0.00025f /* g/LSB */

/* SPI: channel 0 (CE0 / GPIO8), 1 MHz, mode 3 (CPOL=1, CPHA=1) */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0b11000000000  /* auxSPI=0, CPOL=1, CPHA=1, MSB first */

#define SAMPLE_PERIOD_US  100000   /* 100 ms */
#define STALL_DELAY_US    40       /* > 40 us stall between request and data */
#define NON_BLOCK_STEP_US 5000     /* 5 ms per check of running flag */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_fp        = NULL;

/* ------------------------------------------------------------------ */
/* Cleanup: close SPI, close file, terminate pigpio                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Signal handler: set flag so main loop exits and cleanup runs         */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit register from the ADIS16488A                         */
/* Sends [0, reg_addr]  ->  data returned on next [0, reg_addr]        */
/* ------------------------------------------------------------------ */
static int adis_read_register(uint8_t reg_addr, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    /* Request: 16-bit word, MSB = 0, followed by the 7-bit register */
    tx[0] = (char)(reg_addr & 0x7F);
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (request) failed for reg 0x%02X: ret=%d\n",
                reg_addr, ret);
        return -1;
    }

    /* ADIS16488A data return on the *next* transfer of the same length */
    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (data) failed for reg 0x%02X: ret=%d\n",
                reg_addr, ret);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a vector of three axes from the IMU                             */
/* ------------------------------------------------------------------ */
static int read_axis_vector(uint8_t reg_addr, const char *name,
                            float *x, float *y, float *z)
{
    int16_t raw;

    if (adis_read_register(reg_addr, &raw) != 0)
        return -1;

    *x = (float)raw * GYRO_SENSITIVITY;
    *y = (float)(raw >> 8) * GYRO_SENSITIVITY;  /* two's complement */
    *z = (float)(raw >> 8) * ACCEL_SENSITIVITY; /* two's complement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Format one sample row into the CSV buffer                            */
/* ------------------------------------------------------------------ */
static void format_sample(char *buf, size_t buflen,
                          float gx, float gy, float gz,
                          float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    snprintf(buf, buflen, "%s.%03ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f",
             ts_str, ts.tv_nsec / 1000000L,
             gx, gy, gz, ax, ay, az);
}

/* ------------------------------------------------------------------ */
/* Append one sample to the CSV file                                    */
/* ------------------------------------------------------------------ */
static int log_sample(const char *sample)
{
    if (fputs(sample, g_fp) == EOF) {
        perror("fputs to CSV file");
        return -1;
    }
    fflush(g_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char sample_buf[256];

    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- CSV file ---------------------------------------------------- */
    g_fp = fopen("imu_data.csv", "a");
    if (g_fp == NULL) {
        perror("fopen imu_data.csv");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(g_fp);
    }

    /* --- Signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- atexit cleanup ---------------------------------------------- */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        fclose(g_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop ------------------------------------------ */
    while (g_running) {
        float gx = 0.0f, gy = 0.0f, gz = 0.0f,
              ax = 0.0f, ay = 0.0f, az = 0.0f;

        if (read_axis_vector(REG_X_GYRO, "gyro_x", &gx, &gy, &gz) != 0 ||
            read_axis_vector(REG_X_ACCEL, "accel_x", &ax, &ay, &az) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
        } else {
            format_sample(sample_buf, sizeof(sample_buf),
                          gx, gy, gz, ax, ay, az);
            if (log_sample(sample_buf) != 0) {
                fprintf(stderr, "CSV write error — continuing\n");
            }
        }

        /* Non-blocking wait: check flag every 5 ms */
        for (int i = 0; i < 20 && g_running; i++)
            gpioDelay(NON_BLOCK_STEP_US);
    }

    /* --- normal exit path ------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

