#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip4"
#define CS_GPIO_LINE    8

#define ADIS16448_REG_XGYRO_OUT 0x04
#define ADIS16448_REG_YGYRO_OUT 0x06
#define ADIS16448_REG_ZGYRO_OUT 0x08
#define ADIS16448_REG_XACCL_OUT 0x0A
#define ADIS16448_REG_YACCL_OUT 0x0C
#define ADIS16448_REG_ZACCL_OUT 0x0E

#define GYRO_SCALE  0.02f
#define ACCL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_register(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int read_axis(int fd, struct gpiod_line *cs, uint8_t reg, const char *name, float scale, float *value) {
    int16_t raw;
    if (read_register(fd, cs, reg, &raw) < 0) {
        fprintf(stderr, "Error reading %s\n", name);
        return -1;
    }
    *value = (float)raw * scale;
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line failed");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16448_cs", 1) < 0) {
        perror("gpiod_line_request_output failed");
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    printf("ADIS16448 IMU Reader (SPI mode 3, CS on GPIO8)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float gx = 0, gy = 0, gz = 0, ax = 0, ay = 0, az = 0;
        int err = 0;

        if (read_axis(spi_fd, cs_line, ADIS16448_REG_XGYRO_OUT, "gyro X", GYRO_SCALE, &gx) < 0) err = 1;
        if (read_axis(spi_fd, cs_line, ADIS16448_REG_YGYRO_OUT, "gyro Y", GYRO_SCALE, &gy) < 0) err = 1;
        if (read_axis(spi_fd, cs_line, ADIS16448_REG_ZGYRO_OUT, "gyro Z", GYRO_SCALE, &gz) < 0) err = 1;
        if (read_axis(spi_fd, cs_line, ADIS16448_REG_XACCL_OUT, "accel X", ACCL_SCALE, &ax) < 0) err = 1;
        if (read_axis(spi_fd, cs_line, ADIS16448_REG_YACCL_OUT, "accel Y", ACCL_SCALE, &ay) < 0) err = 1;
        if (read_axis(spi_fd, cs_line, ADIS16448_REG_ZACCL_OUT, "accel Z", ACCL_SCALE, &az) < 0) err = 1;

        if (err) {
            fprintf(stderr, "SPI read error encountered. Continuing...\n");
        } else {
            printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
                   "Accel: X=%.6f g, Y=%.6f g, Z=%.6f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        usleep(100000);
    }

    printf("\nExiting cleanly...\n");
    ret = 0;

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

