#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define ADIS16448_X_GYRO_OUT 0x04
#define ADIS16448_Y_GYRO_OUT 0x06
#define ADIS16448_Z_GYRO_OUT 0x08
#define ADIS16448_X_ACCL_OUT 0x0A
#define ADIS16448_Y_ACCL_OUT 0x0C
#define ADIS16448_Z_ACCL_OUT 0x0E

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */

/* Global SPI handle for signal handler cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADIS16448.
 * The ADIS16448 requires a two-cycle SPI read:
 *   Cycle 1: send (reg | 0x8000) to select the register and start a read.
 *   Cycle 2: send 0x0000 to clock out the 16-bit data.
 * A stall time of >= 40 us between cycles is required.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];
    int  status;

    /* Cycle 1: send read command */
    tx_buf[0] = (char)(reg | 0x8000);
    tx_buf[1] = 0x00;

    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "SPI read command failed for reg 0x%02X (status=%d)\n", reg, status);
        return -1;
    }

    /* Stall time between read command and data read */
    gpioDelay(50); /* 50 us is more than sufficient */

    /* Cycle 2: dummy transfer to clock out the data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "SPI data read failed for reg 0x%02X (status=%d)\n", reg, status);
        return -1;
    }

    /* ADIS16448 data is big-endian */
    *value = (int16_t)(((uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read a vector of three axes from a register address */
static int read_axis_vector(uint8_t reg, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(reg, &raw_x) != 0) return -1;
    if (read_register(reg + 2, &raw_y) != 0) return -1;
    if (read_register(reg + 4, &raw_z) != 0) return -1;

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Reader (pigpio SPI)\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (running) {
        float gyro_x, gyro_y, gyro_z;
        float accl_x, accl_y, accl_z;

        if (read_axis_vector(ADIS16448_X_GYRO_OUT, &gyro_x, &gyro_y, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
        } else if (read_axis_vector(ADIS16448_X_ACCL_OUT, &accl_x, &accl_y, &accl_z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        } else {
            printf("Gyro:  X: %7.3f deg/s  Y: %7.3f deg/s  Z: %7.3f deg/s\n",
                   gyro_x, gyro_y, gyro_z);
            printf("Accel: X: %7.3f g     Y: %7.3f g     Z: %7.3f g\n\n",
                   accl_x, accl_y, accl_z);
