#include <linux/i2c-dev.h>

#define MPU6886_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define REG_SMPLRT_DIV   0x19
#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_INT_PIN_CFG  0x37
#define REG_INT_ENABLE  0x38
#define REG_INT_STATUS  0x39
#define REG_WHO_AM_I    0x75
#define REG_PWR_MGMT_1  0x6B
#define REG_PWR_MGMT_2  0x6C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

#define WHO_AM_I_EXPECTED 0x86

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6886(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);

    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_PIN_CFG, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_STATUS, 0x06) < 0) return -1;

    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, buf, 6) == 0) {
            *ax = (int16_t)((buf[0] << 8) | buf[1]);
            *ay = (int16_t)((buf[2] << 8) | buf[3]);
            *az = (int16_t)((buf[4] << 8) | buf[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, 6) == 0) {
            *gx = (int16_t)((buf[0] << 8) | buf[1]);
            *gy = (int16_t)((buf[2] << 8) | buf[3]);
            *gz = (int16_t)((buf[4] << 8) | buf[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_mpu6886(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms (Ctrl+C to exit).\n");

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_accel(fd, &ax, &ay, &az) == 0 &&
            read_gyro(fd, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }

        usleep(50000);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

