#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0  0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATA_FORMAT 0x31

#define LED_PIN 17
#define IMPACT_THRESHOLD 2.5
#define SCALE_FACTOR 256.0
#define I2C_BUS 1
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} AccelerationData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID: %s\n", pigpio_error(devid));
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x00) < 0) {
        fprintf(stderr, "Error setting DATA_FORMAT\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error setting BW_RATE\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error setting POWER_CTL\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, AccelerationData *data) {
    char raw[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x = (int16_t)((raw[1] << 8) | raw[0]);
    y = (int16_t)((raw[3] << 8) | raw[2]);
    z = (int16_t)((raw[5] << 8) | raw[4]);

    data->x = (float)x / SCALE_FACTOR;
    data->y = (float)y / SCALE_FACTOR;
    data->z = (float)z / SCALE_FACTOR;
    return 0;
}

static float calculate_magnitude(AccelerationData data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

static void log_impact(AccelerationData data, float magnitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Impact: Magnitude = %.2f g, X = %.2f, Y = %.2f, Z = %.2f\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        AccelerationData data;
        if (read_acceleration(i2c_handle, &data) == 0) {
            float magnitude = calculate_magnitude(data);
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                gpioWrite(LED_PIN, 1);
                log_impact(data, magnitude);
                gpioDelay(LED_ON_DELAY_US);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            gpioDelay(POLL_DELAY_US);
        }
    }

    cleanup();
    return 0;
}

