#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Scaling factors for default ranges (+/- 2g, +/- 250 dps) */
#define ACCEL_SCALE 16384.0f  /* LSB/g */
#define GYRO_SCALE  131.0f    /* LSB/dps */

#define I2C_BUS 1
#define LOG_FILE "imu_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block at 0x%02X: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_imu(int handle) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (read_register(handle, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, ICM20602_WHO_AM_I);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (write_register(handle, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    if (write_register(handle, ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    if (write_register(handle, GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

static int read_imu_data(int handle, float *ax, float *ay, float *az,
                         float *gx, float *gy, float *gz) {
    uint8_t buf[6];

    /* Burst read 6 bytes of accelerometer data starting at ACCEL_XOUT_H */
    if (read_block(handle, ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]);

    /* Burst read 6 bytes of gyroscope data starting at GYRO_XOUT_H */
    if (read_block(handle, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_gx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_gy = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_gz = (int16_t)((buf[4] << 8) | buf[5]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return 0;
}

static void log_data(FILE *fp, float ax, float ay, float az,
                     float gx, float gy, float gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void) {
    int i2c_handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ICM20602_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    /* Initialize IMU */
    if (init_imu(i2c_handle) < 0) {
        fprintf(stderr, "IMU initialization failed\n");
        goto cleanup_i2c;
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening log file");
        goto cleanup_i2c;
    }
    fprintf(fp, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    /* Main loop */
    while (running) {
        float ax, ay, az, gx, gy, gz;
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(fp, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    rc = EXIT_SUCCESS;

    /* Cleanup */
    if (fp) {
        fclose(fp);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

