        close(fd);
        return EXIT_FAILURE;
    }

    printf("TMAG5273 magnetic field logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetic_field(fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading magnetic field data: %s\n", strerror(errno));
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

