#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x53
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define LOG_FILE        "freefall_log.csv"

#define REG_DEVID       0x00
#define REG_THRESH_FF   0x28
#define REG_TIME_FF     0x29
#define REG_INT_MAP    0x2F
#define REG_INT_ENABLE 0x2E
#define REG_POWER_CTL  0x2D
#define REG_DATA_FORMAT 0x31
#define REG_INT_SOURCE 0x30
#define REG_DATAX0     0x32

#define EXPECTED_DEVID 0xE5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg(fd, REG_DEVID, &devid) < 0) return -1;
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, EXPECTED_DEVID);
        return -1;
    }
    if (i2c_write_reg(fd, REG_DATA_FORMAT, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_THRESH_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg(fd, REG_TIME_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg(fd, REG_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_INT_ENABLE, 0x04) < 0) return -1;
    if (i2c_write_reg(fd, REG_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

