#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_A 0x28
#define OUTX_H_A 0x29
#define OUTY_L_A 0x2A
#define OUTY_H_A 0x2B
#define OUTZ_L_A 0x2C
#define OUTZ_H_A 0x2D

#define ACCEL_SCALE 0.061f
#define GYRO_SCALE 8.75f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define TIMEOUT_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) return -1;
    return 0;
}

static int read_regs(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (read_regs(WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X != 0x%02X). Sensor absent or wrong address.\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (write_reg(CTRL1_XL, 0x80) != 0) return -1;
    if (write_reg(CTRL2_G, 0x80) != 0) return -1;
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[6];
    if (read_regs(OUTX_L_A, buf, 6) != 0) return -1;
    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_gx = (int16_t)((buf[6] << 8) | buf[5]);
    int16_t raw_gy = (int16_t)((buf[8] << 8) | buf[7]);
    int16_t raw_gz = (int16_t)((buf[10] << 8) | buf[9]);
    data->accel_x = (float)raw_ax * ACCEL_SCALE;
    data->accel_y = (float)raw_ay * ACCEL_SCALE;
    data->accel_z = (float)raw_az * ACCEL_SCALE;
    data->gyro_x = (float)raw_gx * GYRO_SCALE;
    data->gyro_y = (float)raw_gy * GYRO_SCALE;
    data->gyro_z = (float)raw_gz * GYRO_SCALE;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const sensor_data_t *data) {
    static enum {IDLE, FREEFALL, IMPACT} state = IDLE;
    static struct timespec freefall_start, impact_start;
    static int in_freefall = 0;
    float mag = sqrtf(data->accel_x * data->accel_x + data->accel_y * data->accel_y + data->accel_z * data->accel_z);
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    if (mag < FREEFALL_THRESHOLD) {
        if (!in_freefall) {
            in_freefall = 1;
            freefall_start = now;
            state = FREEFALL;
        }
    } else {
        in_freefall = 0;
        if (state == FREEFALL && (now.tv_sec - freefall_start.tv_sec) < 1) {
            state = IMPACT;
            impact_start = now;
        }
    }
    if (state == IMPACT) {
        if ((now.tv_sec - impact_start.tv_sec) >= 1) {
            printf("Potential Impact Detected!\n");
            state = IDLE;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X.\n", LSM6DSR_ADDR);
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open motion_log.txt.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            detect_fall(&sensor_data);
        } else {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }
        gpioDelay(10000);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

