#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDRESS 0x69

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28

/* Expected WHO_AM_I value for L3G4200D */
#define WHO_AM_I_EXPECTED 0xD3

/* Sensitivity for +-250 dps range: 8.75 mdps/LSB = 114.285 dps/LSB */
#define SENSITIVITY 114.285f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_checked(int handle, uint8_t reg, uint8_t value, const char *label) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write failed (reg 0x%02X, val 0x%02X): rc=%d. Attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to write %s after %d attempts.\n", label, MAX_RETRIES);
    return -1;
}

static int i2c_read_block_checked(int handle, uint8_t reg, uint8_t *buf, uint32_t len, const char *label) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C block read failed (reg 0x%02X, len %u): rc=%d. Attempt %d/%d\n",
                reg, len, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to read %s after %d attempts.\n", label, MAX_RETRIES);
    return -1;
}

static int initialize_gyro(void) {
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X: %d\n", GYRO_ADDRESS, i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: got 0x%02X, expected 0x%02X. Sensor absent or wrong device.\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* CTRL_REG1: Normal mode, all axes enabled (0x0F) */
    if (i2c_write_checked(i2c_handle, CTRL_REG1, 0x0F, "CTRL_REG1") < 0) {
        return -1;
    }

    /* CTRL_REG4: +-250 dps full-scale range (0x00) */
    if (i2c_write_checked(i2c_handle, CTRL_REG4, 0x00, "CTRL_REG4") < 0) {
        return -1;
    }

    /* Allow sensor to settle after mode change */
    gpioDelay(50000); /* 50 ms */

    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    uint8_t buf[6];

    /* Read 6 bytes starting at OUT_X_L (0x28) in a single block */
    if (i2c_read_block_checked(i2c_handle, OUT_X_L, buf, 6, "gyro data block") < 0) {
        return -1;
    }

    /* L3G4200D is left-justified: shift right by 4 to get 12-bit value */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]) >> 4;
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]) >> 4;
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]) >> 4;

    data->x = (float)raw_x / SENSITIVITY;
    data->y = (float)raw_y / SENSITIVITY;
    data->z = (float)raw_z / SENSITIVITY;

    return 0;
}

static void log_data(const gyro_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    gyro_data_t gyro_data;

    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(&gyro_data);
        } else {
            fprintf(stderr, "Warning: Failed to read gyro data. Continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Info: Terminating gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

