    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    gyro_data_t gyro_data;

    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(&gyro_data);
        } else {
            fprintf(stderr, "Warning: Failed to read gyro data. Continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Info: Terminating gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
