}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately.     */
/* Returns 0 on success, -1 on write/flush error.                      */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor.                                              */
/* Returns 1 if a flame is detected (DO == 0), 0 if clear, -1 on error.*/
/* ------------------------------------------------------------------ */
static int read_flame_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value == PI_BAD_GPIO) {
        return -1;
    }
    return (value == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

