            if (log_event("Flame detected: NO") != 0) {
                ret = EXIT_FAILURE;
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup ----------------------------------------------------- */
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
        log_file = NULL;
    }

    gpioTerminate();
    return ret;
}

