#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x53
#define CSV_FILENAME   "vibration_log.csv"
#define SAMPLE_MS      100

/* D7S-0001 acceleration registers (LSB first, then MSB) */
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_axis(int fd, uint8_t lsb_reg, uint8_t msb_reg, int16_t *out)
{
    uint8_t lsb = 0, msb = 0;

    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, msb_reg, &msb) < 0)
        return -1;

    /* D7S-0001: LSB first, then MSB */
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (read_axis(fd, REG_X_LSB, REG_X_MSB, x) < 0)
        return -1;
    if (read_axis(fd, REG_Y_LSB, REG_Y_MSB, y) < 0)
        return -1;
    if (read_axis(fd, REG_Z_LSB, REG_Z_MSB, z) < 0)
        return -1;
    return 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm the sensor is present */
    uint8_t probe = 0;
    if (i2c_read_reg8(g_i2c_fd, REG_X_LSB, &probe) < 0) {
        fprintf(stderr, "D7S-0001 not detected at 0x%02X on %s\n",
                I2C_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "Timestamp,X,Y,Z\n");
        fflush(g_csv);
    }

    printf("Monitoring vibration (D7S-0001 @ 0x%02X) every %d ms. Ctrl+C to stop.\n",
           I2C_ADDR, SAMPLE_MS);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_sensor(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
        } else {
            char ts[32];
            get_iso8601_timestamp(ts, sizeof(ts));
            log_data(g_csv, ts, x, y, z);
            printf("%s  X=%d  Y=%d  Z=%d\n", ts, x, y, z);
        }

        /* Sleep SAMPLE_MS milliseconds, interruptible by signals */
        struct timespec ts_sleep = {
            .tv_sec  = SAMPLE_MS / 1000,
            .tv_nsec = (long)(SAMPLE_MS % 1000) * 1000000L
        };
        nanosleep(&ts_sleep, NULL);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

