#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_accelerometer(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x10) < 0) {
        fprintf(stderr, "Error setting standby mode: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000);
    if (i2c_write_reg(fd, CTRL_REG1, 0x11) < 0) {
        fprintf(stderr, "Error setting active mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 4;
    int16_t raw_y = (int16_t)(((uint16_t)buf[2] << 8) | buf[3]) >> 4;
    int16_t raw_z = (int16_t)(((uint16_t)buf[4] << 8) | buf[5]) >> 4;
    *x = raw_x;
    *y = raw_y;
    *z = raw_z;
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x;
    double y_g = (double)y;
    double z_g = (double)z;
    return atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (init_accelerometer(g_i2c_fd) < 0) {
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Monitoring for falls (threshold: %.1f degrees)...\n", TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accelerometer(g_i2c_fd, &x, &y, &z) < 0) {
            usleep(POLL_DELAY_US);
            continue;
        }
        double tilt = calculate_tilt_angle(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_fall(x, y, z);
            printf("Fall detected! Logged to %s\n", LOG_FILE);
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

