#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL354B Register Addresses */
#define ADXL354_REG_DEVID_AD   0x00
#define ADXL354_REG_PARTID     0x01
#define ADXL354_REG_XDATA      0x08
#define ADXL354_REG_YDATA      0x0B
#define ADXL354_REG_ZDATA      0x0E
#define ADXL354_REG_STATUS     0x04
#define ADXL354_REG_POWER_CTL  0x2D
#define ADXL354_REG_RESET      0x1F

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CS */

/* ADXL354B Constants */
#define ADXL354_PARTID_VALUE  0x1D
#define ADXL354_SENSITIVITY  0.0000039f  /* 3.9 microg/LSB for +-2g range */
#define ADXL354_RESET_CMD    0x52

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} accel_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* SPI read: returns 0 on success, -1 on failure                       */
/* ------------------------------------------------------------------ */
static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI write: returns 0 on success, -1 on failure                      */
/* ------------------------------------------------------------------ */
static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 3 bytes of acceleration data (X, Y, Z)                         */
/* ------------------------------------------------------------------ */
static int read_acceleration(accel_data_t *data) {
    uint8_t x_msb, x_lsb, x_p, y_msb, y_lsb, y_p, z_msb, z_lsb, z_p;

    if (spi_read_register(ADXL354_REG_XDATA, &x_msb) ||
        spi_read_register(ADXL354_REG_XDATA + 1, &x_lsb) ||
        spi_read_register(ADXL354_REG_XDATA + 2, &x_p))
        return -1;

    if (spi_read_register(ADXL354_REG_YDATA, &y_msb) ||
        spi_read_register(ADXL354_REG_YDATA + 1, &y_lsb) ||
        spi_read_register(ADXL354_REG_YDATA + 2, &y_p))
        return -1;

    if (spi_read_register(ADXL354_REG_ZDATA, &z_msb) ||
        spi_read_register(ADXL354_REG_ZDATA + 1, &z_lsb) ||
        spi_read_register(ADXL354_REG_ZDATA + 2, &z_p))
        return -1;

    /* 20-bit left-justified: sign-extend from bit 19 to bit 31 */
    int32_t x_raw = ((int32_t)x_msb << 12) | ((int32_t)x_lsb << 4) | ((int32_t)x_p >> 4);
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;

    int32_t y_raw = ((int32_t)y_msb << 12) | ((int32_t)y_lsb << 4) | ((int32_t)y_p >> 4);
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;

    int32_t z_raw = ((int32_t)z_msb << 12) | ((int32_t)z_lsb << 4) | ((int32_t)z_p >> 4);
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    data->x = (float)x_raw * ADXL354_SENSITIVITY;
    data->y = (float)y_raw * ADXL354_SENSITIVITY;
    data->z = (float)z_raw * ADXL354_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize SPI                                                      */
/* ------------------------------------------------------------------ */
static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize ADXL354B                                                 */
/* ------------------------------------------------------------------ */
static int initialize_adxl354(void) {
    uint8_t partid;

    /* Verify device presence */
    if (spi_read_register(ADXL354_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID_VALUE) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                partid, ADXL354_PARTID_VALUE);
        return -1;
    }

    /* Reset */
    if (spi_write_register(ADXL354_REG_RESET, ADXL354_RESET_CMD) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Clear STANDBY bit in POWER_CTL, wait for STABLE */
    if (spi_write_register(ADXL354_REG_POWER_CTL, 0x00) != 0)
        return -1;
    for (int i = 0; i < 100; i++) {
        uint8_t status;
        if (spi_read_register(ADXL354_REG_STATUS, &status) != 0)
            return -1;
        if (status & 0x01) break;
        gpioDelay(1000);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Sensor not ready after reset\n");
        return -1;
    }

    /* Set RUN bit to start measurement */
    if (spi_write_register(ADXL354_REG_POWER_CTL, 0x02) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static void log_data(const accel_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
            timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    accel_data_t accel_data;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (initialize_adxl354() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL354B vibration logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_acceleration(&accel_data) == 0) {
            log_data(&accel_data);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

