#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define X_GYRO   0x04
#define Y_GYRO   0x06
#define Z_GYRO   0x08
#define X_ACCL   0x0A
#define Y_ACCL   0x0C
#define Z_ACCL   0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCL_SCALE  0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: CPOL=1, CPHA=1 (active-high, sampled on trailing edge) */

/* Sampling interval */
#define SAMPLE_DELAY_US 10000 /* 10 ms -> ~100 Hz */

/* Global handles for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x_gyro, y_gyro, z_gyro;
    float x_accel, y_accel, z_accel;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * ADIS16362 SPI read protocol:
 *   Send [reg_addr | 0x80, 0x00]  (address with MSB set, dummy byte)
 *   Wait for conversion (~1 ms typical, adjust if needed).
 *   Send [0x00, 0x00]  (dummy bytes to clock out data).
 *   The 16-bit response is the register value.
 */
static int read_register(uint8_t reg_addr, int16_t *value) {
    char tx_buf[2], rx_buf[2];
    int ret;

    /* Phase 1: send address with MSB set */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed (addr phase): ret=%d\n", ret);
        return -1;
    }
    /* Small delay for conversion */
    gpioDelay(1000); /* 1 ms */

    /* Phase 2: dummy bytes to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed (data phase): ret=%d\n", ret);
        return -1;
    }

    /* ADIS16362 returns 16-bit data in little-endian order */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    int16_t raw_x_gyro, raw_y_gyro, raw_z_gyro;
    int16_t raw_x_accel, raw_y_accel, raw_z_accel;

    if (read_register(X_GYRO, &raw_x_gyro) != 0) return -1;
    if (read_register(Y_GYRO, &raw_y_gyro) != 0) return -1;
    if (read_register(Z_GYRO, &raw_z_gyro) != 0) return -1;
    if (read_register(X_ACCL, &raw_x_accel) != 0) return -1;
    if (read_register(Y_ACCL, &raw_y_accel) != 0) return -1;
    if (read_register(Z_ACCL, &raw_z_accel) != 0) return -1;

    data->x_gyro = (float)raw_x_gyro * GYRO_SCALE;
    data->y_gyro = (float)raw_y_gyro * GYRO_SCALE;
    data->z_gyro = (float)raw_z_gyro * GYRO_SCALE;
    data->x_accel = (float)raw_x_accel * ACCL_SCALE;
    data->y_accel = (float)raw_y_accel * ACCL_SCALE;
    data->z_accel = (float)raw_z_accel * ACCL_SCALE;

    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    fprintf(log_file, "%.6f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp,
            data->x_gyro, data->y_gyro, data->z_gyro,
            data->x_accel, data->y_accel, data->z_accel);
    fflush(log_file);
}

int main(void) {
    imu_data_t imu_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("IMU logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            log_data(&imu_data);
        } else {
            fprintf(stderr, "Failed to read IMU data, skipping log entry\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

