/*
 * KY-032 IR Obstacle Avoidance System (libgpiod v2)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 x2 on GPIO17 and GPIO27 (BCM)
 *          Active-low: 0 = obstacle detected, 1 = clear
 * Build:   gcc -Wall -Wextra -O2 -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO bank on Pi 3B+ (libgpiod >= 2.x) */
#define GPIO_PIN_17     17
#define GPIO_PIN_27     27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

