#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_PIN 8

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24
#define ADIS16266_REG_DEVICE_ID 0x00

#define ADIS16266_MSC_CTRL_DATA_READY 0x01
#define ADIS16266_MSC_CTRL_MODE_3 0x00

#define ADIS16266_DEVICE_ID_VALUE 0x1626

#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define GYRO_SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int adis16266_read_register(int fd, struct gpiod_line *cs_line, uint8_t reg_addr, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg_addr | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int adis16266_write_register(int fd, struct gpiod_line *cs_line, uint8_t reg_addr, uint16_t value) {
    uint8_t tx[3] = { (uint8_t)(reg_addr & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    return 0;
}

static int adis16266_init(int fd, struct gpiod_line *cs_line) {
    uint16_t device_id = 0;

    if (adis16266_read_register(fd, cs_line, ADIS16266_REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Error: Failed to read device ID (SPI bus error or sensor absent).\n");
        return -1;
    }

    if (device_id != ADIS16266_DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Invalid device ID: 0x%04X (expected 0x%04X).\n", device_id, ADIS16266_DEVICE_ID_VALUE);
        return -1;
    }

    uint16_t msc_ctrl = ADIS16266_MSC_CTRL_MODE_3;
    if (adis16266_write_register(fd, cs_line, ADIS16266_REG_MSC_CTRL, msc_ctrl) < 0) {
        fprintf(stderr, "Error: Failed to write MSC_CTRL register.\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(int fd, struct gpiod_line *cs_line, float *x_rate, float *y_rate, float *z_rate) {
    uint16_t x_raw = 0, y_raw = 0, z_raw = 0;

    if (adis16266_read_register(fd, cs_line, ADIS16266_REG_XGYRO_OUT, &x_raw) < 0) return -1;
    if (adis16266_read_register(fd, cs_line, ADIS16266_REG_YGYRO_OUT, &y_raw) < 0) return -1;
    if (adis16266_read_register(fd, cs_line, ADIS16266_REG_ZGYRO_OUT, &z_raw) < 0) return -1;

    *x_rate = (float)((int16_t)x_raw) * GYRO_SCALE_FACTOR;
    *y_rate = (float)((int16_t)y_raw) * GYRO_SCALE_FACTOR;
    *z_rate = (float)((int16_t)z_raw) * GYRO_SCALE_FACTOR;

    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = 1;

    struct sigaction sa = {
        .sa_handler = sigint_handler,
        .sa_flags = 0,
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    if (adis16266_init(spi_fd, cs_line) < 0) {
        fprintf(stderr, "Error: ADIS16266 initialization failed.\n");
        goto cleanup;
    }

    printf("ADIS16266 initialized. Reading gyroscope data every 100ms...\n");

    while (running) {
        float x_rate, y_rate, z_rate;

        if (read_gyro_data(spi_fd, cs_line, &x_rate, &y_rate, &z_rate) < 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data (SPI bus error).\n");
            break;
        }

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);
        usleep(100000);
    }

    ret = 0;

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

