#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I    0x0F
#define CTRL1_XL    0x10
#define CTRL2_G     0x11
#define STATUS_REG  0x1E
#define OUTX_L_G    0x22
#define OUTX_H_G    0x23
#define OUTY_L_G    0x24
#define OUTY_H_G    0x25
#define OUTZ_L_G    0x26
#define OUTZ_H_G    0x27
#define OUTX_L_XL   0x28
#define OUTX_H_XL   0x29
#define OUTY_L_XL   0x2A
#define OUTY_H_XL   0x2B
#define OUTZ_L_XL   0x2C
#define OUTZ_H_XL   0x2D

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivity values */
#define GYRO_SENSITIVITY 0.00875f  /* mdps/LSB for +-250 dps */
#define ACCEL_SENSITIVITY 0.000061f /* mg/LSB for +-2g */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_byte(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read error at reg 0x%02X: expected %u, got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;

    if (read_byte(handle, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Accelerometer: +-2g, 104 Hz -> 0x42 */
    if (write_byte(handle, CTRL1_XL, 0x42) != 0) {
        return -1;
    }
    /* Gyroscope: +-250 dps, 104 Hz -> 0x42 */
    if (write_byte(handle, CTRL2_G, 0x42) != 0) {
        return -1;
    }

    return 0;
}

static int read_sensor_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z) {
    uint8_t buf[12];

    if (read_burst(handle, OUTX_L_G, buf, sizeof(buf)) != 0) {
        return -1;
    }

    int16_t raw_gyro_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gyro_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gyro_z = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_accel_x = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_accel_y = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_accel_z = (int16_t)((buf[11] << 8) | buf[10]);

    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

int main(void) {
    int handle = -1;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X: %d\n",
                LSM6DSR_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr(handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        if (read_sensor_data(handle, &gyro_x, &gyro_y, &gyro_z,
                             &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f  |  Accel: X=%.2f, Y=%.2f, Z=%.2f\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

