#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to VDD -> 0x1D) */
#define FXOS8700_ADDRESS 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* CTRL_REG1: hybrid mode, 100 Hz ODR, no standby */
#define CTRL_REG1_VAL 0x0D
/* CTRL_REG2: full-scale +/-2g, no high-res */
#define CTRL_REG2_VAL 0x00
/* M_CTRL_REG1: hybrid mode, ODR matched to accel */
#define M_CTRL_REG1_VAL 0x1F
/* M_CTRL_REG2: auto-reset, auto-increment */
#define M_CTRL_REG2_VAL 0x20

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, expected %u, got %d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X, rc=%d)\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_block(handle, FXOS8700_WHO_AM_I, &who_am_i, 1) != 0) {
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, CTRL_REG1_VAL) != 0) return -1;
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, CTRL_REG2_VAL) != 0) return -1;
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, M_CTRL_REG1_VAL) != 0) return -1;
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, M_CTRL_REG2_VAL) != 0) return -1;

    return 0;
}

static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t data[12];
    if (i2c_read_block(handle, FXOS8700_OUT_X_MSB, data, sizeof(data)) != 0) {
        return -1;
    }

    /* 14-bit left-aligned accelerometer: shift right 2 to get 14-bit value */
    *ax = (int16_t)((data[0] << 8) | data[1]) >> 2;
    *ay = (int16_t)((data[2] << 8) | data[3]) >> 2;
    *az = (int16_t)((data[4] << 8) | data[5]) >> 2;

    /* 16-bit magnetometer */
    *mx = (int16_t)((data[6] << 8) | data[7]);
    *my = (int16_t)((data[8] << 8) | data[9]);
    *mz = (int16_t)((data[10] << 8) | data[11]);

    return 0;
}

int main(void) {
    int handle = -1;
    int16_t ax, ay, az, mx, my, mz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, FXOS8700_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, FXOS8700_ADDRESS, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 ready. Sampling every %d ms. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_US / 1000);

    while (g_running) {
        if (read_sensor_data(handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying next cycle.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

