#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DEVID 0x00
#define ADXL345_DEVID_VAL 0xE5
#define TILT_THRESHOLD 30.0
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "/var/log/tilt_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *ax, float *ay, float *az) {
    *ax = atan2((float)y, sqrt((float)x * x + (float)z * z)) * 180.0 / M_PI;
    *ay = atan2(-(float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
    *az = atan2((float)z, sqrt((float)x * x + (float)y * y)) * 180.0 / M_PI;
}

static void log_event(float ax, float ay, float az) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt event: X=%.2f, Y=%.2f, Z=%.2f\n", s, ax, ay, az);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Monitoring tilt... (Ctrl+C to exit)\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(100000);
            continue;
        }

        float ax, ay, az;
        calculate_tilt_angles(x, y, z, &ax, &ay, &az);

        if (fabs(ax) > TILT_THRESHOLD || fabs(ay) > TILT_THRESHOLD || fabs(az) > TILT_THRESHOLD) {
            log_event(ax, ay, az);
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

