#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms between samples */
#define WINDOW_SECONDS 5          /* sampling window per alert cycle */
#define SAMPLES_PER_WINDOW (WINDOW_SECONDS * 1000 / SAMPLE_INTERVAL_US) /* 500 */
#define DEFAULT_THRESHOLD 50      /* default alert threshold */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the pin reads LOW when no sound is present */
    if (gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed for GPIO %d.\n", SOUND_SENSOR_GPIO);
        /* Non-fatal: continue anyway */
    }

    return 0;
}

static int read_sound_level(void)
{
    return gpioRead(SOUND_SENSOR_GPIO);
}

static int count_high_readings(int *high_count)
{
    int count = 0;
    for (int i = 0; i < SAMPLES_PER_WINDOW; i++) {
        int level = read_sound_level();
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", SOUND_SENSOR_GPIO);
            return -1;
        }
        if (level == 1) {
            count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    *high_count = count;
    return 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
            return;
        }
    }
    /* Fallback if time functions fail */
    printf("[unknown-time] ");
}

static void check_threshold(int high_count, int threshold)
{
    if (high_count > threshold) {
        print_timestamp();
        printf("ALERT: Noise level exceeded threshold (%d high readings in %d s).\n",
               high_count, WINDOW_SECONDS);
    } else {
        print_timestamp();
        printf("Status: Noise level normal (%d high readings in %d s).\n",
               high_count, WINDOW_SECONDS);
    }
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        char *endptr = NULL;
        errno = 0;
        long val = strtol(argv[1], &endptr, 10);

        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || val < 0) {
            fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
            fprintf(stderr, "  threshold: minimum high readings per %d s window\n", WINDOW_SECONDS);
            fprintf(stderr, "  must be a non-negative integer.\n");
            return EXIT_FAILURE;
        }

        threshold = (int)val;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring noise levels on GPIO %d (KY-038). Threshold: %d high readings per %d s.\n",
           SOUND_SENSOR_GPIO, threshold, WINDOW_SECONDS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int high_count = 0;

        if (count_high_readings(&high_count) != 0) {
            /* Error already reported; terminate pigpio and exit */
            gpioTerminate();
            return EXIT_FAILURE;
        }

        check_threshold(high_count, threshold);

        /* Pause 1 second between monitoring windows */
        gpioDelay(1000000);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

