/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12V electromagnetic door locks (via TIP120 + 5V relay module) on:
 *   GPIO17 (Door A)  — active-HIGH: HIGH = unlocked
 *   GPIO27 (Door B)  — active-HIGH: HIGH = unlocked
 *
 * libgpiod C API (never wiringPi).  Compile:
 *   gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_DOOR_A  17
#define GPIO_DOOR_B  27
#define MIN_CODE     100000
#define MAX_CODE     999999
#define UNLOCK_SEC   5
#define LOG_FILE     "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
