#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HIGH_RES2 0x21
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes = read(fd, buf, len);
    if (bytes < 0 || (size_t)bytes != len) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_byte(fd, BH1750_CMD_OT_HIGH_RES2) < 0) {
        fprintf(stderr, "Error writing to BH1750: %s\n", strerror(errno));
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t data[2];
    if (i2c_read_bytes(fd, data, 2) < 0) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux = (float)raw * 5.0f / 6.0f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(fd, &lux) == 0) {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

