#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_MAG_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

#define LED_PIN 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000000ULL
#define PWM_DUTY_MAX 1000000000ULL

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calc_magnitude(int16_t z) {
    return sqrt((double)z * z);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC magnetometer.\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "lsm303_pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
    };

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config pwm_config = {
        .consumer = "lsm303_pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
    };

    if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
        fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
            usleep(100000);
            continue;
        }

        double magnitude = calc_magnitude(z);

        unsigned int duty_ns = (unsigned int)(magnitude / 100.0);
        if (duty_ns > PWM_DUTY_MAX) duty_ns = PWM_DUTY_MAX;

        struct gpiod_line_request_config pwm_config = {
            .consumer = "lsm303_pwm",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
        };

        if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
            fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
            break;
        }

        struct gpiod_line_request_config pwm_config2 = {
            .consumer = "lsm303_pwm",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
        };

        if (gpiod_line_request(led_line, &pwm_config2, 0) < 0) {
            fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
            break;
        }

        unsigned long long period_ns = PWM_PERIOD_NS;
        unsigned long long duty_ns = (unsigned long long)duty_ns;
        unsigned long long elapsed_ns = 0;
        unsigned long long target_ns = period_ns;

        while (running && elapsed_ns < period_ns) {
            unsigned long long step_ns = (target_ns > elapsed_ns + 100000000ULL) ? 100000000ULL : (target_ns - elapsed_ns);
            unsigned long long sleep_ns = step_ns;
            if (duty_ns > 0) {
                unsigned long long on_ns = elapsed_ns + step_ns;
                unsigned long long off_ns = on_ns + duty_ns;
                if (off_ns < target_ns) {
                    sleep_ns = off_ns - elapsed_ns;
                }
            }
            struct timespec ts = {
                .tv_sec = sleep_ns / 1000000000ULL,
                .tv_nsec = sleep_ns % 1000000000ULL
            };
            nanosleep(&ts, NULL);
            elapsed_ns += step_ns;
        }

        if (duty_ns > 0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

