    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "lsm303_pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
    };

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config pwm_config = {
        .consumer = "lsm303_pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
    };

    if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
        fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
            usleep(100000);
            continue;
        }

        double magnitude = calc_magnitude(z);

        unsigned int duty_ns = (unsigned int)(magnitude / 100.0);
        if (duty_ns > PWM_DUTY_MAX) duty_ns = PWM_DUTY_MAX;

        struct gpiod_line_request_config pwm_config = {
            .consumer = "lsm303_pwm",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
        };

        if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
            fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
            break;
        }

        struct gpiod_line_request_config pwm_config2 = {
            .consumer = "lsm303_pwm",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
        };

        if (gpiod_line_request(led_line, &pwm_config2, 0) < 0) {
            fprintf(stderr, "Failed to request PWM on GPIO line %d: %s\n", LED_PIN, strerror(errno));
            break;
        }

        unsigned long long period_ns = PWM_PERIOD_NS;
        unsigned long long duty_ns = (unsigned long long)duty_ns;
        unsigned long long elapsed_ns = 0;
        unsigned long long target_ns = period_ns;

        while (running && elapsed_ns < period_ns) {
            unsigned long long step_ns = (target_ns > elapsed_ns + 100000000ULL) ? 100000000ULL : (target_ns - elapsed_ns);
            unsigned long long sleep_ns = step_ns;
            if (duty_ns > 0) {
                unsigned long long on_ns = elapsed_ns + step_ns;
                unsigned long long off_ns = on_ns + duty_ns;
                if (off_ns < target_ns) {
                    sleep_ns = off_ns - elapsed_ns;
                }
            }
            struct timespec ts = {
                .tv_sec = sleep_ns / 1000000000ULL,
                .tv_nsec = sleep_ns % 1000000000ULL
            };
            nanosleep(&ts, NULL);
            elapsed_ns += step_ns;
        }

        if (duty_ns > 0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

