#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define HARD_IRON_WINDOW 100
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading magnetometer data (pigpio rc=%d)\n", rc);
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static void apply_hard_iron(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                            float *offset_x, float *offset_y, float *offset_z) {
    *offset_x = (float)raw_x;
    *offset_y = (float)raw_y;
    *offset_z = (float)raw_z;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (pigpio rc=%d)\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0 ||
        write_reg(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0 ||
        write_reg(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t raw_x, raw_y, raw_z;
    float hard_iron_x = 0.0f, hard_iron_y = 0.0f, hard_iron_z = 0.0f;
    int hard_iron_index = 0;
    int samples_collected = 0;

    while (running) {
        if (read_magnetometer(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            samples_collected++;
            if (samples_collected >= HARD_IRON_WINDOW) {
                apply_hard_iron(raw_x, raw_y, raw_z, &hard_iron_x, &hard_iron_y, &hard_iron_z);
                hard_iron_index = (hard_iron_index + 1) % HARD_IRON_WINDOW;
            }
        } else {
            samples_collected = 0;
            hard_iron_index = 0;
        }

        if (samples_collected >= HARD_IRON_WINDOW) {
            float corrected_x = hard_iron_x;
            float corrected_y = hard_iron_y;
            float corrected_z = hard_iron_z;
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
            fflush(stdout);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

