/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * I2C:  /dev/i2c-1, address 0x1D (SA0 tied high)
 * INT1: GPIO23 (BCM 23, physical pin 16) — rising edge triggers dump of
 *        the last 10 samples from the circular buffer.
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D register definitions ---- */
#define LSM303D_WHO_AM_I   0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1  0x20
#define LSM303D_CTRL_REG4  0x23
#define LSM303D_INT1_CFG   0x30
#define LSM303D_INT1_SRC   0x31
#define LSM303D_OUT_X_L_A  0x28

/* ---- Configuration constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define LSM303D_ADDR       0x1D
#define GPIO_CHIP          "gpiochip0"
#define GPIO_INT1_LINE     23          /* BCM 23 */
#define BUFFER_SIZE        64
#define SAMPLE_PERIOD_US   10000       /* 10 ms  -> ~100 Hz polling */
#define INT1_THRESHOLD_MG  2000        /* 2 g full-scale, 12-bit */
#define INT1_THRESHOLD_REG (INT1_THRESHOLD_MG / 16)   /* 12-bit */

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1 = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    int r = i2c_smbus_read_byte_data(fd, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write 0x%02X=0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) {
        fprintf(stderr, "I2C block read 0x%02X (%d bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D initialization ---- */
static int lsm303d_init(void)
{
    uint8_t who;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &who) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, XYZ axes enabled (0x57) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* CTRL_REG4: +-2g full-scale, high-resolution disabled (0x00) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4, 0x00) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* INT1_CFG: any-axis threshold interrupt, active-high, latch off (0x2A) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_CFG, 0x2A) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* INT1_SRC: clear any pending interrupts */
    if (i2c_read_reg8(g_i2c_fd, LSM303D_INT1_SRC, &who) == 0) {
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_INT1_SRC, 0x01);
    }

    return 0;
}

/* ---- Acceleration read ---- */
static int read_acceleration(accel_sample_t *sample)
{
    uint8_t raw[6];

    if (i2c_read_block(g_i2c_fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    /* LSM303D is little-endian: [X_L, X_H, Y_L, Y_H, Z_L, Z_H] */
    sample->x = (int16_t)((raw[1] << 8) | raw[0]);
    sample->y = (int16_t)((raw[3] << 8) | raw[2]);
    sample->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf)
{
    memset(buf, 0, sizeof(*buf));
}

static void buffer_add(circular_buffer_t *buf, accel_sample_t s)
{
    buf->data[buf->head] = s;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf, int n)
{
    if (n > buf->count)
        n = buf->count;
    if (n <= 0) {
        printf("No samples available.\n");
        return;
    }
    printf("--- Last %d samples ---\n", n);
    int start = (buf->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] X=%6d  Y=%6d  Z=%6d  mg\n",
               idx,
               (int)buf->data[idx].x,
               (int)buf->data[idx].y,
               (int)buf->data[idx].z);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1) {
        gpiod_line_release(g_int1);
        g_int1 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    g_int1 = gpiod_chip_get_line(g_chip, GPIO_INT1_LINE);
    if (!g_int1) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_INT1_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1, "lsm303d_int1") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (lsm303d_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    circular_buffer_t ring;
    buffer_init(&ring);

    printf("LSM303D monitoring started.  INT1 on GPIO23.  Ctrl-C to exit.\n");

    while (g_running) {
        accel_sample_t sample;

        if (read_acceleration(&sample) < 0) {
            /* I2C error: warn and keep going */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        buffer_add(&ring, sample);

        /* Check for rising-edge interrupt event */
        while (gpiod_line_event_wait(g_int1, NULL) > 0) {
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(g_int1, &ev) == 0) {
                if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    printf("INT1 rising edge detected — dumping last 10 samples...\n");
                    buffer_dump(&ring, 10);
                }
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

