#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define CHIP_NAME      "gpiochip0"
#define CONSUMER       "reciprocating_actuator"
#define DELAY_MS       500

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry on signal interruption */
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SOLENOID_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SOLENOID_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(SOLENOID_1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(SOLENOID_2_PIN)");
        goto cleanup;
    }

    /* Ensure no solenoid is energized at startup */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(SOLENOID_1_PIN)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(SOLENOID_2_PIN)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(SOLENOID_1_PIN)");
            goto cleanup;
        }
        if (sleep_ms(DELAY_MS) < 0) {
            perror("nanosleep");
            goto cleanup;
        }

        if (!running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(SOLENOID_1_PIN)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(SOLENOID_2_PIN)");
            goto cleanup;
        }
        if (sleep_ms(DELAY_MS) < 0) {
            perror("nanosleep");
            goto cleanup;
        }

        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(SOLENOID_2_PIN)");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* De-energize both solenoids and release lines */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

