#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define SERIAL_PORT_1 "/dev/serial0"
#define SERIAL_PORT_2 "/dev/serial1"
#define BAUD_RATE B9600
#define EXPECTED_CODE "123456"
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_US 2000000
#define POLL_DELAY_US 100000
#define BUF_SIZE 256

static volatile sig_atomic_t running = 1;
static int serial_fd1 = -1;
static int serial_fd2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial_port(const char *port, int *fd) {
    int fd_tmp = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd_tmp < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd_tmp, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd_tmp);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd_tmp, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr on %s: %s\n", port, strerror(errno));
        close(fd_tmp);
        return -1;
    }
    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;
    if (tcsetattr(fd_tmp, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr on %s: %s\n", port, strerror(errno));
        close(fd_tmp);
        return -1;
    }
    *fd = fd_tmp;
    return 0;
}

static int read_serial_port(int fd, char *buf, size_t buf_size, int timeout_sec) {
    size_t total = 0;
    time_t start = time(NULL);
    while (total < buf_size - 1) {
        if (!running) return -1;
        if (difftime(time(NULL), start) >= timeout_sec) return -1;
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            fprintf(stderr, "Error reading %s: %s\n", SERIAL_PORT_1, strerror(errno));
            return -1;
        }
        if (n == 0) continue;
        if (ch == '\n') {
            buf[total] = '\0';
            return 0;
        }
        if (ch >= '0' && ch <= '9') {
            buf[total++] = ch;
        } else {
            total = 0;
        }
    }
    buf[total] = '\0';
    return 0;
}

static int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != strlen(code2)) return 0;
    for (int i = 0; i < (int)strlen(code1); i++) {
        if ((unsigned char)code1[i] != (unsigned char)code2[i]) return 0;
    }
    return 1;
}

static void unlock_doors(void) {
    if (gpioWrite(LOCK_GPIO_1, 1) < 0) {
        fprintf(stderr, "Error unlocking lock 1\n");
        return;
    }
    if (gpioWrite(LOCK_GPIO_2, 1) < 0) {
        fprintf(stderr, "Error unlocking lock 2\n");
        gpioWrite(LOCK_GPIO_1, 0);
        return;
    }
    gpioDelay(UNLOCK_DURATION_US);
    if (gpioWrite(LOCK_GPIO_1, 0) < 0) {
        fprintf(stderr, "Error relocking lock 1\n");
    }
    if (gpioWrite(LOCK_GPIO_2, 0) < 0) {
        fprintf(stderr, "Error relocking lock 2\n");
    }
}

static void cleanup(void) {
    gpioWrite(LOCK_GPIO_1, 0);
    gpioWrite(LOCK_GPIO_2, 0);
    if (serial_fd1 >= 0) { close(serial_fd1); serial_fd1 = -1; }
    if (serial_fd2 >= 0) { close(serial_fd2); serial_fd2 = -1; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(LOCK_GPIO_1, PI_OUTPUT) < 0 || gpioSetMode(LOCK_GPIO_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
