                code1_idx = 0;
            }
        } else if (code1_idx > 0) {
            printf("Code 1 timeout\n");
            code1_idx = 0;
        }

        if (read_serial_port(serial_fd2, code2_buf, sizeof(code2_buf), TIMEOUT_SEC) == 0) {
            if (code2_idx < 6) {
                code2_buf[code2_idx++] = '\0';
                code2_start = time(NULL);
            } else if (code2_idx == 6 && strcmp(code2_buf, EXPECTED_CODE) == 0) {
                printf("Code 2 correct: %s\n", code2_buf);
