#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define STRIKE_MS    1000
#define POLL_MS      50
#define FAILSAFE_S   10

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

int main(void) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_msg(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_msg(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_msg(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_msg(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_msg(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_msg(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "Door strike controller started (PIR=GPIO%d, Relay=GPIO%d)", PIR_PIN, RELAY_PIN);

    time_t last_motion_time = 0;

    while (running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            log_msg(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            usleep(POLL_MS * 1000);
            continue;
        }

        time_t now = time(NULL);

        if (pir_val == 1) {
            if (last_motion_time == 0) {
                last_motion_time = now;
                log_msg(LOG_INFO, "Motion detected");
            } else if (difftime(now, last_motion_time) >= FAILSAFE_S) {
                log_msg(LOG_WARNING, "Potential PIR malfunction: sensor HIGH for >%d seconds", FAILSAFE_S);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    log_msg(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                } else {
                    log_msg(LOG_INFO, "Relay de-energized as failsafe");
                }
                break;
            }

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_msg(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
            } else {
                log_msg(LOG_INFO, "Relay energized (strike)");
            }

            for (int i = 0; i < STRIKE_MS / POLL_MS && running; i++) {
                usleep(POLL_MS * 1000);
            }

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_msg(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
            } else {
                log_msg(LOG_INFO, "Relay de-energized");
            }
            last_motion_time = now;
        } else {
            if (last_motion_time != 0) {
                last_motion_time = 0;
                log_msg(LOG_INFO, "Motion ended");
            }
            usleep(POLL_MS * 1000);
        }
    }

    if (gpiod_line_set_value(relay_line, 0) < 0) {
        log_msg(LOG_ERR, "Failed to reset relay to LOW on shutdown: %s", strerror(errno));
    }
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    log_msg(LOG_INFO, "Door strike controller stopped");
    closelog();
    return EXIT_SUCCESS;
}

