#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_TIME_SEC 300
#define PAUSE_TIME_SEC 60

#define TIMER_ID 0

static volatile sig_atomic_t program_running = 1;

static const int relay_gpios[4] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            log_message(LOG_ERR, "Failed to set GPIO mode for relay");
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            log_message(LOG_ERR, "Failed to initialize relay to OFF state");
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void activate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        log_message(LOG_ERR, "Failed to activate relay");
        return;
    }
    char message[128];
    snprintf(message, sizeof(message), "Relay on GPIO %d activated", gpio_pin);
    log_message(LOG_INFO, message);
}

static void deactivate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        log_message(LOG_ERR, "Failed to deactivate relay");
        return;
    }
    char message[128];
    snprintf(message, sizeof(message), "Relay on GPIO %d deactivated", gpio_pin);
    log_message(LOG_INFO, message);
}

static void timer_callback(int timer_id, void *user_data) {
    (void)timer_id;
    (void)user_data;

    static int current_relay = 0;
    static int current_action = 0;
    static time_t last_action_time = 0;

    time_t now = time(NULL);

    if (current_action == 0) {
        if (now - last_action_time >= PAUSE_TIME_SEC) {
            current_action = 1;
            last_action_time = now;
        }
    } else if (current_action == 1) {
        if (now - last_action_time >= RELAY_ON_TIME_SEC) {
            current_action = 2;
            last_action_time = now;
        }
    } else {
        current_relay = (current_relay + 1) % 4;
        current_action = 0;
        last_action_time = now;
    }

    int gpio_pin = relay_gpios[current_relay];

    switch (current_action) {
        case 1:
            activate_relay(gpio_pin);
            break;
        case 2:
            deactivate_relay(gpio_pin);
            break;
        default:
            break;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (gpioSetTimerFuncEx(TIMER_ID, 60, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set up timer function");
        gpioTerminate();
        return 1;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Irrigation system shutting down");

    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_gpios[i], 1);
    }

    gpioTerminate();
    return 0;
}

