#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B

#define ACCEL_SCALE 16384.0f

#define TIMER_PERIOD_NS 10000000L  /* 100 Hz */

typedef struct {
    float x, y, z;
} accel_data_t;

static accel_data_t accel_buffer[64];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    struct timespec ts = {0, TIMER_PERIOD_NS};
    nanosleep(&ts, NULL);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(void) {
    if (i2c_write_reg(REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(REG_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(accel_data_t *d) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
    d->x = (float)rx / ACCEL_SCALE;
    d->y = (float)ry / ACCEL_SCALE;
    d->z = (float)rz / ACCEL_SCALE;
    return 0;
}

static void store_data(const accel_data_t *d) {
    accel_buffer[buffer_index] = *d;
    buffer_index = (buffer_index + 1) % 64;
    if (buffer_count < 64) buffer_count++;
}

static int write_sysfs(const char *path, const char *val) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror(path); return -1; }
    if (write(fd, val, strlen(val)) < 0) { perror(path); close(fd); return -1; }
    close(fd);
    return 0;
}

static int read_sysfs(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror(path); return -1; }
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) { perror(path); return -1; }
    buf[n] = '\0';
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    remove("/sys/kernel/mpu6050_accel/latest");
    remove("/sys/kernel/mpu6050_accel/buffer_size");
    remove("/sys/kernel/mpu6050_accel/sample_rate");
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(i2c_fd); return 1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        close(i2c_fd); return 1;
    }

    if (mkdir("/sys/kernel/mpu6050_accel", 0777) < 0 && errno != EEXIST) {
        perror("mkdir"); close(i2c_fd); return 1;
    }

    char buf[64];
    snprintf(buf, sizeof(buf), "%d", 100);
    write_sysfs("/sys/kernel/mpu6050_accel/sample_rate", buf, 0);
    snprintf(buf, sizeof(buf), "%d", 64);
    write_sysfs("/sys/kernel/mpu6050_accel/buffer_size", buf, 0);

    struct sigaction sh = {0};
    sh.sa_flags = SA_SIGINFO;
    sh.sa_sigaction = timer_handler;
    sigemptyset(&sh.sa_mask);
    sh.sa_restorer = NULL;
    sigaction(SIGRTMIN, &sh, NULL);

    if (timer_create(CLOCK_MONOTONIC, &sh, &timer_id) < 0) {
        perror("timer_create"); cleanup(); return 1;
    }
    if (timer_settime(timer_id, 0, &ts, NULL) < 0) {
        perror("timer_settime"); cleanup(); return 1;
    }

    while (running) {
        accel_data_t d;
        if (read_accel(&d) < 0) {
            fprintf(stderr, "Read error, continuing\n");
            continue;
        }
        store_data(&d);
    }

    timer_delete(timer_id);
    cleanup();
    return 0;
}

