#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "smart_lighting"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int intervals[NUM_RELAYS] = {2, 3, 5, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static bool running = true;

static void signal_handler(int sig) {
    (void)sig;
    running = false;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void toggle_relay(int index) {
    int current = gpiod_line_get_value(lines[index]);
    if (current < 0) {
        fprintf(stderr, "Failed to read GPIO line %u: %s\n", relay_pins[index], strerror(errno));
        return;
    }
    if (gpiod_line_set_value(lines[index], !current) < 0) {
        fprintf(stderr, "Failed to toggle GPIO line %u: %s\n", relay_pins[index], strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec last_time[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        last_time[i].tv_sec = 0;
        last_time[i].tv_nsec = 0;
    }

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                continue;
            }

            long elapsed_ns = (now.tv_sec - last_time[i].tv_sec) * 1000000000L + (now.tv_nsec - last_time[i].tv_nsec);
            if (elapsed_ns >= (long)intervals[i] * 1000000000L) {
                toggle_relay(i);
                last_time[i] = now;
            }
        }
        struct timespec sleep_time = {0, 100000000}; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

