#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define ALARM_DURATION_MS 3000
#define POLL_INTERVAL_MS 100
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set relay GPIO %d HIGH\n", gpio);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set relay GPIO %d LOW\n", gpio);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    int relay_active = 0;

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_GPIO);
        if (sound_level < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", SOUND_SENSOR_GPIO);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (sound_level == 1 && last_state == 0) {
            printf("Sound detected! Activating alarm.\n");

            if (activate_relay(RELAY_GPIO, ALARM_DURATION_MS) != 0) {
                fprintf(stderr, "Relay activation failed.\n");
            }

            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log timestamp.\n");
            }

            relay_active = 1;
            gpioDelay(POLL_INTERVAL_MS * 1000);
        } else if (sound_level == 0 && last_state == 1 && relay_active) {
            relay_active = 0;
            printf("Sound level returned to normal.\n");
        }

        last_state = sound_level;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

