#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity for default +-250 dps range
#define GYRO_SENSITIVITY 131.0f

// Circular Buffer Size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;
static float angular_velocity_threshold = 50.0f;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication using Linux I2C user-space API
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read raw gyroscope data from the MPU-6050
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buf[6];

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axis)
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (Big Endian)
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Process raw gyroscope data and convert to degrees per second
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    gyro_data_t data;
    data.x = (float)gyro_x / GYRO_SENSITIVITY;
    data.y = (float)gyro_y / GYRO_SENSITIVITY;
    data.z = (float)gyro_z / GYRO_SENSITIVITY;

    add_to_buffer(&gyro_buffer, data);
    check_threshold(data);
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if the angular velocity exceeds the threshold
void check_threshold(gyro_data_t data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > angular_velocity_threshold) {
        printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    // Initialize I2C communication
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify device identity
    uint8_t who_am_i = 0;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I_VAL, who_am_i);
        cleanup();
        return 1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t pwr_mgmt_1 = 0;
    if (read(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        fprintf(stderr, "Error reading PWR_MGMT_1 register: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    pwr_mgmt_1 &= ~(1 << 6); // Clear sleep bit
    if (write(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    usleep(100000); // Wait 100ms for sensor to stabilize

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Gyroscope data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            process_gyro_data(gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }
        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

