#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define RESPONSE_LEN 9
#define READ_TIMEOUT_MS 1000
#define INIT_CMD_LEN 9

static const uint8_t init_cmd[INIT_CMD_LEN] = {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79};

static volatile sig_atomic_t g_running = 1;
static int g_uart_handle = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

static void log_error(const char *msg) {
    if (!g_err_fp) return;
    struct timespec ts;
