#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HMC5883L I2C address (A0=A1=GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_START 0x03

/* GPIO pin for alert output */
#define ALERT_PIN 17

/* Target heading (degrees) */
#define TARGET_HEADING 90.0

/* Hard-iron offsets (adjust per calibration) */
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

/* Function prototypes */
static int  init_hmc5883l(void);
static int  read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
static float calculate_heading(int16_t x, int16_t y);
static void add_to_buffer(CircularBuffer *cb, float value);
static float get_average_heading(const CircularBuffer *cb);
static void signal_handler(int sig);
static void cleanup(void);

/* Initialize the HMC5883L magnetometer */
static int init_hmc5883l(void) {
    /* CONFIG_A: 8-average, 15 Hz output rate, normal measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }

    /* CONFIG_B: 1.3 Gauss gain */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }

    /* MODE: Continuous measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of magnetometer data in a single burst transaction */
static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    /* Set register pointer to 0x03 (DATA_START) */
    if (i2cWriteByte(i2c_handle, HMC5883L_DATA_START) < 0) {
        fprintf(stderr, "Error setting data register pointer\n");
        return -1;
    }

    /* Read 6 bytes: X MSB, X LSB, Z MSB, Z LSB, Y MSB, Y LSB */
    int bytes_read = i2cReadDevice(i2c_handle, data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading magnetometer data (read %d bytes)\n", bytes_read);
        return -1;
    }

    /* HMC5883L outputs data MSB first */
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

/* Calculate heading in degrees from raw X and Y values */
static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

/* Add a value to the circular buffer */
static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

/* Calculate the average of the values in the circular buffer */
static float get_average_heading(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1E */
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize HMC5883L */
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", ALERT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    /* Initialize circular buffer */
    heading_buffer.head = 0;
    heading_buffer.count = 0;

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HMC5883L heading monitor started. Target heading: %.1f degrees\n", TARGET_HEADING);

    int16_t x, y, z;
    float heading;
    float compensated_heading;
    bool alert_active = false;

    while (!terminate) {
        if (read_magnetometer(&x, &y, &z) == 0) {
            heading = calculate_heading(x, y);

            /* Hard-iron compensation */
            compensated_heading = heading - HARD_IRON_X;

            /* Check if heading deviates significantly from target */
            if (fabsf(compensated_heading - TARGET_HEADING) > 10.0f) {
                if (!alert_active) {
                    gpioWrite(ALERT_PIN, 1);
                    alert_active = true;
                    printf("Alert: Heading %.2f deviates from target %.2f\n",
                           compensated_heading, TARGET_HEADING);
                }
            } else {
                if (alert_active) {
                    gpioWrite(ALERT_PIN, 0);
                    alert_active = false;
                    printf("Alert cleared: Heading %.2f close to target %.2f\n",
                           compensated_heading, TARGET_HEADING);
                }
            }

            add_to_buffer(&heading_buffer, compensated_heading);
            float avg = get_average_heading(&heading_buffer);
            printf("Heading: %.2f, Average: %.2f\n", compensated_heading, avg);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

