#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN    17
#define GREEN_RELAY_PIN  27
#define BLUE_RELAY_PIN   22

#define BH1750_ADDR      0x23
#define BH1750_CONT_HRES 0x10
#define BH1750_CONV_MS   120

#define LOG_FILE         "lighting_log.txt"
#define I2C_DEV          "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0)
        return -1;
    usleep(BH1750_CONV_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_relay(struct gpiod_line *line, int pin, int state) {
    if (gpiod_line_set_value(line, state) < 0)
        fprintf(stderr, "Failed to set GPIO%d: %s\n", pin, strerror(errno));
}

static void control_relays(float lux, struct gpiod_line *r,
                           struct gpiod_line *g, struct gpiod_line *b) {
    if (lux < 50.0f)
        set_relay(r, RED_RELAY_PIN, 1);
    else if (lux < 150.0f)
        set_relay(g, GREEN_RELAY_PIN, 1);
    else if (lux < 300.0f)
        set_relay(b, BLUE_RELAY_PIN, 1);
    else
        set_relay(r, RED_RELAY_PIN, 0);
    set_relay(g, GREEN_RELAY_PIN, 0);
    set_relay(b, BLUE_RELAY_PIN, 0);
}

static void log_data(FILE *fp, float lux, int r_on, int g_on, int b_on) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, R:%d G:%d B:%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, r_on, g_on, b_on);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *r_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    struct gpiod_line *g_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    struct gpiod_line *b_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!r_line || !g_line || !b_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(r_line, "smart_light", 0) < 0 ||
        gpiod_line_request_output(g_line, "smart_light", 0) < 0 ||
        gpiod_line_request_output(b_line, "smart_light", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        gpiod_line_release(r_line);
        gpiod_line_release(g_line);
        gpiod_line_release(b_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        gpiod_line_release(r_line);
        gpiod_line_release(g_line);
        gpiod_line_release(b_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        close(fd);
        gpiod_line_release(r_line);
        gpiod_line_release(g_line);
        gpiod_line_release(b_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        gpiod_line_release(r_line);
        gpiod_line_release(g_line);
        gpiod_line_release(b_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; turning off all relays.\n");
            set_relay(r_line, RED_RELAY_PIN, 0);
            set_relay(g_line, GREEN_RELAY_PIN, 0);
            set_relay(b_line, BLUE_RELAY_PIN, 0);
        } else {
            control_relays(lux, r_line, g_line, b_line);
            int r_on = gpiod_line_get_value(r_line);
            int g_on = gpiod_line_get_value(g_line);
            int b_on = gpiod_line_get_value(b_line);
            log_data(log_fp, lux, r_on, g_on, b_on);
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    set_relay(r_line, RED_RELAY_PIN, 0);
    set_relay(g_line, GREEN_RELAY_PIN, 0);
    set_relay(b_line, BLUE_RELAY_PIN, 0);
    fclose(log_fp);
    close(fd);
    gpiod_line_release(r_line);
    gpiod_line_release(g_line);
    gpiod_line_release(b_line);
    gpiod_chip_close(chip);
    return 0;
}

