#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define DISTANCE_THRESHOLD 50
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int control_motor(int distance, int *pwm_out) {
    int duty = (int)(((float)(MAX_DISTANCE - distance) /
                     (MAX_DISTANCE - MIN_DISTANCE)) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (distance < DISTANCE_THRESHOLD) {
        if (safe_write(MOTOR_A_IN1, 1) < 0 || safe_write(MOTOR_A_IN2, 0) < 0 ||
            safe_write(MOTOR_B_IN3, 1) < 0 || safe_write(MOTOR_B_IN4, 0) < 0)
            return -1;
        if (safe_pwm(MOTOR_A_IN2, duty) < 0 || safe_pwm(MOTOR_B_IN4, duty) < 0)
            return -1;
    } else {
        if (safe_write(MOTOR_A_IN1, 0) < 0 || safe_write(MOTOR_A_IN2, 0) < 0 ||
            safe_write(MOTOR_B_IN3, 0) < 0 || safe_write(MOTOR_B_IN4, 0) < 0)
            return -1;
    }
    *pwm_out = duty;
    return 0;
}

static void stop_motors(void) {
    safe_write(MOTOR_A_IN1, 0);
    safe_write(MOTOR_A_IN2, 0);
    safe_write(MOTOR_B_IN3, 0);
    safe_write(MOTOR_B_IN4, 0);
    safe_pwm(MOTOR_A_IN2, 0);
    safe_pwm(MOTOR_B_IN4, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int distance = 20;
        int pwm_a = 0, pwm_b = 0;

        if (control_motor(distance, &pwm_a) < 0) {
            fprintf(stderr, "Error: motor A control failed\n");
            break;
        }
        if (control_motor(distance, &pwm_b) < 0) {
            fprintf(stderr, "Error: motor B control failed\n");
            break;
        }

        usleep(100000);
    }

    stop_motors();
    gpioTerminate();
    return EXIT_SUCCESS;
}

