static int read_mpu6050(int fd, float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    uint8_t buf[14];
    if (i2c_read_regs(fd, 0x3B, buf, sizeof(buf)) < 0) return -1;
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]);
    /* Temperature compensation (simplified) */
    static float off_ax = 0, off_ay = 0, off_az = 0;
    off_ax += raw_ax; off_ay += raw_ay; off_az += raw_az;
    float ax = (float)(raw_ax - off_ax) / 16384.0f;
    float ay = (float)(raw_ay - off_ay) / 16384.0f;
    float az = (float)(raw_az - off_az) / 16384.0f;
    int16_t raw_gx = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_gy = (int16_t)((buf[10] << 8) | buf[11]);
    int16_t raw_gz = (int16_t)((buf[12] << 8) | buf[13]);
    *gx = (float)(raw_gx - 128) / 131.0f;
    *gy = (float)(raw_gy - 128) / 131.0f;
    *gz = (float)(raw_gz - 128) / 131.0f;
    return 0;
}

static int set_servo_angle(int pwm_fd, int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_us = SERVO_MIN_US + (int)((float)angle / 180.0f * (SERVO_MAX_US - SERVO_MIN_US));
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int period_fd = open(path, O_WRONLY);
    if (period_fd < 0) { perror("open period"); return -1; }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int duty_fd = open(path, O_WRONLY);
    if (duty_fd < 0) { perror("open duty"); close(period_fd); return -1; }
    if (ioctl(period_fd, I_PIODW, &PWM_PERIOD_NS) < 0) { perror("ioctl period"); goto cleanup; }
    if (ioctl(duty_fd, I_PIODW, &pulse_us * 1000) < 0) { perror("ioctl duty"); goto cleanup; }
    close(duty_fd);
    close(period_fd);
    return 0;
cleanup:
    close(duty_fd);
    close(period_fd);
    return -1;
}

static int log_data(FILE *fp, float pitch, float roll, int servo_pos) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_pos) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) { perror("ioctl slave"); close(i2c_fd); return 1; }
    if (init_mpu6050(i2c_fd) < 0) { fprintf(stderr, "MPU6050 init failed\n"); close(i2c_fd); return 1; }

    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int pwm_exported = access(pwm_path, F_OK);
    if (pwm_exported == -1 && errno != ENOENT) { perror("access pwm export"); close(i2c_fd); return 1; }
    if (pwm_exported == 0) {
        snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
        int fd = open(pwm_path, O_WRONLY);
        if (fd < 0) { perror("open pwm"); close(i2c_fd); return 1; }
        if (ioctl(fd, I_PIODW, &PWM_PERIOD_NS) < 0) { perror("ioctl pwm period"); close(fd); close(i2c_fd); return 1; }
        close(fd);
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen log"); close(i2c_fd); return 1; }

    while (running) {
        float ax, ay, az, gx, gy, gz;
        if (read_mpu6050(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Sensor read error\n");
            usleep(100000);
            continue;
        }
        float pitch = atan2f(ay, az) * 180.0f / M_PI;
        float roll = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / M_PI;
        int servo_pos = (int)(pitch * 1.5f);
        if (servo_pos < 0) servo_pos = 0;
        if (servo_pos > 180) servo_pos = 180;
        if (set_servo_angle(PWM_CHANNEL, servo_pos) < 0) {
            fprintf(stderr, "Servo set error\n");
        }
        if (log_data(log_fp, pitch, roll, servo_pos) < 0) {
            fprintf(stderr, "Log write error\n");
        }
        usleep(50000);
    }

    set_servo_angle(PWM_CHANNEL, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

