#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define TRANSITION_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int relay_pins[], int *schedule[], int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    *num_entries = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        int hour, minute, second, relay_num;
        char state[16];

        if (sscanf(line, "%d:%d:%d,%d,%15s", &hour, &minute, &second, &relay_num, state) == 5) {
            if (relay_num >= 0 && relay_num < NUM_RELAYS) {
                schedule[*num_entries] = relay_num;
                (*num_entries)++;
            } else {
                fprintf(stderr, "Invalid relay number in schedule: %d\n", relay_num);
                fclose(fp);
                return -1;
            }
        } else {
            fprintf(stderr, "Invalid format in schedule: %s", line);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

static int validate_schedule(int schedule[], int num_entries) {
    if (num_entries == 0) return 0;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        perror("localtime failed");
        return -1;
    }

    for (int i = 0; i < num_entries; i++) {
        int h = schedule[i * 3];
        int m = schedule[i * 3 + 1];
        int s = schedule[i * 3 + 2];
        int relay = schedule[i * 3 + 3];

        if (relay < 0 || relay >= NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number in schedule: %d\n", relay);
            return -1;
        }

        if (h < 0 || h > 23 || m < 0 || m > 59 || s < 0 || s > 59) {
            fprintf(stderr, "Invalid time in schedule: %d:%d:%d\n", h, m, s);
            return -1;
        }

        if (relay_pins[relay] != relay_pins[0]) {
            if (gpioRead(relay_pins[relay]) != 0) {
                fprintf(stderr, "Relay %d already ON at startup\n", relay);
                return -1;
            }
        }
    }
    return 0;
}

static void set_relay(int pin, int state) {
    gpioWrite(pin, state);
}

static void fade_relay(int pin, int target_state, int duration) {
    int current_pwm = 0;
    int target_pwm = 0;
    if (target_state == 1) {
        target_pwm = PWM_RANGE;
    } else {
        target_pwm = 0;
    }

    if (target_pwm > current_pwm) {
        current_pwm += 1;
        if (current_pwm > PWM_RANGE) current_pwm = PWM_RANGE;
    } else if (target_pwm < current_pwm) {
        current_pwm -= 1;
        if (current_pwm < 0) current_pwm = 0;
    }

    gpioPWM(pin, current_pwm);
    gpioDelay(50);
}

static void apply_schedule(int schedule[], int num_entries) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        perror("localtime failed");
        return;
    }

    int current_hour = tm_info->tm_hour;
    int current_minute = tm_info->tm_min;
    int current_second = tm_info->tm_sec;

    for (int i = 0; i < num_entries; i++) {
        int h = schedule[i * 3];
        int m = schedule[i * 3 + 1];
        int s = schedule[i * 3 + 2];
        int relay = schedule[i * 3 + 3];

        if (relay == -1) continue;

        if (h == current_hour && m == current_minute && s == current_second) {
            if (relay_pins[relay] != relay_pins[0]) {
                set_relay(relay_pins[relay], 0);
            }
            for (int t = 0; t < TRANSITION_DURATION && running; t++) {
                fade_relay(relay_pins[relay], 1, 1);
                gpioDelay(1000000);
            }
            if (running) {
                set_relay(relay_pins[relay], 1);
            }
        }
    }
}

int main() {
    int schedule[NUM_RELAYS * 5];
    int num_entries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        set_relay(relay_pins[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_schedule(SCHEDULE_FILE, relay_pins, schedule, &num_entries) != 0) {
        fprintf(stderr, "Failed to read schedule. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (validate_schedule(schedule, num_entries) != 0) {
        fprintf(stderr, "Invalid schedule. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        apply_schedule(schedule, num_entries);
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

