/*
 * Rudimentary theremin using an HC-SR04 ultrasonic sensor and a PWM buzzer.
 *
 * Wiring (Raspberry Pi Zero W):
 *   HC-SR04 TRIG -> GPIO23 (physical pin 16)
 *   HC-SR04 ECHO -> GPIO24 (physical pin 18) [use a voltage divider if ECHO is 5 V]
 *   Buzzer +     -> GPIO18 (physical pin 12, hardware PWM0)
 *   Buzzer -     -> GND
 *
 * Build: gcc -Wall -O2 -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* ~5 m round-trip; clamp to ~4 m max range */
#define LOOP_DELAY_US    20000   /* 50 Hz */
#define MEASURE_GAP_US   60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / sensor-absent.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Warning: echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
        gpioDelay(20);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Warning: echo end timeout\n");
            return -1.0f;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us / 1000000.0f) * 34300.0f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f-%.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance;
}

static int map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float ratio = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY_HZ + ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency > 0) {
        if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
            fprintf(stderr, "Warning: gpioSetPWMfrequency failed for %d Hz\n", frequency);
        }
        if (gpioPWM(BUZZER_PIN, 128) < 0) {  /* 50 % duty cycle */
            fprintf(stderr, "Warning: gpioPWM failed\n");
        }
    } else {
        gpioPWM(BUZZER_PIN, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioPWM(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin ready. TRIG=GPIO%d, ECHO=GPIO%d, BUZZER=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Move your hand between %.0f-%.0f cm to change pitch.\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            set_buzzer_frequency(0);
            gpioDelay(MEASURE_GAP_US);
            continue;
        }

