#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void led_off(void) {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
}

static void set_color(float proximity) {
    if (proximity < 0.0f) proximity = 0.0f;
    if (proximity > 1.0f) proximity = 1.0f;

    float red   = 1.0f - proximity;
    float green = proximity;
    float blue  = 0.0f;

    int r_val = (int)(red   * (float)PWM_RANGE);
    int g_val = (int)(green * (float)PWM_RANGE);
    int b_val = (int)(blue  * (float)PWM_RANGE);

    if (r_val < 0) r_val = 0;
    if (r_val > PWM_RANGE) r_val = PWM_RANGE;
    if (g_val < 0) g_val = 0;
    if (g_val > PWM_RANGE) g_val = PWM_RANGE;
    if (b_val < 0) b_val = 0;
    if (b_val > PWM_RANGE) b_val = PWM_RANGE;

    if (gpioPWM(RED_PIN, r_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on RED_PIN\n");
    if (gpioPWM(GREEN_PIN, g_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GREEN_PIN\n");
    if (gpioPWM(BLUE_PIN, b_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on BLUE_PIN\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float phase = 0.0f;
    while (running) {
        phase += 0.01f;
        if (phase > 2.0f * M_PI) phase -= 2.0f * M_PI;

        float proximity = 0.5f + 0.5f * sinf(phase);
        set_color(proximity);

        usleep(50000);
    }

    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

