#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SCALE     131.0f   /* LSB per deg/s at ±250 deg/s */
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read from 0x%02X failed (%zd/%zu): %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */
    return 0;
}

static void log_data(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 gyro logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t raw[6];
        if (i2c_read_block(fd, GYRO_XOUT_H, raw, sizeof(raw)) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int16_t gx = (int16_t)((raw[0] << 8) | raw[1]);
        int16_t gy = (int16_t)((raw[2] << 8) | raw[3]);
        int16_t gz = (int16_t)((raw[4] << 8) | raw[5]);

        float gx_dps = (float)gx / GYRO_SCALE;
        float gy_dps = (float)gy / GYRO_SCALE;
        float gz_dps = (float)gz / GYRO_SCALE;

        log_data(fp, gx_dps, gy_dps, gz_dps);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

