#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5
#define HIGH_THRESHOLD 3
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s value=%d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(fileno(fp)) != 0) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_earthquake(const int *window, int size, int threshold) {
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1) high_count++;
    }
    if (high_count >= threshold) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) != 0) {
                printf("EARTHQUAKE ALERT! %s\n", timestamp);
            } else {
                printf("EARTHQUAKE ALERT!\n");
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "localtime_r failed in earthquake check: %s\n", strerror(errno));
        }
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec poll_timeout;
    FILE *log_fp = NULL;
    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_filled = 0;
    int opt_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--timeout") == 0 && i + 1 < argc) {
            opt_timeout_ms = atoi(argv[++i]);
            if (opt_timeout_ms <= 0) {
                fprintf(stderr, "Invalid timeout value. Using default %d ms.\n", DEFAULT_POLL_TIMEOUT_MS);
                opt_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
            }
        } else {
            fprintf(stderr, "Usage: %s [--timeout <ms>]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    memset(window, 0, sizeof(window));

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error getting line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_both_edges_events(line, "vibration_monitor") < 0) {
        fprintf(stderr, "Error requesting both-edges events on line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (chip %s). Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET, GPIO_CHIP_NAME);

    while (program_running) {
        poll_timeout.tv_sec = opt_timeout_ms / 1000;
        poll_timeout.tv_nsec = (opt_timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &poll_timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(errno));
            continue;
        }

        int value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;

        if (log_event(log_fp, value) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_filled < WINDOW_SIZE) {
            window_filled++;
        }

        check_earthquake(window, window_filled, HIGH_THRESHOLD);
    }

    printf("\nExiting gracefully...\n");

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

