/*
 * LSM303DLHC magnetometer logger for Raspberry Pi Zero W
 * Uses Linux I2C-dev (/dev/i2c-1) — no wiringPi dependency.
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi GPIO2 (physical pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3 (physical pin 5)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o mag_log mag_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define LSM303_MAG_ADDR   0x1E
#define LSM303_CRA_REG_M  0x00   /* Temp enable / ODR */
#define LSM303_MR_REG_M   0x02   /* Operating mode */
#define LSM303_OUT_X_H_M  0x03   /* X MSB (first of 6 data registers) */

#define I2C_BUS          "/dev/i2c-1"
#define CSV_FILENAME     "mag_log.csv"

#define X_OFFSET 10.0f
#define Y_OFFSET (-5.0f)
#define Z_OFFSET 20.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level SMBus helpers ---- */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    union i2c_smbus_data data;
    data.byte = value;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_WRITE,
        .command    = reg,
        .size       = I2C_SMBUS_BYTE_DATA,
        .data       = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_READ,
        .command    = reg,
        .size       = I2C_SMBUS_BYTE_DATA,
        .data       = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = data.byte & 0xFF;
    return 0;
}

/*
 * Read 6 consecutive bytes starting at OUT_X_H_M (0x03).
 * Returns 0 on success, -1 on error.
 */
static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_READ,
        .command    = LSM303_OUT_X_H_M,
        .size       = I2C_SMBUS_BLOCK_DATA,
        .data       = &buf
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C block read of 6 data registers failed: %s\n",
                strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Compass direction from calibrated X/Y ---- */
static const char *compass_direction(float x, float y)
{
    if (x > 0 && y > 0) return "NE";
    if (x > 0 && y < 0) return "E";
    if (x < 0 && y < 0) return "SE";
    if (x < 0 && y > 0) return "NW";
    if (x == 0 && y == 0) return "N";
    if (x > 0) return "E";
    return "W";
}

/* ---- CSV logging ---- */
static int log_data_to_csv(FILE *fp, int16_t x, int16_t y, int16_t z,
                           float cal_x, float cal_y, float cal_z,
                           float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%.2f,%.2f,%.2f,%.2f\n",
                ts, x, y, z, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int16_t x, y, z;
    float cal_x, cal_y, cal_z, heading;
    int need_header = 0;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure magnetometer: continuous-conversion mode */
    if (i2c_write_byte(fd, LSM303_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set magnetometer mode.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set ODR = 15 Hz (0x14) — optional, default is 80 Hz */
    if (i2c_write_byte(fd, LSM303_CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Warning: could not set ODR; continuing.\n");
    }

    /* Open CSV file (append); write header if file is empty */
    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        need_header = 1;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_magnetometer_data(fd, &x, &y, &z) < 0) {
            /* I2C error — skip this sample, keep running */
            sleep(1);
            continue;
        }

        cal_x = ((float)x - X_OFFSET) * 100.0f;   /* calibrated units */
        cal_y = ((float)y - Y_OFFSET) * 100.0f;
        cal_z = ((float)z - Z_OFFSET) * 100.0f;

        heading = atan2f((float)cal_y, (float)cal_x) * 180.0f / (float)M_PI;
        if (heading < 0.0f)
            heading += 360.0f;

        const char *dir = compass_direction(cal_x, cal_y);
        printf("Heading: %6.2f  (%s)  X=%6.2f  Y=%6.2f  Z=%6.2f\n",
               heading, dir, cal_x, cal_y, cal_z);

        if (log_data_to_csv(fp, x, y, z, cal_x, cal_y, cal_z, heading) < 0) {
            fprintf(stderr, "CSV logging error — continuing.\n");
        }

        sleep(1);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fp) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

