#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_log(void) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

static int simulate_moisture(void) {
    return rand() % 101;
}

static void log_activation(int relay_num, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Relay %d activated, Moisture: %d\n",
                timestamp, relay_num, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
    }
}

static void activate_relay(int relay_num) {
    if (gpiod_line_set_value(lines[relay_num], 0) < 0) {
        fprintf(stderr, "Error: Failed to activate relay %d: %s\n",
                relay_num, strerror(errno));
        return;
    }
    printf("Relay %d activated\n", relay_num);
    log_activation(relay_num, simulate_moisture());

    sleep(RELAY_ON_TIME);

    if (gpiod_line_set_value(lines[relay_num], 1) < 0) {
        fprintf(stderr, "Error: Failed to deactivate relay %d: %s\n",
                relay_num, strerror(errno));
        return;
    }
    printf("Relay %d deactivated\n", relay_num);

    sleep(RELAY_GAP);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    srand((unsigned int)time(NULL));

    if (init_gpio() < 0) {
        cleanup_gpio();
        return 1;
    }

    if (init_log() < 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture = simulate_moisture();
        printf("Simulated moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && program_running; i++) {
                activate_relay(i);
            }
        }

        for (int i = 0; i < POLL_INTERVAL && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    cleanup_log();
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

