        }

        for (int i = 0; i < POLL_INTERVAL && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    cleanup_log();
    printf("Smart Irrigation System stopped.\n");
