/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 * Library : pigpio (modern, actively maintained)
 * Servos  : Two SG90 micro-servos
 *   GPIO17 (physical pin 11) — water valve (0° = closed, 90° = open)
 *   GPIO18 (physical pin 12) — directional nozzle (0° = off, 180° = full flow)
 *
 * Build   : gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run     : sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define WATER_VALVE_GPIO 17
#define NOZZLE_GPIO      18

#define SERVO_MIN_PULSE_WIDTH  500   /* ~0°   */
#define SERVO_MAX_PULSE_WIDTH  2500  /* ~180° */
#define SERVO_OPEN_PULSE_WIDTH 1500  /* ~90°  */

#define MOISTURE_THRESHOLD   50
#define CYCLE_DELAY_US       5000000 /* 5 s between moisture readings */
#define WATERING_DELAY_US    2000000 /* 2 s per nozzle angle */
#define HOLD_WATERING_US     5000000 /* 5 s hold with valve open */
#define SERVO_RETRY_DELAY_US 100000  /* 100 ms backoff on gpioServo failure */
#define SERVO_RETRY_COUNT    3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — keep it async-signal-safe (no gpio calls)          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Stop both servos immediately (pulse width 0)                       */
/* ------------------------------------------------------------------ */
static void stop_servos(void)
{
    gpioServo(WATER_VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Set a servo to a pulse width in microseconds.                       */
/* Returns 0 on success, -1 on failure after retries.                  */
/* ------------------------------------------------------------------ */
static int set_servo(int gpio, int pulse_width)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; ++attempt) {
        if (gpioServo(gpio, pulse_width) == 0)
            return 0;
        fprintf(stderr,
                "Warning: gpioServo(%d, %d) failed (attempt %d/%d)\n",
                gpio, pulse_width, attempt + 1, SERVO_RETRY_COUNT);
        gpioDelay(SERVO_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Open the water valve (0° -> 90°).                                   */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    if (set_servo(WATER_VALVE_GPIO, SERVO_OPEN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: failed to open water valve after retries.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close the water valve (90° -> 0°).                                 */
/* Returns 0 on success, -1 on failure (non-fatal).                   */
/* ------------------------------------------------------------------ */
static int close_valve(void)
{
    if (set_servo(WATER_VALVE_GPIO, SERVO_MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr,
                "Warning: failed to close water valve after retries.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sweep the nozzle through the five angles.                           */
/* Each angle is held for WATERING_DELAY_US before advancing.          */
/* Returns 0 on success, -1 if a step fails.                          */
/* ------------------------------------------------------------------ */
static int sweep_nozzle(void)
{
    const int angles[5] = {0, 45, 90, 135, 180};
    for (int i = 0; i < 5 && g_running; ++i) {
        int pulse = (int)(SERVO_MIN_PULSE_WIDTH +
                          (float)angles[i] / 180.0 *
                          (float)(SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
        if (set_servo(NOZZLE_GPIO, pulse) != 0) {
            fprintf(stderr,
                    "Error: failed to set nozzle angle %d after retries.\n",
                    angles[i]);
            return -1;
        }
        gpioDelay(WATERING_DELAY_US);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simulated soil-moisture reading that cycles through [20, 40, 60, 80, 100].*/
/* ------------------------------------------------------------------ */
static int read_soil_moisture(void)
{
    static int moisture = 20;
    moisture = (moisture + 1) % 5;
    return moisture;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Centre both servos at start ---- */
    if (set_servo(WATER_VALVE_GPIO, SERVO_MIN_PULSE_WIDTH) != 0 ||
        set_servo(NOZZLE_GPIO, SERVO_MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: failed to initialise servos.\n");
        stop_servos();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold — watering.\n");

            if (open_valve() != 0) {
                fprintf(stderr, "Critical: water valve open failed.\n");
                break;
            }

            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Warning: nozzle sweep failed.\n");
            }

            if (close_valve() != 0) {
                fprintf(stderr, "Warning: water valve close failed.\n");
            }

            /* Hold with valve open for the hold duration */
            for (int elapsed = 0;
                 elapsed < HOLD_WATERING_US && g_running;
                 elapsed += WATERING_DELAY_US) {
                gpioDelay(WATERING_DELAY_US);
            }
        } else {
            printf("Moisture above threshold — no watering.\n");
        }

        /* Wait before next reading (interruptible) */
        for (int elapsed = 0;
             elapsed < CYCLE_DELAY_US && g_running;
             elapsed += 100000) {
            gpioDelay(100000); /* 100 ms slices */
        }
    }

    /* ---- Clean shutdown ---- */
    stop_servos();
    gpioTerminate();
    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

