/* ---- Pin assignments (BCM numbering) ---- */
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

/* ---- Motor parameters ---- */
#define STEPS_PER_ROTATION 512   /* ~1.2 degrees per step; ~290 degrees total */
#define STEP_DELAY_US      3000  /* 3 ms between steps */
#define DEBOUNCE_US        50000 /* 50 ms debounce window */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Energize the four coils for one full-step excitation (single coil active). */
static int motor_step(int a, int b, int c, int d)
{
    if (gpioWrite(IN1, a) < 0) return -1;
    if (gpioWrite(IN2, b) < 0) return -1;
    if (gpioWrite(IN3, c) < 0) return -1;
    if (gpioWrite(IN4, d) < 0) return -1;
    return 0;
}

/* De-energize all coils to reduce power consumption and motor heating. */
static void motor_off(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/* Rotate the motor the given number of steps in the given direction. */
static int rotate_motor(int steps, int direction)
{
    int a, b, c, d;

    if (direction == 1) {
        /* Clockwise: IN1->IN2, IN2->IN3, IN3->IN4, IN4->IN1 (single coil) */
        a = 1; b = 0; c = 0; d = 1;
    } else if (direction == -1) {
        /* Counter-clockwise: IN1<-IN2, IN2<-IN3, IN3<-IN4, IN4<-IN1 */
        a = 0; b = 1; c = 1; d = 0;
    } else {
        fprintf(stderr, "Invalid direction %d\n", direction);
        return -1;
    }

    for (int i = 0; i < steps && g_running; i++) {
        if (motor_step(a, b, c, d) < 0) {
            fprintf(stderr, "gpioWrite failed during step %d\n", i);
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
        a = a ^ 1; b = b ^ 1; c = c ^ 1; d = d ^ 1;
    }

    motor_off();
    return 0;
}

/* Read a button with internal pull-up; returns 1 if pressed (active-low). */
static int button_pressed(int gpio)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on button GPIO %d\n", gpio);
        return 0;
    }
    return (level == 0);
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins as outputs ---- */
    if (gpioSetMode(IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(IN4, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

