    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0)
    {
        fprintf(stderr, "Failed to set button GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0)
    {
        fprintf(stderr, "Failed to set button pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handler for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic Door Lock Simulation\n");
    printf("Press LOCK (GPIO%d) to rotate %d steps CW | UNLOCK (GPIO%d) to rotate %d steps CCW\n",
           LOCK_BUTTON, STEPS_PER_ROTATION, UNLOCK_BUTTON, STEPS_PER_ROTATION);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (button_pressed(LOCK_BUTTON)) {
            printf("[LOCK] Rotating %d steps CW...\n", STEPS_PER_ROTATION);
            if (rotate_motor(STEPS_PER_ROTATION, 1) < 0) {
                fprintf(stderr, "Lock rotation failed\n");
            } else {
                printf("Lock rotation complete.\n");
            }
            gpioDelay(DEBOUNCE_US);
        }

        if (button_pressed(UNLOCK_BUTTON)) {
            printf("[UNLOCK] Rotating %d steps CCW...\n", STEPS_PER_ROTATION);
            if (rotate_motor(STEPS_PER_ROTATION, -1) < 0) {
                fprintf(stderr, "Unlock rotation failed\n");
            } else {
                printf("Unlock rotation complete.\n");
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(10000); /* 10 ms idle poll */
    }

    /* ---- Clean shutdown ---- */
    motor_off();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

