#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_LINE_OFFSET 17
#define ECHO_LINE_OFFSET    18
#define TIMEOUT_US          50000   /* 50 ms */
#define MIN_GUARD_MS        60      /* HC-SR04 minimum between measurements */
#define SPEED_CM_PER_US     0.01715 /* 343 m/s in cm/us */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout or read error.
 */
static long measure_echo_pulse(struct gpiod_line *echo_line)
{
    struct timespec t_start, t_now;
    long elapsed_us;

    /* --- Wait for echo rising edge --- */
    if (gpiod_line_event_wait(echo_line, &(struct timespec){0, 0}) < 0) {
        fprintf(stderr, "Error: gpiod_line_event_wait (rising edge): %s\n",
                strerror(errno));
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) {
        fprintf(stderr, "Error: clock_gettime: %s\n", strerror(errno));
        return -1;
    }

    /* --- Wait for echo falling edge --- */
    while (g_running) {
        if (gpiod_line_event_wait(echo_line, &(struct timespec){0, 0}) < 0) {
            fprintf(stderr, "Error: gpiod_line_event_wait (falling edge): %s\n",
                    strerror(errno));
            return -1;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &t_now) < 0) {
            fprintf(stderr, "Error: clock_gettime: %s\n", strerror(errno));
            return -1;
        }
        elapsed_us = (long)(t_now.tv_sec - t_start.tv_sec) * 1000000L
                   + (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Error: echo pulse timeout (> %d us)\n", TIMEOUT_US);
            return -1;
        }
    }

    /* --- Compute full pulse width --- */
    if (clock_gettime(CLOCK_MONOTONIC, &t_now) < 0) {
        fprintf(stderr, "Error: clock_gettime: %s\n", strerror(errno));
        return -1;
    }
    return (long)(t_now.tv_sec - t_start.tv_sec) * 1000000L
         + (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
}

static void log_distance(FILE *fp, float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance_cm < 0.0f) {
        fprintf(fp, "%s, -1\n", timestamp);
    } else {
        fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    }
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open default gpiochip (gpiochip0 on Pi 4) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_LINE_OFFSET);
    if (!trigger_line) {
        fprintf(stderr, "Error: gpiod_chip_get_line(trigger %d): %s\n",
                TRIGGER_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_LINE_OFFSET);
    if (!echo_line) {
        fprintf(stderr, "Error: gpiod_chip_get_line(echo %d): %s\n",
                ECHO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* --- Request trigger as output, initial value LOW --- */
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output(trigger): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request echo as input with rising/falling edge events --- */
    if (gpiod_line_request_rising_falling_events(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_rising_falling_events: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Open log file once --- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: fopen(distance_log.txt): %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        /* Ensure trigger is LOW before starting */
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Error: gpiod_line_set_value(trigger LOW): %s\n",
                    strerror(errno));
            break;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            fprintf(stderr, "Error: gpiod_line_set_value(trigger HIGH): %s\n",
                    strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Error: gpiod_line_set_value(trigger LOW): %s\n",
                    strerror(errno));
            break;
        }

        /* Wait for measurement to complete (guard + timeout) */
        usleep(MIN_GUARD_MS * 1000);

        long duration = measure_echo_pulse(echo_line);
        if (duration < 0) {
            log_distance(g_log_fp, -1.0f);
        } else {
            float distance_cm = (float)duration * SPEED_CM_PER_US;
            log_distance(g_log_fp, distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        }

        /* Enforce 1 Hz sampling rate */
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (echo_line)
        gpiod_line_release(echo_line);
    if (chip)
        gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return ret;
}

