#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_PIN 18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_US 100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START_STOP  0x0080
#define REG_INT_STATUS              0x0044
#define REG_RESULT_DISTANCE_MSB     0x0096
#define REG_RESULT_DISTANCE_LSB     0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle) {
    /* Software reset */
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int read_distance_cm(int handle, int *distance_cm) {
    uint8_t status = 0;
    uint8_t data[2];

    /* Check interrupt status for data ready */
    if (vl53l1x_read_reg16(handle, REG_INT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x07) == 0) {
        /* No new data yet */
        return 1;
    }

    /* Read 16-bit distance (MSB at 0x0096, LSB at 0x0097) */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read distance registers\n");
        return -1;
    }

    *distance_cm = (data[0] << 8) | data[1];

    /* Clear interrupt by writing to REG_INT_STATUS */
    if (vl53l1x_write_reg16(handle, REG_INT_STATUS, status) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt status\n");
        /* Non-fatal */
    }

    return 0;
}

int main(void) {
    int distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X sensor not detected or init failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X proximity door system running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int rc = read_distance_cm(g_i2c_handle, &distance);
        if (rc == 0) {
            printf("Distance: %d cm\n", distance);
            if (distance <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(RELAY_PIN, 1);
                printf("Door OPEN\n");
            } else {
                gpioWrite(RELAY_PIN, 0);
                printf("Door CLOSED\n");
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failure, continuing...\n");
        }
        /* rc == 1: no new data yet, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

