/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev interface (/dev/i2c-1) — no wiringPi dependency.
 *
 * Wiring:
 *   MPU-6050 VCC -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND -> Pi GND  (Pin 9)
 *   MPU-6050 SCL -> Pi GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA -> Pi GPIO2 / SDA (Pin 3)
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Sensitivity scale factor for ±250 dps range (LSB/dps) */
#define GYRO_SCALE_250DPS 131.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU-6050 initialization                                            */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* Wake up the MPU-6050: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Allow time for oscillator to stabilize after wake-up */
    usleep(100000); /* 100 ms */

    /* Set gyroscope full-scale range to ±250 dps (FS_SEL = 0) */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and convert gyroscope data                                    */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    /* MPU-6050 outputs are big-endian: [H][L] per axis */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE_250DPS;
    *gy = (float)raw_y / GYRO_SCALE_250DPS;
    *gz = (float)raw_z / GYRO_SCALE_250DPS;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    float gx, gy, gz;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor may be absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 Gyroscope Reader\n");
    printf("Bus: %s, Address: 0x%02X, Range: ±250 dps\n", i2c_dev, MPU6050_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        if (read_gyro_data(g_i2c_fd, &gx, &gy, &gz) == 0) {
            printf("Gyro X: %7.2f dps, Y: %7.2f dps, Z: %7.2f dps\n", gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(100000); /* 100 ms delay between readings */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

