        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor may be absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 Gyroscope Reader\n");
    printf("Bus: %s, Address: 0x%02X, Range: ±250 dps\n", i2c_dev, MPU6050_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        if (read_gyro_data(g_i2c_fd, &gx, &gy, &gz) == 0) {
            printf("Gyro X: %7.2f dps, Y: %7.2f dps, Z: %7.2f dps\n", gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(100000); /* 100 ms delay between readings */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

