/*
 * Automated Plant Watering System (libgpiod v1 API)
 * Board:  Raspberry Pi 4 Model B
 * Relays: BCM GPIO17, GPIO18, GPIO27, GPIO22 (physical pins 11, 12, 13, 15)
 * Log:    watering_log.txt (YYYY-MM-DD HH:MM:SS)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define POLL_INTERVAL   60          /* seconds */
#define WATERING_DURATION 5         /* seconds */
#define LOG_FILE        "watering_log.txt"
#define GPIO_CHIP_NAME  "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_watering_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int water_plant(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) < 0) {   /* active-low: LOW = ON */
        perror("gpiod_line_set_value(ON)");
        return -1;
    }

    /* Sleep in 1-second increments so signals are caught promptly. */
    for (int i = 0; i < WATERING_DURATION && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 1) < 0) {   /* HIGH = OFF */
        perror("gpiod_line_set_value(OFF)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_requested = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* ---- Get and request all relay lines as outputs (HIGH = inactive) ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    printf("Automated Plant Watering System started.\n");
    printf("Relays on BCM GPIO17, GPIO18, GPIO27, GPIO22 (8-hour cycle).\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop: cycle relays every 86400 seconds ---- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (water_plant(lines[i]) < 0) {
                fprintf(stderr, "Watering cycle failed on relay %d (BCM %u).\n",
                        i + 1, relay_pins[i]);
                goto cleanup;
            }
        }

        if (g_running) {
            /* Sleep in 1-second increments so signals are caught promptly. */
            for (int s = 0; s < POLL_INTERVAL && g_running; s++)
                sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines (safe to call even if not requested). */
    for (int i = 0; i < lines_requested; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }

    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nShutdown complete.\n");

    return ret;
}

