#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define LOG_FILE "smart_lighting.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
}

static void set_relay_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(pin, brightness);
}

static void sunrise_simulation(void) {
    int brightness = 0;
    int step = 6;
    int duration = SUNRISE_DURATION;

    while (running && brightness <= PWM_RANGE) {
        set_relay_state(RELAY1_PIN, 1);
        set_relay_state(RELAY2_PIN, 1);
        set_relay_state(RELAY3_PIN, 1);
        set_relay_state(RELAY4_PIN, 1);

        set_relay_brightness(RELAY1_PIN, brightness);
        set_relay_brightness(RELAY2_PIN, brightness);
        set_relay_brightness(RELAY3_PIN, brightness);
        set_relay_brightness(RELAY4_PIN, brightness);

        log_event("Sunrise simulation started");

        for (int i = 0; i < duration && running; i += step) {
            brightness += step;
            if (brightness > PWM_RANGE) brightness = PWM_RANGE;
            set_relay_brightness(RELAY1_PIN, brightness);
            set_relay_brightness(RELAY2_PIN, brightness);
            set_relay_brightness(RELAY3_PIN, brightness);
            set_relay_brightness(RELAY4_PIN, brightness);
            gpioDelay(1000000);
        }

        if (running) {
            log_event("Sunrise simulation complete");
        }
    }
}

static void cleanup(void) {
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);
    gpioTerminate();
    log_event("Smart lighting simulation stopped");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Smart lighting simulation started");

    sunrise_simulation();

    cleanup();

    return 0;
}

