#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define PWR_MGMT_1         0x6B
#define SMPLRT_DIV         0x19
#define GYRO_CONFIG        0x1B
#define GYRO_XOUT_H        0x43

/* GPIO and timing */
#define LED_PIN            17
#define BUFFER_SIZE        100
#define SAMPLE_PERIOD_US   50000  /* 50 ms = 20 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Sensitivity for ±250 deg/s full-scale range: 131 LSB/deg/s */
#define GYRO_SENSITIVITY 131.0f

typedef struct {
    float x, y, z;
    uint32_t timestamp;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after wake */

    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I\n");
        return -1;
