#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "gyro_log.txt"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define GYRO_REG_XOUT_H 0x43
#define GYRO_REG_XOUT_L 0x44
#define GYRO_REG_YOUT_H 0x45
#define GYRO_REG_YOUT_L 0x46
#define GYRO_REG_ZOUT_H 0x47
#define GYRO_REG_ZOUT_L 0x48
#define GYRO_SCALE      131.0f
#define SAMPLE_DELAY_US 10000
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip); chip = NULL; cs_line = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_burst(uint8_t *buf) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};

    tx[0] = GYRO_REG_XOUT_H | 0x80;
    for (size_t i = 1; i < 7; i++) tx[i] = 0;

    if (spi_transfer(tx, rx, 7) < 0) return -1;

    if (rx[0] & 0x01) {
        fprintf(stderr, "Gyroscope not ready\n");
        return -1;
    }

    for (int i = 0; i < 6; i++) {
        buf[i] = rx[i + 1];
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_gyro_burst(buf) == 0) {
            int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
            int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

            *x = (float)raw_x / GYRO_SCALE;
            *y = (float)raw_y / GYRO_SCALE;
            *z = (float)raw_z / GYRO_SCALE;
            return 0;
        }
        retries++;
        usleep(1000);
    }

    fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) {
        close(spi_fd); spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed, continuing...\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

