#define LED_PIN 17
#define BUFFER_SIZE 64
#define SAMPLE_DELAY_US 10000
#define THRESHOLD 200.0f
#define SPI_SPEED_HZ 3900000
#define GYRO_SENSITIVITY 131.0f

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP ")");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("gpiod_chip_get_line(CS)");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(cs_line, "mpu6050-cs", 1) < 0) {
        perror("gpiod_line_request_output(CS)");
        gpiod_chip_close(chip); chip = NULL; cs_line = NULL; return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_line_release(cs_line); cs_line = NULL;
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(led_line, "mpu6050-led", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        gpiod_line_release(cs_line); cs_line = NULL;
        gpiod_chip_close(chip); chip = NULL; led_line = NULL; return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static int read_register(uint8_t reg, uint8_t *value) {
    if (!value) return -1;

    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(CS low)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(CS high)");
        return -1;
    }

    *value = rx[1];
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t x_raw, y_raw, z_raw;

    if (read_register(0x43, &x_raw) < 0) return -1;
    if (read_register(0x45, &y_raw) < 0) return -1;
    if (read_register(0x47, &z_raw) < 0) return -1;

    int16_t x_val = (int16_t)((x_raw << 8) | 0x00);
    int16_t y_val = (int16_t)((y_raw << 8) | 0x00);
    int16_t z_val = (int16_t)((z_raw << 8) | 0x00);

    *x = (float)x_val / GYRO_SENSITIVITY;
    *y = (float)y_val / GYRO_SENSITIVITY;
    *z = (float)z_val / GYRO_SENSITIVITY;

    if (*x == 0.0f && *y == 0.0f && *z == 0.0f) {
        return -2;
    }
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD) {
        printf("Threshold exceeded: X = %.2f deg/s\n", x);
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    } else if (y > THRESHOLD || y < -THRESHOLD) {
        printf("Threshold exceeded: Y = %.2f deg/s\n", y);
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    } else if (z > THRESHOLD || z < -THRESHOLD) {
        printf("Threshold exceeded: Z = %.2f deg/s\n", z);
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(ts, "INVALID", sizeof(ts));
        }
        printf("%s,%.2f,%.2f,%.2f\n", ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    printf("MPU-6050 Stability Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        int rc = read_gyro_data(&x, &y, &z);

        if (rc == -1) {
            fprintf(stderr, "SPI read error.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        } else if (rc == -2) {
            fprintf(stderr, "Invalid gyro data (all zeros).\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        add_to_buffer(x, y, z);
        check_threshold(x, y, z);

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return 0;
}

