#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* GPIO pin for the LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_mpu6050(void);
static int read_accel_data(int16_t *ax, int16_t *ay, int16_t *az);
static double calculate_roll(int16_t ax, int16_t ay, int16_t az);
static double calculate_pitch(int16_t ax, int16_t ay, int16_t az);
static void control_led(double roll, double pitch);
static void log_data(double roll, double pitch);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize the MPU-6050: wake up and set accelerometer range to +/-2g */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (write to PWR_MGMT_1 failed).\n");
        return -1;
    }

    /* Set accelerometer full-scale range to +/-2g (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range (write to ACCEL_CONFIG failed).\n");
        return -1;
    }

    /* Verify configuration by reading back ACCEL_CONFIG */
    int reg_val = i2cReadByteData(i2c_handle, ACCEL_CONFIG);
    if (reg_val < 0) {
        fprintf(stderr, "Error: Could not read back ACCEL_CONFIG (sensor may be absent).\n");
        return -1;
    }
    if ((reg_val & 0x03) != 0x00) {
