#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1145_ADDR 0x5A
#define SI1145_REG_ALS 0x20
#define SI1145_REG_PS1 0x22
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define PROXIMITY_THRESHOLD 100
#define LED_PIN 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_word(fd, SI1145_REG_ALS, ambient_light) == 0 &&
            i2c_read_word(fd, SI1145_REG_PS1, proximity) == 0) {
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Si1145 sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient_light = 0, proximity = 0;
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

