#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, CE0 active low */

/* Sensitivity: 200 LSB per degree per second */
#define SENSITIVITY 200.0f

/* Sampling interval: ~10 ms -> 100 Hz */
#define SAMPLE_DELAY_US 10000

/* Maximum reinitialisation retries */
#define MAX_REINIT_ATTEMPTS 3

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * SPI frame: [reg | 0x80, 0x00] -> response: [don't care, data_high]
 * Data is returned MSB-first, two's complement.
 */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer failed for reg 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp_s,x_rate_raw,y_rate_raw\n");
    if (fflush(fp) != 0) {
        fprintf(stderr, "Initial fflush failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int reinit_attempts = 0;

    while (!terminate) {
        gyro_data_t data;
        int16_t x_raw = 0, y_raw = 0;
        int ok = 1;

        if (read_register(ADXRS290_REG_X_RATE, &x_raw) != 0) {
            ok = 0;
        }
        if (ok && read_register(ADXRS290_REG_Y_RATE, &y_raw) != 0) {
            ok = 0;
        }

        if (ok) {
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
                perror("clock_gettime");
                ok = 0;
            } else {
                double timestamp = (double)ts.tv_sec +
                                   (double)ts.tv_nsec / 1.0e9;
                if (fprintf(fp, "%.6f,%d,%d\n", timestamp, x_raw, y_raw) < 0) {
                    fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
                    ok = 0;
                }
                if (fflush(fp) != 0) {
                    fprintf(stderr, "fflush failed: %s\n", strerror(errno));
                    ok = 0;
                }
            }
        } else {
            fprintf(stderr, "Gyro read failed; reinitialising SPI...\n");
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                spiClose(spi_handle);
                spi_handle = -1;
                if (initialize_spi() != 0) {
                    fprintf(stderr, "SPI reinit failed (attempt %d/%d)\n",
                            reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
                } else {
                    reinit_attempts++;
                }
            } else {
                fprintf(stderr, "Max reinit attempts reached; exiting.\n");
                terminate = 1;
            }
        }

        if (!terminate) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    fprintf(stderr, "Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

