#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define SEISMIC_DURATION_MS 500
#define ALERT_DURATION_MS  2000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void seismic_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int s1_active = 0, s2_active = 0;

    if (level == 1) {
        if (gpio == SENSOR_1_PIN) {
            s1_active = 1;
        } else if (gpio == SENSOR_2_PIN) {
            s2_active = 1;
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN) {
            s1_active = 0;
        } else if (gpio == SENSOR_2_PIN) {
            s2_active = 0;
        }
    }

    if (gpio == SENSOR_1_PIN && s1_active && !start_tick) {
        start_tick = tick;
    } else if (gpio == SENSOR_2_PIN && s2_active && !start_tick) {
        start_tick = tick;
    }

    if (start_tick != 0 &&
        (gpio == SENSOR_1_PIN && s1_active) &&
        (gpio == SENSOR_2_PIN && s2_active)) {

        uint32_t elapsed = tick - start_tick;
        if (elapsed >= (uint32_t)(SEISMIC_DURATION_MS * 1000)) {
            log_event("Seismic event detected!");
            gpioWrite(ALERT_PIN, 1);
            gpioDelay(ALERT_DURATION_MS * 1000);
            gpioWrite(ALERT_PIN, 0);
            start_tick = 0;
            s1_active = 0;
            s2_active = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetAlertFunc(SENSOR_1_PIN, seismic_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, seismic_callback) != 0) {
        fprintf(stderr, "Error registering callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started.");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFunc(SENSOR_1_PIN, NULL);
    gpioSetAlertFunc(SENSOR_2_PIN, NULL);
    if (log_file) {
        log_event("Monitoring stopped.");
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

