#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_FLAGS 0        /* Mode 0: CPOL=0, CPHA=0 */

/* LED GPIO Pin */
#define LED_PIN 17

/* Circular Buffer Configuration */
#define BUFFER_SIZE 100

/* Threshold for Angular Velocity (deg/s) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    double angular_velocity;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

/* Global variables */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_spi(void);
static int read_gyro_data(double *angular_velocity);
static void add_to_buffer(circular_buffer_t *buffer, double angular_velocity);
static int check_threshold(double angular_velocity, double threshold);
static void signal_handler(int signal);
static void cleanup(void);
static void init_circular_buffer(circular_buffer_t *buffer);

/* Initialize circular buffer */
static void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

/* Initialize SPI interface */
static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* Read gyroscope data from the ADXRS290 */
static int read_gyro_data(double *angular_velocity) {
    char tx_buf[2];
    char rx_buf[2];
    int16_t raw_data;
    int result;

    /* ADXRS290: set MSB of address to 1 for read operation */
    tx_buf[0] = ADXRS290_REG_RATE_XL | 0x80;
    tx_buf[1] = 0x00; /* Dummy byte to clock out data */

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    /* Combine the two bytes (little-endian) */
    raw_data = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);

    /* Convert raw data to angular velocity (deg/s) */
    *angular_velocity = (double)raw_data / SENSITIVITY;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, double angular_velocity) {
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    buffer->buffer[buffer->head].angular_velocity = angular_velocity;
    buffer->buffer[buffer->head].timestamp = ts;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

/* Check if angular velocity exceeds the threshold */
static int check_threshold(double angular_velocity, double threshold) {
    return (fabs(angular_velocity) > threshold);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0); /* Turn off LED */
    gpioTerminate();
}

int main(void) {
    double angular_velocity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is off initially */

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Initialize circular buffer */
    init_circular_buffer(&gyro_buffer);

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&angular_velocity) == 0) {
