#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

#define PWM_RANGE 255
#define PWM_FREQUENCY 100
#define FADE_STEP 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid brightness %d for pin %d\n", brightness, pin);
        return -1;
    }
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration_seconds) {
    int current_brightness = PWM_RANGE;
    int elapsed = 0;

    while (current_brightness > 0 && g_running) {
        elapsed += FADE_STEP;
        if (elapsed >= duration_seconds) {
            break;
        }
        current_brightness -= FADE_STEP;
        if (set_lamp_brightness(pin, current_brightness) != 0) {
            return -1;
        }
        gpioDelay(100000);
    }

    if (set_lamp_brightness(pin, 0) != 0) {
        return -1;
    }

    printf("Lamp on GPIO%d faded out in %d seconds.\n", pin, duration_seconds);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: 1 - 3600\n");
        return EXIT_FAILURE;
    }

    int fade_duration = atoi(argv[1]);
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Invalid fade duration. Must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_lamp_brightness(pins[i], PWM_RANGE) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Smart Sunset Simulator started. Fading %d lamps over %d seconds.\n", num_pins, fade_duration);
    printf("Lamp 1: GPIO%d, Lamp 2: GPIO%d, Lamp 3: GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Press Ctrl+C to exit early.\n");

    for (int i = 0; i < num_pins && g_running; i++) {
        if (fade_lamp(pins[i], fade_duration) != 0) {
            fprintf(stderr, "Error: Fade failed for lamp %d (GPIO%d)\n", i + 1, pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (g_running) {
        printf("All lamps turned off.\n");
    } else {
        printf("\nInterrupted by signal. Cleaning up...\n");
    }

    for (int i = 0; i < num_pins; i++) {
        set_lamp_brightness(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

