#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_DURATION   10
#define YELLOW_DURATION 2
#define GREEN_DURATION  10
#define YELLOW_BLINK_DURATION 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(int seconds) {
    while (seconds > 0 && running) {
        int s = seconds > 5 ? 5 : seconds;
        sleep(s);
        seconds -= s;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *yellow_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        return EXIT_FAILURE;
    }

    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !yellow_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(green_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(blue_line, "traffic_light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        printf("Red\n");
        if (gpiod_line_set_value(red_line, 0) < 0 ||
            gpiod_line_set_value(yellow_line, 1) < 0 ||
            gpiod_line_set_value(green_line, 1) < 0 ||
            gpiod_line_set_value(blue_line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        sleep_seconds(RED_DURATION);

        if (!running) break;

        printf("Red + Yellow\n");
        if (gpiod_line_set_value(red_line, 0) < 0 ||
            gpiod_line_set_value(yellow_line, 0) < 0 ||
            gpiod_line_set_value(green_line, 1) < 0 ||
            gpiod_line_set_value(blue_line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        sleep_seconds(YELLOW_DURATION);

        if (!running) break;

        printf("Green\n");
        if (gpiod_line_set_value(red_line, 1) < 0 ||
            gpiod_line_set_value(yellow_line, 1) < 0 ||
            gpiod_line_set_value(green_line, 0) < 0 ||
            gpiod_line_set_value(blue_line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        sleep_seconds(GREEN_DURATION);

        if (!running) break;

        printf("Yellow (blink)\n");
        if (gpiod_line_set_value(red_line, 1) < 0 ||
            gpiod_line_set_value(yellow_line, 0) < 0 ||
            gpiod_line_set_value(green_line, 1) < 0 ||
            gpiod_line_set_value(blue_line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        sleep_seconds(YELLOW_BLINK_DURATION);

        if (!running) break;

        if (gpiod_line_set_value(red_line, 1) < 0 ||
            gpiod_line_set_value(yellow_line, 1) < 0 ||
            gpiod_line_set_value(green_line, 1) < 0 ||
            gpiod_line_set_value(blue_line, 0) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (yellow_line) gpiod_line_release(yellow_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);
    return ret;
}

