#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LOG_FILE "touch_relay.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        log_error("I2C write failed");
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(0x80, 0x63) < 0) return -1;
    if (mpr121_write(0x5E, 0x00) < 0) return -1;
    if (mpr121_write(0x5D, 0x01) < 0) return -1;
    if (mpr121_write(0x41, 0x0A) < 0) return -1;
    if (mpr121_write(0x42, 0x08) < 0) return -1;
    if (mpr121_write(0x5B, 0x21) < 0) return -1;
    if (mpr121_write(0x5C, 0x0D) < 0) return -1;
    if (mpr121_write(0x5E, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lsb = i2cReadByteData(i2c_handle, 0x00);
    if (lsb < 0) {
        log_error("I2C read LSB failed");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, 0x01);
    if (msb < 0) {
        log_error("I2C read MSB failed");
        return -1;
    }
    *status = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialisation failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    uint16_t touch_status;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x0001) {
                gpioDelay(100000);
                if (read_touch_status(&touch_status) == 0 &&
                    (touch_status & 0x0001)) {
                    relay_state = !relay_state;
                    gpioWrite(RELAY_GPIO, relay_state);
                    log_error(relay_state ? "Touch: Relay ON" : "Touch: Relay OFF");
                }
            }
        }
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

