#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_SAMPLES 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
    printf("%s: %s\n", timestamp, message);
}

static int read_flame_sensor(void) {
    int first = gpiod_line_get_value(flame_line);
    if (first < 0) {
        log_event("Error reading flame sensor");
        return -1;
    }
    usleep(DEBOUNCE_DELAY_MS * 1000);
    int second = gpiod_line_get_value(flame_line);
    if (second < 0) {
        log_event("Error reading flame sensor");
        return -1;
    }
    usleep(DEBOUNCE_DELAY_MS * 1000);
    int third = gpiod_line_get_value(flame_line);
    if (third < 0) {
        log_event("Error reading flame sensor");
        return -1;
    }
    return (first == 0 && second == 0 && third == 0) ? 1 : 0;
}

static void cleanup(void) {
    if (buzzer_line) gpiod_line_set_value(buzzer_line, 0);
    if (led_line) gpiod_line_set_value(led_line, 0);
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input flame_sensor");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output buzzer");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("gpiod_line_request_output led");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Fire alarm system started");

    int flame_active = 0;
    while (program_running) {
        int flame = read_flame_sensor();
        if (flame < 0) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (flame && !flame_active) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0 || gpiod_line_set_value(led_line, 1) < 0) {
                log_event("Error activating alarm outputs");
            } else {
                log_event("Flame Detected");
            }
            flame_active = 1;
        } else if (!flame && flame_active) {
            if (gpiod_line_set_value(buzzer_line, 0) < 0 || gpiod_line_set_value(led_line, 0) < 0) {
                log_event("Error deactivating alarm outputs");
            } else {
                log_event("Flame Cleared");
            }
            flame_active = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Fire alarm system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

