static int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening dispense_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Solenoid 1 (GPIO%d), Solenoid 2 (GPIO%d), Duration: %d ms\n",
            timestamp, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);
    return 0;
}

static int dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    if (gpioWrite(solenoid1_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid 1 on GPIO%d\n", solenoid1_pin);
        return -1;
    }
    gpioDelay(SOLENOID_HALF_DURATION_MS * 1000);

    if (gpioWrite(solenoid1_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid 1 on GPIO%d\n", solenoid1_pin);
        return -1;
    }

    if (gpioWrite(solenoid2_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid 2 on GPIO%d\n", solenoid2_pin);
        return -1;
    }
    gpioDelay((DISPENSE_DURATION_MS - SOLENOID_HALF_DURATION_MS) * 1000);

    if (gpioWrite(solenoid2_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid 2 on GPIO%d\n", solenoid2_pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0 || gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise solenoids to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error: Dispense cycle failed\n");
        }
        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error: Failed to log dispense event\n");
        }
        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

