#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* Motor A definitions */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B definitions */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* L298N enable pins */
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

/* PID constants */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Maximum motor speed */
#define MAX_SPEED 255

/* Log file path */
#define LOG_FILE "balance_log.txt"

/* Global flag for graceful shutdown */
volatile sig_atomic_t program_running = 1;

/* PID state */
typedef struct {
    double kp, ki, kd;
    double integral;
    double last_error;
} PIDController;

/* Function prototypes */
int initialize_gpio(void);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
double pid_control(PIDController *pid, double setpoint, double process_variable);
double generate_tilt_error(void);
double generate_distance(void);

/* PID controller implementation */
double pid_control(PIDController *pid, double setpoint, double process_variable) {
    double error = setpoint - process_variable;
    double proportional = pid->kp * error;
    pid->integral += pid->ki * error;
    double derivative = pid->kd * (error - pid->last_error);
    double output = proportional + pid->integral + derivative;
    pid->last_error = error;
    if (output > MAX_SPEED) output = MAX_SPEED;
    if (output < -MAX_SPEED) output = -MAX_SPEED;
    return output;
}

/* Tilt error simulation */
double generate_tilt_error(void) {
    return (double)rand() / RAND_MAX * 20.0 - 10.0;
}

/* Distance sensor simulation */
double generate_distance(void) {
    return (double)rand() / RAND_MAX * 400.0 + 2.0;
}

/* Motor control function */
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
    if (motor_a_speed < -MAX_SPEED) motor_a_speed = -MAX_SPEED;
    if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
    if (motor_b_speed < -MAX_SPEED) motor_b_speed = -MAX_SPEED;

    gpioWrite(MOTOR_A_FORWARD, (motor_a_speed > 0));
    gpioWrite(MOTOR_A_BACKWARD, (motor_a_speed < 0));
    gpioPWM(MOTOR_A_FORWARD, abs(motor_a_speed));
    gpioPWM(MOTOR_A_BACKWARD, abs(motor_a_speed));

    gpioWrite(MOTOR_B_FORWARD, (motor_b_speed > 0));
    gpioWrite(MOTOR_B_BACKWARD, (motor_b_speed < 0));
    gpioPWM(MOTOR_B_FORWARD, abs(motor_b_speed));
    gpioPWM(MOTOR_B_BACKWARD, abs(motor_b_speed));
}

/* Logging function */
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        exit(1);
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            tilt_error, distance, motor_a_speed, motor_b_speed);

    fclose(fp);
}

/* Signal handler for graceful shutdown */
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, stopping motors and exiting...\n");
        program_running = 0;
        set_motor_speed(0, 0);
        gpioTerminate();
        exit(0);
    }
}

/* GPIO initialization function */
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    return 0;
}

int main(void) {
    /* Seed the random number generator */
    srand(time(NULL));

    /* Initialize pigpio */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* PID controller initialization */
    PIDController pid = {KP, KI, KD, 0.0, 0.0};

    /* Set up signal handling */
    signal(SIGINT, signal_handler);

    /* Main control loop */
    while (program_running) {
        /* Generate simulated sensor data */
        double tilt_error = generate_tilt_error();
        double distance = generate_distance();

        /* PID control */
        double motor_a_speed = (int)pid_control(&pid, 0.0, tilt_error);
        double motor_b_speed = (int)pid_control(&pid, 0.0, tilt_error);

        /* Set motor speeds */
        set_motor_speed((int)motor_a_speed, (int)motor_b_speed);

        /* Obstacle avoidance */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -50;
            motor_b_speed = 50;
        }

        /* Log data */
        log_data(tilt_error, distance, (int)motor_a_speed, (int)motor_b_speed);

        /* Delay */
        gpioDelay(50000); /* 50 ms */
    }

    /* Cleanup (should not normally reach here due to signal handler) */
    set_motor_speed(0, 0);
    gpioTerminate();
    return 0;
}

