#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with internal pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        /* Non-fatal: continue with external pull-down or rely on internal */
    }

    /* Configure relay pin as output and ensure it starts de-energized */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Light Switch ready. Touch GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: poll touch sensor and toggle relay on state change */
    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge (touch) */
        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            /* Re-read after debounce to confirm the touch is still active */
            touch_state = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_state < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d during debounce.\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (touch_state == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write relay GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10000);  /* 10 ms polling interval */
    }

    /* Clean shutdown: ensure relay is off and release pigpio resources */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

