/*
 * mood_light.c — Raspberry Pi 3 Model B+ RGB mood light driven by ambient noise.
 *
 * Build (pigpio + ALSA):  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lrt -lm
 * Build (pigpio only, no ALSA): gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lrt -lm
 *
 * Usage: ./mood_light [sensitivity_scale]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define DEFAULT_SENSITIVITY_SCALE 1.0
#define PERIOD_SIZE              1024
#define PWM_RANGE                255
#define PWM_FREQ                 1000
#define LOOP_DELAY_US            10000   /* 10 ms */

/* ------------------------------------------------------------------ */
/* Compile-time configuration                                          */
/* ------------------------------------------------------------------ */
#if defined(HAVE_ALSA)
  #define HAVE_ALSA 1
  #define ALSA_AVAILABLE 1
#else
  #define HAVE_ALSA 0
  #define ALSA_AVAILABLE 0
#endif

#if HAVE_ALSA
  #define USE_ALSA 1
