        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    if ((err = snd_pcm_hw_params_alloca(&hw_params)) < 0) {
        fprintf(stderr, "ALSA hw_params alloc failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(g_alsa_handle, hw_params)) < 0) {
        fprintf(stderr, "ALSA hw_params_any failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    unsigned int rate = 8000;
    if ((err = snd_pcm_hw_params_set_rate_near(g_alsa_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "ALSA set rate failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    unsigned int channels = 1;
    if ((err = snd_pcm_hw_params_set_channels(g_alsa_handle, hw_params, SND_PCM_CHANNEL_IN, channels)) < 0) {
        fprintf(stderr, "ALSA set channels failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    unsigned int format = SND_PCM_FORMAT_S16_LE;
    if ((err = snd_pcm_hw_params_set_format(g_alsa_handle, hw_params, format)) < 0) {
        fprintf(stderr, "ALSA set format failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    unsigned int period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(g_alsa_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "ALSA set period_size failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    if ((err = snd_pcm_hw_params(g_alsa_handle, hw_params)) < 0) {
        fprintf(stderr, "ALSA hw_params apply failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

    if ((err = snd_pcm_prepare(g_alsa_handle)) < 0) {
        fprintf(stderr, "ALSA prepare failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = NULL;
        return -1;
    }

