}

static int alsa_read_frames(short *buffer, int frames)
{
    int err;
    int bytes = frames * sizeof(short);

    if ((err = snd_pcm_readi(g_alsa_handle, buffer, frames)) != frames) {
        if (err < 0) {
            if (err == -EPIPE) {
                fprintf(stderr, "ALSA EPIPE: buffer overrun\n");
                if (snd_pcm_prepare(g_alsa_handle) < 0) {
