/* ------------------------------------------------------------------ */
/* RGB LED control                                                     */
/* ------------------------------------------------------------------ */
static void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/* ------------------------------------------------------------------ */
/* Noise-to-color mapping                                              */
/* ------------------------------------------------------------------ */
static void map_noise_to_color(int amplitude, float scale,
                               int *red, int *green, int *blue)
{
    /* Normalize amplitude to [0, 1] */
    float normalized = (float)amplitude / 32768.0f;

    /* Cool colors (low amplitude) */
    if (normalized < 0.5f) {
        float t = normalized * 2.0f;
        *red   = (int)(t * t * 255.0f);
        *green = (int)(1.0f - t * t * 255.0f);
        *blue  = 0;
    } else {
        /* Warm colors (high amplitude) */
        float t = (normalized - 0.5f) * 2.0f;
        *red   = (int)(t * t * 255.0f);
        *green = 0;
        *blue  = (int)(t * t * 255.0f);
    }

    /* Scale to 0-255 range */
    *red   = (int)((float)*red   * scale);
    *green = (int)((float)*green * scale);
    *blue  = (int)((float)*blue  * scale);

    /* Clamp */
    if (*red   > 255) *red   = 255;
    if (*green > 255) *green = 255;
    if (*blue  > 255) *blue  = 255;
}

/* ------------------------------------------------------------------ */
/* Sine-wave simulation for no-ALSA build                              */
/* ------------------------------------------------------------------ */
#if !HAVE_ALSA
static int simulate_audio_input(short *buffer, int frames)
{
    for (int i = 0; i < frames; i++) {
        float phase = (float)i / (float)frames * 2.0f * (float)M_PI;
        buffer[i] = (short)(16384.0f * sinf(phase));
    }
    return 0;
}
#endif /* !HAVE_ALSA */

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float sensitivity_scale = DEFAULT_SENSITIVITY_SCALE;

    if (argc > 1) {
        char *endptr = NULL;
        sensitivity_scale = strtof(argv[1], &endptr);
        if (endptr == argv[1] || sensitivity_scale <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity scale: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure RGB pins as hardware PWM outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LED to off */
    set_led_color(0, 0, 0);

    /* Initialize ALSA (if available) */
    if (USE_ALSA) {
        if (alsa_init() < 0) {
            fprintf(stderr, "ALSA initialization failed; using sine-wave simulation\n");
            ALSA_INIT_FAILED = 1;
        } else {
            printf("ALSA initialized on default device at 8000 Hz, 1 channel, %d frames\n", PERIOD_SIZE);
        }
    } else {
        printf("ALSA not available; using sine-wave simulation for mood light\n");
    }

    /* Allocate audio buffer */
    short *audio_buffer = malloc(PERIOD_SIZE * sizeof(short));
    if (!audio_buffer) {
        perror("malloc");
        goto cleanup;
    }

    /* Main loop */
    while (g_running) {
        int frames_read = 0;

#if HAVE_ALSA
        frames_read = alsa_read_frames(audio_buffer, PERIOD_SIZE);
        if (frames_read < 0) {
            fprintf(stderr, "ALSA read error; continuing\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
#else
        if (simulate_audio_input(audio_buffer, PERIOD_SIZE) < 0) {
            fprintf(stderr, "Simulation error; continuing\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
#endif /* HAVE_ALSA */

        /* Compute RMS amplitude */
        double sum_sq = 0.0;
        for (int i = 0; i < frames_read; i++) {
            sum_sq += (double)audio_buffer[i] * (double)audio_buffer[i];
        }
        double rms = sqrt(sum_sq / frames_read);

        /* Map to RGB */
        int red, green, blue;
        map_noise_to_color((int)rms, sensitivity_scale, &red, &green, &blue);

        /* Update LED */
        set_led_color(red, green, blue);

        /* Print status */
        printf("RMS: %.2f  RGB: (%3d, %3d, %3d)\n", rms, red, green, blue);

        usleep(LOOP_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);

    if (audio_buffer) {
        free(audio_buffer);
    }
#if HAVE_ALSA
    if (g_alsa_handle) {
        alsa_close();
    }
#endif /* HAVE_ALSA */

    gpioTerminate();
    return EXIT_SUCCESS;
}

