#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_HOURS 1
#define DAYTIME_HOURS 6
#define SUNSET_HOURS 1
#define NIGHTTIME_HOURS 14.4

static const unsigned int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LAMPS];
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_all_lamps(int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], value);
        }
    }
}

static void cleanup(void) {
    set_all_lamps(1);
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", lamp_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "sunrise_sunset", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", lamp_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Sunrise/Sunset Simulator started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        int hour = lt->tm_hour;

        if (hour >= 6 && hour < 12) {
            printf("Sunrise phase (0-60%% brightness over %d hours)\n", SUNRISE_HOURS);
            for (int i = 0; i < SUNRISE_HOURS * 3600 && running; i++) {
                int brightness = (int)((float)i / (SUNRISE_HOURS * 3600.0f * 100.0f));
                if (brightness > 100) brightness = 100;
                set_all_lamps(0);
                usleep(brightness * 1000);
                set_all_lamps(1);
                usleep((100 - brightness) * 1000);
            }
        } else if (hour < 18 && running) {
            printf("Daytime phase (100%% brightness for %d hours)\n", DAYTIME_HOURS);
            for (int i = 0; i < DAYTIME_HOURS * 3600 && running; i++) {
                set_all_lamps(0);
                usleep(1000);
                set_all_lamps(1);
                usleep(999999);
            }
        } else if (hour >= 18 && hour < 23 && running) {
            printf("Sunset phase (100%% -> 0%% brightness over %d hours)\n", SUNSET_HOURS);
            for (int i = 0; i < SUNSET_HOURS * 3600 && running; i++) {
                int brightness = (int)((float)i / (SUNSET_HOURS * 3600.0f * 100.0f));
                if (brightness < 0) brightness = 0;
                set_all_lamps(0);
                usleep(brightness * 1000);
                set_all_lamps(1);
                usleep((100 - brightness) * 1000);
            }
        } else if (running) {
            printf("Nighttime phase (off for %d hours)\n", NIGHTTIME_HOURS);
            for (int i = 0; i < (int)(NIGHTTIME_HOURS * 3600) && running; i++) {
                set_all_lamps(1);
                usleep(1000);
            }
        }
    }

    cleanup();
    printf("Sunrise/Sunset Simulator stopped.\n");
    return EXIT_SUCCESS;
}

