#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_DIR "/home/pi/logs/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    return 0;
}

static int save_video(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "raspivid -w 1920 -h 1080 -t %d -o '%s'",
        VIDEO_DURATION_SEC * 1000, filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid failed (status=0x%04x)\n", status);
        return -1;
    }
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_DIR "motion_log.txt", "a");
        if (log_file == NULL) {
            perror("fopen log");
            return -1;
        }
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        perror("fprintf log");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush log");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed\n");
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;
            if (last_trigger_tick == 0 || elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    char filename[256];
                    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);
                    if (save_video(filename) == 0) {
                        printf("Video saved: %s\n", filename);
                    } else {
                        fprintf(stderr, "Video save failed\n");
                    }
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Logging failed\n");
                    }
                } else {
                    fprintf(stderr, "Timestamp generation failed\n");
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(50 * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

