            if (last_trigger_tick == 0 || elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    char filename[256];
                    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);
                    if (save_video(filename) == 0) {
                        printf("Video saved: %s\n", filename);
                    } else {
                        fprintf(stderr, "Video save failed\n");
                    }
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Logging failed\n");
                    }
                } else {
                    fprintf(stderr, "Timestamp generation failed\n");
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(50 * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

