#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define SMPLRT_DIV          0x19
#define GYRO_CONFIG         0x1B
#define GYRO_XOUT_H         0x43
#define GYRO_XOUT_L         0x44
#define GYRO_YOUT_H         0x45
#define GYRO_YOUT_L         0x46
#define GYRO_ZOUT_H         0x47
#define GYRO_ZOUT_L         0x48

#define GYRO_SENSITIVITY    131.0f
#define SAMPLE_RATE_HZ      100
#define SAMPLE_PERIOD_US    (1000000 / SAMPLE_RATE_HZ)
#define MAX_REINIT_ATTEMPTS 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (write PWR_MGMT_1)\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to set sample rate divider\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set gyroscope full-scale range\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes of gyro data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%03ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open gyro_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    int consecutive_failures = 0;

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: read failure #%d\n", consecutive_failures);
            if (consecutive_failures >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: %d consecutive failures, re-initializing sensor\n", consecutive_failures);
                if (init_mpu6050() < 0) {
                    fprintf(stderr, "Error: re-initialisation failed, continuing to retry\n");
                } else {
                    consecutive_failures = 0;
                }
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

