#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_PIN_1 4
#define RELAY_PIN_2 17
#define RELAY_PIN_3 27
#define RELAY_PIN_4 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SENSOR_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    return rand() % 101;
}

static int log_data(int sensor_reading, int relay_state, int pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Sensor %d: %d, Relay %d: %s\n",
                timestamp, pin, sensor_reading, pin,
                (relay_state == 0) ? "ACTIVE" : "INACTIVE") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int pins[] = {RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4};
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int relay_states[4] = {1, 1, 1, 1};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_relay_state(pins[i], relay_states[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    srand((unsigned int)time(NULL));

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int sensor_reading = read_sensor();
            if (sensor_reading < MOISTURE_THRESHOLD) {
                relay_states[i] = 0;
            } else {
                relay_states[i] = 1;
            }
            if (set_relay_state(pins[i], relay_states[i]) != 0) {
                fprintf(stderr, "Error setting relay state for pin %d\n", pins[i]);
            }
            if (log_data(sensor_reading, relay_states[i], pins[i]) != 0) {
                fprintf(stderr, "Error logging data for pin %d\n", pins[i]);
            }
        }
        gpioDelay(SENSOR_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        if (set_relay_state(pins[i], 1) != 0) {
            fprintf(stderr, "Error deactivating relay on pin %d during shutdown\n", pins[i]);
        }
    }
    cleanup();
    return EXIT_SUCCESS;
}

