#include <math.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION 0.5f
#define ALARM_HOLD_TIME 5.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    if (i2cWriteByteData(handle, POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear POWER_CTL\n");
        return -1;
    }
    if (i2cWriteByteData(handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to set DATA_FORMAT\n");
        return -1;
    }
    if (i2cWriteByteData(handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char data[6];
    if (i2cReadI2CBlockData(handle, DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((data[1] << 8) | data[0]);
    int16_t raw_y = (int16_t)((data[3] << 8) | data[2]);
    int16_t raw_z = (int16_t)((data[5] << 8) | data[4]);
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fclose(fp);
}

static void trigger_alarm(void) {
    gpioWrite(ALARM_GPIO, 1);
    gpioDelay(ALARM_HOLD_TIME * 1000000);
    gpioWrite(ALARM_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Freefall detection started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                printf("Freefall detected!\n");
                log_event(x, y, z);
                trigger_alarm();
                gpioDelay(FREEFALL_DURATION * 1000000);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

