#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    18
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 200000
#define MAX_PULSE_WIDTH_US 23200
#define TIMEOUT_US 100000
#define LOG_FILE "distance_log.txt"

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end   = 0;
static volatile int      pulse_ready = 0;
static FILE             *log_file    = NULL;
static pthread_mutex_t   pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_start = tick;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_end = tick;
        pthread_mutex_unlock(&pulse_mutex);
        pulse_ready = 1;
    }
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    return (double)pulse_width_us / 2.0 / 1000000.0 * 34300.0;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm) < 0) {
        perror("fprintf");
    }
    fflush(log_file);
}

static void cleanup(void) {
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_ready = 0;
        pulse_start = 0;
        pulse_end   = 0;
        pthread_mutex_unlock(&pulse_mutex);

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        while (running && !pulse_ready && (gpioTick() - start_tick) < TIMEOUT_US) {
            gpioDelay(100);
        }

        uint32_t pulse_width = 0;
        pthread_mutex_lock(&pulse_mutex);
        if (pulse_ready) {
            pulse_width = pulse_end - pulse_start;
            if (pulse_width > MAX_PULSE_WIDTH_US) {
                pthread_mutex_unlock(&pulse_mutex);
                continue;
            }
            log_distance(calculate_distance_cm(pulse_width));
        }
        pthread_mutex_unlock(&pulse_mutex);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

