#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FF_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define SENSITIVITY 16384.0f
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    return -1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %d\n", reg, len, rc);
    return -1;
}

static int init_accelerometer(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1, 0x77) != 0) return -1;
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) != 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L, buf, 6) != 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < DEFAULT_FF_THRESHOLD && fabsf(y) < DEFAULT_FF_THRESHOLD && fabsf(z) < DEFAULT_FF_THRESHOLD);
}

static int detect_impact(float x, float y, float z) {
    return (fabsf(x) > DEFAULT_IMPACT_THRESHOLD || fabsf(y) > DEFAULT_IMPACT_THRESHOLD || fabsf(z) > DEFAULT_IMPACT_THRESHOLD);
}

static void activate_buzzer(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(1000000);
    gpioWrite(gpio, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float ff_threshold = DEFAULT_FF_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) ff_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold = atof(argv[2]);

    if (ff_threshold <= 0.0f || impact_threshold <= 0.0f) {
        fprintf(stderr, "Error: thresholds must be positive (got ff=%.3f, impact=%.3f)\n", ff_threshold, impact_threshold);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_accelerometer(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing LIS3DH\n");
        cleanup();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    signal(SIGINT, signal_handler);

    printf("Fall detection started. FF threshold: %.3f g, Impact threshold: %.3f g\n", ff_threshold, impact_threshold);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading acceleration data\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (detect_freefall(x, y, z)) {
            printf("Freefall detected!\n");
        }

        if (detect_impact(x, y, z)) {
            printf("Impact detected!\n");
            activate_buzzer(BUZZER_GPIO);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

