#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LIS3DH_ADDR_MIN 0x08
#define LIS3DH_ADDR_MAX 0x77
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define ACCEL_THRESHOLD_DEFAULT 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static int lis3dh_address = 0x18;
static float acceleration_threshold = ACCEL_THRESHOLD_DEFAULT;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1 (0x20).\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4 (0x23).\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data.\n");
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x >> 4;
    *y = (float)raw_y >> 4;
    *z = (float)raw_z >> 4;
    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down the system...\n");
    fflush(stdout);
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        fprintf(stderr, "Error: Failed to execute shutdown command.\n");
    }
}

static void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            lis3dh_address = (int)strtol(argv[++i], NULL, 16);
            if (lis3dh_address < LIS3DH_ADDR_MIN || lis3dh_address > LIS3DH_ADDR_MAX) {
                fprintf(stderr, "Error: Invalid I2C address 0x%02X (must be 0x%02X-0x%02X).\n",
                        lis3dh_address, LIS3DH_ADDR_MIN, LIS3DH_ADDR_MAX);
                exit(1);
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            acceleration_threshold = (float)atof(argv[++i]);
            if (acceleration_threshold <= 0.0f) {
                fprintf(stderr, "Error: Acceleration threshold must be greater than 0.\n");
                exit(1);
            }
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t acceleration_threshold]\n", argv[0]);
            exit(1);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, lis3dh_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X (pigpio error %d).\n",
                lis3dh_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() < 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Monitoring acceleration (threshold: %.2f g)... Press Ctrl+C to exit.\n",
           acceleration_threshold);
    fflush(stdout);

    while (program_running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = sqrtf(x * x + y * y + z * z);
            if (magnitude > acceleration_threshold) {
                log_acceleration(x, y, z);
                printf("High acceleration detected! (X: %.3f g, Y: %.3f g, Z: %.3f g)\n", x, y, z);
                fflush(stdout);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

