#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

#define BUFFER_SIZE 5
#define POLL_DELAY_US  10000   /* 10 ms */
#define ALERT_HOLD_MS  2000    /* 2 s   */

typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

typedef struct {
    SensorReadings readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_lines[4] = {NULL, NULL, NULL, NULL};
static struct gpiod_line *g_alert_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_alert_line) {
        gpiod_line_set_value(g_alert_line, 0);
        gpiod_line_release(g_alert_line);
        g_alert_line = NULL;
    }
    for (int i = 0; i < 3; i++) {
        if (g_lines[i]) {
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_label("pinctrl-bcm2712");
    }
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_number(0);
    }
    if (!g_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    unsigned int pins[4] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN, ALERT_PIN};
    for (int i = 0; i < 4; i++) {
