#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD_MT 5.0f
#define POLL_TIMEOUT 50
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "magnetic_events.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int read_field_raw(int *raw_out) {
    if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
        fprintf(stderr, "I2C write 0xC1 failed\n");
        return -1;
    }
    for (int i = 0; i < POLL_TIMEOUT; i++) {
        int status = i2cReadByteData(i2c_handle, 0xC1);
        if (status < 0) {
            fprintf(stderr, "I2C read 0xC1 failed: %d\n", status);
            return -1;
        }
        if (status == 0) {
            break;
        }
        gpioDelay(1000);
        if (i == POLL_TIMEOUT - 1) {
            fprintf(stderr, "Timeout waiting for conversion\n");
            return -1;
        }
    }
    int lsb = i2cReadByteData(i2c_handle, 0xC0);
    if (lsb < 0) {
        fprintf(stderr, "I2C read 0xC0 LSB failed: %d\n", lsb);
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, 0xC0 + 1);
    if (msb < 0) {
        fprintf(stderr, "I2C read 0xC0 MSB failed: %d\n", msb);
        return -1;
    }
    *raw_out = (msb << 8) | lsb;
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "gpioWrite failed: %d\n", state);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }
    log_event("Program started");
    while (running) {
        int raw;
        if (read_field_raw(&raw) != 0) {
            log_event("Error reading field data");
            control_relay(0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float field_mt_x100 = (float)raw * 25.0f / 1000.0f;
        float field_mt = field_mt_x100 / 100.0f;
        char buf[128];
        snprintf(buf, sizeof(buf), "Field: %.2f mT (raw=%d)", field_mt, raw);
        log_event(buf);
        if (field_mt > FIELD_THRESHOLD_MT) {
            if (control_relay(1) == 0) {
                log_event("Relay activated");
            } else {
                log_event("Error activating relay");
            }
        } else {
            if (control_relay(0) == 0) {
                log_event("Relay deactivated");
            } else {
                log_event("Error deactivating relay");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

