        } else {
            log_event("Invalid command received.");
            fprintf(stderr, "Invalid command: %s\n", command);
            const char *err = "ERROR: Invalid command\n";
            send(client_socket, err, strlen(err), 0);
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
    }
    close(client_socket);
    printf("Client disconnected.\n");
}

