/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F Liquid Flow Sensor Monitor
 *
 * Hardware:
 *   - Two Sensirion SLF3S-1300F sensors on I2C bus 1
 *     (sensor 1, address 0x08  ; sensor 2, address 0x09)
 *   - Active-high relay module on GPIO 18 (BCM)
 *
 * Behavior:
 *   - Polls both sensors every 100 ms, validates CRC-8, converts to ml/min.
 *   - Energizes the relay when either sensor reports flow < 5.0 ml/min.
 *   - Logs timestamped flow data to flow_log.txt.
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:
 *   gcc -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f   /* ml/min – relay energizes below this */
#define POLL_DELAY_US        100000 /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S start-measurement command (bytes 0x36 0x08) */
static const uint8_t CMD_START_MEAS[2] = { 0x36, 0x08 };

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;

/* --------------------------- CRC-8 (Sensirion) --------------------------- */
/* Polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Sensor Abstraction -------------------------- */
typedef struct {
    int           handle;
    int           address;
    const char   *name;
    bool          initialized;
} sensor_t;

static sensor_t s1 = { -1, SENSOR1_ADDR, "sensor1", false };
static sensor_t s2 = { -1, SENSOR2_ADDR, "sensor2", false };

/*
 * Open an I2C handle for the given address.
 * Returns 0 on success, -1 on failure (handle stored in *out_h).
 */
static int open_sensor(int addr, int *out_h)
{
    int h = i2cOpen(I2C_BUS, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(0x%02X) failed: %d\n", addr, h);
        return -1;
    }
    *out_h = h;
    return 0;
}

/*
 * Send the start-measurement command to the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int start_measurement(int handle)
{
    if (i2cWriteDevice(handle, (char *)CMD_START_MEAS, 2) != 0) {
        fprintf(stderr, "[WARN] i2cWriteDevice failed on handle %d\n", handle);
        return -1;
    }
    return 0;
}

/*
 * Read 3 bytes (2 data + 1 CRC) from the sensor and convert to ml/min.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow(sensor_t *sensor, float *out_flow)
{
    uint8_t buf[3];

    if (!sensor->initialized) {
        fprintf(stderr, "[WARN] %s not initialized; skipping read\n",
                sensor->name);
        return -1;
    }

    int n = i2cReadDevice(sensor->handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] %s read returned %d (expected 3)\n",
                sensor->name, n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on %s data: calc=0x%02X recv=0x%02X\n",
                sensor->name, crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_flow = (float)raw / 1500.0f;
    return 0;
}

/* ------------------------------- Relay Helpers --------------------------- */
static int relay_init(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void relay_set(bool on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n",
                RELAY_GPIO, on ? 1 : 0);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_flow(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------- Signal Handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- sensors --- */
    if (open_sensor(SENSOR1_ADDR, &s1.handle) != 0 ||
        open_sensor(SENSOR2_ADDR, &s2.handle) != 0) {
        goto fail_gpio;
    }
    s1.initialized = true;
    s2.initialized = true;

    /* --- relay --- */
    if (relay_init() != 0) {
        goto fail_i2c;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitor started. Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int rc1 = read_flow(&s1, &f1);
        int rc2 = read_flow(&s2, &f2);

        if (rc1 == 0 && rc2 == 0) {
            bool below = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD);
            relay_set(below);
            log_flow(f1, f2);
            printf("Flow1: %.2f ml/min | Flow2: %.2f ml/min | Relay: %s\n",
                   f1, f2, below ? "ENERGIZED" : "DE-ENERGIZED");
        } else {
            /* On read error or CRC mismatch, de-energize for safety */
            relay_set(false);
            if (rc1 == -1)
                fprintf(stderr, "[WARN] Sensor1 read error; de-energizing relay.\n");
            if (rc2 == -1)
                fprintf(stderr, "[WARN] Sensor2 read error; de-energizing relay.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- graceful shutdown --- */
    printf("\nShutting down...\n");
    relay_set(false);
    if (s1.handle >= 0) i2cClose(s1.handle);
    if (s2.handle >= 0) i2cClose(s2.handle);
    gpioTerminate();
    printf("Flow monitor stopped.\n");
    return EXIT_SUCCESS;

fail_i2c:
    if (s1.handle >= 0) i2cClose(s1.handle);
    if (s2.handle >= 0) i2cClose(s2.handle);
fail_gpio:
    gpioTerminate();
    return EXIT_FAILURE;
}

