#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds */
#define POLL_INTERVAL_US 200000    /* 200 ms */
#define DRY_CONFIRM_POLLS 3        /* 3 consecutive dry readings = 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(int pin, int level, const char *label)
{
    int rc = gpioWrite(pin, level);
    if (rc < 0) {
        syslog(LOG_WARNING, "gpioWrite(%d, %d) failed: %s", pin, level, pigpio_error(rc));
    } else {
        syslog(LOG_INFO, "GPIO %d set to %d (%s)", pin, level, label);
    }
    return rc;
}

static void stop_motor(void)
{
    safe_gpio_write(MOTOR_ENABLE_PIN, 0, "ENABLE");
    safe_gpio_write(MOTOR_INPUT_1_PIN, 0, "INPUT1");
    safe_gpio_write(MOTOR_INPUT_2_PIN, 0, "INPUT2");
}

static void close_window(void)
{
    syslog(LOG_INFO, "Closing window...");

    if (safe_gpio_write(MOTOR_ENABLE_PIN, 1, "ENABLE") < 0) return;
    if (safe_gpio_write(MOTOR_INPUT_1_PIN, 1, "INPUT1") < 0) {
        safe_gpio_write(MOTOR_ENABLE_PIN, 0, "ENABLE");
        return;
    }
    if (safe_gpio_write(MOTOR_INPUT_2_PIN, 0, "INPUT2") < 0) {
        safe_gpio_write(MOTOR_ENABLE_PIN, 0, "ENABLE");
        safe_gpio_write(MOTOR_INPUT_1_PIN, 0, "INPUT1");
        return;
    }

    /* gpioDelay is microsecond-accurate and non-busy */
    gpioDelay(MOTOR_RUN_TIME_US);

    stop_motor();
    syslog(LOG_INFO, "Window closed.");
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised.");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set pull-up on rain sensor pin");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    stop_motor();

    int last_rain_state = gpioRead(RAIN_SENSOR_PIN);
    if (last_rain_state < 0) {
        syslog(LOG_ERR, "Initial rain sensor read failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (initial state: %s)",
           last_rain_state ? "DRY" : "RAIN");

    while (g_running) {
        int rain_state = gpioRead(RAIN_SENSOR_PIN);
        if (rain_state < 0) {
            syslog(LOG_ERR, "Rain sensor read failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain_state == 0 && last_rain_state == 1) {
            /* Rising edge: dry -> wet (rain detected) */
            syslog(LOG_INFO, "Rain detected!");
            close_window();
            /* Wait for 3 consecutive dry readings to avoid re-trigger */
            int dry_count = 0;
            for (int i = 0; i < DRY_CONFIRM_POLLS && g_running; i++) {
                gpioDelay(POLL_INTERVAL_US);
                int v = gpioRead(RAIN_SENSOR_PIN);
                if (v < 0) {
                    syslog(LOG_ERR, "Dry confirmation read failed");
                    break;
                }
                if (v == 1) {
                    dry_count++;
                }
            }
            if (dry_count == DRY_CONFIRM_POLLS) {
                last_rain_state = 1;
            }
        } else if (rain_state == 1 && last_rain_state == 0) {
            /* Falling edge: wet -> dry (rain stopped) */
            last_rain_state = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

