#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22
#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    50000   /* 50 ms */
#define POLL_US        10000   /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button inputs with internal pull-ups (pressed -> 0 V). */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in a known state. */
    if (set_servo(UNLOCK_PULSE_US) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door lock servo initialised: UNLOCKED (pulse %d us)\n", UNLOCK_PULSE_US);
    fflush(stdout);

    int last_lock = 0;
    int last_unlock = 0;

    while (running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed && !last_lock) {
            if (set_servo(LOCK_PULSE_US) == 0) {
                printf("Door LOCKED\n");
                fflush(stdout);
                last_lock = 1;
            }
        }

        if (unlock_pressed && !last_unlock) {
            if (set_servo(UNLOCK_PULSE_US) == 0) {
                printf("Door UNLOCKED\n");
                fflush(stdout);
                last_unlock = 1;
            }
        }

        /* Debounce: wait until both buttons are released or timeout. */
        int wait_ms = 0;
        while (running && (wait_ms < 1000)) {
            if (!lock_pressed && !unlock_pressed) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
            wait_ms += (DEBOUNCE_US / 1000);
        }

        last_lock = (gpioRead(LOCK_BUTTON) == 0);
        last_unlock = (gpioRead(UNLOCK_BUTTON) == 0);

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: stop servo pulses and release pigpio. */
    set_servo(0);
    gpioTerminate();
    printf("Door lock servo stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

