#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */
#define FLOODLIGHT_ON_TIME_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write an ISO-8601 timestamp into buf (size >= 25). */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* Append a line to the log file. Returns 0 on success, -1 on error. */
static int log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s\n", event) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Activate the floodlight for FLOODLIGHT_ON_TIME_S seconds. */
static int activate_floodlight(void)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(FLOODLIGHT_PIN, 1) failed\n");
        return -1;
    }

    printf("Floodlight activated at %s\n", ts);

    /*
     * gpioDelay blocks for the given microseconds. We still want to
     * respond to signals during the on-time, so we break the delay
     * into 100 ms slices and check g_running each iteration.
     */
    for (int elapsed = 0; elapsed < FLOODLIGHT_ON_TIME_S * 1000000 && g_running;
         elapsed += POLL_DELAY_US) {
        gpioDelay(POLL_DELAY_US);
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(FLOODLIGHT_PIN, 0) failed\n");
        return -1;
    }

    get_timestamp(ts, sizeof(ts));
    char duration_str[64];
    snprintf(duration_str, sizeof(duration_str), "%.0f",
             (double)FLOODLIGHT_ON_TIME_S);

    char log_event_str[256];
    snprintf(log_event_str, sizeof(log_event_str),
             "Floodlight deactivated after %s seconds at %s",
             duration_str, ts);

    printf("Floodlight deactivated at %s (duration: %s)\n", ts, duration_str);

    if (log_event(log_event_str) != 0) {
        fprintf(stderr, "Warning: failed to log floodlight deactivation event\n");
    }
    return 0;
}

/*
 * Read the PIR pin. Returns 1 if motion is detected (rising edge),
 * 0 if no motion, -1 on read error.
 */
static int detect_motion(void)
{
    int prev = gpioRead(PIR_PIN);
    if (prev < 0) {
        fprintf(stderr, "Error: gpioRead(PIR_PIN) failed\n");
        return -1;
    }

    int cur = gpioRead(PIR_PIN);
    if (cur < 0) {
        fprintf(stderr, "Error: gpioRead(PIR_PIN) failed\n");
        return -1;
    }

    /* Rising edge: 0 -> 1 */
    return (prev == 0 && cur == 1) ? 1 : 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure floodlight pin as output and ensure it starts OFF */
    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(FLOODLIGHT_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started.\n");
    printf("PIR sensor on GPIO %d, floodlight on GPIO %d.\n", PIR_PIN, FLOODLIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_motion_state = 0;

    while (g_running) {
        int motion = detect_motion();
        if (motion < 0) {
            /* Read error — ensure floodlight is off and exit */
            gpioWrite(FLOODLIGHT_PIN, 0);
            gpioTerminate();
