/*
 * Raspberry Pi 5 - MPR121 Capacitive Touch Relay Controller
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR-> GND  (I2C address 0x5A)
 *   MPR121 VDD-> 3.3V, GND-> GND
 *   Relay IN  -> GPIO17 (active-high 5V relay module)
 *
 * Behavior:
 *   On a fresh touch of electrode 0, the relay toggles state.
 *   Relay is forced OFF on startup/shutdown for safety.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_SOFTRESET     0x80
#define MPR121_AUTO_CONFIG0  0x7B
#define MPR121_AUTO_CONFIG1  0x7C
#define MPR121_USL           0x7D

#define DEBOUNCE_MS         200
#define POLL_DELAY_US       10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static bool g_relay_state = false;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read_word(uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Baseline filtering */
    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_CONFIG1, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, ESI=1 ms */
    if (mpr121_write(MPR121_CONFIG2, 0x24) < 0) return -1;

    /* Auto-config: enable, retries=0, FFI=6, SFI=4, ESI=1 ms */
    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_USL, 200) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    if (g_relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_state = false;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);
    g_relay_state = false;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Touch electrode 0 to toggle GPIO17.\n");
    printf("Press Ctrl+C to exit.\n");

    uint16_t prev_touch = 0;

    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_word(MPR121_TOUCHSTATUS_L, &touch_status) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t new_touch = touch_status & 0x0FFF; /* 12 electrodes */

        /* Rising edge on electrode 0 */
        if ((prev_touch == 0) && (new_touch != 0) && (new_touch & 0x01)) {
            g_relay_state = !g_relay_state;
            if (gpioWrite(RELAY_GPIO, g_relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to write relay GPIO\n");
            } else {
                printf("Relay toggled to %s\n", g_relay_state ? "ON" : "OFF");
            }
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        prev_touch = new_touch;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

