#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define SERVO_PIN      17
#define PIR_PIN        4
#define TCP_PORT       5000
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_RANGE    180
#define PWM_PERIOD_US  20000  /* 50 Hz */
#define PWM_TOLERANCE  1000   /* 5 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_sockfd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_servo_line = NULL;
static struct gpiod_line *g_pir_line = NULL;

static void log_message(int priority, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    syslog(priority, "[%s] ", ts);
    vsyslog(priority, fmt, ap);
    va_end(ap);
    if (g_log_file) {
        fprintf(g_log_file, "[%s] ", ts);
        fflush(g_log_file);
        vfprintf(g_log_file, fmt, ap);
        fflush(g_log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_us = SERVO_MIN_PULSE_US + (angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US)) / SERVO_RANGE;
    int period_us = PWM_PERIOD_US;
    int high_us = pulse_us;
    int low_us = period_us - pulse_us;
    if (low_us < 0) low_us = 0;
    if (gpiod_line_set_value(g_servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo high: %s", strerror(errno));
        return -1;
    }
    usleep(high_us);
    if (gpiod_line_set_value(g_servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo low: %s", strerror(errno));
        return -1;
    }
    usleep(low_us);
    return 0;
}

static int read_pir(void) {
    int val = gpiod_line_get_value(g_pir_line);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read PIR: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[256];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        close(client_fd);
        return;
    }
    if (n == 0) {
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    char *cmd = strtok(buffer, " ");
    if (strcmp(cmd, "SERVO") == 0) {
        char *arg = strtok(NULL, " ");
        if (!arg) {
            log_message(LOG_ERR, "SERVO missing angle");
            const char *resp = "ERROR: missing angle\n";
            send(client_fd, resp, strlen(resp), 0);
            close(client_fd);
            return;
        }
        int angle = atoi(arg);
        if (set_servo_angle(angle) == 0) {
            log_message(LOG_INFO, "Set servo to %d degrees", angle);
            const char *resp = "OK\n";
            send(client_fd, resp, strlen(resp), 0);
        } else {
