static void log_message(int priority, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    syslog(priority, "[%s] ", ts);
    vsyslog(priority, fmt, ap);
    va_end(ap);
    if (g_log_file) {
        fprintf(g_log_file, "[%s] ", ts);
        fflush(g_log_file);
