    if (angle < 0 || angle > SERVO_RANGE) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_us = SERVO_MIN_PULSE_US + (angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US)) / SERVO_RANGE;
    int period_us = PWM_PERIOD_US;
    int high_us = pulse_us;
    int low_us = period_us - pulse_us;
    if (low_us < 0) low_us = 0;
