static int read_hx711(int32_t *raw_value) {
    if (!raw_value) return -1;

    int timeout = DOUT_TIMEOUT_US;
    while (gpiod_line_get_value(dout_line) == 1) {
        if (timeout <= 0) {
            syslog(LOG_ERR, "HX711 DOUT timeout (stuck HIGH)");
            return -1;
        }
        usleep(10);
        timeout -= 10;
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "SCK high failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        data <<= 1;
        int bit = gpiod_line_get_value(dout_line);
        if (bit < 0) {
            syslog(LOG_ERR, "DOUT read failed: %s", strerror(errno));
            return -1;
        }
        if (bit) data |= 1;
        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "25th SCK high failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "25th SCK low failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *raw_value = (int32_t)data;
    return 0;
}

static int read_weight(float *weight) {
    if (!weight) return -1;

    int32_t raw = 0;
    int valid = 0;
    for (int i = 0; i < NUM_READINGS; i++) {
        if (read_hx711(&raw) == 0) {
            valid++;
        } else {
