            return -1;
        }
        usleep(10000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "All HX711 readings failed");
        return -1;
    }

    int32_t sum = 0;
    for (int i = 0; i < valid; i++) {
        sum += raw;
    }
    *weight = (float)(sum / valid - tare_offset) / scale;
    return 0;
}

static int tare_load_cell(void) {
    int32_t raw = 0;
    int valid = 0;
    for (int i = 0; i < NUM_TARE_READINGS; i++) {
        if (read_hx711(&raw) == 0) {
