        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

static void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
