 * MQTT:
 *   - Broker: localhost
 *   - Port:  1883
 *   - Topic: home/lights/control
 *   - QoS:   0
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define MQTT_KEEPALIVE 60

#define GPIO_PIN       17
#define RECONNECT_DELAY 5
#define LOOP_DELAY     10

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_relay(int state)
{
    int rc = gpioWrite(GPIO_PIN, state);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(%d) failed: %s", GPIO_PIN, pigpio_error(rc));
        return -1;
    }
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe failed: %s", mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "Connect failed: %s", mosquitto_connack_string(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)userdata;
    syslog(LOG_WARNING, "Disconnected from MQTT broker (rc=%d)", rc);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *msg)
{
    (void)mosq;
    (void)userdata;

    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty message on topic %s", msg->topic ? msg->topic : "(null)");
        return;
    }

    /* NUL-terminate the payload for safe string handling */
    char payload_buf[256];
    size_t len = (size_t)msg->payloadlen;
    if (len >= sizeof(payload_buf))
        len = sizeof(payload_buf) - 1;
    memcpy(payload_buf, msg->payload, len);
    payload_buf[len] = '\0';

    syslog(LOG_INFO, "Received message: %s", payload_buf);

    if (strcmp(payload_buf, "ON") == 0) {
        if (set_relay(1) == 0)
            syslog(LOG_INFO, "Relay ON");
    } else if (strcmp(payload_buf, "OFF") == 0) {
        if (set_relay(0) == 0)
            syslog(LOG_INFO, "Relay OFF");
    } else {
        syslog(LOG_ERR, "Invalid command: %s", payload_buf);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "GPIO%d configured as output, relay OFF", GPIO_PIN);

    /* ---- mosquitto ---- */
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect(%s:%d) failed: %s",
               MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Allow the broker to send a CONNACK before we start the loop */
    usleep(100000);

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- event loop ---- */
    while (g_running) {
        rc = mosquitto_loop(g_mosq, LOOP_DELAY, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            sleep(RECONNECT_DELAY);
            continue;
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

