/*
 * Closed-loop speed control for two DRV8833-driven DC motors.
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio
 *
 * Wiring:
 *   Motor A: IN1 -> GPIO17 (PWM), IN2 -> GPIO18 (direction)
 *   Motor B: IN3 -> GPIO22 (PWM), IN4 -> GPIO23 (direction)
 *   Encoder A: A -> GPIO4, B -> GPIO5 (1 count per rising edge)
 *   Encoder B: A -> GPIO6, B -> GPIO12 (1 count per rising edge)
 *
 * Build:  gcc -O2 -Wall -o speed_control speed_control.c -lpigpio -lrt
 * Run:    sudo ./speed_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments ---- */
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

/* ---- Control parameters ---- */
#define TARGET_RPM      50
#define KP              0.5
#define KI              0.05
#define PWM_FREQ_HZ     10000
#define PWM_RANGE       255
#define LOOP_PERIOD_US  100000   /* 100 ms */
#define STALL_TIMEOUT_S 2

/* ---- Shared state (protected by pigpio's ISR-aware dispatch) ---- */
static volatile int32_t encoder_a_count = 0;
static volatile int32_t encoder_b_count = 0;
static volatile uint32_t last_a_tick = 0;
static volatile uint32_t last_b_tick = 0;

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t running = 1;
static int pigpio_ready = 0;

/* ---- Function prototypes ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static void cleanup(void);
static void set_motor_speed(int motor, int pwm_value);
static int calculate_pwm(int motor, int target_rpm, int current_rpm);
static void update_motor_speed(int motor, int pwm_value);
static void set_motor_direction(int motor, int direction);
static void stop_motor(int motor);
static double calculate_rpm(int32_t *count, uint32_t *last_tick);
static void anti_windup(double *integral, double dt);

/* ---- ISR callbacks ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    if (tick >= last_a_tick) {
        encoder_a_count++;
    } else {
        encoder_a_count--;
    }
    last_a_tick = tick;
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    if (tick >= last_b_tick) {
        encoder_b_count++;
    } else {
        encoder_b_count--;
    }
    last_b_tick = tick;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (pigpio_ready) {
        stop_motor(1);
        stop_motor(2);
        gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        pigpio_ready = 0;
    }
}

/* ---- Motor helpers ---- */
static void set_motor_speed(int motor, int pwm_value)
{
    if (motor == 1) {
        if (gpioPWM(MOTOR_A_PWM, pwm_value) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", MOTOR_A_PWM);
        }
        if (gpioWrite(MOTOR_A_DIR, 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_A_DIR);
        }
    } else if (motor == 2) {
        if (gpioPWM(MOTOR_B_PWM, pwm_value) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", MOTOR_B_PWM);
        }
        if (gpioWrite(MOTOR_B_DIR, 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_B_DIR);
        }
    }
}

static void update_motor_speed(int motor, int pwm_value)
{
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    set_motor_speed(motor, pwm_value);
}

static void stop_motor(int motor)
{
    set_motor_speed(motor, 0);
}

static void set_motor_direction(int motor, int direction)
{
    if (motor == 1) {
        if (direction == 1) {
            if (gpioWrite(MOTOR_A_DIR, 1) < 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_A_DIR);
            }
        } else if (direction == -1) {
            if (gpioWrite(MOTOR_A_DIR, 0) < 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_A_DIR);
            }
        }
    } else if (motor == 2) {
        if (direction == 1) {
            if (gpioWrite(MOTOR_B_DIR, 1) < 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_B_DIR);
            }
        } else if (direction == -1) {
            if (gpioWrite(MOTOR_B_DIR, 0) < 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", MOTOR_B_DIR);
            }
        }
    }
}

/* ---- RPM calculation ---- */
static double calculate_rpm(int32_t *count, uint32_t *last_tick)
{
    uint32_t now = gpioTick();
    double dt = (double)(now - *last_tick) / 1000000.0;
    if (dt <= 0.0) dt = 0.001;

    int32_t delta = *count - *last_tick;
    *last_tick = *count;

    /* 64 ticks per revolution, 1 count per rising edge */
    return (delta / 64.0) / dt * 60.0;
}

/* ---- PI controller with anti-windup ---- */
static int calculate_pwm(int motor, int target_rpm, int current_rpm)
{
    double error = (double)target_rpm - (double)current_rpm;
    static double integral_motor[2] = {0.0, 0.0};

    integral_motor[motor] += error;
    anti_windup(&integral_motor[motor], error);

    double output = KP * error + KI * integral_motor[motor];

    if (output < 0.0) {
        output = 0.0;
    } else if (output > (double)PWM_RANGE) {
        output = (double)PWM_RANGE;
    }

    return (int)output;
}

static void anti_windup(double *integral, double dt)
{
    if (dt > 0.0) {
        *integral -= dt * PWM_RANGE;
        if (*integral < 0.0) *integral = 0.0;
    }
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_ready = 1;

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins as inputs */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM range and frequency */
    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISRs for encoder ticks */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISRs\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Speed control started. Target RPM = %d\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    int32_t enc_a_count = 0, enc_b_count = 0;
    uint32_t last_a_tick = 0, last_b_tick = 0;

    while (running) {
        /* Read current encoder counts (atomic-ish on 32-bit) */
        int32_t current_a = encoder_a_count;
        int32_t current_b = encoder_b_count;

        /* Calculate RPM */
        double rpm_a = calculate_rpm(&enc_a_count, &last_a_tick);
        double rpm_b = calculate_rpm(&enc_b_count, &last_b_tick);

        /* Calculate PWM for each motor */
        int pwm_a = calculate_pwm(1, TARGET_RPM, (int)rpm_a);
        int pwm_b = calculate_pwm(2, TARGET_RPM, (int)rpm_b);

        /* Update motor speeds */
        update_motor_speed(1, pwm_a);
        update_motor_speed(2, pwm_b);

        /* Check for stall (no encoder movement for > 2 seconds) */
        if ((uint32_t)(current_a - last_a_tick) > STALL_TIMEOUT_S * 1000000) {
            printf("Warning: Motor A (GPIO %d) stall detected\n", MOTOR_A_PWM);
            last_a_tick = current_a;
        }
        if ((uint32_t)(current_b - last_b_tick) > STALL_TIMEOUT_S * 1000000) {
            printf("Warning: Motor B (GPIO %d) stall detected\n", MOTOR_B_PWM);
            last_b_tick = current_b;
        }

        printf("Motor A: PWM=%3d  RPM=%6.2f  |  Motor B: PWM=%3d  RPM=%6.2f\n",
               pwm_a, rpm_a, pwm_b, rpm_b);

