#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define LUX_THRESHOLD_DAWN 200
#define LUX_THRESHOLD_DUSK 50
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int read_lux(int handle, int *lux_out) {
    char cmd = BH1750_ONE_TIME_HIGH_RES_MODE_2;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }
    gpioDelay(BH1750_MEASUREMENT_DELAY_US);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | (unsigned int)buf[1];
    *lux_out = (int)(raw / 1.2f);
    return 0;
}

void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    log_message("System started");

    while (running) {
        int lux;
        if (read_lux(i2c_handle, &lux) != 0) {
            log_message("Error reading lux value from BH1750");
            control_relay(0);
            relay_state = 0;
        } else {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Lux = %d", lux);
            log_message(log_buffer);

            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_message("Dusk detected, turning relay ON");
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_message("Dawn detected, turning relay OFF");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    log_message("Shutting down");
    cleanup();
    return 0;
}

