#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define MAIN_LOOP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int last_touch = 0;
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input (code %d).\n",
                TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (code %d).\n",
                RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure relay starts OFF --- */
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO %d (code %d).\n",
                RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to install SIGINT handler");
    }

    printf("Touch-controlled relay started. Touch GPIO %d toggles GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main loop --- */
    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d (code %d).\n",
                    TOUCH_SENSOR_PIN, touch);
            break;
        }

        /* Detect rising edge: touch press (HIGH) */
        if (touch == 1 && last_touch == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            /* Re-read after debounce to confirm the touch is still active */
            touch = gpioRead(TOUCH_SENSOR_PIN);
            if (touch < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce (code %d).\n",
                        TOUCH_SENSOR_PIN, touch);
                break;
            }
            if (touch == 1) {
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d (code %d).\n",
                            RELAY_PIN, ret);
                    break;
                }
                log_state(relay_state);
            }
        }

        last_touch = touch;
        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

