#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define DEBOUNCE_SECONDS 1
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE_NAME "water_flow.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static int solenoid_state = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level != 1) return;
    uint32_t diff = tick - last_pulse_tick;
    if (diff > DEBOUNCE_SECONDS * 1000000) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        last_pulse_tick = tick;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_flow_rate(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static int set_solenoid(int state) {
    if (state == solenoid_state) return 0;
    if (gpioWrite(SOLENOID_GPIO, state) != 0) {
        log_event("ERROR: gpioWrite failed for solenoid");
        return -1;
    }
    solenoid_state = state;
    log_event(state ? "Solenoid OPEN" : "Solenoid CLOSED");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("fopen log");
        gpioWrite(SOLENOID_GPIO, 1);
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_SECONDS, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        fclose(log_file);
        gpioWrite(SOLENOID_GPIO, 1);
        gpioTerminate();
        return 1;
    }

    while (running) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow = calculate_flow_rate(pulses);

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f L/min", flow);
        log_event(msg);

        if (flow > FLOW_THRESHOLD_HIGH) {
            set_solenoid(0);
        } else if (flow < FLOW_THRESHOLD_LOW) {
            set_solenoid(1);
        }
    }

    log_event("Shutting down");
    set_solenoid(1);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

