static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);

    return 0;
}

static int read_hx711(void) {
    int data = 0;
    int i;

    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < HX711_TIMEOUT_ATTEMPTS; i++) {
        if (gpioRead(HX711_DATA_PIN) == 0) {
            break;
        }
        gpioDelay(HX711_TIMEOUT_DELAY_US);
        if (i == HX711_TIMEOUT_ATTEMPTS - 1) {
            fprintf(stderr, "Error: HX711 not ready (DATA stuck HIGH).\n");
            return -1;
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid servo pulse width: %d\n", pulse_width);
        return -1;
    }
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

static int dispense_ingredient(double target_weight) {
    int pulse_width = (int)target_weight * 100 + SERVO_NEUTRAL_PULSE_WIDTH;
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;

    if (set_servo_pulse_width(pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }

    gpioDelay(SERVO_OPEN_DELAY_US);
    gpioServo(SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    gpioDelay(SERVO_CLOSE_DELAY_US);

    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char json_string[512];
    snprintf(json_string, sizeof(json_string),
             "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
             timestamp, target_weight, actual_weight, error_message ? error_message : "None");

    if (fputs(json_string, log_file) == EOF) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    read_config("config.ini");

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s.\n", DEFAULT_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t addrlen = sizeof(client_address);
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (client_fd < 0) {
            if (running) perror("accept failed");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection accepted from %s:%d\n", client_ip, ntohs(client_address.sin_port));

        char buffer[MAX_BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, MAX_BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("recv failed");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[bytes_received] = '\0';

        printf("Received: %s\n", buffer);

        double target_weight = atof(buffer);

        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed.\n");
            log_dispensing_event(target_weight, 0.0, "HX711 read failed");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        double actual_weight = calibrate_weight(raw_value);

        gpioDelay(LOAD_CELL_STABILIZE_DELAY_US);

        if (dispense_ingredient(target_weight) != 0) {
            fprintf(stderr, "Error: Dispensing failed.\n");
            log_dispensing_event(target_weight, actual_weight, "Dispensing failed");
        } else {
            printf("Dispensed: %.2f grams\n", actual_weight);
            log_dispensing_event(target_weight, actual_weight, NULL);
        }

        const char *response = target_weight == actual_weight ? "OK" : "ERROR";
        send(client_fd, response, strlen(response), 0);

        close(client_fd);
        client_fd = -1;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

