#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static void toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for relay GPIO %d\n", RELAY_GPIO);
        return;
    }
    log_relay_state(relay_state);
}

static void parse_arguments(int argc, char *argv[]) {
    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 1000) {
            fprintf(stderr, "Warning: invalid debounce value '%s'. Using default %d ms.\n", argv[1], DEFAULT_DEBOUNCE_MS);
        } else {
            debounce_ms = (int)val;
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Touch-controlled desk lamp started. Touch GPIO %d to toggle relay GPIO %d.\n", TOUCH_SENSOR_GPIO, RELAY_GPIO);
    printf("Debounce: %d ms. Press Ctrl+C to exit.\n", debounce_ms);
    fflush(stdout);

    int last_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: gpioRead failed for touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(debounce_ms * 1000);
            if (running) {
                touch_state = gpioRead(TOUCH_SENSOR_GPIO);
                if (touch_state < 0) {
                    fprintf(stderr, "Error: gpioRead failed for touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
                    break;
                }
                if (touch_state == 1) {
                    toggle_relay();
                }
            }
        }
        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

