#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define PWM_FREQ_HZ    50
#define PWM_PERIOD_US  20000   /* 50 Hz -> 20 ms period */
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define INITIAL_ANGLE  90
#define STEP           10

static volatile sig_atomic_t g_running = 1;
static int g_termios_saved = 0;
static struct termios g_termios_orig;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int restore_terminal_settings(void)
{
    if (g_termios_saved) {
        if (tcsetattr(STDIN_FILENO, TCSANOW, &g_termios_orig) != 0) {
            perror("tcsetattr");
            return -1;
        }
        g_termios_saved = 0;
    }
    return 0;
}

static int save_terminal_settings(void)
{
    if (tcgetattr(STDIN_FILENO, &g_termios_orig) != 0) {
        perror("tcgetattr");
        return -1;
    }
    g_termios_saved = 1;
    return 0;
}

static int angle_to_pulse_us(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return MIN_PULSE_US + (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / 180);
}

int main(void)
{
    int angle = INITIAL_ANGLE;
    int rc;

    /* --- pigpio init --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGQUIT, &sa, NULL) != 0) {
        perror("sigaction(SIGQUIT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- terminal raw mode --- */
    if (save_terminal_settings() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- servo on GPIO18 --- */
    rc = gpioSetMode(SERVO_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode failed (code %d)\n", rc);
        restore_terminal_settings();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioServo(SERVO_PIN, angle_to_pulse_us(angle));
    if (rc != 0) {
        fprintf(stderr, "gpioServo initial set failed (code %d)\n", rc);
        restore_terminal_settings();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo on GPIO%d at %d degrees (pulse %d us).\n",
           SERVO_PIN, angle, angle_to_pulse_us(angle));
    printf("Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    /* --- main loop --- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (feof(stdin)) break;          /* end of input */
            continue;
        }

        switch (c) {
        case '+':
            angle += STEP;
            if (angle > 180) angle = 180;
            break;
        case '-':
            angle -= STEP;
            if (angle < 0) angle = 0;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            /* consume */
            break;
        }

        int pw = angle_to_pulse_us(angle);
        if (pw < MIN_PULSE_US || pw > MAX_PULSE_US) {
            fprintf(stderr, "Pulse width %d us out of range [%d, %d]\n",
                    pw, MIN_PULSE_US, MAX_PULSE_US);
            break;
        }

        rc = gpioServo(SERVO_PIN, pw);
        if (rc != 0) {
            fprintf(stderr, "gpioServo update failed (code %d)\n", rc);
            break;
        }

        printf("Angle: %d degrees  (pulse %d us)\n", angle, pw);
        fflush(stdout);
    }

    /* --- cleanup --- */
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    restore_terminal_settings();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

