    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (feof(stdin)) break;          /* end of input */
            continue;
        }

        switch (c) {
        case '+':
            angle += STEP;
            if (angle > 180) angle = 180;
            break;
        case '-':
            angle -= STEP;
            if (angle < 0) angle = 0;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            /* consume */
            break;
        }

        int pw = angle_to_pulse_us(angle);
        if (pw < MIN_PULSE_US || pw > MAX_PULSE_US) {
            fprintf(stderr, "Pulse width %d us out of range [%d, %d]\n",
                    pw, MIN_PULSE_US, MAX_PULSE_US);
            break;
        }

        rc = gpioServo(SERVO_PIN, pw);
        if (rc != 0) {
            fprintf(stderr, "gpioServo update failed (code %d)\n", rc);
            break;
        }

        printf("Angle: %d degrees  (pulse %d us)\n", angle, pw);
        fflush(stdout);
    }

    /* --- cleanup --- */
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    restore_terminal_settings();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

