#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17
#define LOG_FILE_NAME       "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_NS         2000000L   /* 2 ms */
#define PULSES_PER_REV      1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static double calculate_rpm(unsigned long pulseCount, double elapsedSec)
{
    if (elapsedSec <= 0.0)
        return 0.0;
    return ((double)pulseCount / elapsedSec) * 60.0;
}

static int log_rpm(FILE *fp, double rpm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld,%.2f\n", timestamp, ts.tv_nsec / 1000000L, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *logFile = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get GPIO line --- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* --- Request line as input with pull-up bias --- */
    /* A3144 has an open-collector output; enable the internal pull-up. */
    if (gpiod_line_request_input_flags(line, "motor_rpm",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* --- Open log file --- */
    logFile = fopen(LOG_FILE_NAME, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring motor RPM on GPIO %d (BCM). Press Ctrl+C to stop.\n", GPIO_LINE_OFFSET);

    struct timespec lastEvent = {0, 0};
    unsigned long pulseCount = 0;
    struct timespec sleepTime = {SAMPLE_INTERVAL_SEC, 0};

    while (g_running) {
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            fprintf(stderr, "clock_gettime(CLOCK_MONOTONIC) failed: %s\n", strerror(errno));
            break;
        }

        /* Sleep for the sample interval (interruptible by signals) */
        if (nanosleep(&sleepTime, NULL) != 0) {
            if (errno == EINTR) {
                if (!g_running)
                    break;
                continue;
            }
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }

        /* Read all pending edge events with a 2 ms debounce window */
        struct timespec debounceDeadline = {0, DEBOUNCE_NS};
        int numEvents = gpiod_line_event_wait(line, &debounceDeadline);
        if (numEvents < 0) {
            if (errno == EINTR) {
                if (!g_running)
                    break;
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < numEvents; i++) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) != 0) {
                fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pulseCount++;
            }
        }

        /* --- Log and print every sample interval --- */
        double rpm = calculate_rpm(pulseCount, (double)now.tv_sec - (double)lastEvent.tv_sec);

        if (log_rpm(logFile, rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("RPM: %.2f\n", rpm);

        lastEvent = now;
    }

    ret = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (logFile != NULL) {
        fclose(logFile);
    }
cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return ret;
}

