#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000   /* 50 ms */
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with the relay OFF (active-HIGH module). */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        safe_write(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int touch_active = 0;
    time_t touch_start = 0;

    while (running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            break;
        }

        if (touch == 1) {
            if (!touch_active) {
                touch_active = 1;
                touch_start = time(NULL);
            } else {
                if (difftime(time(NULL), touch_start) > FAILSAFE_TIMEOUT_S) {
                    fprintf(stderr,
                            "Failsafe: sensor HIGH for >%d s — forcing relay OFF\n",
                            FAILSAFE_TIMEOUT_S);
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        break;
                    }
                    relay_state = 0;
                    touch_active = 0;
                }
            }
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                break;
            }
        } else {
            touch_active = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup: ensure relay is OFF and release pigpio. */
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

