#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000   /* Hz */
#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */

#define FLOW_CALIBRATION   450.0  /* pulses per liter (YF-S201) */
#define KP                 1.0
#define MAX_FLOW_RATE      10.0   /* L/min */

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin %d as output.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set enable pin %d as output.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on flow sensor pin %d.\n", FLOW_SENSOR_PIN);
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve on pin %d.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on flow sensor pin %d.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static double calculate_flow_rate(int pulses, double interval_s)
{
    if (interval_s <= 0.0) {
        return 0.0;
    }
    return ((double)pulses / FLOW_CALIBRATION) / interval_s;
}

static int control_valve(double target_flow_rate, double current_flow_rate, double *valve_position)
{
    double error = target_flow_rate - current_flow_rate;
    double adjustment = KP * error;

    *valve_position += adjustment;

    if (*valve_position < 0.0) {
        *valve_position = 0.0;
    } else if (*valve_position > (double)PWM_RANGE) {
        *valve_position = (double)PWM_RANGE;
    }

    if (gpioPWM(VALVE_PWM_PIN, (int)(*valve_position + 0.5)) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
        return -1;
    }

    return 0;
}

static void log_data(double flow_rate, double valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);

    if (fprintf(g_log_file, "%ld,%.2f,%.2f\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
    }
    if (fflush(g_log_file) != 0) {
