#define FLOW_CALIBRATION   450.0  /* pulses per liter (YF-S201) */
#define KP                 1.0
#define MAX_FLOW_RATE      10.0   /* L/min */

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin %d as output.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set enable pin %d as output.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on flow sensor pin %d.\n", FLOW_SENSOR_PIN);
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on pin %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
