#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN_1           17
#define LOCK_PIN_2           27
#define BUTTON_PIN           22
#define SPI_CHANNEL          0
#define SPI_SPEED            100000
#define SPI_READ_LEN         10
#define RFID_TAG_LEN         10
#define VALID_TAG            {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0A}
#define UNLOCK_DURATION_US   5000000
#define POLL_DELAY_US        100000
#define DEBOUNCE_US          50000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log);
    }
}

static int read_rfid(unsigned char *data) {
    if (!data || data < RFID_TAG_LEN) return -1;
    char tx[SPI_READ_LEN] = {0};
    char rx[SPI_READ_LEN] = {0};
    int ret = spiXfer(g_spi_handle, tx, rx, SPI_READ_LEN);
    if (ret != SPI_READ_LEN) return -1;
    for (int i = 0; i < RFID_TAG_LEN; i++)
        data[i] = (unsigned char)rx[i];
    return 0;
}

static int authenticate(void) {
    unsigned char tag[RFID_TAG_LEN];
    if (read_rfid(tag) != 0) {
        log_event("RFID read failure");
        return 0;
    }
    if (memcmp(tag, VALID_TAG, RFID_TAG_LEN) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Invalid RFID tag: %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X",
                 tag[0], tag[1], tag[2], tag[3], tag[4], tag[5], tag[6], tag[7], tag[8], tag[9]);
        log_event(msg);
        return 0;
    }
    log_event("RFID tag validated");
    gpioDelay(DEBOUNCE_US);
    if (gpioRead(BUTTON_PIN) != 0) return 0;
    gpioDelay(DEBOUNCE_US);
    if (gpioRead(BUTTON_PIN) != 0) return 0;
    log_event("Button pressed");
    return 1;
}

static void unlock_locks(void) {
    if (gpioWrite(LOCK_PIN_1, 0) != 0) {
        log_event("Failed to unlock lock 1");
        return;
    }
    if (gpioWrite(LOCK_PIN_2, 0) != 0) {
        log_event("Failed to unlock lock 2");
        gpioWrite(LOCK_PIN_1, 1);
        return;
    }
    log_event("Locks unlocked");
    gpioDelay(UNLOCK_DURATION_US);
    if (gpioWrite(LOCK_PIN_1, 1) != 0) log_event("Failed to re-lock lock 1");
    if (gpioWrite(LOCK_PIN_2, 1) != 0) log_event("Failed to re-lock lock 2");
    log_event("Locks re-locked");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_log = fopen("/var/log/door_access.log", "a");
    if (!g_log) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        log_event("SPI open failed");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        log_event("GPIO mode set failed");
        spiClose(g_spi_handle);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    if (gpioWrite(LOCK_PIN_1, 1) != 0 || gpioWrite(LOCK_PIN_2, 1) != 0) {
        log_event("Failed to engage locks on startup");
        spiClose(g_spi_handle);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_event("Door access system started");
    while (g_running) {
        if (authenticate()) {
            log_event("Access granted");
            unlock_locks();
        }
        gpioDelay(POLL_DELAY_US);
    }
    log_event("Shutting down");
    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);
    spiClose(g_spi_handle);
    fclose(g_log);
    gpioTerminate();
    return EXIT_SUCCESS;
}

