static volatile int enc_last_dir[2] = {0, 0};

static double integral[2] = {0.0, 0.0};
static double prev_error[2] = {0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double m1_sp, double m1_pi, double m1_di,
                     double m2_sp, double m2_pi, double m2_di,
                     double m1_speed, double m2_speed) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s.%03ld,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tbuf, ts.tv_nsec / 1000000,
            m1_sp, m1_pi, m1_di,
            m2_sp, m2_pi, m2_di,
            m1_speed, m2_speed);
    fflush(log_file);
}

static void *encoder_thread(void *arg) {
    int id = *(int *)arg;
    struct gpiod_line *a = enc_a_lines[id];
    struct gpiod_line *b = enc_b_lines[id];
    int *count = &enc_counts[id];
    int *dir = &enc_last_dir[id];
    int prev_state = -1;

    while (running) {
        int cur = gpiod_line_get_value(a);
        if (cur < 0) {
            fprintf(stderr, "Error reading encoder A pin %d: %s\n", id, strerror(errno));
            usleep(10000);
            continue;
        }
        int b_val = gpiod_line_get_value(b);
        if (b_val < 0) {
            fprintf(stderr, "Error reading encoder B pin %d: %s\n", id, strerror(errno));
            usleep(10000);
            continue;
        }

        int delta = cur - prev_state;
        prev_state = cur;

        if (delta == 2) {
            *count += ENCODER_PPR;
            *dir = 1;
        } else if (delta == -2) {
            *count -= ENCODER_PPR;
            *dir = -1;
        }
        /* delta == 0 or 1 handled by software PWM timing */

        usleep(100);
    }
    return NULL;
}

static void motor_stop(int idx) {
    if (motor_lines[idx]) {
        gpiod_line_set_value(motor_lines[idx], 0);
    }
}

static void motor_drive(int idx, double speed) {
    if (speed > 1.0) speed = 1.0;
    if (speed < -1.0) speed = -1.0;

    int in1_val = (speed > 0) ? 1 : 0;
    int in2_val = (speed < 0) ? 1 : 0;

    gpiod_line_set_value(motor_lines[idx], 1);
    gpiod_line_set_value(motor_lines[idx + 3], 0);
    gpiod_line_set_value(motor_lines[idx + 4], in2_val);
    gpiod_line_set_value(motor_lines[idx + 5], in1_val);
}

static double pid_calc(double setpoint, double measured, double *integral, double *prev_error) {
    double error = setpoint - measured;
    *integral += error;
    double derivative = error - *prev_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2,
                         MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    int enc_a_pins[2] = {ENCODER1_A, ENCODER2_A};
    int enc_b_pins[2] = {ENCODER1_B, ENCODER2_B};

    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 2; i++) {
        enc_a_lines[i] = gpiod_chip_get_line(chip, enc_a_pins[i]);
        enc_b_lines[i] = gpiod_chip_get_line(chip, enc_b_pins[i]);
        if (!enc_a_lines[i] || !enc_b_lines[i]) {
            fprintf(stderr, "Failed to get encoder line for A/B %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_both_edges_events(enc_a_lines[i], "encoder_a") < 0) {
            fprintf(stderr, "Failed to request edge events on encoder A %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(enc_b_lines[i], "encoder_b") < 0) {
            fprintf(stderr, "Failed to request input on encoder B %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
        pthread_mutex_init(&enc_mutex[i], NULL);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }
    fprintf(log_file, "Timestamp,Motor1_Target_RPM,Motor1_PID_P,Motor1_PID_I,Motor1_PID_D,"
                      "Motor2_Target_RPM,Motor2_PID_P,Motor2_PID_I,Motor2_PID_D,Motor1_Speed_RPM,Motor2_Speed_RPM\n");

    pthread_t tid[2];
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&tid[i], NULL, encoder_thread, &i) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        int cur_count[2];
        for (int i = 0; i < 2; i++) {
            pthread_mutex_lock(&enc_mutex[i]);
            cur_count[i] = enc_counts[i];
            pthread_mutex_unlock(&enc_mutex[i]);
        }

        double m1_speed = (double)cur_count[0] / SAMPLE_INTERVAL_US * 60.0 / ENCODER_PPR;
        double m2_speed = (double)cur_count[1] / SAMPLE_INTERVAL_US * 60.0 / ENCODER_PPR;

        double m1_target = TARGET_RPM;
        double m2_target = TARGET_RPM;

        double m1_pi = pid_calc(m1_target, m1_speed, &integral[0], &prev_error[0]);
        double m2_pi = pid_calc(m2_target, m2_speed, &integral[1], &prev_error[1]);

        motor_drive(0, m1_pi);
        motor_drive(3, m2_pi);

        log_data(m1_target, m1_pi, m1_pi, m1_speed, m2_speed);

        usleep(SAMPLE_INTERVAL_US);
    }

cleanup:
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_set_value(motor_lines[i], 0);
            gpiod_line_release(motor_lines[i]);
        }
    }
    for (int i = 0; i < 2; i++) {
        if (enc_a_lines[i]) gpiod_line_release(enc_a_lines[i]);
        if (enc_b_lines[i]) gpiod_line_release(enc_b_lines[i]);
        pthread_mutex_destroy(&enc_mutex[i]);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return 0;
}

