#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35
#define MPR121_TOUCHTH_0     0x41
#define MPR121_RELEASETH_0   0x42

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms */

    /* Configuration registers */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1; /* FFI=6 samples, CDC=16 µA */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1; /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */

    /* Filtering registers */
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write_reg(handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) return -1;
    }

    /* Enable 12 electrodes in run mode: ECR = 0b11000000 = 0xC0 */
    if (mpr121_write_reg(handle, MPR121_ECR, 0xC0) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "Error reading touch status low: %d\n", low);
        return -1;
    }
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "Error reading touch status high: %d\n", high);
        return -1;
    }
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Relay state: %s\n", s, state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int relay_state = 0;
    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            gpioDelay(50000);
            continue;
        }

        int any_touched = (touch_status & 0x0FFF) ? 1 : 0;

        if (any_touched && !relay_state) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_relay_state(relay_state);
            printf("Relay ON (touch detected)\n");
        } else if (!any_touched && relay_state) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_relay_state(relay_state);
            printf("Relay OFF (no touch)\n");
        }

        gpioDelay(50000); /* 50 ms */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

