#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("gpiod_chip_get_line VALVE1");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("gpiod_chip_get_line VALVE2");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "water_valve", 0) < 0) {
        perror("gpiod_line_request_output VALVE1");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, "water_valve", 0) < 0) {
        perror("gpiod_line_request_output VALVE2");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Watering schedule started.");

    while (running) {
        log_event("Activating Valve 1 for 500ms.");
        if (gpiod_line_set_value(valve1_line, 1) < 0) {
            perror("gpiod_line_set_value VALVE1 ON");
            break;
        }
        usleep(500000);
        if (!running) break;
        if (gpiod_line_set_value(valve1_line, 0) < 0) {
            perror("gpiod_line_set_value VALVE1 OFF");
            break;
        }
        usleep(5000000);

        log_event("Activating Valve 2 for 1000ms.");
        if (gpiod_line_set_value(valve2_line, 1) < 0) {
            perror("gpiod_line_set_value VALVE2 ON");
            break;
        }
        usleep(1000000);
        if (!running) break;
        if (gpiod_line_set_value(valve2_line, 0) < 0) {
            perror("gpiod_line_set_value VALVE2 OFF");
            break;
        }
        usleep(10000000);
    }

    log_event("Watering schedule stopped.");
    cleanup();
    return EXIT_SUCCESS;
}

