#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_NHD_FILT 0x33
#define MPR121_NCL_FILT 0x34
#define MPR121_FDL_FILT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_STOP 0x20
#define MPR121_RUN 0x10

static volatile int running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(handle, MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_FILT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_FILT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_FILT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + (i * 2), 0x10) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(handle, MPR121_ECR, MPR121_STOP) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(handle, MPR121_ECR, MPR121_RUN) < 0) return -1;
    gpioDelay(100000);

    return 0;
}

int read_touch_status(int handle) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (low < 0 || high < 0) {
        fprintf(stderr, "Error reading touch status: %d\n", low < 0 ? low : high);
        return -1;
    }
    return (high << 8) | low;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0;
    while (running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status > 0) {
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);
            printf("Relay toggled to state: %d\n", relay_state);
        }
        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

