#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void log_event(const char *event_type, const char *additional_info) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        long ms = ts.tv_nsec / 1000000;
        fprintf(log_file, "%s.%03ld: %s %s\n", timestamp, ms, event_type, additional_info);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        pthread_mutex_lock(&log_mutex);
        fclose(log_file);
        log_file = NULL;
        pthread_mutex_unlock(&log_mutex);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        log_event("ERROR", "Failed to activate relay");
        return;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_event("ERROR", "Failed to deactivate relay");
    }
    log_event("Door unlocked", NULL);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set PIR pull-down\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to off\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");
    log_event("System started", NULL);

    int last_pir = 0;
    uint32_t last_trigger_time = 0;

    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            log_event("ERROR", "Failed to read PIR sensor");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1 && last_pir == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_time >= (uint32_t)(RATE_LIMIT_MS * 1000)) {
                unlock_door();
                last_trigger_time = now;
            } else {
                log_event("Motion detected, rate limited", "Event ignored due to rate limit");
            }
        }
        last_pir = pir_value;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down", NULL);
    cleanup();
    return 0;
}

