#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_RANGE 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15

typedef struct {
    int motor1_duty;
    int motor2_duty;
    int duration_ms;
} PatternStep;

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void generate_random_pattern(PatternStep *pattern, int *step_count) {
    *step_count = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    for (int i = 0; i < *step_count; i++) {
        pattern[i].motor1_duty = rand() % (PWM_RANGE + 1);
        pattern[i].motor2_duty = rand() % (PWM_RANGE + 1);
        pattern[i].duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
}

static void play_pattern(const PatternStep *pattern, int step_count) {
    for (int i = 0; i < step_count; i++) {
        if (shutdown_flag) break;

        if (gpioPWM(MOTOR1_PIN, pattern[i].motor1_duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d.\n", MOTOR1_PIN);
        }
        if (gpioPWM(MOTOR2_PIN, pattern[i].motor2_duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d.\n", MOTOR2_PIN);
        }

        gpioDelay(pattern[i].duration_ms * 1000);
    }
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    PatternStep *pattern = (PatternStep *)malloc((size_t)MAX_STEPS * sizeof(PatternStep));
    if (pattern == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern array.\n");
        gpioTerminate();
        return 1;
    }

    while (!shutdown_flag) {
        int step_count;
        generate_random_pattern(pattern, &step_count);

        if (step_count > 0) {
            play_pattern(pattern, step_count);
        }
    }

    stop_motors();
    free(pattern);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return 0;
}

