#define WEIGHT_LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000

static double scale_factor = 1.0;
static double offset = 0.0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(void) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_CLOCK_PIN, 0);

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(100);
        if (++timeout > READ_TIMEOUT_US / 100) {
            fprintf(stderr, "HX711 read timeout\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static double calibrate_hx711(void) {
    double sum = 0.0;
    int valid = 0;

    printf("Calibrating HX711 (ensure no weight on load cell)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711();
        if (raw == -1) {
            fprintf(stderr, "Calibration read failed at iteration %d\n", i);
            continue;
        }
        sum += raw;
        valid++;
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1.0;
    }

    offset = sum / valid;
    scale_factor = 1.0;

    printf("Calibration complete. Offset: %.2f, Scale: %.2f\n", offset, scale_factor);
    return offset;
}

static double convert_to_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

static void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Weight %.2f kg exceeds threshold %.2f kg. Lock engaged.\n", weight, WEIGHT_THRESHOLD);
    } else {
        gpioWrite(SOLENOID_PIN, 0);
        printf("Weight %.2f kg below threshold %.2f kg. Lock released.\n", weight, WEIGHT_THRESHOLD);
    }
}

static void log_weight(double weight) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", WEIGHT_LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", s, weight);
    fclose(fp);
}

static void save_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
}

static void load_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        printf("Calibration file not found. Using defaults.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        printf("Invalid calibration data. Using defaults.\n");
        scale_factor = 1.0;
        offset = 0.0;
    } else {
        printf("Calibration data loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    load_calibration_data();

    if (calibrate_hx711() != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    save_calibration_data();

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            gpioDelay(500000);
            continue;
        }

        double weight = convert_to_weight(raw_value);
        control_solenoid(weight);
        log_weight(weight);

        gpioDelay(500000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

