        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE);
    gpioPWM(MOTOR_PWM_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Window control system started");

    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected, closing window");
            close_window();
            log_event("Window closed");
            gpioDelay(CHECK_INTERVAL_US);
        } else {
            log_event("No rain detected");
            gpioDelay(CHECK_INTERVAL_US);
        }
    }

    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    log_event("Window control system stopped");
    closelog();
    return EXIT_SUCCESS;
}

