#define LOG_FILE "stock_events.txt"
#define WEIGHT_SCALE_FACTOR 1000.0
#define READ_TIMEOUT_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(void) {
    int32_t data = 0;
    int timeout = 0;

    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    while (gpioRead(HX711_DT_PIN)) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout)\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DT_PIN)) {
