}

static int control_solenoid(int activate) {
    if (gpioWrite(SOLENOID_PIN, activate) != 0) {
        fprintf(stderr, "Error: Failed to write to solenoid pin\n");
        return -1;
    }
    if (activate) {
        gpioDelay(SOLENOID_DURATION * 1000000);
        if (gpioWrite(SOLENOID_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to deactivate solenoid\n");
            return -1;
        }
    }
    return 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

