    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0 ||
