    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Ingredient stock monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = convert_to_grams(raw_value);
        printf("Weight: %.2f g\n", weight);

        if (weight < STOCK_THRESHOLD) {
            printf("Stock level below threshold. Activating solenoid.\n");
