                log_event("Solenoid activated");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

