#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_TIMEOUT_US 100000
#define READ_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *raw_value) {
    if (raw_value == NULL) return -1;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_tick > CALIBRATION_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout).\n");
            return -1;
        }
        gpioDelay(100);
    }

    int32_t data = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *raw_value = data;
    return 0;
}

static double read_weight(void) {
    int32_t raw;
    if (read_hx711(&raw) != 0) {
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int calibrate_load_cell(void) {
    double known_weight;
    printf("Place a known weight on the load cell (e.g., 1 kg): ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid weight entered.\n");
        while (getchar() != '\n');
        return -1;
    }

    int32_t raw;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Error reading raw value during calibration.\n");
        return -1;
    }

    calibration_factor = raw / known_weight;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("Error opening calibration file");
        return -1;
    }

    if (fprintf(fp, "%lf\n", calibration_factor) < 0) {
        perror("Error writing calibration factor to file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing calibration file");
        return -1;
    }

    printf("Calibration complete. Factor: %.2lf\n", calibration_factor);
    return 0;
}

static int log_security_event(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
