#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        perror("gpiod_line_request_input");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val == 1) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_file, "%s Motion detected\n", timestamp);
                fflush(log_file);
            } else {
                fprintf(stderr, "localtime failed\n");
            }

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value (on)");
                break;
            }

            usleep(BUZZER_DURATION_MS * 1000);

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value (off)");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

