#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE "watering.conf"
#define MAX_LINE_LEN 256
#define MAX_DURATION 3600

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_config(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[MAX_LINE_LEN];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Config file is empty\n");
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Config file format error: expected 'duration=<value>' (got '%s')\n", line);
        return -1;
    }

    char *val_start = eq + 1;
    while (*val_start == ' ' || *val_start == '\t') val_start++;

    char *endptr = NULL;
    long val = strtol(val_start, &endptr, 10);
    if (endptr == val_start) {
        fprintf(stderr, "Config value is not a valid integer\n");
        return -1;
    }

    if (val < 1 || val > MAX_DURATION) {
        fprintf(stderr, "Config value %ld out of range (1-%d)\n", val, MAX_DURATION);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (read_config(CONFIG_FILE, &duration) != 0)
        goto cleanup;

    printf("Watering system started. Valve on GPIO%d for %d seconds.\n",
           GPIO_LINE_OFFSET, duration);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve ON\n");
    fflush(stdout);

    for (int i = 0; i < duration && !g_stop; i++)
        sleep(1);

    if (g_stop) {
        fprintf(stderr, "Interrupted by signal. Shutting down.\n");
    } else {
        printf("Watering complete.\n");
    }
    fflush(stdout);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve OFF\n");
    fflush(stdout;
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

