#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Sensor GPIO pins (active-low: 0 = black line detected) */
#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27

/* Motor PWM GPIO pins (L298N IN1, IN2, IN3, IN4) */
#define MOTOR_LEFT_PWM  22
#define MOTOR_RIGHT_PWM 23
#define MOTOR_LEFT_DIR  24
#define MOTOR_RIGHT_DIR 25

/* Control parameters */
#define BASE_SPEED      150
#define TURN_MULTIPLIER 0.5
#define LOOP_DELAY_US   10000  /* 10 ms */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set_pwm(int pin, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    if (gpioPWM(pin, speed) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (motor_set_pwm(MOTOR_LEFT_PWM, 0) < 0) return -1;
    if (motor_set_pwm(MOTOR_RIGHT_PWM, 0) < 0) return -1;
    return 0;
}

static int motor_drive(int left_speed, int right_speed)
{
    if (motor_set_pwm(MOTOR_LEFT_PWM, left_speed) < 0) return -1;
    if (motor_set_pwm(MOTOR_RIGHT_PWM, right_speed) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Control logic                                                       */
/* ------------------------------------------------------------------ */
static int control_loop(int left, int middle, int right)
{
    int left_speed  = 0;
    int right_speed = 0;

    if (left == 0 && middle == 1 && right == 1) {
        /* Black line centered: drive straight */
        left_speed  = BASE_SPEED;
        right_speed = BASE_SPEED;
    } else if (left == 0 && middle == 1 && right == 0) {
        /* Left sensor only: turn right */
        left_speed  = (int)(BASE_SPEED * TURN_MULTIPLIER);
        right_speed = BASE_SPEED;
    } else if (left == 1 && middle == 0 && right == 1) {
        /* Right sensor only: turn left */
        left_speed  = BASE_SPEED;
        right_speed = (int)(BASE_SPEED * TURN_MULTIPLIER);
    } else if (left == 1 && middle == 0 && right == 0) {
        /* No sensor: stop */
        left_speed  = 0;
        right_speed = 0;
    } else {
        /* Invalid state: stop */
        left_speed  = 0;
        right_speed = 0;
    }

    if (motor_drive(left_speed, right_speed) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(int left, int middle, int right, int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
                timestamp, left, middle, right, left_speed, right_speed) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_LEFT,   PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT,  PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor pins: PWM as output, direction as input */
    if (gpioSetMode(MOTOR_LEFT_PWM,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_DIR,  PI_INPUT)  < 0 ||
        gpioSetMode(MOTOR_RIGHT_DIR, PI_INPUT)  < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motors are stopped at startup */
    if (motor_stop() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open trace_log.txt: %s\n", strerror(errno));
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,left,middle,right,left_speed,right_speed\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line follower started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        int left   = read_sensor(SENSOR_LEFT);
        int middle = read_sensor(SENSOR_MIDDLE);
        int right  = read_sensor(SENSOR_RIGHT);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error; stopping motors.\n");
            motor_stop();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (control_loop(left, middle, right) < 0) {
            fprintf(stderr, "Motor control error.\n");
        }

        if (log_data(left, middle, right, 0, 0) < 0) {
            fprintf(stderr, "Logging error.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    motor_stop();
    cleanup();
    return EXIT_SUCCESS;
}

