    if (gpioSetMode(MOTOR_LEFT_PWM,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_DIR,  PI_INPUT)  < 0 ||
        gpioSetMode(MOTOR_RIGHT_DIR, PI_INPUT)  < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motors are stopped at startup */
    if (motor_stop() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open trace_log.txt: %s\n", strerror(errno));
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,left,middle,right,left_speed,right_speed\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line follower started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        int left   = read_sensor(SENSOR_LEFT);
        int middle = read_sensor(SENSOR_MIDDLE);
        int right  = read_sensor(SENSOR_RIGHT);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error; stopping motors.\n");
            motor_stop();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (control_loop(left, middle, right) < 0) {
            fprintf(stderr, "Motor control error.\n");
        }

        if (log_data(left, middle, right, 0, 0) < 0) {
            fprintf(stderr, "Logging error.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    motor_stop();
    cleanup();
    return EXIT_SUCCESS;
}

