#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_lux(int handle, int *lux_out) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, BH1750_CONT_HIGH_RES);
    if (rc < 0) {
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

static void log_event(const char *event_type, int lux, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld - %s - Lux: %d, Relay: %s\n",
            timestamp, ts.tv_nsec / 1000000,
            event_type, lux,
            relay_state ? "ON" : "OFF");

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int last_relay_state = -1;

    while (running) {
        int lux = -1;
        if (read_lux(i2c_handle, &lux) == 0) {
            if (lux < LUX_THRESHOLD) {
                if (gpioRead(RELAY_GPIO) == 0) {
                    gpioWrite(RELAY_GPIO, 1);
                    log_event("Grow lamp ON", lux, 1);
                    last_relay_state = 1;
                }
            } else {
                if (gpioRead(RELAY_GPIO) == 1) {
                    gpioWrite(RELAY_GPIO, 0);
                    log_event("Grow lamp OFF", lux, 0);
                    last_relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
            log_event("Error reading lux", -1, last_relay_state);
        }

        gpioDelay(5000000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

