#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define SERVO_LOCKED_US  1000   /* ~0 degrees  */
#define SERVO_UNLOCKED_US 2000  /* ~180 degrees */
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500
#define DEBOUNCE_MS      100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_servo(int pulse_us)
{
    if (pulse_us < SERVO_MIN_US || pulse_us > SERVO_MAX_US) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_us, SERVO_MIN_US, SERVO_MAX_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop PWM signal to the servo */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    /* Ensure servo is in a known state */
    if (set_servo(SERVO_UNLOCKED_US) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Door lock initialized. Press Ctrl+C to exit.\n");

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            if (set_servo(SERVO_LOCKED_US) == 0) {
                gpioDelay(DEBOUNCE_MS * 1000);
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            if (set_servo(SERVO_UNLOCKED_US) == 0) {
                gpioDelay(DEBOUNCE_MS * 1000);
            }
        }
        gpioDelay(10 * 1000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

