#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define CONSUMER "haptic-feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low (motors off) */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Motor 1 on for 200 ms */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            break;
        }
        usleep(200000);

        /* Motor 1 off */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            break;
        }

        /* Motor 2 on for 300 ms */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            break;
        }
        usleep(300000);

        /* Motor 2 off */
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure motors are off and release lines */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Haptic feedback system stopped.\n");
    return ret;
}

