#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[]) {
    const char *mode = (argc > 1) ? argv[1] : NULL;

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_GPIO);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
