#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <string.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK   9000
#define NEC_HDR_SPACE  4500
#define NEC_BIT_MARK   560
#define NEC_ONE_SPACE  1690
#define NEC_ZERO_SPACE 560

typedef struct {
    uint32_t address;
    uint32_t command;
    bool valid;
} NECData;

typedef struct {
    uint32_t pulses[MAX_PULSES];
    int count;
    uint32_t lastTick;
    bool active;
} PulseBuffer;

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;
static MQTTClient_connectOptions mqtt_opts = MQTTClient_connectOptions_initializer;
static PulseBuffer pulseBuf;

static void signalHandler(int sig) {
    (void)sig;
    running = 0;
}

static void pulseCallback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return; /* Only falling edges */

    uint32_t diff = tick - pulseBuf.lastTick;
    pulseBuf.lastTick = tick;

    if (diff > 10000) {
        pulseBuf.count = 0;
        return;
    }

    if (pulseBuf.count < MAX_PULSES) {
        pulseBuf.pulses[pulseBuf.count++] = diff;
    } else {
        syslog(LOG_WARNING, "Pulse buffer overflow, resetting");
        pulseBuf.count = 0;
    }
}

static bool decodeNEC(uint32_t *p, int n, uint32_t *addr, uint32_t *cmd) {
    if (n < 67) return false;

    /* Validate header */
    if (p[0] < NEC_HDR_MARK * 0.8 || p[0] > NEC_HDR_MARK * 1.2 ||
        p[1] < NEC_HDR_SPACE * 0.8 || p[1] > NEC_HDR_SPACE * 1.2) {
        return false;
    }

    uint32_t decoded = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= n) return false;

        if (p[idx] > NEC_BIT_MARK * 0.8 && p[idx] < NEC_BIT_MARK * 1.2) {
            decoded <<= 1;
        } else if (p[idx] > NEC_ONE_SPACE * 0.8 && p[idx] < NEC_ONE_SPACE * 1.2) {
            decoded = (decoded << 1) | 1;
        } else if (p[idx] > NEC_ZERO_SPACE * 0.8 && p[idx] < NEC_ZERO_SPACE * 1.2) {
            decoded = (decoded << 1) | 0;
        } else {
            return false;
        }
    }

    *addr = decoded & 0xFF;
    *cmd = (decoded >> 8) & 0xFF;
    return true;
}

static void mqttConnectCallback(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicName; (void)message;
}

static void mqttDisconnectCallback(void *context, MQTTClient_responseOptions *respOptions, int code) {
    (void)context; (void)respOptions;
    syslog(LOG_WARNING, "MQTT disconnected (code %d)", code);
}

static void mqttDeliverCallback(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicName; (void)message;
}

static int mqttReconnect() {
    int rc = MQTTClient_connect(mqtt_client, &mqtt_opts);
    if (rc == MQTTCLIENT_SUCCESS) {
        syslog(LOG_INFO, "MQTT reconnected");
        MQTTClient_setCallbacks(mqtt_client, NULL, mqttConnectCallback, mqttDisconnectCallback, mqttDeliverCallback);
    } else {
        syslog(LOG_ERR, "MQTT reconnect failed (rc=%d)", rc);
    }
    return rc;
}

static void publishDecoded(uint32_t addr, uint32_t cmd) {
    char payload[128];
    int len = snprintf(payload, sizeof(payload),
                       "{\"address\": %u, \"command\": %u}",
                       addr, cmd);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)len;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed (rc=%d)", rc);
    } else {
        syslog(LOG_INFO, "Published: %s", payload);
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, pulseCallback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID_GENERATE, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    mqtt_opts.keepAliveInterval = 60;
    mqtt_opts.cleansession = 1;

    int rc = MQTTClient_connect(mqtt_client, &mqtt_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Initial MQTT connect failed (rc=%d)", rc);
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Connected to MQTT broker %s:%d", MQTT_BROKER, MQTT_PORT);
    MQTTClient_setCallbacks(mqtt_client, NULL, mqttConnectCallback, mqttDisconnectCallback, mqttDeliverCallback);

    while (running) {
        if (pulseBuf.count >= 67) {
            uint32_t addr, cmd;
            if (decodeNEC(pulseBuf.pulses, pulseBuf.count, &addr, &cmd)) {
                if (addr != (addr >> 8) || cmd != (cmd >> 8)) {
                    syslog(LOG_WARNING, "NEC frame: addr=0x%02X cmd=0x%02X (extended)");
                } else {
                    syslog(LOG_INFO, "Decoded NEC: addr=0x%02X cmd=0x%02X", addr, cmd);
                    publishDecoded(addr, cmd);
                }
            } else {
                syslog(LOG_WARNING, "Invalid NEC frame (pulses=%d)", pulseBuf.count);
            }
            pulseBuf.count = 0;
        }
        gpioDelay(10000); /* 10 ms */
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(mqtt_client, 3000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

