#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define CONV_TIME_MS   180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS    4

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float read_bh1750(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1.0f;
    }
    if (write(fd, &BH1750_CMD_OT_HRES, 1) != 1) {
        fprintf(stderr, "write cmd 0x%02X to 0x%02X: %s\n", BH1750_CMD_OT_HRES, addr, strerror(errno));
        return -1.0f;
    }
    usleep(CONV_TIME_MS * 1000);
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read from 0x%02X: got %zd bytes, %s\n", addr, n, n < 0 ? strerror(errno) : "short read");
        return -1.0f;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

static void send_multicast(int sockfd, const float vals[NUM_SENSORS]) {
    char buf[256];
    int len = snprintf(buf, sizeof(buf), "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f\n",
                       (int)vals[0], vals[0],
                       (int)vals[1], vals[1],
                       (int)vals[2], vals[2],
                       (int)vals[3], vals[3]);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed\n");
        return;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sockfd, buf, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int addrs[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3, BH1750_ADDR_4};
    int sock_fd = -1;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, addrs[i]) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed for sensor %d\n", addrs[i], i + 1);
        }
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int ttl = 1;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt IP_MULTICAST_TTL: %s\n", strerror(errno));
    }

    while (g_running) {
        float vals[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            vals[i] = read_bh1750(i2c_fd, addrs[i]);
            if (vals[i] < 0.0f) {
                vals[i] = -1.0f;
            }
        }
        send_multicast(sock_fd, vals);
        sleep(1);
    }

    if (sock_fd >= 0) close(sock_fd);
    close(i2c_fd);
    return 0;
}

