#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR   0x28
#define LOG_FILE        "airflow_log.txt"
#define SAMPLE_PERIOD_S 1
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_len(int fd)
{
    /* Issue a zero-length write as a start condition (no data bytes) */
    if (write(fd, NULL, 0) < 0) {
        if (errno == ENXIO)
            return -1;  /* sensor not present */
        return -2;     /* bus error */
    }
    return 0;
}

static int i2c_read_flow(int fd, uint16_t *raw_out)
{
    uint8_t buf[2];
    ssize_t n;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_zero_len(fd) < 0) {
            if (errno == ENXIO)
                return -1;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        n = read(fd, buf, sizeof(buf));
        if (n == 2) {
            *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        if (n < 0) {
            if (errno == ENXIO)
                return -1;
            usleep(RETRY_DELAY_MS * 1000);
        } else {
            /* Short read — sensor may be disconnected or bus stuck */
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -2;
}

static float convert_to_slpm(uint16_t raw)
{
    int16_t signed_raw = (int16_t)raw;
    return (float)(signed_raw - 3277) * 0.1f;
}

static void log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(fp, "%s, Flow Rate: %.2f SLPM\n", ts, flow_rate);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    uint16_t raw;
    float flow_rate;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        if (errno == ENXIO) {
            fprintf(stderr, "Sensor at 0x%02X not present on %s\n",
                    AWM7300V_ADDR, I2C_BUS);
        } else {
            perror("ioctl(I2C_SLAVE)");
        }
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        if (i2c_read_flow(g_i2c_fd, &raw) == 0) {
            flow_rate = convert_to_slpm(raw);
            log_flow_rate(g_log_fp, flow_rate);
            printf("Flow Rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow data after %d retries.\n",
                    MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

