#define I2C_BUS        "/dev/i2c-1"
#define AS7341_ADDR    0x39

#define AS7341_ENABLE  0x80
#define AS7341_ATIME   0x81
#define AS7341_WTIME   0x83
#define AS7341_ID      0x24
#define AS7341_CFG6    0xAF
#define AS7341_F1DATA  0x60
#define AS7341_F8DATA  0x73

#define AS7341_ID_VAL  0x19
#define AS7341_PON_BIT 0x01
#define AS7341_SP_EN_BIT 0x20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
