#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_REG 0x28
#define NUM_BYTES 6
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t program_running = 1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(const char *message) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s\n", ts, message);
    fflush(error_file);
}

static int i2c_write_byte(uint8_t reg) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(i2c_fd, &reg, 1) == 1) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(i2c_fd, buf, len) == (ssize_t)len) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t reg = ACCEL_REG;
    if (i2c_write_byte(reg) < 0) return -1;
    uint8_t buf[NUM_BYTES];
    if (i2c_read_bytes(buf, NUM_BYTES) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = raw_x * 0.000244f;
    *y = raw_y * 0.000244f;
    *z = raw_z * 0.000244f;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(data_file, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(data_file);
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (error_file) { fclose(error_file); error_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (interval <= 0) { fprintf(stderr, "Invalid interval.\n"); return EXIT_FAILURE; }
    if (i2c_address < 0x03 || i2c_address > 0x77) {
        fprintf(stderr, "Invalid I2C address (0x%02X). Must be 0x03-0x77.\n", i2c_address);
        return EXIT_FAILURE;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    error_file = fopen(ERROR_LOG_FILENAME, "a");
    if (!error_file) { perror("fopen error_log"); return EXIT_FAILURE; }
    data_file = fopen(filename, "a");
    if (!data_file) {
        perror("fopen data_file");
        log_error("Failed to open data file.");
        fclose(error_file); error_file = NULL;
        return EXIT_FAILURE;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        log_error("Failed to open I2C bus.");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("ioctl I2C_SLAVE");
        log_error("Failed to set I2C slave address.");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Seismic data logger started. I2C addr=0x%02X, interval=%d s, file=%s\n",
           i2c_address, interval, filename);
    while (program_running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            log_error("Failed to read acceleration data.");
        }
        sleep(interval);
    }
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

