#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HIGH_RES 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int udp_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error (cmd 0x%02X): %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    return 0;
}

static int init_udp_socket(void) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt TTL");
        close(sock);
        return -1;
    }
    return sock;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (udp_socket >= 0) {
        close(udp_socket);
        udp_socket = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor.\n");
        cleanup();
        return 1;
    }

    udp_socket = init_udp_socket();
    if (udp_socket < 0) {
        cleanup();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    while (running) {
        uint16_t raw;
        if (i2c_read_word(i2c_fd, &raw) < 0) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float lux = (float)raw / 1.2f;

        char buffer[64];
        int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
        if (len < 0 || (size_t)len >= sizeof(buffer)) {
            fprintf(stderr, "snprintf failed or truncated.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (sendto(udp_socket, buffer, (size_t)len, 0,
                    (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("sendto");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

