#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 8192
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD_0 0x0204
#define MAGIC_WORD_1 0x0306
#define MAGIC_WORD_2 0x0805
#define MAGIC_WORD_3 0x0709

#pragma pack(push, 1)
typedef struct {
    uint32_t magic_word[4];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} MmwHeader;

typedef struct {
    uint32_t type;
    uint32_t length;
} TlvHeader;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} DetectedObj;
#pragma pack(pop)

static volatile sig_atomic_t terminate = 0;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int read_exact(uint8_t *buf, int len) {
    int total = 0;
    while (total < len && !terminate) {
        int n = serRead(uart_handle, (char *)(buf + total), len - total);
        if (n < 0) {
            fprintf(stderr, "UART read error\n");
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        total += n;
    }
    return (total == len) ? 0 : -1;
}

static int find_magic_word(uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        uint32_t w0 = (uint32_t)buf[i] | ((uint32_t)buf[i+1] << 8);
        uint32_t w1 = (uint32_t)buf[i+2] | ((uint32_t)buf[i+3] << 8);
        uint32_t w2 = (uint32_t)buf[i+4] | ((uint32_t)buf[i+5] << 8);
        uint32_t w3 = (uint32_t)buf[i+6] | ((uint32_t)buf[i+7] << 8);
        if (w0 == MAGIC_WORD_0 && w1 == MAGIC_WORD_1 &&
            w2 == MAGIC_WORD_2 && w3 == MAGIC_WORD_3) {
            return i;
        }
    }
    return -1;
}

static int process_frame(uint8_t *frame, int len) {
    if (len < (int)sizeof(MmwHeader)) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }
    MmwHeader *hdr = (MmwHeader *)frame;
    if (hdr->total_packet_len < sizeof(MmwHeader) || hdr->total_packet_len > MAX_FRAME_SIZE) {
        fprintf(stderr, "Invalid packet length: %u\n", hdr->total_packet_len);
        return -1;
    }
    if (len < (int)hdr->total_packet_len) {
        fprintf(stderr, "Incomplete frame (%d < %u)\n", len, hdr->total_packet_len);
        return -1;
    }
    uint32_t offset = sizeof(MmwHeader);
    int obj_count = 0;
    for (uint32_t i = 0; i < hdr->num_tlvs; i++) {
        if (offset + (int)sizeof(TlvHeader) > hdr->total_packet_len) break;
        TlvHeader *tlv = (TlvHeader *)(frame + offset);
        offset += sizeof(TlvHeader);
        if (offset + (int)tlv->length > hdr->total_packet_len) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            break;
        }
        if (tlv->type == 1) {
            uint32_t obj_offset = offset;
            for (uint32_t j = 0; j < hdr->num_detected_obj; j++) {
                if (obj_offset + (int)sizeof(DetectedObj) > offset + tlv->length) break;
                DetectedObj *obj = (DetectedObj *)(frame + obj_offset);
                float range = obj->range_idx * 0.0436f;
                float velocity = obj->doppler_idx * 0.0436f;
                time_t now = time(NULL);
                fprintf(csv_file, "%ld,%d,%.3f,%.3f\n", (long)now, obj_count++, range, velocity);
                fflush(csv_file);
                obj_offset += sizeof(DetectedObj);
            }
        }
        offset += tlv->length;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);
    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(csv_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(stderr, "Radar data acquisition started. Press Ctrl+C to stop.\n");
    while (!terminate) {
        int mw_pos = find_magic_word(frame_buf, MAX_FRAME_SIZE);
        if (mw_pos < 0) {
            if (!terminate) {
                gpioDelay(10000);
            }
            continue;
        }
        if (mw_pos > 0) {
            memmove(frame_buf, frame_buf + mw_pos, MAX_FRAME_SIZE - mw_pos);
        }
        int remaining = MAX_FRAME_SIZE - MAGIC_WORD_SIZE;
        if (remaining <= 0) {
            remaining = MAX_FRAME_SIZE - MAGIC_WORD_SIZE;
            memmove(frame_buf, frame_buf + MAGIC_WORD_SIZE, remaining);
        }
        int n = serRead(uart_handle, (char *)(frame_buf + MAGIC_WORD_SIZE), remaining);
        if (n < 0) {
            fprintf(stderr, "UART read error\n");
            break;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        int frame_len = MAGIC_WORD_SIZE + n;
        if (frame_len < (int)sizeof(MmwHeader)) {
            fprintf(stderr, "Frame too small, discarding\n");
            continue;
        }
        MmwHeader *hdr = (MmwHeader *)frame_buf;
        if (hdr->total_packet_len < sizeof(MmwHeader) || hdr->total_packet_len > MAX_FRAME_SIZE) {
            fprintf(stderr, "Invalid packet length: %u\n", hdr->total_packet_len);
            continue;
        }
        if (frame_len < (int)hdr->total_packet_len) {
            fprintf(stderr, "Incomplete frame (%d < %u), resyncing\n", frame_len, hdr->total_packet_len);
            continue;
        }
        process_frame(frame_buf, frame_len);
    }
    free(frame_buf);
    if (csv_file) fclose(csv_file);
    if (uart_handle >= 0) serClose(uart_handle);
    gpioTerminate();
    fprintf(stderr, "Radar data acquisition stopped.\n");
    return 0;
}

