#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_terminate = 0;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_PORT);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[LINE_BUF_SIZE];

    printf("Starting AWR1642 range data acquisition on %s...\n", UART_PORT);
    fflush(stdout);

    while (!g_terminate) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            /* Timeout — no data available; loop back to check g_terminate */
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Should not happen on a tty, but handle defensively */
            continue;
        }

        read_buf[n] = '\0';

        for (ssize_t i = 0; i < n && !g_terminate; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                char *endptr = NULL;
                long val = strtol(line_buf, &endptr, 10);
                if (endptr == line_buf || *endptr != '\0') {
                    fprintf(stderr, "Invalid data: '%s'\n", line_buf);
                    line_len = 0;
                    continue;
                }

                float range = (float)val;
                char ts[32];
                get_timestamp(ts, sizeof(ts));
                printf("Timestamp: %s, Range: %.2f meters\n", ts, range);
                fflush(stdout);

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    /* Line too long — discard and reset */
                    fprintf(stderr, "Line exceeded buffer, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        tcflush(g_uart_fd, TCIOFLUSH);
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

